FPI_V200_PROVIDER_SIGNATURES = {
    "Polar Team Pro": {
        "tokens": [
            "teljes tav", "kezdesi ido", "edzesi terhelesi pontertek",
            "sebesseg celzonaban", "izomterhelesi pontertek",
        ],
        "file_tokens": ["polar", "team pro"],
    },
    "Catapult": {
        "tokens": [
            "total distance", "player load", "max velocity",
            "meterage per minute", "explosive efforts",
        ],
        "file_tokens": ["catapult", "openfield", "vector"],
    },
    "PlayerTek": {
        "tokens": [
            "playertek", "total distance", "sprint distance",
            "power plays", "impacts",
        ],
        "file_tokens": ["playertek"],
    },
    "Brainsports": {
        "tokens": [
            "brainsports", "athlete", "session date",
            "high intensity running", "training load",
        ],
        "file_tokens": ["brainsports"],
    },
    "STATSports": {
        "tokens": [
            "statsports", "dynamic stress load", "hsr distance",
            "high metabolic load distance",
        ],
        "file_tokens": ["statsports", "apex"],
    },
    "GPSports": {
        "tokens": [
            "gpsports", "body load", "zone distance", "top speed",
        ],
        "file_tokens": ["gpsports"],
    },
}


def _fpi_v200_norm(value: object) -> str:
    return _norm_mapping_text(value)


def _fpi_v200_detect_provider_from_frame(
    df: pd.DataFrame,
    file_name: str = "",
    current_provider: Optional[str] = None,
) -> Tuple[str, Dict[str, int]]:
    """Providerfelismerés fejléc-, fájlnév- és adattartalom-jelzésekből."""
    if df is None:
        return current_provider or "Ismeretlen / Smart Mapper", {}

    columns_text = " | ".join(_fpi_v200_norm(c) for c in df.columns)
    file_text = _fpi_v200_norm(file_name)
    sample_parts: List[str] = []
    for col in list(df.columns)[:15]:
        try:
            vals = df[col].dropna().astype(str).head(5).tolist()
            sample_parts.extend(vals)
        except Exception:
            continue
    sample_text = _fpi_v200_norm(" ".join(sample_parts))
    full_text = f"{columns_text} {sample_text}"

    scores: Dict[str, int] = {}
    for provider, signature in FPI_V200_PROVIDER_SIGNATURES.items():
        score = 0
        for token in signature["tokens"]:
            if _fpi_v200_norm(token) in full_text:
                score += 3
        for token in signature["file_tokens"]:
            if _fpi_v200_norm(token) in file_text:
                score += 5
        scores[provider] = score

    best = max(scores, key=scores.get) if scores else ""
    if scores.get(best, 0) >= 5:
        return best, scores
    if current_provider and current_provider not in {"", "Ismeretlen", "Általános / Smart Mapper"}:
        return current_provider, scores
    return "Ismeretlen / Smart Mapper", scores


def _fpi_v200_first_existing(df: pd.DataFrame, candidates: List[str]) -> Optional[str]:
    norm_map = {_fpi_v200_norm(col): col for col in df.columns}
    for candidate in candidates:
        found = norm_map.get(_fpi_v200_norm(candidate))
        if found is not None:
            return found
    return None


def _fpi_v200_numeric(df: pd.DataFrame, col: str) -> pd.Series:
    if col not in df.columns:
        return pd.Series(np.nan, index=df.index, dtype=float)
    return pd.to_numeric(df[col], errors="coerce")


def _fpi_v200_session_kind(value: object) -> str:
    text = _fpi_v200_norm(value)
    if any(token in text for token in [
        "meccs", "merkozes", "match", "game", "fixture", "competition",
    ]):
        return "match"
    if any(token in text for token in [
        "edzes", "training", "train", "practice", "session",
    ]):
        return "training"
    return "other"


def _fpi_v200_normalize_session_type(
    df: pd.DataFrame,
    recovery_log: List[str],
) -> pd.DataFrame:
    """Az explicit Típus elsőbbséget élvez; névből csak hiány esetén következtet."""
    data = df.copy()

    type_source = _fpi_v200_first_existing(data, [
        "session_type", "Session Type", "Típus", "Tipus", "Type",
        "Training/Match", "Edzés/Meccs", "Event Type", "Activity Type",
    ])
    name_source = _fpi_v200_first_existing(data, [
        "session_name", "Session Name", "Szakasz neve", "Activity",
        "Drill", "Event", "Period Name", "Split Name",
    ])

    if "session_type" not in data.columns and type_source is not None:
        data["session_type"] = data[type_source]
        recovery_log.append(f"Session Type helyreállítva ebből: {type_source}")

    if "session_type" not in data.columns:
        data["session_type"] = pd.NA

    explicit_kind = data["session_type"].apply(_fpi_v200_session_kind)
    unknown = explicit_kind.eq("other")

    if name_source is not None and unknown.any():
        inferred = data[name_source].apply(_fpi_v200_session_kind)
        training_mask = unknown & inferred.eq("training")
        match_mask = unknown & inferred.eq("match")
        if training_mask.any():
            data.loc[training_mask, "session_type"] = "Edzés"
            recovery_log.append(
                f"{int(training_mask.sum())} ismeretlen típus Edzésként felismerve ebből: {name_source}"
            )
        if match_mask.any():
            data.loc[match_mask, "session_type"] = "Meccs"
            recovery_log.append(
                f"{int(match_mask.sum())} ismeretlen típus Meccsként felismerve ebből: {name_source}"
            )

    final_kind = data["session_type"].apply(_fpi_v200_session_kind)
    data["session_type"] = final_kind.map({
        "training": "Edzés",
        "match": "Meccs",
        "other": "Egyéb",
    })
    return data


def _fpi_v200_normalize_dates(
    df: pd.DataFrame,
    recovery_log: List[str],
) -> pd.DataFrame:
    data = df.copy()
    start_source = _fpi_v200_first_existing(data, [
        "start_time", "Start Time", "Kezdési idő", "Kezdesi ido",
        "Session Date", "Dátum", "Datum", "Date", "Start",
    ])
    end_source = _fpi_v200_first_existing(data, [
        "end_time", "End Time", "Befejezési idő", "Finish", "End",
    ])

    if "start_time" not in data.columns and start_source is not None:
        data["start_time"] = data[start_source]
        recovery_log.append(f"Kezdési idő helyreállítva ebből: {start_source}")

    if "start_time" in data.columns:
        data["start_time"] = pd.to_datetime(data["start_time"], errors="coerce")
        data["session_date"] = data["start_time"].dt.normalize()
        iso = data["start_time"].dt.isocalendar()
        data["week"] = (
            iso["year"].astype("Int64").astype(str)
            + "-W"
            + iso["week"].astype("Int64").astype(str).str.zfill(2)
        )
        data.loc[data["start_time"].isna(), "week"] = pd.NA

    if (
        ("duration_min" not in data.columns or _fpi_v200_numeric(data, "duration_min").notna().sum() == 0)
        and "start_time" in data.columns
        and end_source is not None
    ):
        end_time = pd.to_datetime(data[end_source], errors="coerce")
        data["duration_min"] = (end_time - data["start_time"]).dt.total_seconds() / 60.0
        recovery_log.append(f"Időtartam helyreállítva: {end_source} - start_time")

    return data


def _fpi_v200_recover_metrics(
    df: pd.DataFrame,
    recovery_log: List[str],
) -> pd.DataFrame:
    """Providerfüggetlen, óvatos self-healing mutatómotor."""
    data = df.copy()

    alias_map = {
        "player_name": ["Player Name", "Játékos neve", "Name", "Athlete", "Név"],
        "total_distance": ["Total Distance", "Teljes táv [m]", "Distance", "Össztáv", "TD"],
        "duration_min": ["Duration Min", "Minutes", "Időtartam [perc]", "Duration"],
        "distance_per_min": ["Distance Per Min", "m/min", "Táv/perc [m/min]", "Meterage Per Minute"],
        "max_speed": ["Max Speed", "Top Speed", "Maximum Velocity", "Maximális sebesség [km/h]"],
        "sprints": ["Sprints", "Sprint Count", "Sprintek", "Number of Sprints"],
        "speed_zone_4": ["Speed Zone 4", "Zone 4 Distance", "HSR Distance"],
        "speed_zone_5": ["Speed Zone 5", "Sprint Distance", "Sprint táv"],
        "hsr_distance": ["HSR Distance", "High Speed Running Distance", "High Speed Distance"],
        "sprint_distance": ["Sprint Distance", "Sprint táv", "Zone 5 Distance"],
        "training_load": ["Training Load", "Player Load", "Edzési terhelési pontérték"],
        "acc_high": ["High Accelerations", "Total Accelerations", "Gyorsulások száma (3.00 - 50.00 m/s²)"],
        "dec_high": ["High Decelerations", "Total Decelerations", "Gyorsulások száma (-50.00 - -3.00 m/s²)"],
        "high_efforts": ["High Efforts", "Explosive Efforts", "High Intensity Efforts"],
        "match_minutes": ["Match Minutes", "Minutes Played", "Játékperc", "Játékpercek"],
    }

    for target, aliases in alias_map.items():
        existing_ok = target in data.columns and _fpi_v200_numeric(data, target).notna().sum() > 0
        if target == "player_name":
            existing_ok = target in data.columns and data[target].notna().sum() > 0
        if existing_ok:
            continue
        source = _fpi_v200_first_existing(data, [target] + aliases)
        if source is not None and source != target:
            data[target] = data[source]
            recovery_log.append(f"{target} helyreállítva ebből: {source}")

    numeric_targets = [
        "total_distance", "duration_min", "distance_per_min", "max_speed",
        "sprints", "speed_zone_4", "speed_zone_5", "hsr_distance",
        "sprint_distance", "training_load", "acc_high", "dec_high",
        "high_efforts", "match_minutes",
    ]
    for col in numeric_targets:
        if col in data.columns:
            data[col] = pd.to_numeric(data[col], errors="coerce")

    # Duration oszlopból perc, ha még nincs duration_min.
    if "duration_min" not in data.columns or data["duration_min"].notna().sum() == 0:
        duration_source = _fpi_v200_first_existing(data, ["duration", "Duration", "Időtartam"])
        if duration_source is not None:
            data["duration_min"] = data[duration_source].apply(duration_to_minutes)
            recovery_log.append(f"duration_min helyreállítva ebből: {duration_source}")

    z4 = _fpi_v200_numeric(data, "speed_zone_4")
    z5 = _fpi_v200_numeric(data, "speed_zone_5")

    if "sprint_distance" not in data.columns or _fpi_v200_numeric(data, "sprint_distance").notna().sum() == 0:
        if z5.notna().sum() > 0:
            data["sprint_distance"] = z5
            recovery_log.append("Sprint Distance helyreállítva ebből: Speed Zone 5")

    if "hsr_distance" not in data.columns or _fpi_v200_numeric(data, "hsr_distance").notna().sum() == 0:
        if z4.notna().sum() > 0 or z5.notna().sum() > 0:
            data["hsr_distance"] = z4.fillna(0) + z5.fillna(0)
            recovery_log.append("HSR helyreállítva ebből: Speed Zone 4 + Speed Zone 5")

    if (
        "distance_per_min" not in data.columns
        or _fpi_v200_numeric(data, "distance_per_min").notna().sum() == 0
    ):
        distance = _fpi_v200_numeric(data, "total_distance")
        duration = _fpi_v200_numeric(data, "duration_min")
        valid = duration.gt(0)
        if valid.any() and distance.notna().any():
            data["distance_per_min"] = distance / duration.where(valid)
            recovery_log.append("Distance/min helyreállítva: Total Distance / Duration")

    if (
        "match_minutes" not in data.columns
        or _fpi_v200_numeric(data, "match_minutes").notna().sum() == 0
    ):
        if "duration_min" in data.columns:
            data["match_minutes"] = _fpi_v200_numeric(data, "duration_min")
            recovery_log.append("Match Minutes helyreállítva ebből: Duration")

    if (
        "high_efforts" not in data.columns
        or _fpi_v200_numeric(data, "high_efforts").notna().sum() == 0
    ):
        effort_parts = []
        for col in ["sprints", "acc_high", "dec_high"]:
            if col in data.columns:
                effort_parts.append(_fpi_v200_numeric(data, col))
        if effort_parts:
            data["high_efforts"] = pd.concat(effort_parts, axis=1).sum(axis=1, min_count=1)
            recovery_log.append("High Efforts helyreállítva: Sprint + High Acc + High Dec")

    return data


def _fpi_v200_filter_non_player_rows(
    df: pd.DataFrame,
    recovery_log: List[str],
) -> pd.DataFrame:
    data = df.copy()
    if "player_name" not in data.columns:
        return data

    names = data["player_name"].astype(str).str.strip()
    non_player = names.str.lower().str.contains(
        r"benchmark|átlag|atlag|összesen|osszesen|team average|squad average",
        regex=True,
        na=False,
    )
    empty = names.eq("") | names.str.lower().isin({"nan", "none"})
    remove = non_player | empty
    if remove.any():
        recovery_log.append(f"{int(remove.sum())} nem játékos/összesítő sor kiszűrve")
        data = data.loc[~remove].copy()
    return data


def _fpi_v200_quality_report(
    df: pd.DataFrame,
    provider: str,
    recovery_log: List[str],
    provider_scores: Optional[Dict[str, int]] = None,
) -> Dict[str, object]:
    data = df if isinstance(df, pd.DataFrame) else pd.DataFrame()
    rows = len(data)

    def coverage(col: str) -> float:
        if rows == 0 or col not in data.columns:
            return 0.0
        if col == "player_name":
            valid = data[col].astype(str).str.strip().replace({"nan": "", "None": ""}).ne("")
        else:
            valid = data[col].notna()
        return float(valid.mean())

    weights = {
        "player_name": 15,
        "session_type": 14,
        "start_time": 14,
        "total_distance": 10,
        "duration_min": 7,
        "distance_per_min": 6,
        "max_speed": 6,
        "hsr_distance": 8,
        "sprint_distance": 7,
        "sprints": 5,
        "high_efforts": 4,
        "training_load": 4,
    }
    weighted = sum(coverage(col) * weight for col, weight in weights.items())
    total_weight = sum(weights.values())
    score = int(round(100 * weighted / total_weight)) if total_weight else 0

    kinds = (
        data["session_type"].apply(_fpi_v200_session_kind)
        if "session_type" in data.columns
        else pd.Series(dtype=object)
    )
    start = pd.to_datetime(data.get("start_time"), errors="coerce") if "start_time" in data.columns else pd.Series(dtype="datetime64[ns]")

    warnings: List[str] = []
    critical = ["player_name", "session_type", "start_time"]
    for col in critical:
        if coverage(col) < 0.90:
            warnings.append(f"Kritikus mező gyenge lefedettsége: {col} ({coverage(col):.0%})")
    for col in ["total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts"]:
        if coverage(col) < 0.50:
            warnings.append(f"Hiányos mutató: {col} ({coverage(col):.0%})")
    if "distance_hierarchy_issue" in data.columns:
        hierarchy_issues = int(data["distance_hierarchy_issue"].fillna(False).astype(bool).sum())
        if hierarchy_issues:
            warnings.append(f"Távolság-hierarchia javítás történt {hierarchy_issues} sorban (sprint ≤ HSR ≤ össztáv)")

    if score >= 90:
        label = "Kiváló"
    elif score >= 75:
        label = "Jó"
    elif score >= 60:
        label = "Használható"
    else:
        label = "Javítandó"

    weeks = 0
    if "week" in data.columns:
        weeks = int(data["week"].dropna().nunique())
    elif not start.empty:
        weeks = int(start.dt.to_period("W").nunique())

    return {
        "provider": provider,
        "provider_scores": provider_scores or {},
        "rows": rows,
        "players": int(data["player_name"].dropna().astype(str).nunique()) if "player_name" in data.columns else 0,
        "weeks": weeks,
        "training_rows": int(kinds.eq("training").sum()),
        "match_rows": int(kinds.eq("match").sum()),
        "other_rows": int(kinds.eq("other").sum()),
        "date_min": start.min() if not start.empty else pd.NaT,
        "date_max": start.max() if not start.empty else pd.NaT,
        "quality_score": score,
        "quality_label": label,
        "recoveries": list(dict.fromkeys(recovery_log)),
        "warnings": warnings,
        "available_metrics": [
            col for col in weights
            if col in data.columns and coverage(col) >= 0.50
        ],
    }



def _fpi_v201_training_session_key(df: pd.DataFrame) -> pd.Series:
    """Providerfüggetlen edzésazonosító.

    Elsődlegesen a pontos kezdési időt használja. Ha az nincs, akkor a dátum és
    session_name kombinációját. Így egy edzés belső Period/Split sorai nem
    számítanak külön edzésnek.
    """
    if df is None or df.empty:
        return pd.Series(dtype="object")

    data = df.copy()
    index = data.index

    if "start_time" in data.columns:
        start = pd.to_datetime(data["start_time"], errors="coerce")
    elif "session_date" in data.columns:
        start = pd.to_datetime(data["session_date"], errors="coerce")
    else:
        start = pd.Series(pd.NaT, index=index)

    day_text = start.dt.strftime("%Y-%m-%d").fillna("")
    minute_text = start.dt.floor("min").dt.strftime("%Y-%m-%d %H:%M").fillna("")

    if "session_name" in data.columns:
        name_text = (
            data["session_name"]
            .astype(str)
            .map(_fpi_v200_norm)
            .replace({"nan": "", "none": ""})
        )
    else:
        name_text = pd.Series("", index=index)

    # Az ismert belső szakasznevek ne hozzanak létre külön eseményt.
    generic_period = name_text.str.contains(
        r"^period\b|^split\b|^drill\b|^quarter\b|^half\b|"
        r"első félidő|masodik felido|második félidő|"
        r"warm.?up|bemelegítés|bemelegites|cool.?down|levezetés|levezetes",
        regex=True,
        na=False,
    )
    clean_name = name_text.mask(generic_period, "session")

    # Ha van pontos kezdési idő, az az elsődleges eseményazonosító.
    key = minute_text.where(minute_text.ne(""), day_text + "|" + clean_name)
    key = key.where(key.ne(""), pd.Series(index.astype(str), index=index))
    return key.astype(str)


def _fpi_v201_add_training_attendance(
    df: pd.DataFrame,
    recovery_log: Optional[List[str]] = None,
) -> pd.DataFrame:
    """Heti csapatedzésszám és játékosrészvétel hozzáadása minden sorhoz."""
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df.copy()

    data = df.copy()
    required = {"player_name", "week", "session_type"}
    if not required.issubset(data.columns):
        return data

    training_mask = data["session_type"].apply(_fpi_v200_session_kind).eq("training")
    training = data.loc[training_mask].copy()
    if training.empty:
        data["team_training_sessions"] = 0
        data["player_training_sessions"] = 0
        data["training_availability_pct"] = np.nan
        return data

    training["_fpi_training_session_id"] = _fpi_v201_training_session_key(training)

    # Csapatszint: hány külön edzés volt az adott héten.
    team_sessions = (
        training.groupby("week")["_fpi_training_session_id"]
        .nunique()
        .rename("team_training_sessions")
    )

    # Játékosszint: a játékos hány külön edzésen szerepelt.
    player_sessions = (
        training.drop_duplicates(
            subset=["week", "player_name", "_fpi_training_session_id"]
        )
        .groupby(["week", "player_name"])
        .size()
        .rename("player_training_sessions")
        .reset_index()
    )

    attendance = player_sessions.merge(
        team_sessions.reset_index(),
        on="week",
        how="left",
    )
    attendance["training_availability_pct"] = np.where(
        attendance["team_training_sessions"] > 0,
        attendance["player_training_sessions"]
        / attendance["team_training_sessions"]
        * 100.0,
        np.nan,
    )
    attendance["training_availability_pct"] = (
        attendance["training_availability_pct"].clip(lower=0, upper=100)
    )

    data = data.merge(
        attendance,
        on=["week", "player_name"],
        how="left",
        suffixes=("", "_v201"),
    )

    # Ha újrafut a postprocess, ne keletkezzenek duplikált mezők.
    for col in [
        "team_training_sessions",
        "player_training_sessions",
        "training_availability_pct",
    ]:
        alt = f"{col}_v201"
        if alt in data.columns:
            data[col] = data[alt].combine_first(data.get(col))
            data = data.drop(columns=[alt])

    # Az adott héten csak meccsen szereplő játékos 0 edzésrészvételt kap.
    data["team_training_sessions"] = (
        data["week"].map(team_sessions).fillna(0).astype(int)
    )
    data["player_training_sessions"] = (
        pd.to_numeric(data["player_training_sessions"], errors="coerce")
        .fillna(0)
        .astype(int)
    )
    data["training_availability_pct"] = np.where(
        data["team_training_sessions"] > 0,
        data["player_training_sessions"]
        / data["team_training_sessions"]
        * 100.0,
        np.nan,
    )
    data["training_availability_pct"] = (
        pd.to_numeric(data["training_availability_pct"], errors="coerce")
        .clip(lower=0, upper=100)
    )

    if recovery_log is not None:
        recovery_log.append(
            "Edzésrészvétel kiszámítva: játékos edzései / heti csapatedzések"
        )

    return data


def _fpi_v201_week_attendance_summary(
    df: pd.DataFrame,
    week: str,
) -> Dict[str, object]:
    """Heti, deduplikált részvételi összefoglaló."""
    if df is None or df.empty:
        return {}

    data = _fpi_v201_add_training_attendance(df)
    selected = data[data["week"].astype(str) == str(week)].copy()
    if selected.empty or "training_availability_pct" not in selected.columns:
        return {}

    player_rows = (
        selected[
            [
                "player_name",
                "team_training_sessions",
                "player_training_sessions",
                "training_availability_pct",
            ]
        ]
        .drop_duplicates(subset=["player_name"])
        .copy()
    )
    if player_rows.empty:
        return {}

    availability = pd.to_numeric(
        player_rows["training_availability_pct"], errors="coerce"
    )
    valid = availability.dropna()

    team_sessions = int(
        pd.to_numeric(
            player_rows["team_training_sessions"], errors="coerce"
        ).max()
        or 0
    )

    return {
        "team_training_sessions": team_sessions,
        "tracked_players": int(player_rows["player_name"].nunique()),
        "mean_availability_pct": float(valid.mean()) if not valid.empty else np.nan,
        "median_availability_pct": float(valid.median()) if not valid.empty else np.nan,
        "full_attendance_players": int((availability >= 99.5).sum()),
        "below_75_players": int((availability < 75).sum()),
        "below_50_players": int((availability < 50).sum()),
        "player_table": player_rows.sort_values(
            ["training_availability_pct", "player_name"],
            ascending=[True, True],
        ).reset_index(drop=True),
    }


# =========================================================
# V202 - Adaptive GPS analysis modes
# =========================================================
def _fpi_v202_event_key(df: pd.DataFrame) -> pd.Series:
    # Providerfüggetlen eseménykulcs edzéshez és meccshez.
    if df is None or df.empty:
        return pd.Series(dtype="object")
    data = df.copy()
    if "start_time" in data.columns:
        start = pd.to_datetime(data["start_time"], errors="coerce")
    elif "session_date" in data.columns:
        start = pd.to_datetime(data["session_date"], errors="coerce")
    else:
        start = pd.Series(pd.NaT, index=data.index)
    day = start.dt.strftime("%Y-%m-%d").fillna("")
    minute = start.dt.floor("min").dt.strftime("%Y-%m-%d %H:%M").fillna("")
    name = data.get("session_name", pd.Series("", index=data.index)).astype(str).map(_fpi_v200_norm)
    kind = data.get("session_type", pd.Series("", index=data.index)).apply(_fpi_v200_session_kind)
    generic = name.str.contains(
        r"^period\b|^split\b|^drill\b|^quarter\b|^half\b|warm.?up|cool.?down|"
        r"bemelegítés|bemelegites|levezetés|levezetes|első félidő|masodik felido|második félidő",
        regex=True, na=False,
    )
    name = name.mask(generic, "session")
    fallback = day + "|" + kind.astype(str) + "|" + name
    key = minute.where(minute.ne(""), fallback)
    if "match_event_id" in data.columns:
        match_event = data["match_event_id"].astype("string")
        use_match_event = kind.eq("match") & match_event.notna() & match_event.str.strip().ne("")
        key = key.where(~use_match_event, "match|" + match_event.fillna(""))
    return key.where(key.ne("||"), pd.Series(data.index.astype(str), index=data.index)).astype(str)


def _fpi_v202_detect_analysis_mode(df: pd.DataFrame, selected_week: Optional[str] = None) -> Dict[str, object]:
    # Felismeri az elemzés üzemmódját.
    default = {
        "code": "no_data", "label": "Nincs adat", "icon": "⚪",
        "description": "Nincs elemezhető GPS-adat.", "confidence": "alacsony",
        "selected_week": selected_week, "training_sessions": 0, "match_sessions": 0,
        "total_sessions": 0, "is_complete_week": False, "is_provisional": True,
    }
    if df is None or df.empty or "week" not in df.columns:
        return default

    data = df.copy()
    data["week"] = data["week"].astype(str)
    weeks = [w for w in data["week"].dropna().unique().tolist() if str(w).strip()]
    if not weeks:
        return default
    week = str(selected_week) if selected_week is not None else str(weeks[-1])
    current = data[data["week"] == week].copy()
    if current.empty:
        return default

    current["_kind_v202"] = current.get("session_type", "").apply(_fpi_v200_session_kind)
    current["_event_v202"] = _fpi_v202_event_key(current)
    event_table = current[["_event_v202", "_kind_v202"]].drop_duplicates()
    training_n = int((event_table["_kind_v202"] == "training").sum())
    match_n = int((event_table["_kind_v202"] == "match").sum())
    total_n = int(event_table["_event_v202"].nunique())

    all_data = data.copy()
    all_data["_kind_v202"] = all_data.get("session_type", "").apply(_fpi_v200_session_kind)
    has_match_history = bool((all_data["_kind_v202"] == "match").any())
    other_match_weeks = set(all_data.loc[all_data["_kind_v202"] == "match", "week"].astype(str)) - {week}

    # A kiválasztott hét tekinthető a legfrissebbnek ISO hét szerinti vagy adatbeli sorrend alapján.
    try:
        latest_week = sorted(weeks, key=lambda x: tuple(int(v) for v in re.findall(r"\d+", str(x))[-2:]))[-1]
    except Exception:
        latest_week = weeks[-1]
    is_latest = str(week) == str(latest_week)

    if total_n <= 1:
        code, label, icon = "single_session", "Egyszeri edzéselemzés", "🟦"
        desc = "Egyetlen esemény pillanatképe. Trend, heti readiness és meccsreferencia még nem véglegesíthető."
        confidence = "magas"
    elif training_n > 0 and match_n > 0:
        code, label, icon = "full_microcycle", "Teljes mikrociklus", "🟢"
        desc = f"{training_n} edzés és {match_n} meccs alapján teljes heti elemzés készül."
        confidence = "magas"
    elif training_n > 0 and match_n == 0 and is_latest and bool(other_match_weeks):
        code, label, icon = "week_in_progress", "Folyamatban lévő hét", "🟡"
        desc = f"Eddig {training_n} edzés érkezett, a heti meccs még nincs az adatok között. A heti eredmények ideiglenesek."
        confidence = "magas"
    elif training_n > 1 and match_n == 0:
        code, label, icon = "training_block", "Edzésblokk-elemzés", "🔵"
        desc = f"{training_n} edzés elemzése meccs nélkül. Edzésprofil és részvétel értékelhető, meccsarány nem."
        confidence = "magas" if not has_match_history else "közepes"
    elif match_n > 0 and training_n == 0:
        code, label, icon = "match_only", "Meccselemzés", "🟣"
        desc = f"{match_n} meccsesemény érkezett edzésadat nélkül. A mérkőzésterhelés értékelhető, a mikrociklus nem."
        confidence = "magas"
    else:
        code, label, icon = "limited_data", "Korlátozott GPS-elemzés", "⚪"
        desc = "Az adat elemezhető, de nem alkot teljes heti edzés–meccs struktúrát."
        confidence = "közepes"

    complete = code == "full_microcycle"
    return {
        "code": code, "label": label, "icon": icon, "description": desc,
        "confidence": confidence, "selected_week": week,
        "training_sessions": training_n, "match_sessions": match_n,
        "total_sessions": total_n, "is_complete_week": complete,
        "is_provisional": not complete,
    }


def _fpi_v202_mode_guidance(mode: Dict[str, object]) -> List[str]:
    code = str((mode or {}).get("code", "no_data"))
    guidance = {
        "single_session": [
            "A session KPI-k és játékos-összehasonlítás használható.",
            "A trend, heti terhelésváltozás és readiness csak előzetes jelzés.",
            "Meccsreferencia nem számítható meccsadat nélkül.",
        ],
        "training_block": [
            "Az edzésprofil, intenzitás, volumen és részvétel értékelhető.",
            "A rendszer nem kényszerít meccsreferenciát a számításokra.",
            "A heti readiness meccskészültségi része korlátozott.",
        ],
        "week_in_progress": [
            "Az aktuális heti értékek ideiglenesek, a hét további feltöltéseivel frissülnek.",
            "Az alacsony heti összterhelést a rendszer nem bünteti automatikusan.",
            "A meccs feltöltése után automatikusan teljes mikrociklus módra vált.",
        ],
        "full_microcycle": [
            "A teljes heti trend, readiness, részvétel és meccsreferencia használható.",
        ],
        "match_only": [
            "A meccsterhelés elemezhető, de az edzésfelkészítés nem értékelhető.",
        ],
    }
    return guidance.get(code, ["Az eredményeket a rendelkezésre álló adatmennyiség szerint kell értelmezni."])


def _fpi_v202_render_mode_card(df: pd.DataFrame, selected_week: str) -> Dict[str, object]:
    mode = _fpi_v202_detect_analysis_mode(df, selected_week)
    guide = _fpi_v202_mode_guidance(mode)
    details = " · ".join([
        f"Edzés: {mode.get('training_sessions', 0)}",
        f"Meccs: {mode.get('match_sessions', 0)}",
        f"Biztonság: {mode.get('confidence', 'n.a.')}",
    ])
    bullets = "".join(f"<li>{html.escape(str(x))}</li>" for x in guide)
    st.markdown(
        f'''<div class="fpi-clean-card" style="border-left:8px solid #0f766e;">
        <div style="font-size:1.15rem;font-weight:950;">{mode.get('icon','')} {html.escape(str(mode.get('label','GPS-elemzés')))}</div>
        <div style="margin-top:5px;color:#334155;"><b>{html.escape(details)}</b></div>
        <div style="margin-top:8px;">{html.escape(str(mode.get('description','')))}</div>
        <ul style="margin:8px 0 0 18px;">{bullets}</ul>
        </div>''', unsafe_allow_html=True,
    )
    return mode

def _fpi_v200_universal_postprocess(
    df: pd.DataFrame,
    provider: Optional[str] = None,
    file_name: str = "",
) -> Tuple[pd.DataFrame, Dict[str, object]]:
    """Minden provider és Smart Mapper közös végső normalizáló/validáló rétege."""
    if df is None or df.empty:
        report = _fpi_v200_quality_report(
            pd.DataFrame(),
            provider or "Ismeretlen / Smart Mapper",
            ["Üres input"],
        )
        return pd.DataFrame(), report

    recovery_log: List[str] = []
    detected_provider, provider_scores = _fpi_v200_detect_provider_from_frame(
        df,
        file_name=file_name,
        current_provider=provider,
    )

    data = df.copy()
    data = _fpi_v200_normalize_session_type(data, recovery_log)
    data = _fpi_v200_normalize_dates(data, recovery_log)
    data = _fpi_v200_recover_metrics(data, recovery_log)
    data = _fpi_enforce_distance_hierarchy(data, recovery_log)
    data = _fpi_v200_filter_non_player_rows(data, recovery_log)

    if "player_name" in data.columns:
        data["player_name"] = data["player_name"].astype(str).str.strip()

    # Értelmezhetetlen dátumú sorok nem kerülhetnek heti elemzésbe.
    if "start_time" in data.columns:
        bad_dates = data["start_time"].isna()
        if bad_dates.any():
            recovery_log.append(f"{int(bad_dates.sum())} értelmezhetetlen dátumú sor kihagyva")
            data = data.loc[~bad_dates].copy()

    # Csak a standard session címkék maradjanak.
    if "session_type" in data.columns:
        kind = data["session_type"].apply(_fpi_v200_session_kind)
        data["session_type"] = kind.map({
            "training": "Edzés",
            "match": "Meccs",
            "other": "Egyéb",
        })

    data = _fpi_v201_add_training_attendance(data, recovery_log)

    report = _fpi_v200_quality_report(
        data,
        detected_provider,
        recovery_log,
        provider_scores=provider_scores,
    )
    data.attrs["fpi_import_diagnostics"] = report
    data.attrs["fpi_provider"] = detected_provider
    data.attrs["fpi_import_quality"] = report["quality_score"]
    return data.reset_index(drop=True), report


def _fpi_v200_report_row(
    file_name: str,
    report: Dict[str, object],
    status: str = "OK",
) -> Dict[str, object]:
    warnings = report.get("warnings", []) or []
    recoveries = report.get("recoveries", []) or []
    note_parts = [
        f"Minőség: {report.get('quality_score', 0)}% ({report.get('quality_label', '')})",
        f"Játékosok: {report.get('players', 0)}",
        f"Hetek: {report.get('weeks', 0)}",
        f"Edzés: {report.get('training_rows', 0)}",
        f"Meccs: {report.get('match_rows', 0)}",
    ]
    if recoveries:
        note_parts.append("Öngyógyítás: " + "; ".join(recoveries[:3]))
    if warnings:
        note_parts.append("Figyelem: " + "; ".join(warnings[:2]))

    return {
        "Fájl": file_name,
        "Státusz": status,
        "Rendszer": report.get("provider", "Ismeretlen / Smart Mapper"),
        "Sorok": report.get("rows", 0),
        "Import minőség": f"{report.get('quality_score', 0)}%",
        "Játékosok": report.get("players", 0),
        "Hetek": report.get("weeks", 0),
        "Edzés sor": report.get("training_rows", 0),
        "Meccs sor": report.get("match_rows", 0),
        "Megjegyzés": " | ".join(note_parts),
    }

# -----------------------------------------------------------------------------
# V4.5 - Smart Mapper fallback helpers
# -----------------------------------------------------------------------------
def _norm_mapping_text(text: object) -> str:
    import unicodedata
    text = str(text or "").lower().replace("\u00ad", " ")
    text = unicodedata.normalize("NFKD", text)
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()

def smart_column_score(source_col: object, std_col: str, aliases: List[str]) -> int:
    src = _norm_mapping_text(source_col)
    if not src:
        return 0
    alias_norms = [_norm_mapping_text(a) for a in aliases] + [_norm_mapping_text(std_col)]
    best = 0
    for a in alias_norms:
        if not a:
            continue
        if src == a:
            best = max(best, 100)
        elif src.replace(" ", "") == a.replace(" ", ""):
            best = max(best, 96)
        elif a in src or src in a:
            best = max(best, 86 if len(a) >= 4 else 70)
        else:
            src_tokens = set(src.split())
            a_tokens = set(a.split())
            if src_tokens and a_tokens:
                overlap = len(src_tokens & a_tokens) / max(1, len(a_tokens))
                best = max(best, int(overlap * 78))
    hints = {
        "player_name": ["player", "jatekos", "nev", "name", "athlete"],
        "session_type": ["type", "tipus", "match", "game", "training", "edzes", "meccs"],
        "start_time": ["date", "datum", "start", "day", "ido"],
        "duration": ["duration", "minutes", "perc", "time"],
        "match_minutes": ["minutes played", "match minutes", "jatekp", "jatekperc", "meccsperc", "playing time"],
        "total_distance": ["distance", "tav", "dist", "total"],
        "distance_per_min": ["min", "minute", "rel", "per"],
        "max_speed": ["max", "speed", "velocity", "vmax"],
        "sprints": ["sprint"],
        "training_load": ["load", "terheles", "workload"],
        "speed_zone_4": ["zone 4", "z4", "19", "24", "hsr"],
        "speed_zone_5": ["zone 5", "z5", "25", "sprint distance"],
        "acc_high": ["acc", "acceleration", "gyorsulas", "3"],
        "dec_high": ["dec", "deceleration", "lassitas", "-3"],
        "high_efforts": ["high effort", "effort"],
    }
    if std_col in hints:
        hit = sum(1 for h in hints[std_col] if h in src)
        if hit:
            best = max(best, min(94, 58 + hit * 14))
    return int(best)

def suggest_mapping(raw_df: pd.DataFrame) -> Dict[str, Optional[str]]:
    suggestions: Dict[str, Optional[str]] = {}
    used = set()
    for std_col, aliases in STANDARD_COLUMNS.items():
        scored = []
        for c in raw_df.columns:
            if c in used:
                continue
            scored.append((smart_column_score(c, std_col, aliases), c))
        scored.sort(reverse=True, key=lambda x: x[0])
        if scored and scored[0][0] >= 58:
            suggestions[std_col] = scored[0][1]
            used.add(scored[0][1])
        else:
            suggestions[std_col] = None
    return suggestions

def mapping_quality_df(raw_df: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> pd.DataFrame:
    rows = []
    for std_col, aliases in STANDARD_COLUMNS.items():
        src = mapping.get(std_col)
        score = smart_column_score(src, std_col, aliases) if src else 0
        rows.append({
            "Standard mező": std_col,
            "Felismert forrásoszlop": src or "",
            "Bizonyosság": score,
            "Kötelező": "igen" if std_col in CORE_REQUIRED else "nem",
            "Magyar név": METRIC_LABELS.get(std_col, std_col),
        })
    return pd.DataFrame(rows)

def export_mapping_profile(mapping: Dict[str, Optional[str]], profile_name: str = "GPS mapping profil") -> bytes:
    payload = {
        "profile_name": profile_name,
        "created_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "mapping": mapping,
    }
    return json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")

def load_mapping_profile(uploaded_file) -> Dict[str, Optional[str]]:
    try:
        payload = json.loads(uploaded_file.read().decode("utf-8"))
        return payload.get("mapping", {})
    except Exception:
        return {}

@dataclass
class Insight:
    title: str
    severity: str
    observation: str
    impact: str
    recommendation: str
    scope: str = "Csapat"

    def as_dict(self) -> Dict[str, str]:
        return {
            "Súlyosság": self.severity,
            "Terület": self.scope,
            "Megállapítás": self.title,
            "Mit látunk?": self.observation,
            "Miért fontos?": self.impact,
            "Javaslat": self.recommendation,
        }


# -----------------------------------------------------------------------------
# Segédfüggvények
# -----------------------------------------------------------------------------
def clean_col_name(col: object) -> str:
    if col is None:
        return ""
    return str(col).replace("\u00ad", "").strip()


def find_column(df: pd.DataFrame, aliases: List[str]) -> Optional[str]:
    cleaned = {clean_col_name(c).lower(): c for c in df.columns}
    for alias in aliases:
        key = clean_col_name(alias).lower()
        if key in cleaned:
            return cleaned[key]

    # óvatos fuzzy fallback
    for alias in aliases:
        a = clean_col_name(alias).lower()
        for c in df.columns:
            cc = clean_col_name(c).lower()
            if a and (a in cc or cc in a):
                return c
    return None


def to_numeric(series: pd.Series) -> pd.Series:
    if series.dtype == object:
        return pd.to_numeric(series.astype(str).str.replace(",", ".", regex=False), errors="coerce")
    return pd.to_numeric(series, errors="coerce")


def duration_to_minutes(x) -> float:
    if pd.isna(x):
        return np.nan
    if isinstance(x, pd.Timedelta):
        return x.total_seconds() / 60
    if hasattr(x, "hour") and hasattr(x, "minute") and hasattr(x, "second"):
        return x.hour * 60 + x.minute + x.second / 60
    if isinstance(x, str):
        try:
            td = pd.to_timedelta(x)
            return td.total_seconds() / 60
        except Exception:
            return np.nan
    if isinstance(x, (int, float, np.number)):
        # Excel időtört: 0.5 = 12 óra
        if float(x) < 2:
            return float(x) * 24 * 60
        return float(x)
    return np.nan


def normalize_session_type(x: object) -> str:
    text = str(x).strip().lower()
    if "meccs" in text or "match" in text or "game" in text or "mérk" in text:
        return "Meccs"
    if "edzés" in text or "training" in text or "train" in text:
        return "Edzés"
    return str(x).strip() if str(x).strip() else "Ismeretlen"



def _plausible_datetime(dt: object) -> Optional[pd.Timestamp]:
    """Csak életszerű sportadat-dátumot enged át. Mezszám/ID ne lehessen év."""
    try:
        ts = pd.to_datetime(dt, errors="coerce", dayfirst=True)
        if pd.isna(ts):
            return None
        if 2015 <= int(ts.year) <= 2035:
            return ts
    except Exception:
        return None
    return None


def extract_date_from_text(text: object) -> Optional[pd.Timestamp]:
    """Dátum kinyerése szövegből, de csak valódi dátummintából.

    Fontos: a puszta számokat (pl. mezszám: 49, 9946) nem értelmezzük dátumként.
    Ez akadályozza meg a 9946-W01 típusú hibás hetek képződését.
    """
    s = str(text or "").strip()
    if not s or s.lower() in ["nan", "none", "nat"]:
        return None

    # Puszta szám nem dátum, kivéve Excel serial tartomány.
    if re.fullmatch(r"\d+(\.\d+)?", s):
        try:
            val = float(s)
            if 25000 < val < 90000:
                return _plausible_datetime(pd.to_datetime(val, unit="D", origin="1899-12-30", errors="coerce"))
        except Exception:
            pass
        return None

    patterns = [
        (r"(20\d{2})[-._/ ](\d{1,2})[-._/ ](\d{1,2})", "ymd"),
        (r"(\d{1,2})[-._/ ](\d{1,2})[-._/ ](20\d{2})", "dmy"),
    ]
    for pat, mode in patterns:
        m = re.search(pat, s)
        if m:
            try:
                if mode == "ymd":
                    return _plausible_datetime(f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}")
                return _plausible_datetime(f"{m.group(3)}-{int(m.group(2)):02d}-{int(m.group(1)):02d}")
            except Exception:
                pass

    # 02.01. jellegű lapnév / split. Csak akkor, ha tényleg dátumszerű pontozás van benne.
    m = re.search(r"(?<!\d)(\d{1,2})\.(\d{1,2})\.(?!\d)", s)
    if m:
        year = datetime.now().year
        return _plausible_datetime(f"{year}-{int(m.group(2)):02d}-{int(m.group(1)):02d}")

    # Általános parser csak akkor, ha van benne dátumelválasztó vagy hónap/év jelleg.
    if not re.search(r"[-./:]|20\d{2}", s):
        return None
    return _plausible_datetime(pd.to_datetime(s, errors="coerce", dayfirst=True))


def parse_datetime_series(series: pd.Series, fallback_source: Optional[pd.Series] = None, sheet_name: str = "") -> pd.Series:
    """Robusztus, de védett dátumfelismerés.

    Sorrend:
    1) Ha az oszlop eleve dátum/datetime, azt használja.
    2) Szöveges dátumokat parse-ol.
    3) Csak sikertelen esetben néz Split/lapnév fallbacket.
    4) 2015-2035 közötti dátumokat fogad el.
    """
    n = len(series) if series is not None else (len(fallback_source) if fallback_source is not None else 0)
    if series is None:
        base = pd.Series([pd.NaT] * n)
    else:
        # Excel/pandas datetime oszlopnál ez a legfontosabb út: ne fusson rá text-rescue.
        base = pd.to_datetime(series, errors="coerce", dayfirst=True)
        base = base.apply(lambda x: _plausible_datetime(x) if pd.notna(x) else pd.NaT)

        success_rate = float(base.notna().mean()) if len(base) else 0.0
        if success_rate < 0.60:
            text_parsed = series.apply(extract_date_from_text)
            text_parsed = pd.to_datetime(text_parsed, errors="coerce")
            if len(text_parsed) and text_parsed.notna().mean() > success_rate:
                base = base.fillna(text_parsed)

    if fallback_source is not None and (len(base) == 0 or base.notna().mean() < 0.60):
        fallback = fallback_source.apply(extract_date_from_text)
        fallback = pd.to_datetime(fallback, errors="coerce")
        base = base.fillna(fallback)

    if len(base) and base.notna().mean() < 0.60:
        sheet_dt = extract_date_from_text(sheet_name)
        if sheet_dt is not None and pd.notna(sheet_dt):
            base = base.fillna(sheet_dt)

    return pd.to_datetime(base, errors="coerce")


def make_iso_week_series(dt_series: pd.Series) -> pd.Series:
    """Egységes ISO hét címke: 2025-W29.

    V6.2 WEEK RESCUE:
    - csak a dátumrészt használja, az időpontot figyelmen kívül hagyja;
    - ha egy rövid, összefüggő dátumtartományból irreálisan sok hét keletkezne,
      akkor a teljes blokkot a kezdődátum ISO hetére menti.
    Ez védi az appot attól, hogy egymás utáni napokat külön heteknek vegyen,
    ha a dátumcellában időpont vagy extra szöveg is szerepel.
    """
    dts = pd.to_datetime(dt_series, errors="coerce")
    date_only = dts.dt.normalize() if hasattr(dts, "dt") else pd.to_datetime(dts, errors="coerce")
    weeks = date_only.apply(lambda x: f"{int(x.isocalendar().year)}-W{int(x.isocalendar().week):02d}" if pd.notna(x) else np.nan)

    valid = date_only.dropna()
    if len(valid) >= 2:
        span_days = int((valid.max() - valid.min()).days)
        unique_weeks = weeks.dropna().nunique()
        if span_days <= 10 and unique_weeks > 3:
            anchor = valid.min()
            rescue_week = f"{int(anchor.isocalendar().year)}-W{int(anchor.isocalendar().week):02d}"
            weeks = weeks.where(date_only.isna(), rescue_week)
            st.session_state["week_rescue_applied"] = {
                "reason": "short_date_span_many_weeks",
                "span_days": span_days,
                "original_unique_weeks": int(unique_weeks),
                "rescued_week": rescue_week,
                "date_min": str(valid.min()),
                "date_max": str(valid.max()),
            }
        else:
            st.session_state["week_rescue_applied"] = {
                "reason": "not_needed",
                "span_days": span_days,
                "unique_weeks": int(unique_weeks),
                "date_min": str(valid.min()),
                "date_max": str(valid.max()),
            }
    return weeks


def sheet_is_likely_helper(sheet_name: str, raw_df: Optional[pd.DataFrame] = None) -> bool:
    """Segédlapok kizárása az összesített adatlapból."""
    name = _norm_mapping_text(sheet_name)
    helper_tokens = [
        "dashboard", "riport", "report", "summary", "osszefoglalo", "összefoglaló",
        "benchmark", "benchmarks", "mapping", "mapper", "settings", "beallitas",
        "útmutató", "utmutato", "guide", "help", "readme", "sablon", "template",
        "pivot", "chart", "diagram", "grafikon", "calc", "szamitas", "reference",
        "lista", "players", "jatekoslista", "metadata"
    ]
    if any(tok in name for tok in helper_tokens):
        return True
    if raw_df is None or raw_df.empty:
        return True
    sample = " ".join([str(x).lower() for x in raw_df.head(8).fillna("").astype(str).values.ravel()[:200]])
    data_hints = ["name", "player", "játékos", "jatekos", "total distance", "teljes táv", "duration", "split", "date", "dátum", "datum"]
    return sum(1 for h in data_hints if h in sample) < 2

def detect_header_row(raw_df: pd.DataFrame) -> Optional[int]:
    """Általános fejlécfelismerés GPS/Excel exportokhoz.

    Nem fix sorra épít. Az első 50 sort pontozza magyar és angol GPS kulcsszavak alapján.
    Így működik akkor is, ha a fejléc az első sorban van (MegyeI.xlsx Data lap), és akkor is,
    ha néhány üres/logó/meta sor előzi meg.
    """
    if raw_df is None or raw_df.empty:
        return None

    header_keywords = {
        "player": ["jatekos", "játékos", "player", "athlete", "name", "nev", "név"],
        "date": ["kezdesi ido", "kezdési idő", "start time", "session date", "date", "datum", "dátum", "split"],
        "type": ["tipus", "típus", "session type", "type", "training", "match", "edzes", "edzés", "meccs"],
        "duration": ["idotartam", "időtartam", "duration", "minutes", "time"],
        "distance": ["teljes tav", "teljes táv", "total distance", "distance", "dist", "tav perc", "táv perc"],
        "speed": ["maximalis sebesseg", "maximális sebesség", "max speed", "top speed", "velocity"],
        "load": ["edzesi terheles", "edzési terhelés", "training load", "player load", "workload", "load"],
        "intensity": ["sprintek", "sprints", "gyorsulas", "gyorsulás", "lassitas", "lassítás", "high efforts"],
    }

    max_scan = min(50, len(raw_df))
    best_i: Optional[int] = None
    best_score = -999

    for i in range(max_scan):
        row = raw_df.iloc[i].tolist()
        cells = [str(v).strip() for v in row if str(v).strip().lower() not in ["nan", "none", ""]]
        if not cells:
            continue
        joined_raw = " | ".join(cells)
        joined_norm = _norm_mapping_text(joined_raw)

        score = 0
        matched_groups = 0
        for _, kws in header_keywords.items():
            if any(_norm_mapping_text(k) in joined_norm for k in kws):
                score += 10
                matched_groups += 1

        # A fejléc többnyire sok szöveges cellát tartalmaz, kevés tiszta számot.
        numeric_like = sum(1 for c in cells if re.fullmatch(r"\d+(\.\d+)?", c))
        text_like = len(cells) - numeric_like
        if text_like >= 4:
            score += 8
        if numeric_like > max(3, text_like):
            score -= 18

        # Következő sorban legyen valamennyi adat, különben lehet címblokk.
        if i + 1 < len(raw_df):
            next_vals = [str(v).strip() for v in raw_df.iloc[i + 1].tolist() if str(v).strip().lower() not in ["nan", "none", ""]]
            if len(next_vals) >= 3:
                score += 4

        if matched_groups >= 2 and score > best_score:
            best_score = score
            best_i = i

    return best_i if best_score >= 24 else None


def _fpi_enrich_catapult_vector_v159(df: pd.DataFrame, raw_df: pd.DataFrame, sheet_name: str = "") -> pd.DataFrame:
    """Catapult Vector/OpenField export felismerése és előkészítése.

    A Catapult CSV-k gyakran 8-10 metaadatsor után tartalmazzák a valódi fejlécet.
    A normál fejlécfelismerő ezt már megtalálja; ez a kiegészítés a Catapult-specifikus
    dátumot, eseménytípust és mezőneveket teszi automatikusan használhatóvá.
    Más GPS-formátumot nem módosít.
    """
    if df is None or df.empty:
        return df

    cols = {clean_col_name(c) for c in df.columns}
    is_catapult = (
        "Player Name" in cols
        and "Period Name" in cols
        and ("Total Player Load" in cols or "Player Load Per Minute" in cols)
        and ("Total Distance" in cols or "Meterage Per Minute" in cols)
    )
    if not is_catapult:
        return df

    df = df.copy()
    df.attrs["fpi_source_system"] = "Catapult Vector / OpenField"

    # Metaadatok kiolvasása a fejléc előtti sorokból.
    metadata = {}
    try:
        scan = raw_df.head(20)
        for _, row in scan.iterrows():
            vals = [x for x in row.tolist() if pd.notna(x)]
            if len(vals) >= 2:
                key = str(vals[0]).strip().strip('"').rstrip(":").strip().lower()
                metadata[key] = vals[1]
    except Exception:
        metadata = {}

    # A soronkénti Unix idő a legpontosabb. Catapultnál másodperc alapú epoch.
    catapult_start = None
    if "Unix Start Time" in df.columns:
        unix_s = pd.to_numeric(df["Unix Start Time"], errors="coerce")
        catapult_start = pd.to_datetime(unix_s, unit="s", errors="coerce")
        plausible = catapult_start.dt.year.between(2015, 2035) if len(catapult_start) else pd.Series(dtype=bool)
        if len(catapult_start) and plausible.mean() >= 0.60:
            df["Kezdési idő"] = catapult_start

    # Ha nincs használható Unix idő, a CSV meta Date + Start Time mezőit használjuk.
    if "Kezdési idő" not in df.columns:
        date_val = metadata.get("date")
        time_val = metadata.get("start time")
        combined = " ".join(str(x).strip() for x in [date_val, time_val] if x is not None and str(x).strip())
        dt = pd.to_datetime(combined, errors="coerce", dayfirst=True) if combined else pd.NaT
        if pd.notna(dt):
            df["Kezdési idő"] = dt

    # Catapult esemény/szakasz mezők átvezetése az app standard mezőire.
    if "Period Name" in df.columns:
        period = df["Period Name"].astype(str).str.strip()
        if "Szakasz neve" not in df.columns:
            df["Szakasz neve"] = period
        if "Típus" not in df.columns:
            context = (period + " " + str(sheet_name)).str.lower()
            is_match = context.str.contains(r"match|game|meccs|mérk", regex=True, na=False)
            df["Típus"] = np.where(is_match, "Meccs", "Edzés")

    # Egyértelmű magyar alias a játékosnévhez; a többi Catapult-fejlécet a
    # STANDARD_COLUMNS aliaslistája kezeli.
    if "Játékos neve" not in df.columns and "Player Name" in df.columns:
        df["Játékos neve"] = df["Player Name"]

    return df


def normalize_uploaded_sheet(raw_df: pd.DataFrame, sheet_name: str = "") -> pd.DataFrame:
    """Egy munkalap megtisztítása az app számára.
    Kezeli:
    - üres első sor
    - 2. sorban lévő fejléc
    - több meccslap
    - hiányzó Típus / Kezdési idő / Szakasz neve mező
    """
    if raw_df is None or raw_df.empty:
        return pd.DataFrame()

    df = raw_df.copy()

    # V164: a provider-specifikus importmotorok már valódi fejlécű,
    # standardizált DataFrame-et adnak vissza. Ezeket tilos újra
    # header=None táblaként értelmezni.
    standardized_provider_cols = {"Player Name", "Session Type", "Start Time"}
    if standardized_provider_cols.issubset(set(map(str, df.columns))):
        df.columns = [
            clean_col_name(c) if clean_col_name(c) else f"col_{i+1}"
            for i, c in enumerate(df.columns)
        ]
        df = df.dropna(how="all").reset_index(drop=True)
        for c in df.columns:
            if df[c].dtype == object:
                df[c] = df[c].apply(
                    lambda x: str(x).strip() if pd.notna(x) else x
                )
        return df

    # 1) Ha header=None-ból jön, keressük meg a valódi fejlécsort.
    header_row = detect_header_row(df)
    if header_row is not None:
        new_cols = []
        seen_cols: Dict[str, int] = {}
        for j, x in enumerate(df.iloc[header_row].tolist()):
            base_name = clean_col_name(x)
            base_name = base_name if base_name and base_name.lower() not in ["nan", "none"] else f"col_{j+1}"
            seen_cols[base_name] = seen_cols.get(base_name, 0) + 1
            name = base_name if seen_cols[base_name] == 1 else f"{base_name}__{seen_cols[base_name]}"
            new_cols.append(name)
        df = df.iloc[header_row + 1:].copy()
        df.columns = new_cols
    else:
        # 2) Ha mégis header=0 jelleggel jönne.
        df.columns = [clean_col_name(c) if clean_col_name(c) else f"col_{i+1}" for i, c in enumerate(df.columns)]

    # Catapult Vector/OpenField speciális metaadat- és dátumkezelés.
    df = _fpi_enrich_catapult_vector_v159(df, raw_df, sheet_name)

    # Üres és Unnamed oszlopok törlése.
    df = df.dropna(how="all")
    keep_cols = []
    for c in df.columns:
        cs = str(c).strip()
        if not cs:
            continue
        if cs.startswith("Unnamed"):
            continue
        if cs.lower() in ["nan", "none"]:
            continue
        keep_cols.append(c)
    df = df[keep_cols] if keep_cols else df

    # Cellák whitespace tisztítása szöveges oszlopokban.
    for c in df.columns:
        if df[c].dtype == object:
            df[c] = df[c].apply(lambda x: str(x).strip() if pd.notna(x) else x)

    # Tipikus GPS-export: Name nevű oszlop legyen biztosan felismerhető.
    # Nem nevezzük át player_name-re itt, csak adunk magyar alias oszlopot, ha kell.
    if "Name" in df.columns and "Játékos neve" not in df.columns:
        df["Játékos neve"] = df["Name"]

    # Ha nincs típus, ebből a workbookból ez meccsadat.
    if not any(c in df.columns for c in ["Típus", "Type", "Session Type", "Edzés/Meccs"]):
        df["Típus"] = "Meccs"

    if not any(c in df.columns for c in ["Szakasz neve", "Session Name", "Session"]):
        df["Szakasz neve"] = sheet_name or "GPS mérkőzés"

    # Kezdési idő kinyerése Splitből vagy lapnévből, ha nincs explicit dátum.
    has_start = any(c in df.columns for c in ["Kezdési idő", "Start Time", "Start", "Date", "Dátum", "Session Date"])
    if not has_start:
        dates = []
        split_col = "Split" if "Split" in df.columns else None
        for _, row in df.iterrows():
            dt = extract_date_from_text(row.get(split_col, "")) if split_col else None
            if dt is None or pd.isna(dt):
                dt = extract_date_from_text(sheet_name)
            if dt is None or pd.isna(dt):
                dt = pd.to_datetime("2026-01-01")
            dates.append(dt.strftime("%Y-%m-%d 17:00"))
        df["Kezdési idő"] = dates

    return df


def prepare_uploaded_sheets(sheets: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    """V206: munkalapok és többfájlos csomag normalizálása.

    Elsődleges elemzési forrás:
    - Teljes feltöltött csomag

    Az egyedi fájlok/lapok csak diagnosztikai szűrésre maradnak elérhetők.
    A teljes csomag minden releváns importált fájlt összefűz.
    """
    prepared: Dict[str, pd.DataFrame] = {}
    relevant_frames: List[pd.DataFrame] = []
    data_like_names = []

    def is_data_sheet_name(n: str) -> bool:
        nn = _norm_mapping_text(n)
        return nn in ["data", "adat", "adatok", "gps data", "gps", "raw data", "nyers adat", "nyers adatok"]

    ordered_items = sorted(sheets.items(), key=lambda kv: (0 if is_data_sheet_name(kv[0]) else 1, kv[0]))
    for name, raw in ordered_items:
        clean = normalize_uploaded_sheet(raw, name)
        if clean is None or clean.empty:
            continue
        prepared[name] = clean
        if not sheet_is_likely_helper(name, raw):
            relevant_frames.append(clean)
            data_like_names.append(name)

    final: Dict[str, pd.DataFrame] = {}

    # V206: a teljes releváns többfájlos csomag mindig az első elem.
    frames = [prepared[n] for n in data_like_names if n in prepared]
    if not frames:
        frames = list(prepared.values())

    if frames:
        full_package = pd.concat(frames, ignore_index=True, sort=False)
        final["Teljes feltöltött csomag"] = full_package
        # Régi név kompatibilitása.
        final["Összes releváns adatlap"] = full_package

    # Egyedi források diagnosztikai/ellenőrzési célra.
    for name, df_sheet in prepared.items():
        if name not in final:
            final[name] = df_sheet

    return final if final else sheets

@st.cache_data(show_spinner=False)
def read_excel_all(file) -> Dict[str, pd.DataFrame]:
    # header=None kell, mert sok GPS exportnál az első sor üres,
    # a valódi fejléc a 2. sorban van.
    return pd.read_excel(file, sheet_name=None, header=None)


# =========================================================
# V136 - ZIP / multi-session GPS import
# =========================================================
def _fpi_read_csv_bytes_v136(data: bytes, name: str = "") -> pd.DataFrame:
    """CSV beolvasás több kódolással, Catapult meta-fejléc támogatással.

    A Catapult Vector/OpenField CSV elején rövid, kétoszlopos metaadatblokk áll,
    majd egy 1500+ oszlopos valódi fejléc következik. Ezt a pandas hagyományos
    header=None olvasása ragged CSV-ként elutasítja, ezért előbb megkeressük a
    Player Name / Period Name fejlécsort, és csak onnantól olvasunk.
    """
    last_err = None
    encodings = ["utf-8-sig", "utf-8", "latin2", "cp1250", "iso-8859-2"]
    for enc in encodings:
        try:
            text = data.decode(enc)
        except Exception as e:
            last_err = e
            continue

        lines = text.splitlines()
        catapult_header = None
        for i, line in enumerate(lines[:80]):
            probe = line.lstrip("\ufeff").strip()
            if "Player Name" in probe and "Period Name" in probe and "Total Distance" in probe:
                catapult_header = i
                break

        try:
            if catapult_header is not None:
                trimmed = "\n".join(lines[catapult_header:]).encode(enc, errors="replace")
                df = pd.read_csv(io.BytesIO(trimmed), sep=",", engine="python", encoding=enc, header=None)
                df.attrs["fpi_catapult_header_row"] = int(catapult_header)
                df.attrs["fpi_source_system"] = "Catapult Vector / OpenField"
                return df
            return pd.read_csv(io.BytesIO(data), sep=None, engine="python", encoding=enc, header=None)
        except Exception as e:
            last_err = e

    raise ValueError(f"CSV beolvasási hiba ({name}): {last_err}")


def _fpi_read_gps_upload_to_sheets_v136(uploaded_file) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, str, bool]:
    """Egy Excel/CSV vagy ZIP-ben lévő több GPS fájl beolvasása egységes sheet-dict formába.

    A ZIP mód lényege:
    - minden belső Excel/CSV fájlt beolvasunk,
    - a sheet neve tartalmazza a fájlnevet is,
    - a meglévő normalize_uploaded_sheet + Smart Mapper ugyanúgy fut rajtuk,
    - végül a prepare_uploaded_sheets összefűzi az összes releváns adatlapot.
    """
    if uploaded_file is None:
        return {}, pd.DataFrame(), "", False

    try:
        data = uploaded_file.getvalue()
    except Exception:
        data = uploaded_file.read()

    upload_name = getattr(uploaded_file, "name", "gps_upload")
    signature = hashlib.md5(data or b"").hexdigest()
    ext = Path(str(upload_name)).suffix.lower()

    sheets: Dict[str, pd.DataFrame] = {}
    report_rows: List[Dict[str, object]] = []

    def _add_report(name: str, status: str, rows: int = 0, sheets_n: int = 0, note: str = "") -> None:
        report_rows.append({
            "Fájl": name,
            "Státusz": status,
            "Sor": int(rows or 0),
            "Lap": int(sheets_n or 0),
            "Megjegyzés": note,
        })

    def _read_single_file(data_bytes: bytes, name: str) -> None:
        low = str(name).lower()
        try:
            if low.endswith((".xlsx", ".xls", ".xlsm")):
                xls_sheets = pd.read_excel(io.BytesIO(data_bytes), sheet_name=None, header=None)
                local_count = 0
                local_rows = 0
                for sheet_name, df_sheet in (xls_sheets or {}).items():
                    if df_sheet is None or df_sheet.empty:
                        continue
                    key = f"{Path(name).stem} / {sheet_name}"
                    # Ütközés esetén ne írjuk felül.
                    if key in sheets:
                        key = f"{Path(name).stem} / {sheet_name} / {len(sheets)+1}"
                    sheets[key] = df_sheet
                    local_count += 1
                    local_rows += len(df_sheet)
                _add_report(name, "OK", local_rows, local_count, "Excel beolvasva")
            elif low.endswith(".csv"):
                df_csv = _fpi_read_csv_bytes_v136(data_bytes, name)
                key = Path(name).stem
                if key in sheets:
                    key = f"{Path(name).stem} / {len(sheets)+1}"
                sheets[key] = df_csv
                catapult_hint = "Catapult Vector/OpenField CSV beolvasva" if any(
                    str(x).strip().strip('"') == "Player Name" for x in df_csv.head(15).fillna("").astype(str).values.ravel()
                ) else "CSV beolvasva"
                _add_report(name, "OK", len(df_csv), 1, catapult_hint)
            else:
                _add_report(name, "Kihagyva", 0, 0, "Nem támogatott fájltípus")
        except Exception as e:
            _add_report(name, "Hiba", 0, 0, str(e)[:220])

    is_zip = ext == ".zip"
    if is_zip:
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as zf:
                names = [n for n in zf.namelist() if not n.endswith("/") and not Path(n).name.startswith(("~$", "."))]
                supported = [n for n in names if n.lower().endswith((".xlsx", ".xls", ".xlsm", ".csv"))]
                if not supported:
                    _add_report(upload_name, "Hiba", 0, 0, "A ZIP nem tartalmaz támogatott Excel/CSV fájlt")
                for n in supported:
                    _read_single_file(zf.read(n), n)
        except Exception as e:
            _add_report(upload_name, "Hiba", 0, 0, f"ZIP beolvasási hiba: {e}")
    else:
        _read_single_file(data, upload_name)

    report_df = pd.DataFrame(report_rows)
    return sheets, report_df, signature, is_zip


def _fpi_render_gps_import_report_v136(report_df: pd.DataFrame, is_zip: bool) -> None:
    """Import ellenőrző blokk ZIP vagy egyfájlos GPS importhoz."""
    if report_df is None or report_df.empty:
        return
    ok = int((report_df["Státusz"] == "OK").sum()) if "Státusz" in report_df.columns else 0
    bad = int((report_df["Státusz"] == "Hiba").sum()) if "Státusz" in report_df.columns else 0
    skipped = int((report_df["Státusz"] == "Kihagyva").sum()) if "Státusz" in report_df.columns else 0
    total_rows = int(pd.to_numeric(report_df.get("Sor", 0), errors="coerce").fillna(0).sum()) if "Sor" in report_df.columns else 0

    with st.expander("📦 Feltöltött GPS fájlok ellenőrzése", expanded=bool(is_zip)):
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("OK fájl", ok)
        c2.metric("Hibás fájl", bad)
        c3.metric("Kihagyott", skipped)
        c4.metric("Nyers sor", total_rows)
        st.caption("ZIP mód esetén minden belső Excel/CSV fájlra ugyanaz a normalizálás és Smart Mapper logika fut. Hibás fájl nem állítja meg az egész importot.")
        st.dataframe(report_df, use_container_width=True, hide_index=True)


def standardize_dataframe(raw: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, Optional[str]], List[str]]:
    df = raw.copy()
    df.columns = [clean_col_name(c) for c in df.columns]

    mapping: Dict[str, Optional[str]] = {}
    out = pd.DataFrame()

    for std_col, aliases in STANDARD_COLUMNS.items():
        source = find_column(df, aliases)
        mapping[std_col] = source
        if source is not None:
            out[std_col] = df[source]

    # GPS export fallback: ha van Name oszlop, az legyen játékosnév.
    if "player_name" not in out.columns and "Name" in df.columns:
        out["player_name"] = df["Name"]
        mapping["player_name"] = "Name"
    if "session_type" not in out.columns and "Típus" in df.columns:
        out["session_type"] = df["Típus"]
        mapping["session_type"] = "Típus"
    if "start_time" not in out.columns and "Kezdési idő" in df.columns:
        out["start_time"] = df["Kezdési idő"]
        mapping["start_time"] = "Kezdési idő"

    missing_core = [c for c in CORE_REQUIRED if c not in out.columns]
    if missing_core:
        return out, mapping, missing_core

    out["player_name"] = out["player_name"].astype(str).str.strip()
    out["session_type"] = out["session_type"].apply(normalize_session_type)
    fallback_source = df["Split"] if "Split" in df.columns else None
    out["start_time"] = parse_datetime_series(out["start_time"], fallback_source=fallback_source)
    out["session_date"] = out["start_time"].dt.date
    out["week"] = make_iso_week_series(out["start_time"])

    if "duration" in out.columns:
        out["duration_min"] = out["duration"].apply(duration_to_minutes)
    else:
        out["duration_min"] = np.nan

    numeric_cols = [
        "total_distance", "distance_per_min", "max_speed", "avg_speed", "sprints", "match_minutes",
        "speed_zone_3", "speed_zone_4", "speed_zone_5", "training_load", "cardio_load",
        "recovery_hours", "muscle_load", "hr_avg", "hr_max", "hrv", "high_efforts", "acc_low", "acc_mid",
        "acc_high", "dec_low", "dec_mid", "dec_high",
    ]
    for col in numeric_cols:
        if col in out.columns:
            out[col] = to_numeric(out[col])

    out = _fpi_mapped_distance_units_to_metres(out, mapping)

    for col in ["speed_zone_3", "speed_zone_4", "speed_zone_5", "acc_low", "acc_mid", "acc_high", "dec_low", "dec_mid", "dec_high"]:
        if col not in out.columns:
            out[col] = 0

    out["hsr_distance"] = out[["speed_zone_4", "speed_zone_5"]].sum(axis=1, min_count=1)
    out["sprint_distance"] = out["speed_zone_5"]
    out["acc_count"] = out[["acc_low", "acc_mid", "acc_high"]].sum(axis=1, min_count=1)
    out["dec_count"] = out[["dec_low", "dec_mid", "dec_high"]].sum(axis=1, min_count=1)

    # V161: ha nincs külön játékperc, a szereplési idő az adott sor időtartamából képződik.
    # Meccsnél ez játékperc/exposure, edzésnél résztvevői idő.
    if "match_minutes" not in out.columns:
        out["match_minutes"] = out["duration_min"]
    else:
        out["match_minutes"] = to_numeric(out["match_minutes"])
        out["match_minutes"] = out["match_minutes"].where(
            out["match_minutes"].notna() & (out["match_minutes"] > 0),
            out["duration_min"],
        )

    # V161: külön High Efforts oszlop hiányában:
    # sprintakciók + magas intenzitású gyorsítások + magas intenzitású lassítások.
    derived_high_efforts = pd.concat(
        [
            to_numeric(out["sprints"]) if "sprints" in out.columns else pd.Series(0.0, index=out.index),
            to_numeric(out["acc_high"]) if "acc_high" in out.columns else pd.Series(0.0, index=out.index),
            to_numeric(out["dec_high"]) if "dec_high" in out.columns else pd.Series(0.0, index=out.index),
        ],
        axis=1,
    ).sum(axis=1, min_count=1)

    if "high_efforts" not in out.columns or out["high_efforts"].isna().all():
        out["high_efforts"] = derived_high_efforts
    else:
        out["high_efforts"] = to_numeric(out["high_efforts"]).where(
            to_numeric(out["high_efforts"]).notna(),
            derived_high_efforts,
        )

    out = normalize_combined_fields(out, mapping)
    out = _fpi_enforce_distance_hierarchy(out)

    if "distance_per_min" not in out.columns or out["distance_per_min"].isna().all():
        if "total_distance" in out.columns:
            out["distance_per_min"] = out["total_distance"] / out["duration_min"]

    out = out.dropna(subset=["start_time"])
    out = out[out["player_name"].str.len() > 0]
    out = out[~out["player_name"].str.lower().str.contains("benchmark|átlag|atlag|összesen|osszesen", na=False)]
    out = finalize_exposure_columns(add_position_group(out))
    out, _v200_report = _fpi_v200_universal_postprocess(
        out,
        provider="Általános / Smart Mapper",
        file_name="Smart Mapper import",
    )

    return out, mapping, []

def apply_mapping_to_raw(raw: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> Tuple[pd.DataFrame, Dict[str, Optional[str]], List[str]]:
    df = raw.copy()
    df.columns = [clean_col_name(c) for c in df.columns]
    out = pd.DataFrame()
    fixed_mapping: Dict[str, Optional[str]] = {}
    for std_col in STANDARD_COLUMNS:
        source = mapping.get(std_col)
        source = clean_col_name(source) if source else None
        fixed_mapping[std_col] = source
        if source and source in df.columns:
            out[std_col] = df[source]
    missing_core = [c for c in CORE_REQUIRED if c not in out.columns]
    if missing_core:
        return out, fixed_mapping, missing_core

    out["player_name"] = out["player_name"].astype(str).str.strip()
    out["session_type"] = out["session_type"].apply(normalize_session_type)
    fallback_source = df["Split"] if "Split" in df.columns else None
    out["start_time"] = parse_datetime_series(out["start_time"], fallback_source=fallback_source)
    out["session_date"] = out["start_time"].dt.date
    out["week"] = make_iso_week_series(out["start_time"])
    if "duration" in out.columns:
        out["duration_min"] = out["duration"].apply(duration_to_minutes)
    else:
        out["duration_min"] = np.nan

    numeric_cols = [
        "total_distance", "distance_per_min", "max_speed", "avg_speed", "sprints", "match_minutes",
        "speed_zone_3", "speed_zone_4", "speed_zone_5", "training_load", "cardio_load",
        "recovery_hours", "muscle_load", "hr_avg", "hr_max", "hrv", "high_efforts", "acc_low", "acc_mid",
        "acc_high", "dec_low", "dec_mid", "dec_high",
    ]
    for col in numeric_cols:
        if col in out.columns:
            out[col] = to_numeric(out[col])

    out = _fpi_mapped_distance_units_to_metres(out, mapping)
    for col in ["speed_zone_3", "speed_zone_4", "speed_zone_5", "acc_low", "acc_mid", "acc_high", "dec_low", "dec_mid", "dec_high"]:
        if col not in out.columns:
            out[col] = 0

    out["hsr_distance"] = out[["speed_zone_4", "speed_zone_5"]].sum(axis=1, min_count=1)
    out["sprint_distance"] = out["speed_zone_5"]
    out["acc_count"] = out[["acc_low", "acc_mid", "acc_high"]].sum(axis=1, min_count=1)
    out["dec_count"] = out[["dec_low", "dec_mid", "dec_high"]].sum(axis=1, min_count=1)

    # V161: ha nincs külön játékperc, a szereplési idő az adott sor időtartamából képződik.
    # Meccsnél ez játékperc/exposure, edzésnél résztvevői idő.
    if "match_minutes" not in out.columns:
        out["match_minutes"] = out["duration_min"]
    else:
        out["match_minutes"] = to_numeric(out["match_minutes"])
        out["match_minutes"] = out["match_minutes"].where(
            out["match_minutes"].notna() & (out["match_minutes"] > 0),
            out["duration_min"],
        )

    # V161: külön High Efforts oszlop hiányában:
    # sprintakciók + magas intenzitású gyorsítások + magas intenzitású lassítások.
    derived_high_efforts = pd.concat(
        [
            to_numeric(out["sprints"]) if "sprints" in out.columns else pd.Series(0.0, index=out.index),
            to_numeric(out["acc_high"]) if "acc_high" in out.columns else pd.Series(0.0, index=out.index),
            to_numeric(out["dec_high"]) if "dec_high" in out.columns else pd.Series(0.0, index=out.index),
        ],
        axis=1,
    ).sum(axis=1, min_count=1)

    if "high_efforts" not in out.columns or out["high_efforts"].isna().all():
        out["high_efforts"] = derived_high_efforts
    else:
        out["high_efforts"] = to_numeric(out["high_efforts"]).where(
            to_numeric(out["high_efforts"]).notna(),
            derived_high_efforts,
        )
    out = normalize_combined_fields(out, mapping)
    out = _fpi_enforce_distance_hierarchy(out)

    if "distance_per_min" not in out.columns or out["distance_per_min"].isna().all():
        if "total_distance" in out.columns:
            out["distance_per_min"] = out["total_distance"] / out["duration_min"]
    out = out.dropna(subset=["start_time"])
    out = out[out["player_name"].str.len() > 0]
    out = out[~out["player_name"].str.lower().str.contains("benchmark|átlag|atlag|összesen|osszesen", na=False)]
    out = finalize_exposure_columns(add_position_group(out))
    out, _v200_report = _fpi_v200_universal_postprocess(
        out,
        provider="Általános / Smart Mapper",
        file_name="Kézi mapping import",
    )
    return out, fixed_mapping, []




def apply_manual_mapping(raw: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> pd.DataFrame:
    """Kompatibilitási wrapper a Clean Workspace gyors mapperéhez."""
    mapped, _fixed_mapping, missing = apply_mapping_to_raw(raw, mapping)
    if missing:
        raise ValueError("Hiányzó kötelező mapping: " + ", ".join(missing))
    return mapped


def render_emergency_mapper(raw_df: pd.DataFrame, current_mapping: Dict[str, Optional[str]], missing_core: List[str]) -> None:
    """Mapper blokk akkor is, ha az app még nem tud elemezni.
    Cél: ne fusson hibára / st.stop előtt legyen javítási lehetőség.
    """
    st.markdown("### 🧭 Smart Excel Mapper – kötelező mezők javítása")
    st.info("A fájl szerkezete eltér a várt sablontól. Állítsd be a kötelező mezőket, majd kattints az alkalmazásra.")
    render_mapping_score(current_mapping)
    st.markdown("#### App mezők magyarázata")
    st.dataframe(enhanced_mapping_quality_df(raw_df, current_mapping), use_container_width=True)

    if raw_df is None or raw_df.empty:
        st.error("Nincs beolvasható nyers adat.")
        return

    cols = [""] + sorted([str(c) for c in raw_df.columns], key=lambda x: x.lower())
    manual = dict(current_mapping or {})

    col_a, col_b, col_c = st.columns(3)
    with col_a:
        default = manual.get("player_name") or ("Name" if "Name" in raw_df.columns else ("Játékos neve" if "Játékos neve" in raw_df.columns else ""))
        manual["player_name"] = st.selectbox(
            "Játékos neve / Name – szöveg",
            cols,
            index=cols.index(default) if default in cols else 0,
            key="emergency_map_player_name",
        ) or None

    with col_b:
        default = manual.get("session_type") or ("Típus" if "Típus" in raw_df.columns else "")
        manual["session_type"] = st.selectbox(
            "Típus – Edzés vagy Meccs",
            cols,
            index=cols.index(default) if default in cols else 0,
            key="emergency_map_session_type",
        ) or None

    with col_c:
        default = manual.get("start_time") or ("Kezdési idő" if "Kezdési idő" in raw_df.columns else ("Split" if "Split" in raw_df.columns else ""))
        manual["start_time"] = st.selectbox(
            "Kezdési idő / dátum – dátum/idő",
            cols,
            index=cols.index(default) if default in cols else 0,
            key="emergency_map_start_time",
        ) or None

    with st.expander("Haladó oszlopok mappingje", expanded=False):
        optional_fields = [
            "duration", "match_minutes", "total_distance", "distance_per_min", "max_speed", "sprints",
            "speed_zone_4", "speed_zone_5", "training_load", "muscle_load",
            "hr_avg", "hr_max", "acc_high", "dec_high", "high_efforts"
        ]
        for std_col in optional_fields:
            default = manual.get(std_col) or ""
            manual[std_col] = st.selectbox(
                f"{mapper_label(std_col)} | {mapper_unit(std_col)}",
                cols,
                index=cols.index(default) if default in cols else 0,
                key=f"emergency_map_{std_col}",
                help=mapper_desc(std_col),
            ) or None
            warn = mapper_warning(std_col, manual.get(std_col))
            if warn:
                st.warning(warn)

    c1, c2 = st.columns(2)
    with c1:
        if st.button("✅ Mapping alkalmazása", use_container_width=True, key="apply_emergency_mapping"):
            mapped_df, fixed_mapping, missing = apply_mapping_to_raw(raw_df, manual)
            if missing:
                st.error(f"Még hiányzik: {', '.join(missing)}")
            else:
                st.session_state["mapped_df_override"] = mapped_df
                st.session_state["manual_mapping"] = fixed_mapping
                st.success("Mapping alkalmazva. Újratöltöm az elemzést.")
                st.rerun()

    with c2:
        if st.button("♻️ Mapping törlése", use_container_width=True, key="clear_emergency_mapping"):
            st.session_state.pop("mapped_df_override", None)
            st.session_state.pop("manual_mapping", None)
            st.rerun()

    st.caption("Tipp: Distance(4+5) = összevont nagysebességű táv, ezt a Zone 4 / HSR mezőhöz érdemes tenni. Sprints count = darab, Total sprints distance = méter.")
    st.markdown("#### Beolvasott oszlopok")
    st.write(list(raw_df.columns))
    st.markdown("#### Adat előnézet")
    st.dataframe(raw_df.head(8), use_container_width=True)



# -----------------------------------------------------------------------------
# V6.0 - Kapus + játékperc + exposure normalizálás
# -----------------------------------------------------------------------------
KEEPER_POSITION_TOKENS = ["gk", "goalkeeper", "kapus", "kapusposzt", "kap", "keeper"]
FIELD_METRICS_FOR_EXPOSURE = [
    "total_distance", "hsr_distance", "sprint_distance", "sprints", "acc_count", "dec_count",
    "high_efforts", "training_load", "muscle_load", "distance_per_min", "max_speed",
]
KEEPER_BENCHMARK_WEIGHTS = {
    "total_distance": 0.40,
    "distance_per_min": 0.55,
    "hsr_distance": 0.15,
    "sprint_distance": 0.10,
    "sprints": 0.15,
    "acc_count": 0.55,
    "dec_count": 0.55,
    "high_efforts": 0.60,
    "training_load": 0.70,
    "muscle_load": 0.70,
    "max_speed": 0.45,
}

def is_keeper_position_value(value: object) -> bool:
    txt = _norm_mapping_text(value)
    if not txt:
        return False
    return any(tok in txt for tok in KEEPER_POSITION_TOKENS)

def add_keeper_flag_from_position(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    if "position" in out.columns:
        out["is_goalkeeper"] = out["position"].apply(is_keeper_position_value).astype(bool)
    elif "position_group" in out.columns:
        out["is_goalkeeper"] = out["position_group"].astype(str).str.lower().str.contains("kapus|gk|goalkeeper", na=False)
    else:
        out["is_goalkeeper"] = False
    return out

def render_keeper_controls_and_apply(df: pd.DataFrame) -> pd.DataFrame:
    """Kapusok kezelése.
    - Ha van poszt, automatikusan felismeri a kapusokat.
    - Ha nincs poszt / nincs felismerés, a választók között rákérdez és a kiválasztott játékosokat kapusként kezeli.
    """
    if df is None or df.empty or "player_name" not in df.columns:
        return df
    out = add_keeper_flag_from_position(df)
    players_all = sorted(out["player_name"].dropna().astype(str).unique().tolist())
    auto_keepers = sorted(out.loc[out.get("is_goalkeeper", False), "player_name"].dropna().astype(str).unique().tolist()) if "is_goalkeeper" in out.columns else []
    has_position_col = (
        "position" in out.columns
        and out["position"].notna().any()
        and out["position"].astype(str).str.strip().replace({"": np.nan, "nan": np.nan, "None": np.nan}).notna().any()
    )
    if not has_position_col:
        st.warning("Nincs felismerhető Poszt oszlop. Kérlek add meg, vannak-e kapusok az adatokban.")
    with st.expander("Kapusok és játékpercek", expanded=(not has_position_col)):
        if has_position_col:
            st.caption("Poszt oszlop alapján automatikus kapusfelismerés aktív. Ezt felülírhatod, ha szükséges.")
            st.write("Felismert kapusok: " + (", ".join(auto_keepers) if auto_keepers else "nincs"))
            manual_override = st.checkbox("Kapuslista kézi felülírása", value=False, key="keeper_manual_override")
            if manual_override:
                selected = st.multiselect("Kapusok kiválasztása", players_all, default=auto_keepers, key="manual_keeper_players")
                out["is_goalkeeper"] = out["player_name"].astype(str).isin(selected)
        else:
            st.markdown("**Kapusok kézi megadása szükséges**")
            has_keepers = st.radio(
                "Szerepelnek kapusok az adatok között?",
                ["Igen", "Nem"],
                horizontal=True,
                key="has_goalkeepers_without_position",
                help="Mivel nincs Poszt oszlop, az app csak így tudja külön kezelni a kapusokat."
            )
            if has_keepers == "Igen":
                selected = st.multiselect(
                    "Kapusok kiválasztása",
                    players_all,
                    default=st.session_state.get("manual_keeper_players_no_pos", []),
                    key="manual_keeper_players_no_pos",
                    help="A kiválasztott játékosokra kapus-specifikus súlyozás kerül."
                )
                out["is_goalkeeper"] = out["player_name"].astype(str).isin(selected)
                if not selected:
                    st.warning("Válaszd ki a kapus(oka)t, különben minden játékos mezőnyjátékosként kerül értékelésre.")
            else:
                out["is_goalkeeper"] = False
        st.caption("A csapatszintű meccs-edzés összevetésben a mezőnyjátékos-profil az alap; kapusokra külön súlyozott benchmark kerül.")
    return finalize_exposure_columns(out)

def finalize_exposure_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Játékpercek és terhelési exposure normalizálása.
    Fontos: egy meccsen 14 játékos szereplése nem 14x90 perc. A számítás a tényleges
    játékospercet használja, ha van; különben meccsnél a row szintű duration_min lesz az alap.
    Edzésnél a résztvevői percre és az egy főre jutó terhelésre normalizál.
    """
    if df is None or df.empty:
        return df
    out = df.copy()
    # V406: a függvény többszöri meghívás esetén is stabil maradjon.
    # A korábban számolt exposure/per90 segédmezőket újraszámoljuk, nem merge-eljük önmagukra.
    if "_fpi_v406_drop_exposure_derivatives" in globals():
        out = _fpi_v406_drop_exposure_derivatives(out)
    else:
        derived_fixed_v406 = {
            "player_minutes", "event_duration_min", "match_length_label",
            "session_player_count", "field_player_count", "team_player_minutes",
            "field_team_minutes", "keeper_weight",
        }
        derived_suffixes_v406 = ("_per90", "_per_player", "_per_field_player", "_keeper_adjusted")
        out = out.drop(columns=[c for c in out.columns if c in derived_fixed_v406 or c.endswith(derived_suffixes_v406)], errors="ignore")
    if "is_goalkeeper" not in out.columns:
        out = add_keeper_flag_from_position(out)
    if "duration_min" not in out.columns:
        out["duration_min"] = np.nan
    if "match_minutes" in out.columns:
        out["match_minutes"] = out["match_minutes"].apply(duration_to_minutes)
    else:
        out["match_minutes"] = np.nan
    # player_minutes: meccsnél tényleges játékperc, ha van; ha nincs, duration_min. Edzésnél duration_min.
    out["player_minutes"] = np.where(
        out.get("session_type", "").astype(str).eq("Meccs"),
        out["match_minutes"].where(out["match_minutes"].notna() & (out["match_minutes"] > 0), out["duration_min"]),
        out["duration_min"],
    )
    out["player_minutes"] = pd.to_numeric(out["player_minutes"], errors="coerce")
    out.loc[out["player_minutes"] <= 0, "player_minutes"] = np.nan

    # V156: a mérkőzés tényleges hossza lehet 90 percnél hosszabb is.
    is_match_v156 = out.get("session_type", "").astype(str).eq("Meccs")
    out["event_duration_min"] = out["duration_min"]
    if "match_minutes" in out.columns:
        out.loc[is_match_v156, "event_duration_min"] = (
            out.loc[is_match_v156, "match_minutes"]
            .where(
                out.loc[is_match_v156, "match_minutes"].notna()
                & (out.loc[is_match_v156, "match_minutes"] > 0),
                out.loc[is_match_v156, "duration_min"],
            )
        )
    out["event_duration_min"] = pd.to_numeric(out["event_duration_min"], errors="coerce")
    out["match_length_label"] = np.where(
        is_match_v156 & out["event_duration_min"].notna(),
        out["event_duration_min"].round(0).astype("Int64").astype(str) + " perces mérkőzés",
        "",
    )

    # A teljes 105/120 perces terhelés megmarad, mellette per90 érték készül.
    per90_metrics_v156 = [
        "total_distance", "hsr_distance", "sprint_distance", "sprints",
        "high_efforts", "training_load", "acc_high", "dec_high",
        "speed_zone_4", "speed_zone_5",
    ]
    denominator_v156 = out["player_minutes"].where(out["player_minutes"] > 0)
    for metric_v156 in per90_metrics_v156:
        if metric_v156 in out.columns:
            numeric_v156 = pd.to_numeric(out[metric_v156], errors="coerce")
            out[f"{metric_v156}_per90"] = numeric_v156 / denominator_v156 * 90.0
    group_cols = ["week", "session_date", "session_type"]
    if "session_name" in out.columns:
        group_cols.append("session_name")
    safe_group_cols = [c for c in group_cols if c in out.columns]
    if safe_group_cols:
        out["session_player_count"] = out.groupby(safe_group_cols)["player_name"].transform("nunique")
        out["field_player_count"] = out[~out["is_goalkeeper"]].groupby(safe_group_cols)["player_name"].transform("nunique")
        out["team_player_minutes"] = out.groupby(safe_group_cols)["player_minutes"].transform("sum")
        field_minutes = out.loc[~out["is_goalkeeper"]].groupby(safe_group_cols)["player_minutes"].sum().rename("field_team_minutes")
        out = out.merge(field_minutes.reset_index(), on=safe_group_cols, how="left")
    else:
        out["session_player_count"] = out["player_name"].nunique() if "player_name" in out.columns else np.nan
        out["field_player_count"] = out.loc[~out["is_goalkeeper"], "player_name"].nunique() if "player_name" in out.columns else np.nan
        out["team_player_minutes"] = out["player_minutes"].sum()
        out["field_team_minutes"] = out.loc[~out["is_goalkeeper"], "player_minutes"].sum()
    out["keeper_weight"] = 1.0
    for metric, weight in KEEPER_BENCHMARK_WEIGHTS.items():
        if metric in out.columns:
            out[f"{metric}_keeper_adjusted"] = np.where(out["is_goalkeeper"], out[metric] / max(weight, 0.01), out[metric])
    for metric in FIELD_METRICS_FOR_EXPOSURE:
        if metric in out.columns:
            out[f"{metric}_per90"] = np.where(out["player_minutes"] > 0, out[metric] / out["player_minutes"] * 90, np.nan)
            out[f"{metric}_per_player"] = np.where(out["session_player_count"] > 0, out[metric] / out["session_player_count"], np.nan)
            out[f"{metric}_per_field_player"] = np.where(out["field_player_count"] > 0, out[metric] / out["field_player_count"], np.nan)
    return out

def field_players_only(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return df
    if "is_goalkeeper" in df.columns:
        return df[~df["is_goalkeeper"].fillna(False)].copy()
    return df.copy()

def aggregate_weekly(df: pd.DataFrame) -> pd.DataFrame:
    # Csapatszintű összevetésnél a mezőnyjátékos-profil az alap, hogy a kapusok ne húzzák le
    # a sprint/HSR/intenzitás mutatókat. A kapusok külön szerepként maradnak a játékosszintű elemzésben.
    work = field_players_only(finalize_exposure_columns(df)) if df is not None and not df.empty else pd.DataFrame()
    if work.empty:
        return pd.DataFrame()
    agg_map = {
        "total_distance": "sum",
        "training_load": "sum",
        "muscle_load": "sum",
        "hsr_distance": "sum",
        "sprint_distance": "sum",
        "sprints": "sum",
        "acc_count": "sum",
        "dec_count": "sum",
        "high_efforts": "sum",
        "duration_min": "sum",
        "player_minutes": "sum",
        "team_player_minutes": "max",
        "field_team_minutes": "max",
        "session_player_count": "max",
        "field_player_count": "max",
        "distance_per_min": "mean",
        "max_speed": "max",
        "hr_avg": "mean",
        "hrv": "mean",
    }
    usable = {k: v for k, v in agg_map.items() if k in work.columns}
    res = work.groupby(["week", "session_type"], as_index=False).agg(usable)
    # Per90 / per participant normalizált csapatmutatók: különösen meccs-edzés arányhoz.
    for metric in ["total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts", "training_load"]:
        if metric in res.columns and "field_team_minutes" in res.columns:
            res[f"{metric}_per90_player_avg"] = np.where(res["field_team_minutes"] > 0, res[metric] / res["field_team_minutes"] * 90, np.nan)
        if metric in res.columns and "field_player_count" in res.columns:
            res[f"{metric}_per_field_player"] = np.where(res["field_player_count"] > 0, res[metric] / res["field_player_count"], np.nan)
    return res


def player_weekly(df: pd.DataFrame) -> pd.DataFrame:
    work = finalize_exposure_columns(df) if df is not None and not df.empty else pd.DataFrame()
    if work.empty:
        return pd.DataFrame()
    agg_map = {
        "total_distance": "sum",
        "training_load": "sum",
        "muscle_load": "sum",
        "hsr_distance": "sum",
        "sprint_distance": "sum",
        "sprints": "sum",
        "acc_count": "sum",
        "dec_count": "sum",
        "high_efforts": "sum",
        "duration_min": "sum",
        "player_minutes": "sum",
        "distance_per_min": "mean",
        "max_speed": "max",
        "hr_avg": "mean",
        "hrv": "mean",
        "is_goalkeeper": "max",
        "team_training_sessions": "max",
        "player_training_sessions": "max",
        "training_availability_pct": "max",
    }
    usable = {k: v for k, v in agg_map.items() if k in work.columns}
    res = work.groupby(["player_name", "week", "session_type"], as_index=False).agg(usable)
    for metric in ["total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts", "training_load", "acc_count", "dec_count"]:
        if metric in res.columns and "player_minutes" in res.columns:
            res[f"{metric}_per90"] = np.where(res["player_minutes"] > 0, res[metric] / res["player_minutes"] * 90, np.nan)
    return res


def pct_change(current: float, previous: float) -> Optional[float]:
    if previous is None or pd.isna(previous) or previous == 0 or pd.isna(current):
        return None
    return (current - previous) / previous


def available_metric_options(df: pd.DataFrame, desired: List[str]) -> List[str]:
    return [m for m in desired if m in df.columns and not df[m].isna().all()]


def metric_name(metric: str) -> str:
    return METRIC_LABELS.get(metric, metric)


def format_week_label(week_value: object) -> str:
    """Rövid, dashboard-barát hétfelirat.
    A pandas periodből érkező '2026-06-01/2026-06-07' helyett pl. '2026-W23'.
    """
    text = str(week_value or "")
    try:
        if "/" in text:
            start = pd.to_datetime(text.split("/")[0], errors="coerce")
            if pd.notna(start):
                iso = start.isocalendar()
                return f"{int(iso.year)}-W{int(iso.week):02d}"
        dt = pd.to_datetime(text, errors="coerce")
        if pd.notna(dt):
            iso = dt.isocalendar()
            return f"{int(iso.year)}-W{int(iso.week):02d}"
    except Exception:
        pass
    return text


def team_insights(df: pd.DataFrame, selected_week: str) -> List[Insight]:
    insights: List[Insight] = []
    weeks = sorted(df["week"].dropna().unique().tolist())
    week_idx = weeks.index(selected_week) if selected_week in weeks else len(weeks) - 1
    previous_week = weeks[week_idx - 1] if week_idx > 0 else None

    current = df[df["week"] == selected_week]
    prev = df[df["week"] == previous_week] if previous_week else pd.DataFrame()
    cur_train = current[current["session_type"] == "Edzés"]
    cur_match = current[current["session_type"] == "Meccs"]
    prev_train = prev[prev["session_type"] == "Edzés"] if not prev.empty else pd.DataFrame()

    # 1. Sprint underload
    if not cur_train.empty and not cur_match.empty and "sprint_distance" in df.columns:
        train_sprint = cur_train["sprint_distance"].mean()
        match_sprint = cur_match["sprint_distance"].mean()
        if pd.notna(match_sprint) and match_sprint > 0:
            ratio = train_sprint / match_sprint
            if ratio < 0.65:
                insights.append(Insight(
                    "Alacsony sprintterhelés", "KRITIKUS",
                    f"Az edzések átlagos sprintterhelése a meccsterhelés kb. {ratio:.0%}-a.",
                    "A nagy intenzitású terhelés jelentősen elmaradhat attól, amit a mérkőzés megkövetel.",
                    "Érdemes célzott sprint- vagy nagysebességű blokkokat beépíteni, ha ez illeszkedik a hét terhelési tervéhez.",
                ))
            elif ratio < 0.80:
                insights.append(Insight(
                    "Alacsony sprintterhelés", "FIGYELMEZTETÉS",
                    f"Az edzések átlagos sprintterhelése a meccsterhelés kb. {ratio:.0%}-a.",
                    "A meccsigényhez képest mérsékelt intenzitási hiány látható.",
                    "Érdemes ellenőrizni, hogy tudatos visszaterhelésről vagy nem kívánt intenzitáshiányról van-e szó.",
                ))

    # 2. Weekly load change
    if not cur_train.empty and not prev_train.empty and "training_load" in df.columns:
        cur_load = cur_train["training_load"].sum()
        prev_load = prev_train["training_load"].sum()
        chg = pct_change(cur_load, prev_load)
        if chg is not None:
            if chg > 0.25:
                insights.append(Insight(
                    "Heti terhelési kiugrás", "FIGYELMEZTETÉS",
                    f"Az edzés terhelési pontértéke {chg:.0%}-kal nőtt az előző héthez képest.",
                    "A hirtelen terhelésemelkedés ronthatja a frissességet és növelheti a következő napok terhelési kockázatát.",
                    "Érdemes figyelni a következő edzések intenzitását, illetve a játékosok egyéni reakcióit.",
                ))
            elif chg < -0.25:
                insights.append(Insight(
                    "Heti terheléscsökkenés", "INFORMÁCIÓ",
                    f"Az edzés terhelési pontértéke {abs(chg):.0%}-kal csökkent az előző héthez képest.",
                    "Ez lehet tudatos frissítés, de lehet nem kívánt terhelésvesztés is.",
                    "Érdemes kontextusba helyezni: meccs előtti könnyítés, hiányzók vagy edzéstartalom-váltás okozta-e.",
                ))

    # 3. Match intensity gap
    if not cur_train.empty and not cur_match.empty and "distance_per_min" in df.columns:
        train_int = cur_train["distance_per_min"].mean()
        match_int = cur_match["distance_per_min"].mean()
        if pd.notna(match_int) and match_int > 0:
            ratio = train_int / match_int
            if ratio < 0.85:
                insights.append(Insight(
                    "Meccsintenzitási eltérés", "FIGYELMEZTETÉS",
                    f"Az edzések átlagos táv/perc értéke a meccs kb. {ratio:.0%}-a.",
                    "A csapat edzésintenzitása elmaradhat a mérkőzés tempójától.",
                    "Érdemes lehet rövidebb, intenzívebb játékszituációkat vagy tudatos tempóváltásokat használni.",
                ))

    # 4. High deceleration load
    if not cur_train.empty and not prev_train.empty and "dec_count" in df.columns:
        cur_dec = cur_train["dec_count"].mean()
        prev_dec = prev_train["dec_count"].mean()
        chg = pct_change(cur_dec, prev_dec)
        if chg is not None and chg > 0.35:
            insights.append(Insight(
                "Magas lassítási terhelés", "FIGYELMEZTETÉS",
                f"Az átlagos lassításszám {chg:.0%}-kal nőtt az előző héthez képest.",
                "A lassítások jelentős neuromuszkuláris terhelést jelenthetnek.",
                "Érdemes figyelni a regenerációra és a következő edzés excentrikus terhelésére.",
            ))

    # 5. Max speed suppression
    if not cur_train.empty and not prev_train.empty and "max_speed" in df.columns:
        cur_speed = cur_train["max_speed"].max()
        prev_speed = prev_train["max_speed"].max()
        chg = pct_change(cur_speed, prev_speed)
        if chg is not None and chg < -0.05:
            insights.append(Insight(
                "Maximális sebesség visszaesése", "INFORMÁCIÓ",
                f"A heti legmagasabb maximális sebesség {abs(chg):.0%}-kal alacsonyabb az előző hétnél.",
                "Ez jelezhet alacsonyabb neuromuszkuláris frissességet, de lehet edzéstartalom-függő is.",
                "Érdemes megnézni, volt-e valódi maximális sebességű inger a héten.",
            ))

    # 6. Player outlier alerts
    if not cur_train.empty and "training_load" in cur_train.columns:
        player_load = cur_train.groupby("player_name")["training_load"].sum().dropna()
        if len(player_load) >= 5 and player_load.mean() > 0:
            mean = player_load.mean()
            high = player_load[player_load > mean * 1.25].sort_values(ascending=False)
            low = player_load[player_load < mean * 0.75].sort_values(ascending=True)
            if len(high) > 0:
                names = ", ".join(high.head(3).index.tolist())
                insights.append(Insight(
                    "Kiugró játékosterhelés", "FIGYELMEZTETÉS",
                    f"Néhány játékos jelentősen a csapatátlag felett terhelődött: {names}.",
                    "Egyéni terheléskülönbség alakult ki a héten.",
                    "Érdemes egyéni szinten ránézni a következő edzés terhelésére és a játékpercekre.",
                    scope="Játékos",
                ))
            if len(low) > 0:
                names = ", ".join(low.head(3).index.tolist())
                insights.append(Insight(
                    "Alacsony játékosterhelés", "INFORMÁCIÓ",
                    f"Néhány játékos jelentősen a csapatátlag alatt terhelődött: {names}.",
                    "Terheléslemaradás alakulhat ki, főleg ha ez több héten át fennáll.",
                    "Érdemes ellenőrizni a hiányzásokat, játékperceket és az egyéni kiegészítő munkát.",
                    scope="Játékos",
                ))

    if not insights:
        if len(weeks) <= 1:
            insights.append(Insight(
                "Aktuális heti alapállapot", "INFORMÁCIÓ",
                "Az egyetlen feltöltött hét fő mutatóiban nem látható kiemelt negatív eltérés.",
                "A rendszer teljes értékű heti állapotképet készít, de többhetes trendet csak további hetek feltöltése után számol.",
                "A következő hetek adataival automatikusan megjelenik a heti változás és a gördülő trendértékelés.",
            ))
        else:
            insights.append(Insight(
                "Stabil hét", "INFORMÁCIÓ",
                "Nem látható kiemelt negatív eltérés az aktuális hét fő mutatóiban.",
                "A csapat terhelési profilja stabilnak tűnik az elérhető adatok alapján.",
                "Érdemes tovább figyelni a sprint- és intenzitási trendeket, különösen meccs előtti héten.",
            ))

    return sorted(insights, key=lambda x: SEVERITY_RANK.get(x.severity, 9))[:8]



# -----------------------------------------------------------------------------
# V2 - Football Intelligence Layer
# -----------------------------------------------------------------------------
def fpi_pdf_sanitize_v406(value: object) -> str:
    """Közös V409 PDF-karakter-normalizálás.

    Normál működésben az ő/Ő/ű/Ű karaktereket változatlanul hagyja. Ha egy
    rendkívül szűk szerverkörnyezetben semmilyen Unicode-font nem érhető el,
    a PDF-export nem áll le: csak ebben a végső fallback módban történik
    ő→ö és ű→ü helyettesítés, mert a ReportLab alap Helvetica fontja ezeket
    a karaktereket nem tartalmazza.
    """
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    text = unicodedata.normalize("NFC", str(value))
    replacements = {
        "\u00ad": "",   # soft hyphen
        "\u200b": "",   # zero-width space
        "\ufeff": "",   # BOM / zero-width no-break space
        "\u00a0": " ",  # non-breaking space
        "\u202f": " ",  # narrow no-break space
    }
    for old, new in replacements.items():
        text = text.replace(old, new)

    if globals().get("_FPI_PDF_STANDARD_FONT_FALLBACK", False):
        text = text.translate(str.maketrans({
            "ő": "ö", "Ő": "Ö", "ű": "ü", "Ű": "Ü",
        }))
    return text



def pdf_safe_text(text: object) -> str:
    """Visszafelé kompatibilis alias az egységes V406 PDF-sanitize réteghez."""
    return fpi_pdf_sanitize_v406(text)


def _fpi_v406_sanitize_pdf_flowable(value):
    """V408: PDF story rekurzív tisztítása és Unicode-font kényszerítése.

    Nem csak a szöveget normalizálja: minden Paragraph és nyers táblázatcella
    ugyanazt a magyar ő/ű karaktereket támogató fontcsaládot kapja. Így az
    inline <b>/<strong> részek sem esnek vissza Helvetica betűtípusra.
    """
    if isinstance(value, str):
        return fpi_pdf_sanitize_v406(value)
    if isinstance(value, list):
        return [_fpi_v406_sanitize_pdf_flowable(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_fpi_v406_sanitize_pdf_flowable(item) for item in value)

    paragraph_cls = globals().get("Paragraph")
    table_cls = globals().get("Table")
    keep_cls = globals().get("KeepTogether")

    regular_font, bold_font = _register_pdf_font()

    if paragraph_cls is not None and isinstance(value, paragraph_cls):
        try:
            from copy import copy
            style = copy(value.style)
            old_font = str(getattr(style, "fontName", ""))
            style_name = str(getattr(style, "name", ""))
            bold_hint = "bold" in old_font.lower() or any(
                token in style_name.lower()
                for token in ("title", "head", "strong", "bold", "callh", "label", "big")
            )
            style.fontName = bold_font if bold_hint else regular_font
            clean_text = fpi_pdf_sanitize_v406(getattr(value, "text", ""))
            return paragraph_cls(
                clean_text,
                style,
                bulletText=getattr(value, "bulletText", None),
            )
        except Exception:
            return value

    if table_cls is not None and isinstance(value, table_cls):
        try:
            table_style = ParagraphStyle(
                "FPI_V408_RAW_TABLE_CELL",
                parent=getSampleStyleSheet()["BodyText"],
                fontName=regular_font,
                fontSize=8.5,
                leading=10.5,
            )
            cleaned_rows = []
            for row in value._cellvalues:
                cleaned_row = []
                for cell in row:
                    if isinstance(cell, str):
                        cleaned_row.append(paragraph_cls(fpi_pdf_sanitize_v406(cell), table_style))
                    else:
                        cleaned_row.append(_fpi_v406_sanitize_pdf_flowable(cell))
                cleaned_rows.append(cleaned_row)
            value._cellvalues = cleaned_rows
        except Exception:
            pass
        return value

    if keep_cls is not None and isinstance(value, keep_cls):
        try:
            value._content = [
                _fpi_v406_sanitize_pdf_flowable(item)
                for item in value._content
            ]
        except Exception:
            pass
        return value
    return value

def _fpi_v406_sanitize_pdf_story(story: list) -> list:
    return [_fpi_v406_sanitize_pdf_flowable(item) for item in (story or [])]


def _fpi_pdf_logo_path_v425() -> Optional[Path]:
    """Az összes FPI PDF közös logóforrása: a repo gyökerében lévő logo.png."""
    try:
        candidates = [
            Path(__file__).resolve().parent / "logo.png",
            Path.cwd() / "logo.png",
        ]
        for candidate in candidates:
            if candidate.exists() and candidate.is_file() and candidate.stat().st_size > 0:
                return candidate
    except Exception:
        pass
    return None


def _fpi_pdf_logo_dimensions_v426(max_w: float, max_h: float) -> Tuple[Optional[Path], float, float]:
    """Aránytartó logóméret ReportLabhoz."""
    logo_path = _fpi_pdf_logo_path_v425()
    if logo_path is None:
        return None, 0.0, 0.0
    try:
        from reportlab.lib.utils import ImageReader
        img = ImageReader(str(logo_path))
        iw, ih = img.getSize()
        if not iw or not ih:
            return None, 0.0, 0.0
        scale = min(float(max_w) / float(iw), float(max_h) / float(ih))
        return logo_path, float(iw) * scale, float(ih) * scale
    except Exception:
        return None, 0.0, 0.0


def _fpi_pdf_split_title_v426(raw_title: str) -> Tuple[str, str]:
    """Az FPI címet két, stabilan elférő sorra bontja."""
    clean = fpi_pdf_sanitize_v406(str(raw_title or "").strip())
    if not clean:
        return "Football Performance Intelligence", ""

    # A legtöbb riport címe: Football Performance Intelligence – <riport neve>.
    # Ezt tudatosan két sorba törjük, hogy a jobb oldali logó nagy lehessen.
    m = re.match(r"^Football Performance Intelligence\s*[–—-]\s*(.+)$", clean, flags=re.I)
    if m:
        return "Football Performance Intelligence", m.group(1).strip()
    if clean.lower() == "football performance intelligence":
        return "Football Performance Intelligence", ""
    return "Football Performance Intelligence", clean


def _fpi_pdf_first_page_header_v426(doc_obj, story: list) -> list:
    """
    Nagy, egységes első oldali fejléc minden FPI PDF-hez.

    Bal oldalon két soros cím, jobb oldalon nagy logo.png. Ha az első story-elem
    már FPI-cím Paragraph, azt kivesszük és ugyanazt a szöveget a fejlécbe emeljük.
    """
    items = list(story or [])
    raw_title = ""
    try:
        if items and Paragraph is not None and isinstance(items[0], Paragraph):
            first = items[0]
            plain = first.getPlainText() if hasattr(first, "getPlainText") else getattr(first, "text", "")
            style = getattr(first, "style", None)
            style_name = str(getattr(style, "name", "") or "").lower()
            font_size = float(getattr(style, "fontSize", 0.0) or 0.0)
            looks_like_title = (
                "football performance intelligence" in str(plain).lower()
                or "title" in style_name
                or font_size >= 14.0
            )
            if looks_like_title:
                raw_title = str(plain or "")
                items = items[1:]
    except Exception:
        raw_title = ""

    line1, line2 = _fpi_pdf_split_title_v426(raw_title)
    try:
        styles = getSampleStyleSheet()
        p1 = ParagraphStyle(
            "FPI_V426_BRAND_LINE1",
            parent=styles["Title"],
            fontSize=17.5,
            leading=20.5,
            textColor=colors.HexColor("#0F172A"),
            spaceAfter=0,
            alignment=0,
        )
        p2 = ParagraphStyle(
            "FPI_V426_BRAND_LINE2",
            parent=styles["Heading2"],
            fontSize=12.8,
            leading=15.5,
            textColor=colors.HexColor("#334155"),
            spaceBefore=2,
            spaceAfter=0,
            alignment=0,
        )
        left_bits = [Paragraph(line1, p1)]
        if line2:
            left_bits += [Spacer(1, 0.04 * cm), Paragraph(line2, p2)]

        # Portraitban is elfér, landscape-ben pedig kifejezetten hangsúlyos.
        available_w = float(getattr(doc_obj, "width", 0.0) or (A4[0] - 2.4 * cm))
        portrait_like = available_w < 20.0 * cm
        logo_max_w = 4.15 * cm if portrait_like else 4.75 * cm
        logo_max_h = 2.75 * cm if portrait_like else 3.05 * cm
        logo_path, logo_w, logo_h = _fpi_pdf_logo_dimensions_v426(logo_max_w, logo_max_h)

        if logo_path is not None and logo_w > 0 and logo_h > 0:
            from reportlab.platypus import Image as RLImage
            logo_flow = RLImage(str(logo_path), width=logo_w, height=logo_h)
            logo_col_w = max(4.35 * cm if portrait_like else 4.95 * cm, logo_w + 0.12 * cm)
            title_col_w = max(4.0 * cm, available_w - logo_col_w)
            hdr = Table([[left_bits, logo_flow]], colWidths=[title_col_w, logo_col_w], hAlign="LEFT")
            hdr.setStyle(TableStyle([
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("ALIGN", (1, 0), (1, 0), "RIGHT"),
                ("LEFTPADDING", (0, 0), (0, 0), 0),
                ("RIGHTPADDING", (0, 0), (0, 0), 8),
                ("LEFTPADDING", (1, 0), (1, 0), 4),
                ("RIGHTPADDING", (1, 0), (1, 0), 0),
                ("TOPPADDING", (0, 0), (-1, -1), 0),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
                ("LINEBELOW", (0, 0), (-1, -1), 0.65, colors.HexColor("#CBD5E1")),
            ]))
            return [hdr, Spacer(1, 0.16 * cm)] + items

        # Logó hiányában is megmarad az egységes két soros fejléc.
        header_only = Table([[left_bits]], colWidths=[available_w], hAlign="LEFT")
        header_only.setStyle(TableStyle([
            ("LEFTPADDING", (0, 0), (-1, -1), 0),
            ("RIGHTPADDING", (0, 0), (-1, -1), 0),
            ("TOPPADDING", (0, 0), (-1, -1), 0),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("LINEBELOW", (0, 0), (-1, -1), 0.65, colors.HexColor("#CBD5E1")),
        ]))
        return [header_only, Spacer(1, 0.16 * cm)] + items
    except Exception:
        # PDF-export soha ne álljon meg pusztán a branding miatt.
        return story


def _fpi_pdf_later_page_branding_v426(canvas_obj, doc_obj) -> None:
    """Kisebb, de jól olvasható FPI logó a 2. oldaltól, mindig jobb felül."""
    logo_path, draw_w, draw_h = _fpi_pdf_logo_dimensions_v426(2.95 * cm, 0.95 * cm)
    if logo_path is None or draw_w <= 0 or draw_h <= 0:
        return
    try:
        from reportlab.lib.utils import ImageReader
        canvas_obj.saveState()
        page_w, page_h = canvas_obj._pagesize
        x = page_w - 0.55 * cm - draw_w
        y = page_h - 0.24 * cm - draw_h
        canvas_obj.drawImage(
            ImageReader(str(logo_path)), x, y,
            width=draw_w, height=draw_h,
            preserveAspectRatio=True, mask="auto"
        )
        canvas_obj.restoreState()
    except Exception:
        try:
            canvas_obj.restoreState()
        except Exception:
            pass


def _fpi_pdf_first_page_branding_v426(canvas_obj, doc_obj) -> None:
    """Az első oldali nagy logó a story fejlécben van; itt nem duplázzuk meg."""
    return


def _fpi_pdf_build_v406(doc, story: list) -> None:
    """Minden FPI PDF közös végső build-kapuja + V426 egységes PDF-fejléc."""
    branded_story = _fpi_pdf_first_page_header_v426(doc, story)
    try:
        # Első oldalon a fejléc maga foglal helyet; későbbi oldalakon a kis felső logóhoz kell hely.
        doc.topMargin = max(float(getattr(doc, "topMargin", 0.0) or 0.0), 1.25 * cm)
    except Exception:
        pass
    doc.build(
        _fpi_v406_sanitize_pdf_story(branded_story),
        onFirstPage=_fpi_pdf_first_page_branding_v426,
        onLaterPages=_fpi_pdf_later_page_branding_v426,
    )


def day_label_from_delta(delta_days: int) -> str:
    if delta_days == 0:
        return "MD"
    if delta_days < 0:
        return f"MD{delta_days}"
    return f"MD+{delta_days}"


def _fpi_v407_parse_md_delta(value: object) -> Optional[int]:
    """MD-3 -> -3, MD -> 0, MD+1 -> +1."""
    raw = unicodedata.normalize("NFKC", str(value or "")).upper()
    raw = raw.replace("_", " ")
    exact = re.search(r"(?<![A-Z0-9])MD\s*([+-])?\s*(\d+)?(?![A-Z0-9])", raw)
    if not exact:
        return None
    sign, num = exact.group(1), exact.group(2)
    if num is None:
        return 0
    n = int(num)
    if sign == "+":
        return n
    return -n


def _fpi_v407_date_from_text(value: object) -> pd.Timestamp:
    text = str(value or "")
    patterns = [
        (r"(?<!\d)(20\d{2})[-_. ](\d{1,2})[-_. ](\d{1,2})(?!\d)", (1, 2, 3)),
        (r"(?<!\d)(20\d{2})(\d{2})(\d{2})(?!\d)", (1, 2, 3)),
        (r"(?<!\d)(\d{1,2})[-_. ](\d{1,2})[-_. ](20\d{2})(?!\d)", (3, 2, 1)),
    ]
    for pattern, order in patterns:
        m = re.search(pattern, text)
        if not m:
            continue
        vals = [int(m.group(i)) for i in order]
        try:
            return pd.Timestamp(year=vals[0], month=vals[1], day=vals[2])
        except Exception:
            pass
    return pd.NaT


def _fpi_v407_apply_filename_md_inference(data: pd.DataFrame) -> pd.DataFrame:
    """Fájlnévben lévő MD-horgonyból a dátumos fájlok MD-napját is kikövetkezteti."""
    if data is None or data.empty:
        return pd.DataFrame() if data is None else data.copy()
    out = data.copy()
    source_col = "_fpi_source_file" if "_fpi_source_file" in out.columns else (
        "_fpi_source_key" if "_fpi_source_key" in out.columns else None
    )
    if source_col is None:
        return out

    starts = pd.to_datetime(out.get("start_time"), errors="coerce") if "start_time" in out.columns else pd.Series(pd.NaT, index=out.index)
    source_rows = []
    for source, idx in out.groupby(source_col, dropna=False).groups.items():
        group_start = starts.loc[idx].dropna().min()
        if pd.isna(group_start):
            group_start = _fpi_v407_date_from_text(source)
        names = [source]
        if "session_name" in out.columns:
            names.extend(out.loc[idx, "session_name"].dropna().astype(str).unique().tolist())
        explicit = next((v for v in (_fpi_v407_parse_md_delta(x) for x in names) if v is not None), None)
        source_rows.append({"source": source, "date": pd.to_datetime(group_start, errors="coerce"), "explicit": explicit})

    meta = pd.DataFrame(source_rows)
    if meta.empty:
        return out
    anchors = meta[meta["explicit"].notna() & meta["date"].notna()].copy()
    if anchors.empty:
        return out
    anchors["implied_match"] = anchors["date"].dt.normalize() - pd.to_timedelta(anchors["explicit"].astype(int), unit="D")

    inferred_by_source = {}
    match_by_source = {}
    for _, row in meta.iterrows():
        source = row["source"]
        date = pd.to_datetime(row["date"], errors="coerce")
        explicit = row["explicit"]
        if pd.isna(date):
            continue
        if explicit is not None and not pd.isna(explicit):
            delta = int(explicit)
            match_date = date.normalize() - pd.Timedelta(days=delta)
        else:
            candidates = anchors.copy()
            candidates["distance"] = (candidates["date"].dt.normalize() - date.normalize()).abs().dt.days
            candidates = candidates[candidates["distance"] <= 10].sort_values(["distance", "date"])
            if candidates.empty:
                continue
            match_date = pd.to_datetime(candidates.iloc[0]["implied_match"]).normalize()
            delta = int((date.normalize() - match_date).days)
        if -7 <= delta <= 3:
            inferred_by_source[str(source)] = day_label_from_delta(delta)
            match_by_source[str(source)] = match_date

    source_text = out[source_col].astype(str)
    inferred = source_text.map(inferred_by_source)
    implied_match = pd.to_datetime(source_text.map(match_by_source), errors="coerce")
    if "_fpi_inferred_md_label" in out.columns:
        out["_fpi_inferred_md_label"] = out["_fpi_inferred_md_label"].combine_first(inferred)
    else:
        out["_fpi_inferred_md_label"] = inferred
    if "_fpi_inferred_match_date" in out.columns:
        out["_fpi_inferred_match_date"] = pd.to_datetime(out["_fpi_inferred_match_date"], errors="coerce").combine_first(implied_match)
    else:
        out["_fpi_inferred_match_date"] = implied_match
    return out


def detect_match_day(week_df: pd.DataFrame) -> Optional[pd.Timestamp]:
    if week_df is None or week_df.empty:
        return None
    tmp = _fpi_v407_apply_filename_md_inference(week_df)
    tmp["session_date_dt"] = pd.to_datetime(tmp.get("session_date"), errors="coerce")
    if tmp["session_date_dt"].isna().all() and "start_time" in tmp.columns:
        tmp["session_date_dt"] = pd.to_datetime(tmp["start_time"], errors="coerce").dt.normalize()
    matches = tmp[tmp.get("session_type", pd.Series("", index=tmp.index)).astype(str).eq("Meccs")]
    if not matches.empty:
        return pd.to_datetime(matches["session_date_dt"].max())
    if "_fpi_inferred_match_date" in tmp.columns:
        inferred = pd.to_datetime(tmp["_fpi_inferred_match_date"], errors="coerce").dropna()
        if not inferred.empty:
            return pd.to_datetime(inferred.mode().iloc[0] if not inferred.mode().empty else inferred.median()).normalize()
    if "_fpi_inferred_md_label" in tmp.columns:
        implied = []
        for _, row in tmp[["session_date_dt", "_fpi_inferred_md_label"]].dropna().drop_duplicates().iterrows():
            delta = _fpi_v407_parse_md_delta(row["_fpi_inferred_md_label"])
            if delta is not None:
                implied.append(pd.to_datetime(row["session_date_dt"]).normalize() - pd.Timedelta(days=delta))
        if implied:
            return pd.Series(implied).mode().iloc[0]
    return None



def build_microcycle_table(df: pd.DataFrame, selected_week: str) -> pd.DataFrame:
    week_df = df[df["week"].astype(str) == str(selected_week)].copy()
    if week_df.empty:
        return pd.DataFrame()
    week_df = _fpi_v407_apply_filename_md_inference(week_df)
    match_day = detect_match_day(week_df)
    week_df["session_date_dt"] = pd.to_datetime(week_df.get("session_date"), errors="coerce")
    if week_df["session_date_dt"].isna().all() and "start_time" in week_df.columns:
        week_df["session_date_dt"] = pd.to_datetime(week_df["start_time"], errors="coerce").dt.normalize()

    agg_spec = {
        "training_load": "sum", "total_distance": "sum", "sprint_distance": "sum",
        "hsr_distance": "sum", "distance_per_min": "mean", "max_speed": "max",
        "acc_count": "sum", "dec_count": "sum", "high_efforts": "sum",
        "player_name": "nunique",
    }
    usable = {k: v for k, v in agg_spec.items() if k in week_df.columns}
    daily = week_df.groupby(["session_date_dt", "session_type"], as_index=False).agg(usable)
    daily = daily.rename(columns={"player_name": "játékosok"})
    if match_day is not None:
        daily["md_delta"] = (daily["session_date_dt"].dt.normalize() - pd.to_datetime(match_day).normalize()).dt.days
        daily["md_label"] = daily["md_delta"].apply(day_label_from_delta)
        actual_match_dates = set(
            week_df.loc[week_df["session_type"].astype(str).eq("Meccs"), "session_date_dt"].dropna().dt.normalize()
        )
        daily["md_context_source"] = np.where(
            daily["session_date_dt"].dt.normalize().isin(actual_match_dates), "feltöltött meccs", "fájlnév + dátum következtetés" if not actual_match_dates else "feltöltött meccsnap"
        )
    else:
        daily["md_delta"] = np.nan
        daily["md_label"] = "Nincs meccs"
        daily["md_context_source"] = "nincs MD-horgony"

    if "training_load" in daily.columns and not daily["training_load"].isna().all():
        daily["load_index"] = daily["training_load"]
        daily["load_index_label"] = "Terhelési pont"
    elif "total_distance" in daily.columns:
        daily["load_index"] = daily["total_distance"]
        daily["load_index_label"] = "Össztáv"
    else:
        daily["load_index"] = np.nan
        daily["load_index_label"] = "Nincs load mutató"
    return daily.sort_values("session_date_dt")



def microcycle_insights(df: pd.DataFrame, selected_week: str) -> List[Insight]:
    insights: List[Insight] = []
    daily = build_microcycle_table(df, selected_week)
    if daily.empty:
        return insights
    if daily["md_label"].astype(str).eq("Nincs meccs").all():
        insights.append(Insight(
            "Mikrociklus kontextus hiányzik", "INFORMÁCIÓ",
            "Sem feltöltött meccs, sem fájlnévből felismerhető MD-horgony nem áll rendelkezésre.",
            "Meccsnap vagy MD-horgony nélkül a heti struktúra csak általános terhelési trendként értékelhető.",
            "Legalább egy fájlnévben add meg az MD-napot (például MD-3); a dátumos szomszédos fájlokat a rendszer automatikusan MD-2, MD-1 stb. napként következteti.",
            scope="Mikrociklus",
        ))
        return insights

    train = daily[daily["session_type"] == "Edzés"].copy()
    match = daily[daily["session_type"] == "Meccs"].copy()

    # Maximális sebességű inger: történt-e értelmezhető sprintinger a meccs előtti napokban?
    if not train.empty and "sprint_distance" in daily.columns and not match.empty:
        match_sprint = match["sprint_distance"].mean()
        max_training_sprint = train["sprint_distance"].max()
        if pd.notna(match_sprint) and match_sprint > 0:
            ratio = max_training_sprint / match_sprint if pd.notna(max_training_sprint) else 0
            if ratio < 0.15:
                insights.append(Insight(
                    "Hiányzó maximális sebességű inger", "KRITIKUS",
                    f"A héten nem látszik érdemi sprintinger: a legmagasabb edzésnapi sprintterhelés a meccs kb. {ratio:.0%}-a.",
                    "Meccsigényhez képest alacsony lehetett a maximális sebességű inger, ami a felkészítés minőségét ronthatja.",
                    "Érdemes lehet egy rövid, kontrollált maximális sebességű inger blokkot betervezni a megfelelő napon, ha a heti cél és a játékosállapot engedi.",
                    scope="Mikrociklus",
                ))
            elif ratio < 0.30:
                insights.append(Insight(
                    "Alacsony maximális sebességű inger", "FIGYELMEZTETÉS",
                    f"A legmagasabb edzésnapi sprintterhelés a meccs kb. {ratio:.0%}-a.",
                    "Volt sprintinger, de a meccsigényhez képest visszafogott lehetett.",
                    "Érdemes ellenőrizni, hogy ez tudatos frissítés vagy nem kívánt intenzitáshiány volt-e.",
                    scope="Mikrociklus",
                ))

    # MD-2 túl magas load
    md2 = daily[daily["md_label"] == "MD-2"]
    md3_4 = daily[daily["md_label"].isin(["MD-3", "MD-4"])]
    if not md2.empty and not md3_4.empty:
        md2_load = md2["load_index"].sum()
        peak_early = md3_4["load_index"].max()
        if pd.notna(md2_load) and pd.notna(peak_early) and peak_early > 0 and md2_load > peak_early * 0.80:
            insights.append(Insight(
                "Magas MD-2 terhelés", "FIGYELMEZTETÉS",
                "Az MD-2 nap terhelése közel volt a hét korábbi fő terhelési napjához.",
                "A mérkőzés előtti 48 órában a túl magas load ronthatja a frissességet.",
                "Érdemes lehet az MD-2 napot jobban kontrollálni, és a fő terhelési ingert inkább MD-3 / MD-4 környékére helyezni.",
                scope="Mikrociklus",
            ))

    # MD-1 activation kontroll
    md1 = daily[daily["md_label"] == "MD-1"]
    if not md1.empty and not md2.empty:
        md1_load = md1["load_index"].sum()
        md2_load = md2["load_index"].sum()
        if pd.notna(md1_load) and pd.notna(md2_load) and md2_load > 0 and md1_load > md2_load * 0.85:
            insights.append(Insight(
                "MD-1 activation túl erős lehet", "FIGYELMEZTETÉS",
                "Az MD-1 load nem csökkent érdemben az MD-2 naphoz képest.",
                "A meccs előtti aktiváció célja általában a frissítés, nem egy újabb nagy terhelési inger.",
                "Érdemes lehet az MD-1 napot rövidebb, frissebb, idegrendszeri aktivációs jelleggel tartani.",
                scope="Mikrociklus",
            ))

    # Pozitív taper insight, ha van adat és nincs túl magas MD-1/MD-2
    if not md1.empty and not md3_4.empty:
        md1_load = md1["load_index"].sum()
        peak_early = md3_4["load_index"].max()
        if pd.notna(md1_load) and pd.notna(peak_early) and peak_early > 0 and md1_load < peak_early * 0.45:
            insights.append(Insight(
                "Megfelelő tapering jel", "INFORMÁCIÓ",
                "A meccs előtti nap terhelése jelentősen alacsonyabb volt a hét fő terhelési napjához képest.",
                "Ez támogathatja a mérkőzésnapi frissességet.",
                "Érdemes megtartani ezt a struktúrát, ha a mérkőzésnapi teljesítmény is visszaigazolja.",
                scope="Mikrociklus",
            ))

    return insights


def playstyle_insights(df: pd.DataFrame, selected_week: str, playstyle: str) -> List[Insight]:
    insights: List[Insight] = []
    if playstyle == "Kiegyensúlyozott":
        return insights
    current = df[df["week"] == selected_week]
    train = current[current["session_type"] == "Edzés"]
    match = current[current["session_type"] == "Meccs"]
    if train.empty:
        return insights

    def mean_ratio(metric: str) -> Optional[float]:
        if metric not in current.columns or match.empty:
            return None
        m = match[metric].mean()
        t = train[metric].mean()
        if pd.isna(m) or m == 0 or pd.isna(t):
            return None
        return t / m

    intensity_ratio = mean_ratio("distance_per_min")
    sprint_ratio = mean_ratio("sprint_distance")
    effort_ratio = mean_ratio("high_efforts")

    if playstyle == "Pressing":
        if intensity_ratio is not None and intensity_ratio < 0.90:
            insights.append(Insight(
                "Pressing profil: intenzitáshiány", "FIGYELMEZTETÉS",
                f"A heti edzésintenzitás a meccsintenzitás kb. {intensity_ratio:.0%}-a.",
                "Pressing játékmodellnél fontos, hogy a csapat rendszeresen találkozzon magas munkasűrűségű helyzetekkel.",
                "Érdemes lehet rövidebb, nagyobb nyomású játékokat vagy pressing-specifikus blokkokat használni.",
                scope="Játékmodell",
            ))
        if effort_ratio is not None and effort_ratio < 0.75:
            insights.append(Insight(
                "Pressing profil: kevés nagy intenzitású erőfeszítés", "FIGYELMEZTETÉS",
                f"A high effort profil a meccsigény kb. {effort_ratio:.0%}-a.",
                "A sok gyorsulás, lassítás és ismételt intenzív akció kulcs a pressing identitáshoz.",
                "Érdemes lehet növelni az ismételt intenzív akciókat tartalmazó gyakorlatok arányát.",
                scope="Játékmodell",
            ))

    elif playstyle == "Transition":
        if sprint_ratio is not None and sprint_ratio < 0.80:
            insights.append(Insight(
                "Transition profil: alacsony sprintinger", "FIGYELMEZTETÉS",
                f"A heti sprintprofil a meccsigény kb. {sprint_ratio:.0%}-a.",
                "Átmenetekre építő játékmodellben fontos a rendszeres nagysebességű inger.",
                "Érdemes célzott átmeneti játékokat vagy nagy területű sprinthelyzeteket beépíteni.",
                scope="Játékmodell",
            ))

    elif playstyle == "Possession":
        if intensity_ratio is not None and intensity_ratio > 1.15:
            insights.append(Insight(
                "Possession profil: magas edzésintenzitás", "INFORMÁCIÓ",
                f"Az edzésintenzitás meghaladta a meccsintenzitást: kb. {intensity_ratio:.0%}.",
                "Ez lehet tudatos túlterhelés, de possession modellnél a kontrollált terhelés is fontos.",
                "Érdemes ellenőrizni, hogy az intenzitás a játékelvek tanulását vagy inkább csak a fizikai terhelést szolgálta-e.",
                scope="Játékmodell",
            ))

    elif playstyle == "Low Block":
        if sprint_ratio is not None and sprint_ratio < 0.60:
            insights.append(Insight(
                "Low block profil: kevés átmeneti sprintinger", "FIGYELMEZTETÉS",
                f"A sprintprofil a meccsigény kb. {sprint_ratio:.0%}-a.",
                "Mélyebb védekezésnél is fontosak lehetnek a rövid, robbanékony átmenetek.",
                "Érdemes lehet kontrollált kontra- és visszarendeződési szituációkat alkalmazni.",
                scope="Játékmodell",
            ))
    return insights



def html_linebreaks(text: object) -> str:
    """Streamlit markdown/HTML megjelenítéshez: a literal \\n karaktereket valódi sortöréssé alakítja."""
    safe = str(text or "").replace("\\n", "\n").replace("\\r", "")
    return html.escape(safe).replace("\n", "<br>")


def week_label_short(week_value: object) -> str:
    """Hosszú pandas week labelből rövid, dashboard-barát hét címke."""
    txt = str(week_value or "")
    if "/" in txt:
        try:
            start = pd.to_datetime(txt.split("/")[0])
            return f"{start.strftime('%Y')}-W{int(start.isocalendar().week):02d}"
        except Exception:
            return txt.split("/")[0]
    return txt


