# -----------------------------------------------------------------------------
# V4.3 - Productized Demo / Pro layer - unique Streamlit export keys
# -----------------------------------------------------------------------------
DEMO_PLAYER_LIMIT = 8
DEMO_WEEK_LIMIT = 3
DEMO_ROW_LIMIT = 5000

# -----------------------------------------------------------------------------
# V420 - Backward-compatible dual Supabase access
# -----------------------------------------------------------------------------
# Two access paths run in parallel:
#
# A) LEGACY / grandfathered users
#    Existing e-mail + activation-code access stays valid through the existing
#    public.licenses table and public.validate_license RPC. No existing user
#    needs to be migrated immediately.
#
# B) NAMED USER / new commercial model
#    Supabase Auth e-mail + password + public.fpi_user_licenses. This path can
#    enforce named-user licences, device limits and one active FPI session.
#
# IMPORTANT:
# - Do NOT drop the existing licenses table or validate_license RPC while any
#   legacy customer still uses an activation code.
# - New customers should normally be created in Supabase Auth +
#   fpi_user_licenses.
# - Legacy customers can be migrated one by one later, with no hard cut-over.
#
# Required Streamlit secrets:
#   SUPABASE_URL = "https://...supabase.co"
#   SUPABASE_PUBLISHABLE_KEY = "sb_publishable_..."   # preferred
# or:
#   SUPABASE_ANON_KEY = "..."
#   LICENSE_SALT = "existing-legacy-license-salt"     # keep unchanged
#   DEVICE_HASH_SALT = "long-random-secret"           # recommended for named users
#
# Never place a Supabase secret/service-role key in this client application.


def get_secret_value(name: str, default: str = "") -> str:
    try:
        if name in st.secrets:
            return str(st.secrets[name])
    except Exception:
        pass
    return os.getenv(name, default)


def _fpi_new_supabase_client():
    url = get_secret_value("SUPABASE_URL")
    key = get_secret_value("SUPABASE_PUBLISHABLE_KEY") or get_secret_value("SUPABASE_ANON_KEY")
    if not url or not key or create_client is None:
        return None
    try:
        return create_client(url, key)
    except Exception:
        return None


def get_supabase_client():
    """Return the per-Streamlit-session Supabase client for named-user Auth.

    Do not cache this globally: a Supabase client may carry the authenticated
    user's in-memory Auth session. Global sharing between visitors would be a
    security bug.
    """
    client = st.session_state.get("_fpi_supabase_client")
    if client is not None:
        return client
    client = _fpi_new_supabase_client()
    if client is not None:
        st.session_state["_fpi_supabase_client"] = client
    return client


def _fpi_rpc_dict(data) -> Dict[str, object]:
    if isinstance(data, list):
        data = data[0] if data else None
    return dict(data) if isinstance(data, dict) else {}


# -----------------------------
# Legacy activation-code access
# -----------------------------
def hash_license_key(raw_key: str) -> str:
    # MUST stay identical to the old production logic, otherwise existing
    # activation codes would stop matching the hashes stored in Supabase.
    salt = get_secret_value("LICENSE_SALT", "performance-intelligence")
    return hashlib.sha256((salt + "::" + str(raw_key).strip()).encode("utf-8")).hexdigest()


def _validate_legacy_license_hash_supabase(email: str, license_hash: str) -> Dict[str, object]:
    """Validate a legacy licence using the existing validate_license RPC.

    We keep only the hash in Streamlit session_state, never the raw activation
    code. This lets us re-check expiry/is_active periodically without asking the
    user for the code again during the same browser session.
    """
    email = str(email or "").strip().lower()
    license_hash = str(license_hash or "").strip()
    if not email or not license_hash:
        return {"ok": False, "message": "Hiányzó régi licencadat."}

    client = _fpi_new_supabase_client()  # anonymous client, separate from named Auth client
    if client is None:
        return {"ok": False, "message": "Supabase kapcsolat nincs beállítva. Demo módban folytatható."}

    try:
        resp = client.rpc("validate_license", {
            "p_email": email,
            "p_license_hash": license_hash,
        }).execute()
        data = _fpi_rpc_dict(resp.data)
        if not data:
            return {"ok": False, "message": "Nem található aktív licenc ehhez az e-mailhez és kódhoz."}
        if not data.get("ok"):
            return {"ok": False, "message": data.get("message", "A licenc nem aktív vagy lejárt.")}

        team_name = str(data.get("team_name") or "").strip()
        result = {
            "ok": True,
            "auth_mode": "legacy",
            "email": str(data.get("email") or email),
            "plan": str(data.get("plan") or "pro"),
            "club_name": str(data.get("club_name") or ""),
            "team_name": team_name,
            "licensed_teams": [team_name] if team_name else [],
            "license_id": str(data.get("license_id") or ""),
            "legacy_license_hash": license_hash,
            "message": "Pro hozzáférés aktív (meglévő licenc).",
        }
        return result
    except Exception as exc:
        return {"ok": False, "message": f"Licencellenőrzési hiba: {exc}"}


def validate_legacy_license_supabase(email: str, license_key: str) -> Dict[str, object]:
    email = str(email or "").strip().lower()
    license_key = str(license_key or "").strip()
    if not email or not license_key:
        return {"ok": False, "message": "Add meg az e-mail címet és az aktiváló kódot."}

    # Preserve the old emergency/fallback behaviour if it is still configured.
    fallback = get_secret_value("FALLBACK_PRO_CODE")
    if fallback and license_key == fallback:
        return {
            "ok": True,
            "auth_mode": "legacy_fallback",
            "email": email,
            "plan": "pro",
            "club_name": "Pro klub",
            "team_name": "Pro csapat",
            "licensed_teams": ["Pro csapat"],
            "license_id": "fallback",
            "message": "Pro hozzáférés aktív (meglévő licenc).",
        }

    return _validate_legacy_license_hash_supabase(email, hash_license_key(license_key))


# -----------------------------
# Named-user access
# -----------------------------
def _fpi_browser_device_seed() -> str:
    """Best-effort browser-persistent random seed for MVP device control.

    Streamlit's built-in cookie interface is read-only. To avoid adding an
    extra third-party cookie component, V421 stores a random opaque seed in a
    query parameter. It survives normal reruns/reloads of the same URL. The
    seed is combined with coarse browser context and hashed before Supabase
    receives it. It is a licence-abuse signal, not a hardware fingerprint.
    """
    key = "_fpi_d"
    try:
        raw = st.query_params.get(key, "")
        if isinstance(raw, list):
            raw = raw[0] if raw else ""
        raw = str(raw or "").strip()
        if not raw:
            raw = secrets.token_urlsafe(18)
            st.query_params[key] = raw
        return raw
    except Exception:
        if "_fpi_device_seed_fallback" not in st.session_state:
            st.session_state["_fpi_device_seed_fallback"] = secrets.token_urlsafe(18)
        return str(st.session_state["_fpi_device_seed_fallback"])


def _fpi_context_value(name: str, default: str = "") -> str:
    try:
        ctx = getattr(st, "context", None)
        if ctx is None:
            return default
        value = getattr(ctx, name, default)
        return str(value or default)
    except Exception:
        return default


def _fpi_header_value(name: str, default: str = "") -> str:
    try:
        ctx = getattr(st, "context", None)
        headers = getattr(ctx, "headers", None) if ctx is not None else None
        if headers is None:
            return default
        value = headers.get(name, default)
        return str(value or default)
    except Exception:
        return default


def _fpi_device_hash() -> str:
    seed = _fpi_browser_device_seed()
    coarse_context = "|".join([
        seed,
        _fpi_header_value("User-Agent"),
        _fpi_header_value("Sec-CH-UA-Platform"),
        _fpi_header_value("Sec-CH-UA-Mobile"),
        _fpi_context_value("locale"),
        _fpi_context_value("timezone"),
    ])
    salt = get_secret_value("DEVICE_HASH_SALT") or get_secret_value("LICENSE_SALT", "fpi-device-v421")
    return hashlib.sha256((salt + "::" + coarse_context).encode("utf-8")).hexdigest()


def _fpi_session_token_hash() -> str:
    if "_fpi_runtime_session_token" not in st.session_state:
        st.session_state["_fpi_runtime_session_token"] = secrets.token_urlsafe(32)
    raw = str(st.session_state["_fpi_runtime_session_token"])
    salt = get_secret_value("DEVICE_HASH_SALT") or get_secret_value("LICENSE_SALT", "fpi-session-v421")
    return hashlib.sha256((salt + "::" + raw).encode("utf-8")).hexdigest()


def _fpi_license_rpc(client) -> Dict[str, object]:
    try:
        resp = client.rpc("fpi_get_current_license", {}).execute()
        return _fpi_rpc_dict(resp.data)
    except Exception as exc:
        return {"ok": False, "message": f"Licencellenőrzési hiba: {exc}"}


def _fpi_mark_password_changed_rpc(client) -> Dict[str, object]:
    """Clear the named user's one-time must_change_password flag.

    Requires the V422 Supabase migration, which exposes the authenticated-only
    public.fpi_mark_password_changed() SECURITY DEFINER RPC.
    """
    try:
        resp = client.rpc("fpi_mark_password_changed", {}).execute()
        data = _fpi_rpc_dict(resp.data)
        if data:
            return data
        return {"ok": False, "message": "A jelszócsere státusza nem frissíthető."}
    except Exception as exc:
        return {"ok": False, "message": f"A jelszócsere státuszának mentése nem sikerült: {exc}"}


def _fpi_register_device_rpc(client, device_hash: str) -> Dict[str, object]:
    try:
        ua = _fpi_header_value("User-Agent")[:500]
        platform = _fpi_header_value("Sec-CH-UA-Platform")[:120]
        label = platform.strip('"') or "FPI eszköz"
        resp = client.rpc("fpi_register_device", {
            "p_device_hash": device_hash,
            "p_user_agent": ua,
            "p_device_label": label,
        }).execute()
        return _fpi_rpc_dict(resp.data)
    except Exception as exc:
        return {"ok": False, "message": f"Eszközellenőrzési hiba: {exc}"}


def _fpi_claim_session_rpc(client, device_hash: str, session_hash: str) -> Dict[str, object]:
    try:
        resp = client.rpc("fpi_claim_session", {
            "p_device_hash": device_hash,
            "p_session_token_hash": session_hash,
        }).execute()
        return _fpi_rpc_dict(resp.data)
    except Exception as exc:
        return {"ok": False, "message": f"Munkamenet-ellenőrzési hiba: {exc}"}


def _fpi_query_param_first_v421(name: str, default: str = "") -> str:
    """Return one query-parameter value without ever logging sensitive callback tokens."""
    try:
        value = st.query_params.get(name, default)
        if isinstance(value, list):
            value = value[0] if value else default
        return str(value or default).strip()
    except Exception:
        return str(default or "")


def _fpi_remove_auth_query_params_v421() -> None:
    """Remove one-time auth callback parameters while preserving unrelated params (e.g. device seed)."""
    for key in (
        "token_hash", "type", "fpi_auth", "code",
        "error", "error_code", "error_description",
    ):
        try:
            if key in st.query_params:
                del st.query_params[key]
        except Exception:
            try:
                st.query_params.pop(key, None)
            except Exception:
                pass


def _fpi_clear_invite_state_v421() -> None:
    for key in (
        "_fpi_invite_pending_v421",
        "_fpi_invite_user_id_v421",
        "_fpi_invite_email_v421",
        "_fpi_invite_verified_at_v421",
    ):
        st.session_state.pop(key, None)


def _fpi_complete_named_user_session(client, email_hint: str = "") -> Dict[str, object]:
    """Apply FPI licence, device and single-session controls to an already authenticated Supabase user."""
    if client is None:
        return {"ok": False, "message": "Supabase kapcsolat nincs beállítva."}

    try:
        user_resp = client.auth.get_user()
        user = getattr(user_resp, "user", None)
        if user is None or not getattr(user, "id", None):
            return {"ok": False, "message": "A bejelentkezett felhasználó nem ellenőrizhető."}
    except Exception:
        return {"ok": False, "message": "A bejelentkezett felhasználó nem ellenőrizhető."}

    lic = _fpi_license_rpc(client)
    if not lic.get("ok"):
        return {"ok": False, "message": lic.get("message", "Ehhez a felhasználóhoz nincs aktív FPI licenc.")}

    device_hash = _fpi_device_hash()
    device = _fpi_register_device_rpc(client, device_hash)
    if not device.get("ok"):
        return {"ok": False, "message": device.get("message", "Ez az eszköz nincs engedélyezve.")}

    session_hash = _fpi_session_token_hash()
    claimed = _fpi_claim_session_rpc(client, device_hash, session_hash)
    if not claimed.get("ok"):
        return {"ok": False, "message": claimed.get("message", "A licenc egy másik aktív munkamenetben használatban van.")}

    user_email = str(lic.get("email") or getattr(user, "email", "") or email_hint or "").strip().lower()
    result = {
        "ok": True,
        "auth_mode": "named",
        "user_id": str(lic.get("user_id") or getattr(user, "id", "")),
        "email": user_email,
        "full_name": str(lic.get("full_name") or ""),
        "club_name": str(lic.get("club_name") or ""),
        "licensed_teams": list(lic.get("licensed_teams") or []),
        "plan": str(lic.get("plan") or "pro"),
        "expires_at": lic.get("expires_at"),
        "max_devices": lic.get("max_devices"),
        "must_change_password": bool(lic.get("must_change_password", False)),
        "device_hash": device_hash,
        "session_token_hash": session_hash,
        "message": "Pro hozzáférés aktív.",
    }
    st.session_state["_fpi_supabase_client"] = client
    st.session_state["_fpi_auth_user_id"] = result["user_id"]
    st.session_state["_fpi_auth_last_heartbeat"] = time.time()
    st.session_state["user_email"] = result["email"]
    return result


def _fpi_handle_invite_callback_v421() -> bool:
    """Verify a custom Supabase invite callback carrying token_hash in the query string.

    Required Invite User e-mail template link:
    {{ .SiteURL }}?fpi_auth=invite&token_hash={{ .TokenHash }}&type=invite

    Supabase's default confirmation URL can return the Auth session in a URL fragment,
    which a server-side Streamlit app cannot read via st.query_params. V421 therefore
    intentionally uses TokenHash + verify_otp for the invitation callback.
    """
    if st.session_state.get("_fpi_invite_pending_v421"):
        return True

    flow = _fpi_query_param_first_v421("fpi_auth").lower()
    token_hash = _fpi_query_param_first_v421("token_hash")
    otp_type = _fpi_query_param_first_v421("type").lower()

    # Only consume links explicitly intended for the FPI invitation flow.
    if flow != "invite" and otp_type != "invite":
        return False
    if not token_hash:
        st.session_state["_fpi_auth_message"] = (
            "A meghívó linkből hiányzik az aktiváló token. Küldj új FPI-meghívót a V421 sablonnal."
        )
        _fpi_remove_auth_query_params_v421()
        return False

    client = _fpi_new_supabase_client()
    if client is None:
        st.session_state["_fpi_auth_message"] = "Supabase kapcsolat nincs beállítva; a meghívó nem ellenőrizhető."
        return False

    try:
        client.auth.verify_otp({
            "token_hash": token_hash,
            "type": "invite",
        })
        user_resp = client.auth.get_user()
        user = getattr(user_resp, "user", None)
        if user is None or not getattr(user, "id", None):
            raise RuntimeError("invite verification returned no authenticated user")
    except Exception:
        _fpi_remove_auth_query_params_v421()
        st.session_state["_fpi_auth_message"] = (
            "A meghívó link érvénytelen, lejárt vagy már felhasználták. Küldj új meghívót."
        )
        return False

    st.session_state["_fpi_supabase_client"] = client
    st.session_state["_fpi_invite_pending_v421"] = True
    st.session_state["_fpi_invite_user_id_v421"] = str(getattr(user, "id", ""))
    st.session_state["_fpi_invite_email_v421"] = str(getattr(user, "email", "") or "").strip().lower()
    st.session_state["_fpi_invite_verified_at_v421"] = time.time()
    if st.session_state["_fpi_invite_email_v421"]:
        st.session_state["user_email"] = st.session_state["_fpi_invite_email_v421"]

    # TokenHash is one-time sensitive material. Remove it immediately after verification.
    _fpi_remove_auth_query_params_v421()
    return True


def render_invite_activation_panel_v421() -> None:
    """First-login password setup shown only after a verified Supabase invitation."""
    st.markdown(
        """
        <div style="max-width:760px;margin:30px auto 16px auto;padding:26px 28px;border-radius:24px;
                    background:#ffffff;border:1px solid #dbeafe;box-shadow:0 18px 46px rgba(15,23,42,.12);">
            <div style="font-size:.82rem;font-weight:900;letter-spacing:.07em;color:#0f766e;">FPI FIÓKAKTIVÁLÁS</div>
            <div style="font-size:1.8rem;font-weight:950;color:#0f172a;margin-top:5px;">Állíts be saját jelszót</div>
            <div style="color:#475569;margin-top:8px;line-height:1.45;">
                A meghívó ellenőrzése sikerült. Ez a névre szóló fiók egyetlen szerződésben megjelölt felhasználóhoz tartozik.
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    client = st.session_state.get("_fpi_supabase_client")
    invite_email = str(st.session_state.get("_fpi_invite_email_v421") or "")
    if client is None:
        st.error("Az aktiválási munkamenet megszakadt. Kérj új meghívót.")
        if st.button("Vissza a belépéshez", key="invite_back_no_client_v421"):
            _fpi_clear_invite_state_v421()
            _fpi_remove_auth_query_params_v421()
            st.rerun()
        return

    if invite_email:
        st.info(f"Meghívott fiók: {invite_email}")

    p1 = st.text_input(
        "Új jelszó",
        type="password",
        key="invite_password_1_v421",
        help="Legalább 10 karaktert javaslunk; használj egyedi jelszót.",
    )
    p2 = st.text_input(
        "Új jelszó még egyszer",
        type="password",
        key="invite_password_2_v421",
    )

    c1, c2 = st.columns([1.25, 1])
    with c1:
        if st.button("Fiók aktiválása", type="primary", use_container_width=True, key="invite_set_password_v421"):
            if len(str(p1 or "")) < 10:
                st.warning("A jelszó legyen legalább 10 karakter.")
                return
            if p1 != p2:
                st.warning("A két jelszó nem egyezik.")
                return

            try:
                client.auth.update_user({"password": p1})
            except Exception as exc:
                st.error(f"A jelszó beállítása nem sikerült: {exc}")
                return

            result = _fpi_complete_named_user_session(client, email_hint=invite_email)
            _fpi_clear_invite_state_v421()
            _fpi_remove_auth_query_params_v421()

            if result.get("ok"):
                st.session_state["license_status"] = result
                st.session_state["_fpi_auth_message"] = "FPI-fiók aktiválva. Sikeres Pro belépés."
                st.session_state["fpi_active_page_v100"] = "landing"
                st.rerun()

            # Password setup succeeded, but FPI licence/device/session activation did not.
            try:
                client.auth.sign_out()
            except Exception:
                pass
            st.session_state.pop("_fpi_supabase_client", None)
            st.session_state["_fpi_auth_message"] = (
                "A jelszó sikeresen beállítva, de az FPI hozzáférés még nem aktiválható: "
                + str(result.get("message", "nincs aktív licenc"))
                + " Most már a saját e-mail + jelszó párossal tudsz belépni, amint a licenc aktív."
            )
            st.session_state["fpi_active_page_v100"] = "landing"
            st.rerun()

    with c2:
        if st.button("Megszakítás", use_container_width=True, key="invite_cancel_v421"):
            try:
                client.auth.sign_out()
            except Exception:
                pass
            st.session_state.pop("_fpi_supabase_client", None)
            _fpi_clear_invite_state_v421()
            _fpi_remove_auth_query_params_v421()
            st.session_state["_fpi_auth_message"] = "A fiókaktiválást megszakítottad."
            st.session_state["fpi_active_page_v100"] = "landing"
            st.rerun()

def _fpi_clear_local_auth(keep_message: bool = True) -> None:
    message = st.session_state.get("_fpi_auth_message") if keep_message else None
    for key in [
        "license_status", "_fpi_supabase_client", "_fpi_runtime_session_token",
        "_fpi_auth_last_heartbeat", "_fpi_auth_user_id",
        "_fpi_legacy_last_check",
    ]:
        st.session_state.pop(key, None)
    if message:
        st.session_state["_fpi_auth_message"] = message


def login_named_user_supabase(email: str, password: str) -> Dict[str, object]:
    email = str(email or "").strip().lower()
    password = str(password or "")
    if not email or not password:
        return {"ok": False, "message": "Add meg az e-mail címet és a jelszót."}

    client = _fpi_new_supabase_client()
    if client is None:
        return {"ok": False, "message": "Supabase kapcsolat nincs beállítva. Demo módban folytatható."}

    try:
        client.auth.sign_in_with_password({"email": email, "password": password})
    except Exception:
        return {"ok": False, "message": "Hibás e-mail/jelszó, vagy a felhasználó még nincs aktiválva."}

    result = _fpi_complete_named_user_session(client, email_hint=email)
    if not result.get("ok"):
        try:
            client.auth.sign_out()
        except Exception:
            pass
        return result
    return result


def _fpi_validate_new_password_v422(p1: str, p2: str) -> Dict[str, object]:
    p1 = str(p1 or "")
    p2 = str(p2 or "")
    if len(p1) < 10:
        return {"ok": False, "message": "Az új jelszó legyen legalább 10 karakter."}
    if p1 != p2:
        return {"ok": False, "message": "A két új jelszó nem egyezik."}
    return {"ok": True}


def _fpi_change_named_user_password_v422(
    new_password: str,
    new_password_again: str,
    current_password: str = "",
    verify_current: bool = False,
) -> Dict[str, object]:
    """Change the currently authenticated named user's password.

    For forced first-login changes the user has just authenticated with the
    temporary password, so verify_current=False is sufficient. For voluntary
    changes from the sidebar V422 re-verifies the current password first.
    """
    lic = st.session_state.get("license_status", {}) or {}
    if not lic.get("ok") or str(lic.get("auth_mode") or "").lower() != "named":
        return {"ok": False, "message": "Jelszót csak névre szóló, bejelentkezett FPI-fiók módosíthat."}

    valid = _fpi_validate_new_password_v422(new_password, new_password_again)
    if not valid.get("ok"):
        return valid

    client = get_supabase_client()
    if client is None:
        return {"ok": False, "message": "A Supabase kapcsolat megszakadt. Jelentkezz be újra."}

    email = str(lic.get("email") or st.session_state.get("user_email") or "").strip().lower()
    if verify_current:
        current_password = str(current_password or "")
        if not current_password:
            return {"ok": False, "message": "Add meg a jelenlegi jelszót is."}
        try:
            client.auth.sign_in_with_password({"email": email, "password": current_password})
        except Exception:
            return {"ok": False, "message": "A jelenlegi jelszó nem megfelelő."}

    try:
        client.auth.update_user({"password": str(new_password)})
    except Exception as exc:
        return {"ok": False, "message": f"A jelszó módosítása nem sikerült: {exc}"}

    # Clearing this flag is intentionally server-side. Users cannot directly
    # update their licence row through RLS.
    marked = _fpi_mark_password_changed_rpc(client)
    if not marked.get("ok"):
        return {
            "ok": False,
            "password_changed": True,
            "message": (
                "Az új jelszó már beállításra került, de a must_change_password jelzőt "
                "nem sikerült törölni. Futtasd le a V422 Supabase migrációt. Részlet: "
                + str(marked.get("message") or "ismeretlen hiba")
            ),
        }

    lic["must_change_password"] = False
    st.session_state["license_status"] = lic
    st.session_state["_fpi_auth_last_heartbeat"] = 0.0
    return {"ok": True, "message": "A jelszó sikeresen módosítva."}


