# V9.5 - KTE/Kecskemét saját csapat + GPS-only mikrociklus
# =========================================================

FPI_OWN_TEAM_ALIASES_V95 = [
    "kecskemet", "kecskemeti", "kecskeméti", "kecskemeti te", "kecskeméti te",
    "kecskemeti te hufbau", "kecskeméti te hufbau", "kecskemeti lc", "kecskemeti lc kte",
    "kte", "kte hufbau", "kecskemet te", "kecskemét", "kecskemét te",
]

def _fpi_norm_team_v95(x: object) -> str:
    s = unicodedata.normalize("NFKD", str(x or "").lower())
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    s = re.sub(r"[^a-z0-9]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()

def _fpi_is_own_team_v95(name: object) -> bool:
    n = _fpi_norm_team_v95(name)
    if not n:
        return False
    return any(alias in n for alias in [_fpi_norm_team_v95(a) for a in FPI_OWN_TEAM_ALIASES_V95])

def _fpi_pretty_team_name_v95(name: object) -> str:
    return "KTE / Kecskemét" if _fpi_is_own_team_v95(name) else str(name or "").strip()

def _fpi_mark_own_opponent_teams_v95(teams: Dict[str, str]) -> Dict[str, str]:
    out = dict(teams or {})
    a = out.get("team_a", "")
    b = out.get("team_b", "")
    if _fpi_is_own_team_v95(a):
        out["own_team"] = _fpi_pretty_team_name_v95(a)
        out["opponent_team"] = str(b or "Ellenfél")
        out["own_side"] = "a"
    elif _fpi_is_own_team_v95(b):
        out["own_team"] = _fpi_pretty_team_name_v95(b)
        out["opponent_team"] = str(a or "Ellenfél")
        out["own_side"] = "b"
    else:
        out["own_team"] = "KTE / Kecskemét"
        out["opponent_team"] = str(b or a or "Ellenfél")
        out["own_side"] = "unknown"
    return out

def _fpi_has_tactical_signal_v95(tactical_context: Optional[Dict[str, object]]) -> bool:
    if not tactical_context:
        return False
    keys = ["tactical_findings", "pdf_provider_lines", "pdf_provider_findings", "own_topics", "opp_topics", "team_comparison"]
    for k in keys:
        v = tactical_context.get(k)
        if isinstance(v, list) and len(v) > 0:
            return True
        if isinstance(v, dict) and len(v) > 0:
            return True
    if tactical_context.get("has_own_team_excel") or tactical_context.get("has_opp_team_excel") or tactical_context.get("has_own_pdf") or tactical_context.get("has_opp_pdf"):
        return True
    return False

def _fpi_gps_week_metrics_v95(ctx: Dict[str, object], week: str) -> Dict[str, object]:
    df = ctx.get("df")
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {}
    d = df.copy()

    if "session_name" in d.columns and "session_type" in d.columns:
        # V168: a session_name csak akkor lehet típus-fallback, ha a Típus mező
        # nem tartalmaz egyértelmű Edzés/Meccs értéket.
        #
        # Polar Team Pro esetén a meccssorok szakaszneve is gyakran
        # "Teljes edzésszakasz". A korábbi logika ezért a valódi Meccs sorokat
        # tévesen Edzésre írta át, így a meccsreferencia 0 lett.
        current_kind_v168 = d["session_type"].apply(_fpi_session_kind_v93)
        unknown_type_v168 = current_kind_v168.eq("other")

        training_hint_v168 = d["session_name"].astype(str).str.lower().str.contains(
            r"\bmd-\d+\b|training|train|edzés|edzes",
            regex=True,
            na=False,
        )
        match_hint_v168 = d["session_name"].astype(str).str.lower().str.contains(
            r"match|game|meccs|mérkőzés|merkozes",
            regex=True,
            na=False,
        )

        d.loc[unknown_type_v168 & training_hint_v168, "session_type"] = "Edzés"
        d.loc[unknown_type_v168 & match_hint_v168, "session_type"] = "Meccs"

    if "week" in d.columns:
        d = d[d["week"].astype(str) == str(week)].copy()
    if d.empty:
        return {}
    ratio = _fpi_match_ratio_reference_df_v97(d, week)
    ratio_map = {}
    if isinstance(ratio, pd.DataFrame) and not ratio.empty:
        for _, r in ratio.iterrows():
            ratio_map[str(r.get("Mutató", ""))] = {
                "weekly_pct": r.get("Edzés/heti meccs %"),
                "avg_pct": r.get("Edzésátlag/meccs %"),
                "eval": r.get("Értékelés", ""),
            }
    attendance = _fpi_v201_week_attendance_summary(df, week)
    analysis_mode = _fpi_v202_detect_analysis_mode(df, week)
    return {
        "analysis_mode": analysis_mode,
        "ratio": ratio,
        "ratio_map": ratio_map,
        "attendance": attendance,
        "periodization": ctx.get("periodization_type", "Nincs elég adat"),
        "summary": ctx.get("summary", ""),
    }

def _fpi_single_session_profile_v162(ctx: Dict[str, object], week: str) -> Dict[str, object]:
    """Egyetlen edzésnap felismerése és önálló edzésprofil készítése.

    Catapult esetén a Session és Period sorok ugyanahhoz az edzéshez tartozhatnak.
    Ilyenkor a napi Session összesítő sort használjuk, és nem számoljuk külön eseménynek
    a belső periódusokat.
    """
    df = ctx.get("df")
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {"is_single_session": False, "session_count": 0, "day_count": 0}

    d = df.copy()
    if "week" in d.columns:
        selected = d[d["week"].astype(str) == str(week)].copy()
        if not selected.empty:
            d = selected

    # Dátum meghatározása. Az azonos napon belüli eltérő Period Name nem új edzés.
    if "start_time" in d.columns:
        parsed_start = pd.to_datetime(d["start_time"], errors="coerce")
        session_day = parsed_start.dt.date
    elif "date" in d.columns:
        parsed_start = pd.to_datetime(d["date"], errors="coerce")
        session_day = parsed_start.dt.date
    else:
        parsed_start = pd.Series(pd.NaT, index=d.index)
        session_day = pd.Series(pd.NaT, index=d.index)

    valid_days = session_day.dropna()
    day_count = int(valid_days.nunique()) if not valid_days.empty else 0

    # Ha ugyanazon a napon van "Session" összesítő, azt preferáljuk a Period sorokkal szemben.
    if "session_name" in d.columns:
        names = d["session_name"].astype(str).str.strip().str.lower()
        session_mask = names.eq("session") | names.str.contains(
            r"^session$|full session|entire session|whole session|teljes edzés|teljes edzes",
            regex=True,
            na=False,
        )
        if session_mask.any():
            # Naponta és játékosonként csak az összesítő Session sor maradjon.
            d_session = d.loc[session_mask].copy()
            if not d_session.empty:
                d = d_session

    # Egy játékoshoz ugyanazon a napon több technikai duplikátum is tartozhat.
    player_col = "player_name" if "player_name" in d.columns else None
    if player_col:
        dedupe_cols = [player_col]
        if "start_time" in d.columns:
            d["_fpi_session_day_v163"] = pd.to_datetime(
                d["start_time"], errors="coerce"
            ).dt.date.astype(str)
            dedupe_cols.append("_fpi_session_day_v163")
        elif "date" in d.columns:
            d["_fpi_session_day_v163"] = pd.to_datetime(
                d["date"], errors="coerce"
            ).dt.date.astype(str)
            dedupe_cols.append("_fpi_session_day_v163")
        d = d.drop_duplicates(subset=dedupe_cols, keep="first").copy()

    # Eseményszám napi alapon. Ha nincs értelmezhető dátum, fájlon belül egy eseményt feltételezünk.
    session_count = day_count if day_count > 0 else 1
    is_single = session_count == 1

    player_count = (
        int(d[player_col].dropna().astype(str).nunique())
        if player_col else len(d)
    )

    def num(col: str) -> pd.Series:
        if col not in d.columns:
            return pd.Series(dtype=float)
        return pd.to_numeric(d[col], errors="coerce").replace([np.inf, -np.inf], np.nan)

    metrics = {}
    for col, label, unit in [
        ("total_distance", "Össztáv", "m"),
        ("duration_min", "Időtartam", "perc"),
        ("distance_per_min", "Intenzitás", "m/perc"),
        ("hsr_distance", "HSR", "m"),
        ("sprint_distance", "Sprinttáv", "m"),
        ("sprints", "Sprintek", "db"),
        ("high_efforts", "High Efforts", "db"),
        ("training_load", "Player Load", ""),
    ]:
        s = num(col).dropna()
        if s.empty:
            continue
        mean = float(s.mean())
        std = float(s.std(ddof=0)) if len(s) > 1 else 0.0
        cv = (std / abs(mean) * 100.0) if abs(mean) > 1e-9 else 0.0
        metrics[col] = {
            "label": label,
            "unit": unit,
            "mean": mean,
            "median": float(s.median()),
            "min": float(s.min()),
            "max": float(s.max()),
            "cv": float(cv),
            "count": int(s.notna().sum()),
        }

    extremes = {}
    if player_col:
        for col in ("total_distance", "training_load", "high_efforts"):
            if col not in d.columns:
                continue
            tmp = d[[player_col, col]].copy()
            tmp[col] = pd.to_numeric(tmp[col], errors="coerce")
            tmp = tmp.dropna(subset=[player_col, col])
            if tmp.empty:
                continue
            grouped = tmp.groupby(player_col, dropna=False)[col].sum().sort_values()
            if not grouped.empty:
                extremes[col] = {
                    "low_name": str(grouped.index[0]),
                    "low_value": float(grouped.iloc[0]),
                    "high_name": str(grouped.index[-1]),
                    "high_value": float(grouped.iloc[-1]),
                }

    return {
        "is_single_session": is_single,
        "session_count": session_count,
        "day_count": day_count,
        "player_count": player_count,
        "df": d.drop(columns=["_fpi_session_day_v163"], errors="ignore"),
        "metrics": metrics,
        "extremes": extremes,
    }

def _fpi_single_session_conclusions_v162(
    ctx: Dict[str, object],
    readiness: int,
    week: str,
    limit: int = 6,
) -> List[str]:
    profile = _fpi_single_session_profile_v162(ctx, week)
    if not profile.get("is_single_session"):
        return []

    metrics = profile.get("metrics", {})
    extremes = profile.get("extremes", {})
    players = int(profile.get("player_count", 0) or 0)
    out: List[str] = [
        f"Egyszeri edzésértékelés: {players} játékos adata áll rendelkezésre. Heti trend és meccsreferencia még nem számítható, ezért a riport az aktuális edzés belső profilját értékeli."
    ]

    dist = metrics.get("total_distance")
    dur = metrics.get("duration_min")
    dpm = metrics.get("distance_per_min")
    if dist:
        text = f"Terjedelem: játékosonként átlagosan {dist['mean']:.0f} m"
        if dur:
            text += f", {dur['mean']:.1f} perc alatt"
        if dpm:
            text += f", {dpm['mean']:.1f} m/perc átlagintenzitással"
        out.append(text + ".")

    hsr = metrics.get("hsr_distance")
    sprint_d = metrics.get("sprint_distance")
    sprint_n = metrics.get("sprints")
    speed_parts = []
    if hsr:
        speed_parts.append(f"HSR {hsr['mean']:.0f} m/fő")
    if sprint_d:
        speed_parts.append(f"sprinttáv {sprint_d['mean']:.0f} m/fő")
    if sprint_n:
        speed_parts.append(f"{sprint_n['mean']:.1f} sprint/fő")
    if speed_parts:
        out.append("Sebességi expozíció: " + ", ".join(speed_parts) + ".")

    high = metrics.get("high_efforts")
    load = metrics.get("training_load")
    neu_parts = []
    if high:
        neu_parts.append(f"High Efforts {high['mean']:.1f}/fő")
    if load:
        neu_parts.append(f"Player Load {load['mean']:.1f}/fő")
    if neu_parts:
        out.append("Neuromuszkuláris terhelés: " + ", ".join(neu_parts) + ".")

    # Szóródás: az aktuális edzés belső egyenletessége.
    variation_source = load or dist or high
    if variation_source:
        cv = float(variation_source.get("cv", 0.0))
        if cv < 12:
            judgement = "egyenletes"
        elif cv < 25:
            judgement = "mérsékelten differenciált"
        else:
            judgement = "erősen szóródó"
        out.append(
            f"Terheléseloszlás: {judgement}; a játékosok közötti relatív szóródás {cv:.0f}%. "
            "A szélsőértékeket egyénileg érdemes ellenőrizni."
        )

    ext = extremes.get("training_load") or extremes.get("total_distance")
    if ext:
        out.append(
            f"Szélsőértékek: a legmagasabb terhelést {ext['high_name']}, "
            f"a legalacsonyabbat {ext['low_name']} kapta. "
            "A különbséget a szerepkörrel, játékidővel és esetleges részleges részvétellel együtt kell értelmezni."
        )

    # Egyetlen alkalomból ne állítson hosszú távú readiness-tényeket.
    out.append(
        f"Az aktuális {readiness}/100 readiness csak előzetes munkamutató. "
        "Megbízható trendhez több egymást követő edzés és lehetőleg meccsadat szükséges."
    )

    uniq, seen = [], set()
    for text in out:
        cleaned = _fpi_clean_sentence_v82(text, 220)
        if cleaned and cleaned not in seen:
            uniq.append(cleaned)
            seen.add(cleaned)
    return uniq[:limit]


def _fpi_single_session_summary_table_v162(profile: Dict[str, object]) -> List[Dict[str, object]]:
    rows: List[Dict[str, object]] = []
    metrics = profile.get("metrics", {}) if isinstance(profile, dict) else {}
    order = [
        "duration_min", "total_distance", "distance_per_min", "hsr_distance",
        "sprint_distance", "sprints", "high_efforts", "training_load",
    ]
    for key in order:
        m = metrics.get(key)
        if not m:
            continue
        rows.append({
            "Mutató": m.get("label", key),
            "Átlag": m.get("mean"),
            "Medián": m.get("median"),
            "Minimum": m.get("min"),
            "Maximum": m.get("max"),
            "Szóródás %": m.get("cv"),
            "Egység": m.get("unit", ""),
        })
    return rows

def _fpi_gps_only_conclusions_v95(ctx: Dict[str, object], priorities: List[dict], readiness: int, week: str, limit: int = 6) -> List[str]:
    out = []
    gps = _fpi_gps_week_metrics_v95(ctx, week)
    mode = gps.get("analysis_mode", {}) or {}
    if mode:
        out.append(f"Elemzési mód: {mode.get('label', 'GPS-elemzés')}. {mode.get('description', '')}")
    ratio = gps.get("ratio")
    attendance = gps.get("attendance", {}) or {}
    team_sessions = int(attendance.get("team_training_sessions", 0) or 0)
    mean_availability = attendance.get("mean_availability_pct", np.nan)
    below_75 = int(attendance.get("below_75_players", 0) or 0)
    if team_sessions > 0 and pd.notna(mean_availability):
        out.append(
            f"Edzésrészvétel: heti {team_sessions} csapatedzés, "
            f"átlagosan {mean_availability:.0f}% játékosrészvétel; "
            f"{below_75} játékos 75% alatt."
        )
    if isinstance(ratio, pd.DataFrame) and not ratio.empty:
        for _, r in ratio.iterrows():
            mut = str(r.get("Mutató", ""))
            ev = str(r.get("Értékelés", ""))
            wp = _fpi_fmt_pct_v93(r.get("Edzés/heti meccs %"))
            ap = _fpi_fmt_pct_v93(r.get("Edzésátlag/meccs %"))
            if any(k in ev.lower() for k in ["alacsony", "magas", "kontroll", "referencia", "inger"]):
                out.append(f"{mut}: heti {wp}, edzésátlag {ap}. {ev}")
    for p in priorities or []:
        t = p.get("Teendő", p.get("Cím", "")) if isinstance(p, dict) else str(p)
        why = p.get("Miért", "") if isinstance(p, dict) else ""
        if t:
            out.append(f"{t}. {why}".strip())
    if readiness < 55:
        out.insert(0, f"Readiness {readiness}/100: óvatos, csökkentett volumenű hét javasolt.")
    elif readiness < 70:
        out.insert(0, f"Readiness {readiness}/100: vállalható hét, de a HSR/sprint inger adagolását kontrollálni kell.")
    else:
        out.insert(0, f"Readiness {readiness}/100: jó alapállapot, tervezhető specifikus HSR/sprint expozíció.")
    out.append(f"Periodizációs jelleg: {gps.get('periodization', 'Nincs elég adat')}.")
    # unique, compact
    uniq = []
    seen = set()
    for x in out:
        y = _fpi_clean_sentence_v82(x, 190)
        if y and y not in seen:
            uniq.append(y); seen.add(y)
    return uniq[:limit]

def _fpi_gps_only_md_plan_v95(ctx: Dict[str, object], readiness: int, priorities: List[dict], week: str) -> List[Tuple[str, str, str]]:
    """Taktikai input nélkül is GPS-alapú, változó mikrociklus.
    Nem fix sablon: a readiness, HSR/sprint/High Effort arányok és priority-k alapján állít fókuszt.
    """
    ratio = _fpi_match_ratio_reference_df_v97(ctx.get("df", pd.DataFrame()), week)
    low_hsr = low_sprint = high_vol = high_eff = False
    if isinstance(ratio, pd.DataFrame) and not ratio.empty:
        for _, r in ratio.iterrows():
            m = str(r.get("Mutató", "")).lower()
            eval_txt = str(r.get("Értékelés", "")).lower()
            weekly = r.get("Edzés/heti meccs %")
            if "hsr" in m and ("alacsony" in eval_txt or (pd.notna(weekly) and float(weekly) < 150)):
                low_hsr = True
            if "sprint" in m and ("alacsony" in eval_txt or (pd.notna(weekly) and float(weekly) < 100)):
                low_sprint = True
            if "volumen" in m and (pd.notna(weekly) and float(weekly) > 420):
                high_vol = True
            if "high efforts" in m and (pd.notna(weekly) and float(weekly) > 280):
                high_eff = True

    ptxt = " ".join([str(p.get("Teendő", p.get("Cím", ""))) for p in priorities or [] if isinstance(p, dict)]).lower()
    if "sprint" in ptxt:
        low_sprint = True
    if "hsr" in ptxt or "nagy sebess" in ptxt:
        low_hsr = True
    if "terhel" in ptxt and ("magas" in ptxt or "csökk" in ptxt):
        high_vol = True

    if readiness < 55:
        return [
            ("MD-4", "Regeneráció + alacsony/közepes volumen", "Terhelési visszarendezés, readiness javítása."),
            ("MD-3", "Rövid HSR/sprint expozíció", "Csak idegrendszeri inger, alacsony ismétlésszám."),
            ("MD-2", "Frissítés + technikai intenzitás", "Rövid blokkok, terhelés kontroll."),
            ("MD-1", "Aktiváció", "Rövid gyors döntések, friss láb prioritás."),
        ]
    if high_vol or high_eff:
        return [
            ("MD-4", "Volumen kontroll + aerob visszarendezés", "A heti összterhelés/High Effort magas, ne halmozzunk új terhelést."),
            ("MD-3", "Minőségi, rövid HSR/sprint inger", "Sebességexpozíció volumen nélkül."),
            ("MD-2", "Alacsony volumen + reakciógyorsaság", "Readiness megtartása, frissítés."),
            ("MD-1", "Aktiváció + mobilitás", "Idegrendszeri frissítés, minimális fárasztás."),
        ]
    if low_hsr or low_sprint:
        return [
            ("MD-4", "Stabil csapatvolumen", "Általános heti alap terhelés felépítése."),
            ("MD-3", "HSR/sprint expozíció nap", "Hiányzó nagy sebességű/sprint inger pótlása kontrolláltan."),
            ("MD-2", "High Effort + rövid intenzív blokkok", "Pressing/transition jellegű fizikai inger, de rövid volumen."),
            ("MD-1", "Aktiváció", "Frissítés, 3-5 rövid gyors akció."),
        ]
    return [
        ("MD-4", "Fő terhelési nap", "Volumen és HSR referenciazóna fenntartása."),
        ("MD-3", "Specifikus intenzitási nap", "HSR/sprint/High Effort kontrollált meccsinger."),
        ("MD-2", "Terhelés csökkentése", "Frissesség megtartása, egyéni risk kontroll."),
        ("MD-1", "Aktiváció", "Rövid gyorsasági és döntési inger."),
    ]


def _build_fpi_product_pdf_bytes_v402_base(
    data: pd.DataFrame,
    selected_week: Optional[str] = None,
    playstyle: str = "Kiegyensúlyozott",
    report_type: str = "full",
    demo_label: str = "",
    tactical_context: Optional[Dict[str, object]] = None,
) -> Optional[bytes]:
    """Egységes PDF motor.

    report_type:
    - executive: 1-2 oldalas vezetőedzői / sportigazgatói riport
    - fitness: részletes erőnléti riport
    - microcycle: múlt hét / aktuális hét / jövő hét terv
    - full: teljes döntéstámogató csomag
    """
    if SimpleDocTemplate is None:
        return None
    from reportlab.platypus import PageBreak

    ctx = _fpi_report_context(data, selected_week, playstyle)
    if ctx.get("error"):
        return None
    tactical_context = tactical_context if tactical_context is not None else st.session_state.get("tactical_pro_context", None)

    df = ctx["df"]
    week = ctx["selected_week"]
    readiness = int(ctx["readiness_score"])
    risk_df = ctx["risk_df"] if isinstance(ctx.get("risk_df"), pd.DataFrame) else pd.DataFrame()
    priorities = ctx.get("priorities", []) or []
    insights_df = ctx["insights_df"] if isinstance(ctx.get("insights_df"), pd.DataFrame) else pd.DataFrame()
    weekly = ctx["weekly"] if isinstance(ctx.get("weekly"), pd.DataFrame) else pd.DataFrame()
    player_week = ctx["player_week"] if isinstance(ctx.get("player_week"), pd.DataFrame) else pd.DataFrame()
    player_actions = ctx["player_actions_df"] if isinstance(ctx.get("player_actions_df"), pd.DataFrame) else pd.DataFrame()
    next_df = ctx["next_df"] if isinstance(ctx.get("next_df"), pd.DataFrame) else pd.DataFrame()
    current_df = ctx["current_df"] if isinstance(ctx.get("current_df"), pd.DataFrame) else pd.DataFrame()
    high_risk, med_risk = _fpi_count_risk_levels_v126(risk_df)
    week_type_label_v126 = _fpi_pdf_week_type_label_v126(ctx, demo_label)

    font_name, font_bold = _register_pdf_font()
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=landscape(A4), rightMargin=0.9*cm, leftMargin=0.9*cm, topMargin=0.7*cm, bottomMargin=0.7*cm)
    styles = getSampleStyleSheet()
    title = ParagraphStyle("FPI58Title", parent=styles["Title"], fontName=font_bold, fontSize=22, leading=26, textColor=colors.HexColor("#0F172A"))
    sub = ParagraphStyle("FPI58Sub", parent=styles["Normal"], fontName=font_name, fontSize=10.2, leading=13.2, textColor=colors.HexColor("#334155"), alignment=4)
    h2 = ParagraphStyle("FPI58H2", parent=styles["Heading2"], fontName=font_bold, fontSize=14.0, leading=17.0, textColor=colors.HexColor("#0F172A"))
    body = ParagraphStyle("FPI58Body", parent=styles["Normal"], fontName=font_name, fontSize=10.6, leading=14.0, textColor=colors.HexColor("#111827"), alignment=4)
    small = ParagraphStyle("FPI58Small", parent=styles["Normal"], fontName=font_name, fontSize=9.4, leading=12.4, textColor=colors.HexColor("#111827"), alignment=4)
    head = ParagraphStyle("FPI58Head", parent=styles["Normal"], fontName=font_bold, fontSize=10.7, leading=13.0, alignment=1, textColor=colors.white)
    white_big = ParagraphStyle("FPI58WhiteBig", parent=styles["Normal"], fontName=font_bold, fontSize=17, leading=20, alignment=1, textColor=colors.white)
    white_small = ParagraphStyle("FPI58WhiteSmall", parent=styles["Normal"], fontName=font_name, fontSize=8.4, leading=10.5, alignment=1, textColor=colors.white)
    callout = ParagraphStyle("FPI58Callout", parent=body, fontName=font_bold, fontSize=11.4, leading=14.7, textColor=colors.HexColor("#0F172A"), alignment=4)
    player_label = ParagraphStyle("FPI58PlayerLabel", parent=h2, fontName=font_bold, fontSize=13.0, leading=16.0, textColor=colors.HexColor("#FFFFFF"), alignment=0)

    def clean(v: object) -> str:
        text = pdf_safe_text(v).replace("\r", "")
        text = re.sub(r"(?i)<br\s*/?>", "\n", text)
        text = re.sub(r"(?is)\{\s*['\"]Téma['\"].*?\}", "", text)
        text = re.sub(r"(?is)\{\s*['\"]Tema['\"].*?\}", "", text)
        text = re.sub(r"(?is)\{\s*['\"]Bizonyíték['\"].*?\}", "", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

    def P(v, style=body):
        escaped = html.escape(clean(v)).replace("\n", "<br/>")
        # Csak a saját kiemelőmotor által létrehozott alap ReportLab tageket engedjük vissza.
        escaped = (
            escaped
            .replace("&lt;b&gt;", "<b>")
            .replace("&lt;/b&gt;", "</b>")
            .replace("&lt;i&gt;", "<i>")
            .replace("&lt;/i&gt;", "</i>")
        )
        return Paragraph(escaped, style)

    def section(text: str, color: str = "#DBEAFE"):
        t = Table([[P(text, h2)]], colWidths=[27.7*cm])
        t.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,-1), colors.HexColor(color)),
            ("BOX", (0,0), (-1,-1), 0.4, colors.HexColor("#93C5FD")),
            ("LEFTPADDING", (0,0), (-1,-1), 7), ("RIGHTPADDING", (0,0), (-1,-1), 7),
            ("TOPPADDING", (0,0), (-1,-1), 4), ("BOTTOMPADDING", (0,0), (-1,-1), 4),
        ]))
        return t

    def table(rows, widths, header_bg="#0F172A", row_bgs=None):
        if row_bgs is None:
            row_bgs = [colors.white, colors.HexColor("#F8FAFC")]
        t = Table(rows, colWidths=widths, repeatRows=1)
        t.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,0), colors.HexColor(header_bg)),
            ("GRID", (0,0), (-1,-1), 0.25, colors.HexColor("#CBD5E1")),
            ("VALIGN", (0,0), (-1,-1), "TOP"),
            ("ROWBACKGROUNDS", (0,1), (-1,-1), row_bgs),
            ("LEFTPADDING", (0,0), (-1,-1), 7), ("RIGHTPADDING", (0,0), (-1,-1), 7),
            ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6),
        ]))
        return t

    def kpi(label, value, note, color):
        t = Table([[P(label, white_small)], [P(value, white_big)], [P(note, white_small)]], colWidths=[5.25*cm], rowHeights=[0.5*cm, 0.85*cm, 0.5*cm])
        t.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,-1), colors.HexColor(color)),
            ("BOX", (0,0), (-1,-1), 0.4, colors.white),
            ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
            ("LEFTPADDING", (0,0), (-1,-1), 3), ("RIGHTPADDING", (0,0), (-1,-1), 3),
        ]))
        return t

    story = []
    label_prefix = f"{demo_label} | " if demo_label else ""
    report_names = {
        "executive": "Vezetői riport",
        "fitness": "Erőnléti szakmai riport",
        "microcycle": "Mikrociklus döntéstámogató riport",
        "full": "Teljes stáb riportcsomag",
    }

    def add_cover():
        data_horizon_v149 = _fpi_data_horizon_v149(df)
        has_tactical_cover_v303 = _fpi_has_tactical_signal_v95(tactical_context)
        cover_title_v303 = (
            "Football Performance Intelligence – GPS + taktikai riport"
            if has_tactical_cover_v303
            else "Football Performance Intelligence – GPS vezetői riport"
        )
        story.append(P(cover_title_v303, title))
        story.append(P(f"{label_prefix}{report_names.get(report_type, 'Riport')} | Hét: {format_week_label(str(week))} | Heti típus: {week_type_label_v126} | Játékmodell: {playstyle} | Generálva: {datetime.now().strftime('%Y-%m-%d %H:%M')}", sub))
        story.append(P(_fpi_pdf_match_context_line_v122(demo_label), sub))
        story.append(P(
            f"<b>Adathorizont:</b> {data_horizon_v149['mode']} | "
            f"{data_horizon_v149['weeks']} hét | {data_horizon_v149['sessions']} edzés/meccsnap | "
            f"{data_horizon_v149['players']} játékos. {data_horizon_v149['trend_label']}",
            sub,
        ))
        story.append(Spacer(1, 0.25*cm))
        kpis = [
            kpi("READINESS", f"{readiness}/100", score_to_label(readiness), "#166534" if readiness >= 75 else "#1E3A8A" if readiness >= 60 else "#991B1B"),
            kpi("HIGH RISK", f"{high_risk} fő", "egyéni kontroll", "#7F1D1D" if high_risk else "#166534"),
            kpi("MEDIUM RISK", f"{med_risk} fő", "figyelendő játékos", "#92400E" if med_risk else "#166534"),
            kpi("INSIGHT", str(len(insights_df)), "automatikus megállapítás", "#0F172A"),
            kpi("HETEK", str(df['week'].nunique()) if 'week' in df.columns else "—", "elemzett adatbázis", "#1E3A8A"),
        ]
        story.append(Table([kpis], colWidths=[5.45*cm]*5))
        story.append(Spacer(1, 0.25*cm))

    def add_executive_page():
        story.append(section("1. Vezetői oldal – heti meccs- és edzésterv", "#DBEAFE"))

        has_tactical_signal = _fpi_has_tactical_signal_v95(tactical_context)
        tactical_plan = tactical_context.get("plan_a", "KIE – kiegyensúlyozott") if has_tactical_signal else "GPS-only – erőnléti fókuszú mikrociklus"
        if has_tactical_signal:
            fitness_insights_v146 = _fpi_contextual_gps_only_insights_v146(
                ctx, priorities, readiness, week, 5
            )
            coach_blocks_v146 = _fpi_coach_blocks_v146(
                tactical_context, ctx, readiness, priorities, week
            )
            tactical_insights_v146 = coach_blocks_v146["tactical"]
            match_plan_insights_v146 = coach_blocks_v146["plan"]
            team_tactical_insights_v146 = coach_blocks_v146["team"]
        else:
            fitness_insights_v146 = _fpi_contextual_gps_only_insights_v146(
                ctx, priorities, readiness, week, 7
            )
            tactical_insights_v146 = []
            match_plan_insights_v146 = []
            team_tactical_insights_v146 = []

        fitness_msgs = [
            _fpi_render_insight_text_v146(x) for x in fitness_insights_v146[:3]
        ]
        tactical_msgs = [
            _fpi_render_insight_text_v146(x) for x in tactical_insights_v146
        ]
        team_tactical_msgs = [
            _fpi_render_insight_text_v146(x) for x in team_tactical_insights_v146
        ]
        md_rows_simple = _fpi_contextual_md_plan_rows_v151(
            tactical_context,
            gps_context=ctx,
            readiness=readiness,
            priorities=priorities,
            week=week,
        )
