def _fpi_short_week_type_v99(label: object) -> str:
    s = _fpi_normalize_coach_week_label_v121(label)
    mapping = {
        "Edző által nem megadva": "Nincs megadva",
        "Regenerációs mikrociklus": "Regenerációs",
        "Stabilizáló mikrociklus": "Stabilizáló",
        "Terhelésfokozó mikrociklus": "Terhelésfokozó",
        "Fejlesztő mikrociklus": "Fejlesztő",
        "Formaidőzítő mikrociklus": "Formaidőzítő",
        "Mérkőzésre felkészítő mikrociklus": "Meccsre készítő",
        "Tanuló hét": "Tanuló",
        "Vegyes hét": "Vegyes",
    }
    return mapping.get(s, s[:18] if len(s) > 18 else s)

def _fpi_week_sort_key_v99(w: object) -> Tuple[int, int, str]:
    s = str(w)
    m = re.search(r"(\d{4})-W(\d{1,2})", s)
    if m:
        return (int(m.group(1)), int(m.group(2)), s)
    return (0, 0, s)

def _fpi_previous_weeks_v99(df: pd.DataFrame, week: str, n: int = 4) -> List[str]:
    if df is None or df.empty or "week" not in df.columns:
        return []
    weeks = sorted([str(x) for x in df["week"].dropna().unique()], key=_fpi_week_sort_key_v99)
    if str(week) not in weeks:
        return weeks[-n:]
    idx = weeks.index(str(week))
    return weeks[max(0, idx-n):idx]

def _fpi_week_team_totals_v99(df: pd.DataFrame, weeks: List[str]) -> pd.DataFrame:
    if df is None or df.empty or "week" not in df.columns:
        return pd.DataFrame()
    d = df[df["week"].astype(str).isin([str(w) for w in weeks])].copy()
    if d.empty:
        return pd.DataFrame()
    metrics = [c for c in ["total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts", "training_load"] if c in d.columns]
    if not metrics:
        return pd.DataFrame()
    for c in metrics:
        d[c] = pd.to_numeric(d[c], errors="coerce").fillna(0)
    out = d.groupby("week", as_index=False)[metrics].sum()
    out["_sort"] = out["week"].apply(_fpi_week_sort_key_v99)
    out = out.sort_values("_sort").drop(columns=["_sort"])
    return out

def _fpi_trend_label_v99(values: List[float]) -> str:
    vals = [float(v or 0) for v in values if v is not None]
    if len(vals) < 2:
        return "nincs trend"
    first = vals[0]
    last = vals[-1]
    if first <= 0 and last <= 0:
        return "nincs adat"
    pct = (last - first) / max(abs(first), 1) * 100
    if pct > 20:
        return "emelkedő"
    if pct < -20:
        return "csökkenő"
    return "stabil"

def _fpi_gps_trend_summary_v99(ctx: Dict[str, object], week: str) -> Dict[str, object]:
    df = ctx.get("df")
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {"weeks": [], "signals": [], "totals": pd.DataFrame()}
    prev = _fpi_previous_weeks_v99(df, week, n=4)
    all_weeks = prev + [str(week)]
    totals = _fpi_week_team_totals_v99(df, all_weeks)
    signals = []
    if not totals.empty:
        for metric, label in [
            ("total_distance", "volumen"),
            ("hsr_distance", "HSR"),
            ("sprint_distance", "sprint táv"),
            ("sprints", "sprint count"),
            ("high_efforts", "High Efforts"),
            ("training_load", "Load"),
        ]:
            if metric in totals.columns:
                tr = _fpi_trend_label_v99(totals[metric].tolist())
                if tr in ["emelkedő", "csökkenő"]:
                    signals.append(f"{label}: {tr} trend az utolsó {len(totals)} hétben")
    return {"weeks": all_weeks, "signals": signals[:6], "totals": totals}


def _fpi_clean_profile_noise_v121(text: object) -> str:
    """A PDF mikrociklus szövegeiből kiszedi a gépi referencia-profil zajt."""
    s = str(text or "").strip()
    s = re.sub(r"\s*Profil:\s*.*?(?=$|\.)", "", s, flags=re.IGNORECASE)
    s = re.sub(r"\s+játékosposzt-súlyozott profilhoz képest", "", s, flags=re.IGNORECASE)
    s = re.sub(r"\s+játékosposzt-súlyozott referenciazónában", " referenciazónában", s, flags=re.IGNORECASE)
    s = re.sub(r"\s+", " ", s).strip(" .")
    return s + "." if s else ""


def _fpi_focus_from_kind_v121(md: object, kind: object, train_i: int, coach_week: str) -> str:
    k = _norm_mapping_text(kind)
    md_s = str(md or "")
    if "pihen" in k:
        return "Regeneráció"
    if "meccs" in k:
        return "Mérkőzés"
    if "aktiv" in k or md_s == "MD-1":
        return "Aktiválás"
    if "regener" in k:
        return "Regenerációs kontroll"
    if "hsr" in k or "sebesseg" in k:
        return "Sebességi terhelés"
    if "sprint" in k:
        return "Sprintinger"
    if "terhel" in _norm_mapping_text(coach_week) and train_i == 0:
        return "Terhelésépítés"
    if "formaidozito" in _norm_mapping_text(coach_week) or "merkozesre" in _norm_mapping_text(coach_week):
        return "Mérkőzésre hangolás" if train_i == 0 else "Minőségi intenzitás"
    if "stabilizalo" in _norm_mapping_text(coach_week):
        return "Terhelés stabilizálása" if train_i == 0 else "Kontrollált intenzitás"
    if train_i == 0:
        return "Terhelésépítés"
    if train_i == 1:
        return "Sebességi terhelés"
    if train_i == 2:
        return "Mérkőzésspecifikus terhelés"
    return "Kontrollált edzésterhelés"


def _fpi_status_and_recommendation_v121(md: object, focus: object, why: object, readiness: int, trend_txt: str) -> Tuple[str, str]:
    raw = _fpi_clean_profile_noise_v121(why)
    f = _norm_mapping_text(focus)
    status = raw
    rec = "A terhelést a játékosok egyéni állapotához és a heti célhoz igazítva érdemes adagolni."
    if not status:
        status = f"Readiness: {readiness}/100. Trend: {trend_txt}."
    if "piheno" in f or "regener" in f:
        status = "Tervezett regenerációs nap. Cél a frissesség visszaépítése és a neuromuszkuláris terhelés csökkentése."
        rec = "Alacsony volumen, mobilitás, regenerációs munka és egyéni kezelés javasolt."
    elif "aktiv" in f or str(md) == "MD-1":
        status = f"Readiness: {readiness}/100. A cél a frissesség megtartása, nem új terhelés felépítése."
        rec = "Rövid aktiváló edzés: reakció, gyors lábmunka, pontrúgás és alacsony összvolumen."
    elif "sprint" in f:
        rec = "Rövid, kontrollált sprint-expozíció javasolt hosszú pihenőkkel; kerülni kell a felesleges ismétlésszámot."
    elif "sebesseg" in f or "hsr" in f:
        rec = "Nagyobb területű játék vagy célzott sebességi blokk javasolt, kontrollált mennyiséggel."
    elif "terhelesepites" in f or "volumen" in _norm_mapping_text(raw):
        rec = "A volumen fokozatos emelése javasolt, de a magas kockázatú játékosoknál egyéni korrekcióval."
    elif "merkoz" in f:
        rec = "A gyakorlatok intenzitása legyen mérkőzésszerű, de az összterhelés maradjon kontrollált."
    elif "minosegi" in f:
        rec = "Kevés, jó minőségű intenzív inger javasolt; a fárasztó mennyiségi munka kerülendő."
    if "alacsony" in _norm_mapping_text(raw) and ("hsr" in _norm_mapping_text(raw) or "sprint" in _norm_mapping_text(raw)):
        rec = "Sebességi/sprint inger beépítése javasolt, de csak kontrollált adagban és megfelelő pihenőkkel."
    if "magas" in _norm_mapping_text(raw) or "kockazat" in _norm_mapping_text(raw):
        rec = "Csökkentett volumen vagy egyéni módosítás javasolt a veszélyeztetett játékosoknál."
    return (_fpi_clean_sentence_v82(status, 170), _fpi_clean_sentence_v82(rec, 170))


def _fpi_structured_md_rows_v121(rows: List[Tuple], readiness: int, trend_txt: str) -> List[Tuple[str, str, str, str]]:
    out = []
    for row in rows:
        if len(row) >= 4:
            md, focus, status, rec = row[:4]
        else:
            md, focus, why = row[:3]
            status, rec = _fpi_status_and_recommendation_v121(md, focus, why, readiness, trend_txt)
        out.append((str(md), str(focus), str(status), str(rec)))
    return out

def _fpi_gps_only_md_plan_v99(ctx: Dict[str, object], readiness: int, priorities: List[dict], week: str) -> List[Tuple[str, str, str, str]]:
    """GPS-only Mikrociklus AI Planner v2.
    Figyelembe veszi:
    - edzői hét típust
    - edző által megadott edzésszámot / MD napokat
    - aktuális heti referenciaarányokat
    - előző 4 hét trendjét
    - readiness és játékosrisk jelzéseket
    """
    coach_week = _fpi_normalize_coach_week_label_v121(_fpi_get_coach_context_v97().get("coach_week_type") or "Edző által nem megadva")
    coach_plan = _fpi_session_plan_v97()
    trend = _fpi_gps_trend_summary_v99(ctx, week)
    trend_txt = "; ".join(trend.get("signals", [])[:2]) if trend.get("signals") else "nincs erős 4 hetes trend"
    base = _fpi_gps_only_md_plan_v95(ctx, readiness, priorities, week)

    # hét típus szerinti globális irány
    week_low = coach_week.lower()
    if "regener" in week_low:
        default_focus = ("Regenerációs kontroll", f"Alacsonyabb volumen, kontrollált intenzitás. Trend: {trend_txt}.")
    elif "fenntart" in week_low:
        default_focus = ("Terhelés stabilizálása", f"A fő fizikai képességek fenntartása túlterhelés nélkül. Trend: {trend_txt}.")
    elif "terhel" in week_low:
        default_focus = ("Terhelésépítés", f"Volumen és load fokozatos építése a referenciazónákhoz igazítva. Trend: {trend_txt}.")
    elif "fejleszt" in week_low:
        default_focus = ("Célzott fejlesztő inger", f"Célzott HSR/sprint/High Effort inger játékoskockázat-kontrollal. Trend: {trend_txt}.")
    elif "elez" in week_low or "élez" in week_low:
        default_focus = ("Formaidőzítés", f"Rövid, minőségi intenzitás, alacsony fárasztás. Trend: {trend_txt}.")
    elif "felkeszit" in week_low or "felkész" in week_low or "friss" in week_low:
        default_focus = ("Mérkőzésre hangolás", f"Frissesség megtartása és célzott sebességinger. Trend: {trend_txt}.")
    else:
        default_focus = ("GPS-alapú fókusz", f"Readiness, referenciaarányok és trend alapján. Trend: {trend_txt}.")

    if coach_plan:
        # Adott MD-struktúrát megtartjuk, csak a tartalmat szabjuk GPS-adatokra.
        base_focus = _fpi_gps_only_conclusions_v95(ctx, priorities, readiness, week, limit=6)
        rows = []
        train_i = 0
        for item in coach_plan:
            md = item.get("md", "MD?")
            kind = item.get("type", "Edzés")
            note = item.get("note", "")
            k = str(kind).lower()
            if k.startswith("pihen"):
                rows.append((md, "Pihenő / regeneráció", note or f"Tervezett pihenőnap. {trend_txt}."))
            elif "regener" in k:
                rows.append((md, "Regeneráció", note or f"Visszarendezés, alacsony neuromuszkuláris terhelés. {trend_txt}."))
            elif "aktiv" in k:
                rows.append((md, "Aktiváció", note or "Rövid gyorsasági/reakció inger, fárasztás nélkül."))
            elif "meccs" in k:
                rows.append((md, "Meccsnap", note or "A hét célja erre a napra friss állapotot biztosítani."))
            else:
                # edzésnap: base plan + trend + week type
                if base_focus:
                    focus = base_focus[min(train_i, len(base_focus)-1)]
                elif train_i < len(base):
                    focus = base[train_i][2]
                else:
                    focus = default_focus[1]
                if note:
                    focus = note
                rows.append((md, default_focus[0] if train_i == 0 else str(kind), focus))
                train_i += 1
        return _fpi_structured_md_rows_v121(rows[:8], readiness, trend_txt)

    # Ha nincs megadott edzésstruktúra, akkor v95 terv, de hét típus / trend szerint átfogalmazva
    if "regener" in week_low and readiness < 70:
        return _fpi_structured_md_rows_v121([
            ("MD-4", "Regenerációs kontroll", f"Alacsonyabb volumen és kontrollált intenzitás. Trend: {trend_txt}."),
            ("MD-3", "Minőségi sebességinger", "Csak expozíció, nem mennyiségi sprintmunka."),
            ("MD-2", "Frissítés + egyéni kontroll", "Játékosmonitoring, HSR/sprint halmozás nélkül."),
            ("MD-1", "Aktiváció", "Rövid döntési és mozgásgyorsasági inger."),
        ], readiness, trend_txt)
    if "tanul" in week_low:
        return _fpi_structured_md_rows_v121([
            ("MD-4", "Közepes volumen + tanulási blokk", f"Technikai/taktikai tanulás fizikai túlterhelés nélkül. {trend_txt}."),
            ("MD-3", "Kontrollált HSR/sprint expozíció", "A sebességinger megmarad, de nem ez a fő terhelési cél."),
            ("MD-2", "Alacsony-közepes intenzitás", "Tanulási ismétlések, frissesség megtartása."),
            ("MD-1", "Aktiváció", "Rövid, tiszta, frissítő inger."),
        ], readiness, trend_txt)
    return _fpi_structured_md_rows_v121(base, readiness, trend_txt)

def _fpi_gps_only_conclusions_v99(ctx: Dict[str, object], priorities: List[dict], readiness: int, week: str, limit: int = 6) -> List[str]:
    single = _fpi_single_session_profile_v162(ctx, week)
    if single.get("is_single_session"):
        return _fpi_single_session_conclusions_v162(ctx, readiness, week, limit=limit)

    out = _fpi_gps_only_conclusions_v95(ctx, priorities, readiness, week, limit=limit)
    trend = _fpi_gps_trend_summary_v99(ctx, week)
    if trend.get("signals"):
        out.append("4 hetes trend: " + "; ".join(trend.get("signals", [])[:3]) + ".")
    coach_week = _fpi_get_coach_context_v97().get("coach_week_type")
    if coach_week and coach_week != "Edző által nem megadva":
        out.append(f"Mikrociklus típusa: {_fpi_normalize_coach_week_label_v121(coach_week)}. A napi javaslatok ezt a szakmai keretet veszik alapul.")
    uniq, seen = [], set()
    for x in out:
        y = _fpi_clean_sentence_v82(x, 190)
        if y and y not in seen:
            uniq.append(y); seen.add(y)
    return uniq[:limit]




def _fpi_v205_deduplicate_overlapping_exports(df: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, int]]:
    """Átfedő Barin exportokból érkező duplikált játékos-session sorok kiszűrése.

    Azonosnak tekintjük a sort, ha ugyanaz:
    - játékos,
    - kezdési idő,
    - session neve,
    - session típusa.

    A legteljesebb (legtöbb kitöltött KPI-t tartalmazó) sort tartjuk meg.
    """
    if df is None or df.empty:
        return df, {"before": 0, "after": 0, "removed": 0}

    out = df.copy()
    before = len(out)
    required = ["player_name", "start_time", "session_name", "session_type"]
    if not all(c in out.columns for c in required):
        return out, {"before": before, "after": before, "removed": 0}

    out["_v205_start"] = pd.to_datetime(out["start_time"], errors="coerce").dt.round("min")
    out["_v205_player"] = out["player_name"].astype(str).str.strip().str.casefold()
    out["_v205_session"] = out["session_name"].astype(str).map(_norm_mapping_text)
    out["_v205_type"] = out["session_type"].astype(str).map(_norm_mapping_text)

    metric_cols = [
        c for c in [
            "duration_min", "total_distance", "distance_per_min",
            "hsr_distance", "sprint_distance", "sprints",
            "high_efforts", "training_load", "max_speed"
        ] if c in out.columns
    ]
    if metric_cols:
        out["_v205_quality"] = out[metric_cols].notna().sum(axis=1)
    else:
        out["_v205_quality"] = 0

    key_cols = ["_v205_player", "_v205_start", "_v205_session", "_v205_type"]
    valid_key = (
        out["_v205_player"].ne("")
        & out["_v205_start"].notna()
        & out["_v205_session"].ne("")
    )

    keyed = out[valid_key].sort_values("_v205_quality", ascending=False)
    keyed = keyed.drop_duplicates(subset=key_cols, keep="first")
    unkeyed = out[~valid_key]
    out = pd.concat([keyed, unkeyed], ignore_index=True, sort=False)
    out = out.drop(columns=[
        "_v205_start", "_v205_player", "_v205_session",
        "_v205_type", "_v205_quality"
    ], errors="ignore")

    after = len(out)
    return out, {"before": before, "after": after, "removed": before - after}


def _fpi_v205_period_label(df: pd.DataFrame) -> str:
    starts = pd.to_datetime(df.get("start_time", pd.Series(dtype="datetime64[ns]")), errors="coerce").dropna()
    if starts.empty:
        return "Teljes feltöltött időszak"
    return f"{starts.min().strftime('%Y-%m-%d')} – {starts.max().strftime('%Y-%m-%d')}"


def _fpi_v204_numeric(df: pd.DataFrame, col: str) -> pd.Series:
    if col not in df.columns:
        return pd.Series(np.nan, index=df.index, dtype=float)
    return pd.to_numeric(df[col], errors="coerce")


def _fpi_v204_context(df: pd.DataFrame, week: str) -> Dict[str, object]:
    mode = _fpi_v202_detect_analysis_mode(df, week)
    data = df[df.get("week", pd.Series("", index=df.index)).astype(str) == str(week)].copy()
    if data.empty:
        return {**mode, "code": "no_data", "label": "Nincs adat"}
    kind = data.get("session_type", pd.Series("", index=data.index)).apply(_fpi_v200_session_kind)
    data["_kind204"] = kind
    data["_event204"] = _fpi_v202_event_key(data)
    starts = pd.to_datetime(data.get("start_time", pd.Series(pd.NaT, index=data.index)), errors="coerce")
    data["_date204"] = starts.dt.date
    events = data[["_event204", "_kind204", "_date204"]].drop_duplicates()
    matches = int((events["_kind204"] == "match").sum())
    trainings = int((events["_kind204"] == "training").sum())
    two_a_day = bool(events.groupby("_date204").size().gt(1).any()) if events["_date204"].notna().any() else False
    coach_week = str((_fpi_get_coach_context_v97() or {}).get("coach_week_type", "") or "")
    coach_norm = _norm_mapping_text(coach_week)
    phase_override = str(
        st.session_state.get("fpi_season_phase_v205", "Automatikus felismerés")
        or "Automatikus felismerés"
    )
    phase_norm = _norm_mapping_text(phase_override)

    auto_preseason = (
        "felkesz" in coach_norm or "preseason" in coach_norm
        or matches >= 2 or (two_a_day and trainings >= 3)
    )

    if "felkesz" in phase_norm or "preseason" in phase_norm:
        preseason = True
        phase_source = "edző által megadva"
    elif "verseny" in phase_norm or "bajnoki" in phase_norm:
        preseason = False
        phase_source = "edző által megadva"
    else:
        preseason = auto_preseason
        phase_source = "automatikusan felismerve"
    if preseason:
        mode = dict(mode)
        mode.update({
            "code": "preseason_block", "label": "Felkészülési terhelési blokk", "icon": "🟠",
            "description": f"{trainings} edzés és {matches} meccs felkészülési struktúrában ({phase_source}). A riport gördülő terhelést és regenerációt értékel, nem klasszikus MD-hetet.",
            "is_complete_week": False, "is_provisional": True,
            "confidence": "magas" if phase_source == "edző által megadva" else "közepes",
            "phase_source": phase_source,
        })
    mode["two_a_day"] = two_a_day
    return mode


def _fpi_v204_quality_gate(df: pd.DataFrame, week: str) -> Dict[str, object]:
    data = df[df.get("week", pd.Series("", index=df.index)).astype(str) == str(week)].copy()
    issues, blocked = [], set()
    dist = _fpi_v204_numeric(data, "total_distance")
    dur = _fpi_v204_numeric(data, "duration_min")
    dpm = _fpi_v204_numeric(data, "distance_per_min")
    sprint = _fpi_v204_numeric(data, "sprint_distance")
    hsr = _fpi_v204_numeric(data, "hsr_distance")
    usable = int(data.get("player_name", pd.Series(index=data.index, dtype=object)).notna().sum())
    if usable == 0:
        issues.append("Nincs értelmezhető játékossor.")
    zero_duration_share = float(((dur.fillna(0) <= 0) & (dist.fillna(0) > 500)).mean()) if len(data) else 0
    if zero_duration_share > 0.20:
        issues.append("Az időtartam több játékosnál hiányzik vagy nulla; a perc- és intenzitásmutatók letiltva.")
        blocked.update({"duration_min", "distance_per_min"})
    bad_dpm = dpm.dropna()
    if len(bad_dpm) and float(((bad_dpm < 20) | (bad_dpm > 250)).mean()) > 0.20:
        issues.append("A m/perc értékek jelentős része életszerűtlen; az intenzitásmutató letiltva.")
        blocked.add("distance_per_min")
    paired = pd.DataFrame({"d": dist, "s": sprint}).dropna()
    if len(paired):
        equal_share = float(np.isclose(paired["d"], paired["s"], rtol=0.01, atol=5).mean())
        over_share = float((paired["s"] > paired["d"] * 1.02).mean())
        if equal_share > 0.20 or over_share > 0.05:
            issues.append("A sprinttáv mappingje hibásnak tűnik; sprintkövetkeztetés nem készült.")
            blocked.add("sprint_distance")
    paired_hsr = pd.DataFrame({"d": dist, "h": hsr}).dropna()
    if len(paired_hsr) and float((paired_hsr["h"] > paired_hsr["d"] * 1.02).mean()) > 0.05:
        issues.append("A HSR-táv meghaladja az össztávot; HSR-következtetés nem készült.")
        blocked.add("hsr_distance")
    severity = "kritikus" if len(blocked) >= 3 else "korlátozott" if issues else "megfelelő"
    return {"issues": issues, "blocked": blocked, "severity": severity, "usable_rows": usable}


def _fpi_v204_session_summary(df: pd.DataFrame, week: str, blocked: set) -> pd.DataFrame:
    data = df[df.get("week", pd.Series("", index=df.index)).astype(str) == str(week)].copy()
    if data.empty:
        return pd.DataFrame()
    data["_event204"] = _fpi_v202_event_key(data)
    data["_date204"] = pd.to_datetime(data.get("start_time", pd.Series(pd.NaT,index=data.index)), errors="coerce")
    rows=[]
    for key,g in data.groupby("_event204", dropna=False):
        metric_g = field_players_only(g) if "is_goalkeeper" in g.columns and (~g["is_goalkeeper"].fillna(False)).any() else g
        kind = _fpi_v200_session_kind(g.get("session_type", pd.Series("",index=g.index)).iloc[0])
        name = str(g.get("session_name", pd.Series("Session",index=g.index)).iloc[0])
        start = g["_date204"].dropna().min()
        row={"Dátum": start.strftime("%Y-%m-%d %H:%M") if pd.notna(start) else "—",
             "Típus": "Meccs" if kind=="match" else "Edzés", "Session": name,
             "Létszám": int(g.get("player_name",pd.Series(index=g.index,dtype=object)).nunique())}
        for col,label in [("duration_min","Perc"),("total_distance","Össztáv"),("distance_per_min","m/perc"),("hsr_distance","HSR"),("sprint_distance","Sprint"),("training_load","Load")]:
            vals=_fpi_v204_numeric(metric_g,col)
            row[label]=np.nan if col in blocked else (float(vals.median()) if vals.notna().any() else np.nan)
        rows.append(row)
    return pd.DataFrame(rows).sort_values("Dátum").reset_index(drop=True)


def _fpi_v204_player_period(df: pd.DataFrame, week: str, blocked: set) -> pd.DataFrame:
    data = df[df.get("week", pd.Series("", index=df.index)).astype(str).eq(str(week))].copy()
    if data.empty or "player_name" not in data.columns:
        return pd.DataFrame()
    data["_event204"] = _fpi_v202_event_key(data)
    if "is_goalkeeper" not in data.columns:
        if "position" in data.columns:
            data["is_goalkeeper"] = data["position"].apply(is_keeper_position_value)
        elif "position_group" in data.columns:
            data["is_goalkeeper"] = data["position_group"].astype(str).str.lower().str.contains("kapus|goalkeeper|\\bgk\\b", regex=True, na=False)
        else:
            data["is_goalkeeper"] = False
    agg = {}
    for c in ["duration_min", "total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts", "training_load"]:
        if c in data.columns and c not in blocked:
            agg[c] = "sum"
    if not agg:
        return pd.DataFrame()
    agg["is_goalkeeper"] = "max"
    p = data.groupby("player_name", dropna=False).agg(agg).reset_index()
    p["sessions"] = data.groupby("player_name")["_event204"].nunique().reindex(p["player_name"]).values
    return p



def _fpi_v204_aligned_comparison(df: pd.DataFrame, week: str, blocked: set) -> pd.DataFrame:
    """V301: a trendhez a hetet mindig a javított sessiondátumból számítjuk.

    Nem bízik meg a korábbról hozott week oszlopban, és csak az aktuális
    adathorizont valódi ISO-heteit engedi be.
    """
    if "start_time" not in df.columns:
        return pd.DataFrame()
    data=df.copy()
    data["_dt204"]=pd.to_datetime(data["start_time"],errors="coerce")
    data=data[data["_dt204"].notna()].copy()
    if data.empty: return pd.DataFrame()
    data["_week_v301"]=_fpi_v300_iso_week(data["_dt204"])
    data["week"]=data["_week_v301"]
    cur=data[data["week"].astype(str)==str(week)].copy()
    if cur.empty: return pd.DataFrame()
    cutoff=int(cur["_dt204"].dt.weekday.max())
    current_max=cur["_dt204"].max()
    min_date=data["_dt204"].min().normalize()
    max_date=data["_dt204"].max().normalize()
    # Csak a tényleges feltöltött időszak és a kiválasztott hétig terjedő múlt.
    data=data[(data["_dt204"].dt.normalize()>=min_date)&(data["_dt204"].dt.normalize()<=max_date)&(data["_dt204"]<=current_max)].copy()
    weeks=sorted(data["week"].dropna().astype(str).unique().tolist(),key=_fpi_week_sort_key_v99)
    rows=[]
    for w in weeks[-6:]:
        g=data[(data["week"].astype(str)==w)&(data["_dt204"].dt.weekday<=cutoff)].copy()
        if g.empty: continue
        p=_fpi_v204_player_period(g,w,blocked)
        row={"Hét":w,"Összevetés":f"hétfő–{['hétfő','kedd','szerda','csütörtök','péntek','szombat','vasárnap'][cutoff]}"}
        for c,label in [("total_distance","Medián össztáv"),("hsr_distance","Medián HSR"),("sprint_distance","Medián sprint"),("training_load","Medián load")]:
            row[label]=float(pd.to_numeric(p.get(c),errors='coerce').median()) if c in p.columns else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def _fpi_v204_recommendations(mode: Dict[str,object], sessions: pd.DataFrame, quality: Dict[str,object], player_period: pd.DataFrame) -> List[Tuple[str,str,str]]:
    code=str(mode.get("code","limited_data")); out=[]
    if code=="single_session":
        out += [("Következő 24 óra","Regeneráció vagy normál folytatás","Az aktuális session mediánjai és szélsőértékei alapján dönts; heti readiness nem értelmezhető."),
                ("Játékoskontroll","Csapaton belüli eltérések","A mediántól jelentősen eltérő és részlegesen részt vevő játékosokat ellenőrizd.")]
    elif code=="training_block":
        out += [("Következő edzés","Blokkon belüli egyensúly","A sessionök volumen–intenzitás mintája alapján egészítsd ki a hiányzó HSR/sprint expozíciót."),
                ("Részvétel","Kumulált játékosterhelés","Az alacsony részvételt külön kezeld a valódi alulterheléstől.")]
    elif code=="week_in_progress":
        out += [("Aktuális hét","Nem lezárt hét","A heti összterhelést csak korábbi hetek azonos napjáig elért értékével hasonlítsd."),
                ("Következő 48 óra","Óvatos tervezés","A még hátralévő sessionök és a meccs feltöltéséig ne adj teljes heti alul- vagy túlterhelési minősítést.")]
    elif code=="preseason_block":
        out += [("Következő 48–72 óra","Gördülő terheléskontroll","Az edzést és meccsperceket együtt kezeld; figyeld az egymást követő magas terhelésű napokat."),
                ("Felkészülési blokk","Kereten belüli egyenlőség","A kevés meccspercet kapók kompenzációja és a sok percet kapók regenerációja külön programot igényel."),
                ("Sebességexpozíció","Minőség, nem darabszám","A sprint- és HSR-ingert 3–5 napos gördülő ablakban értékeld; ha van kijelölt következő meccs, az MD-4–MD-1 tervet is használd.")]
    elif code=="full_microcycle":
        out += [("Következő mikrociklus","Meccsreferencia használható","A heti és edzésátlagos meccsarányokat a readiness- és risk-jelzésekkel együtt értelmezd.")]
    else:
        out += [("Következő lépés","További adat","A rendelkezésre álló eseményekből csak korlátozott, eseményszintű következtetés adható.")]
    return out[:5]


def _fpi_v204_conclusions(mode, quality, sessions, player_period, readiness):
    out=[f"Elemzési mód: {mode.get('label')}. {mode.get('description','')}"]
    if not sessions.empty:
        out.append(f"Feldolgozott események: {len(sessions)} session; átlagos létszám {sessions['Létszám'].mean():.1f} fő.")
        valid=sessions.dropna(subset=['Össztáv']) if 'Össztáv' in sessions else pd.DataFrame()
        if not valid.empty:
            valid=valid[pd.to_numeric(valid['Össztáv'],errors='coerce')>0].copy()
        if not valid.empty:
            hi=valid.loc[valid['Össztáv'].idxmax()]; lo=valid.loc[valid['Össztáv'].idxmin()]
            out.append(f"Sessionterhelés: a legnagyobb játékosmedián táv {hi['Session']} ({hi['Össztáv']:.0f} m), a legalacsonyabb {lo['Session']} ({lo['Össztáv']:.0f} m).")
    if not player_period.empty and 'total_distance' in player_period:
        vals=pd.to_numeric(player_period['total_distance'],errors='coerce').dropna()
        if len(vals): out.append(f"Játékosonkénti kumulált össztáv mediánja {vals.median():.0f} m; a referencia középmezőnye: {vals.quantile(.25):.0f}–{vals.quantile(.75):.0f} m.")
    if mode.get('code') in {'single_session','training_block','week_in_progress','preseason_block'}:
        out.append("A readiness nem teljes meccskészültségi minősítés; a riport esemény- vagy blokkszintű döntéstámogatást ad.")
    else:
        out.append(f"Readiness: {readiness}/100; teljes hét esetén a meccsreferenciával együtt értelmezhető.")
    return out[:6]



def _fpi_v401_compact_bar_chart(items, title_text: str, width_cm: float = 13.2, height_cm: float = 4.2, value_suffix: str = "", max_items: int = 8):
    """V401: kompakt ReportLab-diagram, Unicode-biztos címkékkel és szabályozható elemszámmal."""
    try:
        from reportlab.graphics.shapes import Drawing, Rect, String
        from reportlab.lib import colors as rl_colors
        chart_font, chart_bold = _register_pdf_font()
        clean = []
        for label, value in items:
            try:
                v = float(value)
                if pd.notna(v):
                    clean.append((pdf_safe_text(str(label)), v))
            except Exception:
                continue
        if not clean:
            return Spacer(1, 0)
        clean = clean[:max(1, int(max_items))]
        W, H = width_cm * cm, height_cm * cm
        d = Drawing(W, H)
        d.add(String(0, H - 11, pdf_safe_text(title_text), fontName=chart_bold, fontSize=8.5, fillColor=rl_colors.HexColor('#0F172A')))
        top = H - 25
        row_h = max(11, (H - 31) / max(len(clean), 1))
        label_w = W * .31
        bar_w = W * .51
        vmax = max(abs(v) for _, v in clean) or 1
        for i, (label, v) in enumerate(clean):
            y = top - i * row_h
            d.add(String(0, y, label[:25], fontName=chart_font, fontSize=6.8, fillColor=rl_colors.HexColor('#334155')))
            d.add(Rect(label_w, y - 2, bar_w, 6, fillColor=rl_colors.HexColor('#E2E8F0'), strokeColor=None))
            d.add(Rect(label_w, y - 2, max(1, bar_w * abs(v) / vmax), 6, fillColor=rl_colors.HexColor('#0F766E'), strokeColor=None))
            val = (_fpi_v414_number(v, 0) if abs(v) >= 10 else _fpi_v414_number(v, 1)) + value_suffix
            d.add(String(label_w + bar_w + 4, y - 1, val, fontName=chart_bold, fontSize=6.7, fillColor=rl_colors.HexColor('#0F172A')))
        return d
    except Exception:
        return Spacer(1, 0)


# V304-kompatibilis alias: a régebbi hívások is az új rajzolót használják.
def _fpi_v304_compact_bar_chart(items, title_text: str, width_cm: float = 13.2, height_cm: float = 4.2, value_suffix: str = "", max_items: int = 8):
    return _fpi_v401_compact_bar_chart(items, title_text, width_cm, height_cm, value_suffix, max_items)


def _fpi_v304_session_chart(sessions: pd.DataFrame):
    if sessions is None or sessions.empty:
        return Spacer(1, 0)
    charts = []
    labels = [str(x)[:18] for x in sessions.get('Session', pd.Series(range(len(sessions)))).tolist()]
    for col, title, suffix in [('Össztáv', 'Sessionprofil – medián táv / játékos', ' m'), ('HSR', 'Sessionprofil – medián HSR', ' m')]:
        if col in sessions.columns:
            charts.append(_fpi_v401_compact_bar_chart(list(zip(labels, pd.to_numeric(sessions[col], errors='coerce'))), title, 13.4, 4.0, suffix, max_items=8))
    return Table([charts[:2]], colWidths=[13.7 * cm] * len(charts[:2])) if charts else Spacer(1, 0)


def _fpi_v304_trend_charts(aligned: pd.DataFrame):
    if aligned is None or aligned.empty:
        return Spacer(1, 0)
    charts = []
    labels = aligned['Hét'].astype(str).tolist() if 'Hét' in aligned else [str(i + 1) for i in range(len(aligned))]
    for col, title, suffix in [('Medián load', 'Időarányos Load-trend', ''), ('Medián HSR', 'Időarányos HSR-trend', ' m')]:
        if col in aligned.columns:
            charts.append(_fpi_v401_compact_bar_chart(list(zip(labels, pd.to_numeric(aligned[col], errors='coerce'))), title, 13.4, 4.1, suffix, max_items=6))
    return Table([charts[:2]], colWidths=[13.7 * cm] * len(charts[:2])) if charts else Spacer(1, 0)


def _fpi_v401_top_bottom_items(players: pd.DataFrame, metric: str):
    """Pontosan 5 alsó + 5 top játékos, ha legalább 10 külön játékos rendelkezésre áll.
    Kisebb keretnél ismétlés nélkül, kiegyensúlyozott alsó/top bontást ad.
    """
    tmp = players[['player_name', metric]].copy()
    tmp[metric] = pd.to_numeric(tmp[metric], errors='coerce')
    tmp = tmp.dropna(subset=['player_name', metric]).drop_duplicates('player_name').sort_values(metric, kind='mergesort')
    n = len(tmp)
    if n == 0:
        return [], 0, 0
    bottom_n = min(5, n // 2 if n < 10 else 5)
    top_n = min(5, n - bottom_n)
    bottom = tmp.head(bottom_n).copy().sort_values(metric, ascending=True, kind='mergesort')
    used = set(bottom['player_name'].astype(str))
    # A top csoportot is növekvő sorrendben rajzoljuk, így a teljes diagram
    # vizuálisan végig a legkisebb értéktől a legnagyobbig halad.
    top = tmp[~tmp['player_name'].astype(str).isin(used)].tail(top_n).sort_values(metric, ascending=True, kind='mergesort').copy()
    items = [(f"Alsó | {r.player_name}", r[metric]) for _, r in bottom.iterrows()]
    items += [(f"Top | {r.player_name}", r[metric]) for _, r in top.iterrows()]
    return items, len(bottom), len(top)


def _fpi_v304_player_charts(players: pd.DataFrame):
    if players is None or players.empty:
        return Spacer(1, 0)
    field_players = players.copy()
    if "is_goalkeeper" in field_players.columns:
        field_players = field_players[~field_players["is_goalkeeper"].fillna(False)].copy()
    if field_players.empty:
        return Spacer(1, 0)
    charts = []
    for col, label, suffix in [("training_load", "Load", ""), ("hsr_distance", "HSR", " m")]:
        if col not in field_players.columns:
            continue
        items, bottom_n, top_n = _fpi_v401_top_bottom_items(field_players, col)
        if not items:
            continue
        title = f"{label} – mezőnyjátékos alsó {bottom_n} és top {top_n} ({len(items)} külön játékos)"
        chart_height = 5.8 if len(items) >= 9 else 5.1
        charts.append(_fpi_v401_compact_bar_chart(items, title, 13.4, chart_height, suffix, max_items=10))
    return Table([charts[:2]], colWidths=[13.7 * cm] * len(charts[:2])) if charts else Spacer(1, 0)


def _fpi_v304_player_risk_suggestion(level:str, reason:str)->str:
    txt=_norm_mapping_text(f"{level} {reason}")
    if 'reszvetel' in txt or 'hianyz' in txt:return 'Részvétel ellenőrzése; szükség esetén egyéni pótlóprogram.'
    if 'sprint' in txt:return 'Rövid, teljes pihenős sprintblokk a heti célzónáig.'
    if 'hsr' in txt or 'nagy sebesseg' in txt:return 'Egyéni HSR-pótlás kontrollált ismétlésekkel.'
    if 'load' in txt or 'terheles' in txt:
        return 'Magas értéknél volumen visszavétele; alacsonynál kontrollált pótlás.'
    if 'high effort' in txt or 'gyorsul' in txt or 'lassul' in txt:return 'Rövid robbanékony blokk, technikai minőség mellett.'
    return 'A játékos előzményeinek és részvételének egyéni ellenőrzése.'

def build_fpi_gps_only_pdf_bytes(
    data: pd.DataFrame,
    selected_week: Optional[str] = None,
    playstyle: str = "Kiegyensúlyozott",
    demo_label: str = "",
) -> Optional[bytes]:
    """V205 kontextusérzékeny GPS-only PDF heti vagy teljes időszakos módban."""
    if SimpleDocTemplate is None:
        return None
    from reportlab.platypus import PageBreak

    period_mode_v205 = str(selected_week) == "__ALL__"
    period_label_v205 = ""
    report_data_v205 = data

    if period_mode_v205:
        report_data_v205 = _fpi_to_standard_if_needed(data)
        if report_data_v205 is None or report_data_v205.empty:
            return None
        report_data_v205, master_report_period_v300 = _fpi_v300_master_dataset(report_data_v205)
        period_label_v205 = _fpi_v205_period_label(report_data_v205)
        report_data_v205 = report_data_v205.copy()
        # V414: a "Teljes feltöltött időszak" valóban minden kiválasztott sort elemez.
        # Az eredeti ISO-hetet külön oszlopban megőrizzük, ezért a 4+ hetes trendmotor
        # továbbra is valódi hetekből dolgozik, miközben a session- és játékostáblák
        # az egész feltöltött időszakot mutatják.
        full_period_key_v414 = "__FPI_FULL_PERIOD_V414__"
        if "_fpi_original_week_v300" not in report_data_v205.columns:
            report_data_v205["_fpi_original_week_v300"] = report_data_v205.get(
                "week", pd.Series("", index=report_data_v205.index)
            ).astype(str)
        report_data_v205["week"] = full_period_key_v414
        report_data_v205["_fpi_scope_selected_v411"] = True
        report_data_v205["_fpi_scope_code_v411"] = full_period_key_v414
        selected_week = full_period_key_v414
        st.session_state["fpi_analysis_scope_v411"] = {
            "mode_selection": "Teljes feltöltött időszak",
            "scope_type": "full_period",
            "report_key": full_period_key_v414,
            "label": period_label_v205,
            "selected_week": None,
            "selected_event": None,
            "date_range": None,
        }

    ctx=_fpi_report_context(report_data_v205,selected_week,playstyle)
    if ctx.get("error"): return None
    df=ctx["df"]; week=str(ctx["selected_week"]); readiness=int(ctx.get("readiness_score",70) or 70)
    master_report_v300 = ctx.get("master_report_v300", {})
    match_reference_v300 = ctx.get("match_reference_v300", {})
    ratios_v300 = ctx.get("training_match_ratios_v300", pd.DataFrame())
    microcycle_v300 = ctx.get("microcycle_plan_v300", pd.DataFrame())
    readiness_breakdown_v302=ctx.get("readiness_breakdown_v302",pd.DataFrame())
    readiness_status_v411=str(ctx.get("readiness_status_v411","full"))
    trend_status_v411=ctx.get("trend_status_v411",{}) or {}
    coach_actions_v302=_fpi_v302_coach_actions(ratios_v300)
    mode=_fpi_v204_context(df,week); quality=_fpi_v204_quality_gate(df,week); blocked=set(quality.get("blocked",set()))
    if mode.get("code") == "single_session":
        coach_actions_v302 = _fpi_v411_single_session_actions(ratios_v300)
    sessions=_fpi_v204_session_summary(df,week,blocked); players=_fpi_v204_player_period(df,week,blocked)
    aligned=_fpi_v204_aligned_comparison(df,week,blocked)
    recs=_fpi_v204_recommendations(mode,sessions,quality,players)
    conclusions=_fpi_v204_conclusions(mode,quality,sessions,players,readiness)
    risk_df=ctx.get("risk_df") if isinstance(ctx.get("risk_df"),pd.DataFrame) else pd.DataFrame()
    font_name,font_bold=_register_pdf_font(); buffer=io.BytesIO()
    doc=SimpleDocTemplate(buffer,pagesize=landscape(A4),rightMargin=.9*cm,leftMargin=.9*cm,topMargin=.7*cm,bottomMargin=.7*cm)
    styles=getSampleStyleSheet()
    title=ParagraphStyle('V204Title',parent=styles['Title'],fontName=font_bold,fontSize=21,leading=25,textColor=colors.HexColor('#0F172A'))
    sub=ParagraphStyle('V204Sub',parent=styles['Normal'],fontName=font_name,fontSize=9.5,leading=12,textColor=colors.HexColor('#334155'))
    body=ParagraphStyle('V204Body',parent=styles['Normal'],fontName=font_name,fontSize=9.6,leading=12.5,textColor=colors.HexColor('#111827'))
    small=ParagraphStyle('V204Small',parent=body,fontSize=8.5,leading=10.8)
    head=ParagraphStyle('V204Head',parent=body,fontName=font_bold,textColor=colors.white,alignment=1)
    story=[]
    def P(x,s=body):
        x = _fpi_v417_render_load_text(x, df)
        return Paragraph(pdf_safe_text(_fpi_tactical_pdf_text_v157(x)),s)
    def section(x,color='#DBEAFE'):
        return Table([[P(x,ParagraphStyle('Sec'+str(len(story)),parent=body,fontName=font_bold,fontSize=11))]],colWidths=[27.7*cm],style=TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor(color)),('BOX',(0,0),(-1,-1),.4,colors.HexColor('#CBD5E1')),('LEFTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    def tbl(rows,widths,bg='#1E3A8A'):
        t=Table(rows,colWidths=widths,repeatRows=1)
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor(bg)),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),font_bold),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#CBD5E1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F8FAFC')])]))
        return t
    report_title = ('Teljes időszakos GPS trendriport' if period_mode_v205 else {'single_session':'Egyszeri edzés – GPS-pillanatkép','training_block':'Edzésblokk-elemzés','week_in_progress':'Folyamatban lévő hét – adatok eddig','preseason_block':'Felkészülési terhelési blokk','full_microcycle':'Teljes mikrociklus – GPS-riport','match_only':'Meccsterhelési riport'}.get(mode.get('code'),'GPS-only teljesítményriport'))
    display_period_v205 = period_label_v205 if period_mode_v205 else format_week_label(week)
    period_scope_note_v303 = (
        f"Teljes adatbázis: {period_label_v205}; a session- és játékostáblák minden kiválasztott eseményt tartalmaznak."
        if period_mode_v205 else ""
    )
    story += [
        P(demo_label or f'Football Performance Intelligence – {report_title}',title),
        P(f'Hét/időszak: {display_period_v205} | Játékmodell: {playstyle} | Generálva: {datetime.now().strftime("%Y-%m-%d %H:%M")}',sub),
        P(
            f'Elemzési mód: {mode.get("label")} | Sessionök: {len(sessions)}'
            + (' | Teljes feltöltött időszak' if period_mode_v205 else ''),
            sub
        ),
        P(period_scope_note_v303, sub) if period_scope_note_v303 else Spacer(1, 0),
        Spacer(1,.2*cm)
    ]
    database_sessions_v301 = int(master_report_v300.get("sessions", len(sessions)) or len(sessions))
    current_sessions_v301 = int(len(sessions))
    real_matches_v300 = int(master_report_v300.get("match_events", 0) or 0)
    kpis=[
        [P('MÓD',head),P('AKTUÁLIS SESSION',head),P('ADATBÁZIS SESSION',head),P('MECCSESEMÉNY',head),P('READINESS',head)],
        [P(mode.get('label',''),body),P(str(current_sessions_v301),body),P(str(database_sessions_v301),body),P(str(real_matches_v300),body),P('nem számolható' if readiness_status_v411=='not_available' else ('előzetes' if readiness_status_v411=='preliminary' else f'{readiness}/100'),body)]
    ]
    story += [tbl(kpis,[6.5*cm,4.6*cm,4.8*cm,4.2*cm,7.6*cm],'#0F766E'),Spacer(1,.2*cm),section('1. Vezetői konklúziók')]
    story.append(tbl([[P('#',head),P('Konklúzió',head)]]+[[P(str(i),small),P(c,small)] for i,c in enumerate(conclusions,1)],[1.0*cm,26.7*cm]))
    if readiness_status_v411 != 'not_available' and readiness_breakdown_v302 is not None and not readiness_breakdown_v302.empty:
        story += [Spacer(1,.18*cm),section('Readiness - mi alakította a pontszámot?','#ECFDF5')]
        rb=[[P(x,head) for x in ['Komponens','Pont','Státusz','Magyarázat']]]
        for _,r in readiness_breakdown_v302.iterrows(): rb.append([P(str(r.get('Komponens','')),small),P(str(r.get('Pont','')),small),P(str(r.get('Státusz','')),small),P(str(r.get('Magyarázat','')),small)])
        story.append(tbl(rb,[6.0*cm,2.0*cm,4.0*cm,15.7*cm],'#166534'))
        story += [Spacer(1,.08*cm), P('<b>Fontos különbség:</b> a Robbanékony akciók / High Efforts rövid gyorsításokat, lassításokat és irányváltásokat mér; a Speed Exposure nagy futósebességű HSR/sprint ingert mér. Ezért lehet egyszerre magas a robbanékonyság és alacsony a sebességi expozíció.', small)]
    story += [PageBreak(),section('2. Sessionönkénti terhelési profil','#FEF3C7')]
    if sessions.empty: story.append(P('Nincs sessionönként értelmezhető adat.'))
    else:
        rows=[[P(x,head) for x in ['Dátum','Típus','Session','Létszám','Perc','Medián táv','m/perc','HSR','Sprint','Load']]]
        for _,r in sessions.iterrows():
            def f(v,d=0): return _fpi_v414_number(v, decimals=d)
            rows.append([P(str(r['Dátum']),small),P(str(r['Típus']),small),P(str(r['Session']),small),P(_fpi_v414_number(r['Létszám']),small),P(f(r['Perc'],1),small),P(f(r['Össztáv']),small),P(f(r['m/perc'],1),small),P(f(r['HSR']),small),P(f(r['Sprint']),small),P(f(r['Load']),small)])
