render_fpi_methodology_center_v138 = render_fpi_methodology_center_v143



# =========================================================
# V411 - Adaptive analysis scope, blended benchmark and trend gate
# =========================================================
FPI_ANALYSIS_MODE_OPTIONS_V411 = [
    "Automatikus felismerés",
    "Egyetlen esemény",
    "Teljes vagy csonka naptári hét",
    "Egyéni dátumtartomány",
    "Teljes feltöltött időszak",
]
FPI_SCOPE_KEY_V411 = "2099-W52-SCOPE"


def _fpi_v411_list_value(value, fallback):
    if isinstance(value, (list, tuple, set)):
        return [str(x) for x in value if str(x).strip()]
    if value is None:
        return list(fallback)
    s = str(value).strip()
    if not s:
        return list(fallback)
    try:
        parsed = json.loads(s)
        if isinstance(parsed, list):
            return [str(x) for x in parsed if str(x).strip()]
    except Exception:
        pass
    return [s]


def _fpi_v411_playmodel_label(primary: str, secondary: Optional[str] = None) -> str:
    primary = str(primary or "Kiegyensúlyozott")
    secondary = str(secondary or "").strip()
    if secondary and secondary != "Nincs" and secondary != primary:
        return f"{primary} 70% + {secondary} 30%"
    return primary


def _fpi_v411_playmodel_factor(metric: str, primary: str, secondary: Optional[str] = None) -> float:
    primary = primary if primary in FPI_PLAYMODEL_FACTORS_V112 else "Kiegyensúlyozott"
    p = float(FPI_PLAYMODEL_FACTORS_V112[primary].get(metric, 1.0))
    secondary = str(secondary or "").strip()
    if not secondary or secondary == "Nincs" or secondary == primary or secondary not in FPI_PLAYMODEL_FACTORS_V112:
        return p
    s = float(FPI_PLAYMODEL_FACTORS_V112[secondary].get(metric, 1.0))
    return 0.70 * p + 0.30 * s


_fpi_v411_base_reference_profile = _fpi_build_reference_profile_v112

def _fpi_build_reference_profile_v112(age: str, level: str, position: str, playmodel: str) -> Dict[str, object]:
    age = age if age in FPI_AGE_FACTOR_V112 else "Felnőtt"
    level = level if level in FPI_LEVEL_FACTOR_V112 else "NB II"
    position = position if position in FPI_POSITION_FACTORS_V112 else "Középpályás"
    primary = playmodel if playmodel in FPI_PLAYMODEL_FACTORS_V112 else "Kiegyensúlyozott"
    coach_ctx = _fpi_get_coach_context_v97() or {}
    secondary = coach_ctx.get("secondary_playmodel") if str(coach_ctx.get("primary_playmodel", primary)) == str(primary) else None
    ranges = {}
    for metric, base in FPI_REFERENCE_BASE_RANGES_V112.items():
        factor = FPI_AGE_FACTOR_V112[age] * FPI_LEVEL_FACTOR_V112[level]
        factor *= FPI_POSITION_FACTORS_V112[position].get(metric, 1.0)
        factor *= _fpi_v411_playmodel_factor(metric, primary, secondary)
        factor = max(0.25, min(1.45, factor))
        ranges[metric] = _fpi_scale_range_v112(base, factor)
    model_label = _fpi_v411_playmodel_label(primary, secondary)
    provisional = str(level).startswith("Román ")
    source_note = (
        "előzetes liga-profil; induló faktor a magyar NB I referencia" if level.startswith("Román SuperLiga")
        else "előzetes liga-profil; induló faktor a magyar NB II referencia" if level.startswith("Román Liga II")
        else "FPI liga-profil"
    )
    label = f"{age} / {level} / {position} / {model_label}"
    if provisional:
        label += f" | {source_note}; 3 saját teljes meccstől saját meccsmedián az elsődleges"
    return {
        "label": label, "age": age, "level": level, "position": position,
        "playmodel": primary, "secondary_playmodel": secondary,
        "playmodel_label": model_label, "ranges": ranges,
        "provisional": provisional, "source_note": source_note,
    }


def _fpi_v411_event_options(df: pd.DataFrame) -> Tuple[List[str], Dict[str, str]]:
    if df is None or df.empty:
        return [], {}
    data = df.copy()
    data["_event_v411"] = _fpi_v202_event_key(data)
    data["_dt_v411"] = pd.to_datetime(data.get("start_time"), errors="coerce")
    rows = []
    for key, group in data.groupby("_event_v411", dropna=False):
        dt = group["_dt_v411"].dropna().min()
        kind = "Meccs" if group.get("session_type", pd.Series("", index=group.index)).astype(str).eq("Meccs").any() else "Edzés"
        name = str(group.get("session_name", pd.Series("Session", index=group.index)).dropna().astype(str).iloc[0]) if len(group) else "Session"
        label = f"{dt.strftime('%Y-%m-%d %H:%M') if pd.notna(dt) else 'ismeretlen dátum'} | {kind} | {name}"
        rows.append((str(key), label, dt if pd.notna(dt) else pd.Timestamp.min))
    rows.sort(key=lambda x: x[2])
    keys = [x[0] for x in rows]
    return keys, {x[0]: x[1] for x in rows}


def _fpi_v411_prepare_scope(
    df: pd.DataFrame,
    mode: str,
    selected_week: Optional[str] = None,
    selected_event: Optional[str] = None,
    date_range: Optional[Tuple[object, object]] = None,
) -> Tuple[pd.DataFrame, str, Dict[str, object]]:
    data = df.copy()
    data["_fpi_scope_selected_v411"] = False
    data["_fpi_scope_code_v411"] = ""
    dt = pd.to_datetime(data.get("start_time"), errors="coerce")
    mode = str(mode or "Automatikus felismerés")
    report_key = str(selected_week or (_fpi_latest_week(data) or ""))
    label = format_week_label(report_key) if report_key else "Nincs kiválasztott időszak"
    scope_type = "week"

    if mode == "Egyetlen esemény":
        event_key = _fpi_v202_event_key(data).astype(str)
        mask = event_key.eq(str(selected_event))
        scope_type = "single_session"
        report_key = FPI_SCOPE_KEY_V411
        label = "Egyetlen esemény"
        if mask.any():
            dmin = dt[mask].dropna().min()
            name = data.loc[mask, "session_name"].dropna().astype(str).iloc[0] if "session_name" in data.columns and data.loc[mask, "session_name"].notna().any() else "Session"
            label = f"{dmin.strftime('%Y-%m-%d %H:%M') if pd.notna(dmin) else 'ismeretlen dátum'} | {name}"
            data.loc[mask, "_fpi_scope_selected_v411"] = True
            data.loc[mask, "_fpi_scope_code_v411"] = report_key
    elif mode == "Egyéni dátumtartomány":
        start = end = None
        if isinstance(date_range, (tuple, list)) and len(date_range) >= 2:
            start, end = pd.to_datetime(date_range[0], errors="coerce"), pd.to_datetime(date_range[1], errors="coerce")
        if pd.notna(start) and pd.notna(end):
            if end < start:
                start, end = end, start
            mask = dt.dt.normalize().between(start.normalize(), end.normalize())
            data.loc[mask, "_fpi_scope_selected_v411"] = True
            data.loc[mask, "_fpi_scope_code_v411"] = FPI_SCOPE_KEY_V411
            report_key = FPI_SCOPE_KEY_V411
            scope_type = "date_range"
            label = f"{start.strftime('%Y-%m-%d')} – {end.strftime('%Y-%m-%d')}"
    elif mode == "Teljes feltöltött időszak":
        scope_type = "full_period"
        report_key = str(selected_week or (_fpi_latest_week(data) or ""))
        dvalid = dt.dropna()
        label = f"{dvalid.min().strftime('%Y-%m-%d')} – {dvalid.max().strftime('%Y-%m-%d')}" if not dvalid.empty else "Teljes feltöltött időszak"
    else:
        scope_type = "week"
        report_key = str(selected_week or (_fpi_latest_week(data) or ""))
        label = format_week_label(report_key)

    meta = {
        "mode_selection": mode,
        "scope_type": scope_type,
        "report_key": report_key,
        "label": label,
        "selected_week": selected_week,
        "selected_event": selected_event,
        "date_range": date_range,
    }
    st.session_state["fpi_analysis_scope_v411"] = meta
    return data, report_key, meta


_fpi_v411_base_master_dataset = _fpi_v300_master_dataset

def _fpi_v300_master_dataset(data: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, object]]:
    out, report = _fpi_v411_base_master_dataset(data)
    if out is None or out.empty:
        return out, report
    if "_fpi_scope_selected_v411" in out.columns and "_fpi_scope_code_v411" in out.columns:
        mask = out["_fpi_scope_selected_v411"].fillna(False).astype(bool)
        codes = out["_fpi_scope_code_v411"].fillna("").astype(str)
        valid = mask & codes.str.strip().ne("")
        out.loc[valid, "week"] = codes[valid]
        report = dict(report or {})
        report["weeks"] = sorted(out["week"].dropna().astype(str).unique().tolist(), key=_fpi_week_sort_key_v99)
        report["analysis_scope_rows_v411"] = int(valid.sum())
    return out, report


def _fpi_v411_scope_meta_for_week(week: object) -> Dict[str, object]:
    meta = st.session_state.get("fpi_analysis_scope_v411", {}) or {}
    return meta if str(meta.get("report_key", "")) == str(week) else {}


_fpi_v411_base_format_week_label = format_week_label
_fpi_v411_base_week_label_short = week_label_short

def format_week_label(week_code: str) -> str:
    meta = _fpi_v411_scope_meta_for_week(week_code)
    if meta:
        return str(meta.get("label") or week_code)
    return _fpi_v411_base_format_week_label(week_code)


def week_label_short(week_code: str) -> str:
    meta = _fpi_v411_scope_meta_for_week(week_code)
    if meta:
        return str(meta.get("label") or week_code)
    return _fpi_v411_base_week_label_short(week_code)


def _fpi_v411_week_column(df: pd.DataFrame) -> pd.Series:
    if "_fpi_original_week_v300" in df.columns:
        original = df["_fpi_original_week_v300"].astype("string")
        if original.notna().any():
            return original.astype(str)
    return df.get("week", pd.Series("", index=df.index)).astype(str)


def _fpi_v411_complete_week_codes(df: pd.DataFrame, cutoff: Optional[pd.Timestamp] = None) -> List[str]:
    if df is None or df.empty or "start_time" not in df.columns:
        return []
    data = df.copy()
    data["_dt_v411"] = pd.to_datetime(data["start_time"], errors="coerce")
    data = data[data["_dt_v411"].notna()].copy()
    if cutoff is not None and pd.notna(cutoff):
        data = data[data["_dt_v411"] <= pd.to_datetime(cutoff)]
    if data.empty:
        return []
    data["_week_real_v411"] = _fpi_v411_week_column(data)
    data = data[data["_week_real_v411"].str.match(r"^\d{4}-W\d{2}$", na=False)]
    if data.empty:
        return []
    data["_event_v411"] = _fpi_v202_event_key(data)
    data["_kind_v411"] = data.get("session_type", pd.Series("", index=data.index)).apply(_fpi_v200_session_kind)
    complete = []
    for week, group in data.groupby("_week_real_v411"):
        events = group[["_event_v411", "_kind_v411", "_dt_v411"]].drop_duplicates("_event_v411")
        training_n = int((events["_kind_v411"] == "training").sum())
        match_n = int((events["_kind_v411"] == "match").sum())
        event_n = int(len(events))
        span = int((events["_dt_v411"].max().normalize() - events["_dt_v411"].min().normalize()).days) if event_n else 0
        if event_n >= 3 and span >= 3 and (match_n >= 1 or training_n >= 4):
            complete.append(str(week))
    return sorted(set(complete), key=_fpi_week_sort_key_v99)


def _fpi_v411_trend_status(df: pd.DataFrame, selected_week: Optional[str] = None) -> Dict[str, object]:
    cutoff = None
    if df is not None and not df.empty:
        if selected_week and str(selected_week) in set(df.get("week", pd.Series(dtype=str)).astype(str)):
            cutoff = pd.to_datetime(df.loc[df["week"].astype(str).eq(str(selected_week)), "start_time"], errors="coerce").max()
        if cutoff is None or pd.isna(cutoff):
            cutoff = pd.to_datetime(df.get("start_time"), errors="coerce").max()
    complete = _fpi_v411_complete_week_codes(df, cutoff)
    n = len(complete)
    if n >= 4:
        return {"available": True, "code": "trend", "complete_weeks": complete, "count": n, "label": f"{n} teljes hét – trend értékelhető"}
    if n >= 2:
        return {"available": False, "code": "comparison", "complete_weeks": complete, "count": n, "label": f"{n} teljes hét – összehasonlítás, még nem trend"}
    return {"available": False, "code": "limited", "complete_weeks": complete, "count": n, "label": "Nincs legalább 4 teljes hét; trend nem készül"}


_fpi_v411_base_detect_mode = _fpi_v202_detect_analysis_mode

def _fpi_v202_detect_analysis_mode(df: pd.DataFrame, selected_week: Optional[str] = None) -> Dict[str, object]:
    mode = dict(_fpi_v411_base_detect_mode(df, selected_week) or {})
    meta = _fpi_v411_scope_meta_for_week(selected_week)
    if meta.get("scope_type") == "single_session":
        mode.update({"code": "single_session", "label": "Egyszeri edzéselemzés", "description": "Egyetlen esemény sessionprofilja. Heti trend és teljes Readiness nem készül.", "is_complete_week": False, "is_provisional": True})
    elif meta.get("scope_type") == "date_range":
        total = int(mode.get("total_sessions", 0) or 0)
        mode.update({"code": "date_range", "label": "Egyéni dátumtartomány", "description": f"{meta.get('label')} közötti {total} esemény elemzése. A rendszer nem kezeli automatikusan teljes hétként.", "is_complete_week": False, "is_provisional": True})
    trend = _fpi_v411_trend_status(df, selected_week)
    mode["trend_status_v411"] = trend
    return mode


_fpi_v411_base_pattern_insights = build_pattern_insights

def build_pattern_insights(df: pd.DataFrame, selected_week: str) -> List[Insight]:
    status = _fpi_v411_trend_status(df, selected_week)
    if not status.get("available"):
        return []
    return _fpi_v411_base_pattern_insights(df, selected_week)


_fpi_v411_base_report_context = _fpi_report_context

def _fpi_report_context(data: pd.DataFrame, selected_week: Optional[str] = None, playstyle: str = "Kiegyensúlyozott", tactical_context: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    ctx = _fpi_v411_base_report_context(data, selected_week, playstyle, tactical_context)
    if ctx.get("error"):
        return ctx
    df = ctx.get("df", pd.DataFrame())
    week = str(ctx.get("selected_week", selected_week or ""))
    mode = _fpi_v202_detect_analysis_mode(df, week)
    trend = _fpi_v411_trend_status(df, week)
    ctx["analysis_mode_v411"] = mode
    ctx["trend_status_v411"] = trend
    ctx["analysis_scope_v411"] = _fpi_v411_scope_meta_for_week(week)
    code = str(mode.get("code", ""))
    ctx["readiness_status_v411"] = "full" if code == "full_microcycle" else ("preliminary" if code in {"week_in_progress", "preseason_block", "date_range"} else "not_available")

    breakdown = ctx.get("readiness_breakdown_v302")
    if isinstance(breakdown, pd.DataFrame) and not breakdown.empty and not trend.get("available"):
        breakdown = breakdown.copy()
        breakdown["Pont"] = breakdown["Pont"].astype(object)
        mask = breakdown["Komponens"].astype(str).str.contains("Terhelési trend", case=False, na=False)
        breakdown.loc[mask, "Komponens"] = "Terhelési összehasonlítás"
        breakdown.loc[mask, "Pont"] = "n.a."
        breakdown.loc[mask, "Státusz"] = "Nem minősített"
        breakdown.loc[mask, "Magyarázat"] = (
            "Mit jelent? Az elérhető teljes hetek leíró összevetése. Most: "
            + str(trend.get("label"))
            + ". Ez nem trendpont és nem módosítja a Readiness összpontszámát."
        )
        ctx["readiness_breakdown_v302"] = breakdown

    if not trend.get("available"):
        ctx["insights"] = [x for x in (ctx.get("insights") or []) if "trend" not in _norm_mapping_text(getattr(x, "title", ""))]
        ctx["insights_df"] = build_insight_export_df(ctx["insights"])
        summary = str(ctx.get("summary", ""))
        summary = re.sub(r"(?i)többhetes trend", "heti összehasonlítás", summary)
        ctx["summary"] = summary + f"\n\nIdősoros státusz: {trend.get('label')}."

    if code == "single_session":
        ctx["risk_df"] = pd.DataFrame()
        ctx["next_df"] = pd.DataFrame()
        ctx["microcycle_plan_v300"] = pd.DataFrame()
        ctx["summary"] = "Egyetlen esemény sessionprofilja készült. A riport az edzés volumenét, intenzitását, sebességi ingerét és a kereten belüli eltéréseket értékeli; heti trendet és teljes Readiness pontot nem közöl."
    return ctx


_fpi_v411_base_aligned_comparison = _fpi_v204_aligned_comparison

def _fpi_v204_aligned_comparison(df: pd.DataFrame, week: str, blocked: set) -> pd.DataFrame:
    status = _fpi_v411_trend_status(df, week)
    meta = _fpi_v411_scope_meta_for_week(week)
    if not status.get("available") and status.get("count", 0) < 2:
        return pd.DataFrame()
    if not meta:
        return _fpi_v411_base_aligned_comparison(df, week, blocked)
    if df is None or df.empty or "start_time" not in df.columns:
        return pd.DataFrame()
    data = df.copy()
    data["_dt204"] = pd.to_datetime(data["start_time"], errors="coerce")
    data = data[data["_dt204"].notna()].copy()
    selected = data[data.get("week", pd.Series("", index=data.index)).astype(str).eq(str(week))].copy()
    if selected.empty:
        return pd.DataFrame()
    cutoff_day = int(selected["_dt204"].dt.weekday.max())
    selected_max = selected["_dt204"].max()
    data = data[data["_dt204"] <= selected_max].copy()
    data["_week_real_v411"] = _fpi_v411_week_column(data)
    rows = []

    def _row_from_group(group: pd.DataFrame, group_week: str, display_week: str, comparison_text: str) -> Optional[Dict[str, object]]:
        if group is None or group.empty:
            return None
        local = group.copy()
        local["week"] = str(group_week)
        player_period = _fpi_v204_player_period(local, str(group_week), blocked)
        row = {"Hét": display_week, "Összevetés": comparison_text}
        for c, label in [("total_distance", "Medián össztáv"), ("hsr_distance", "Medián HSR"), ("sprint_distance", "Medián sprint"), ("training_load", "Medián load")]:
            row[label] = float(pd.to_numeric(player_period.get(c), errors="coerce").median()) if c in player_period.columns else np.nan
        return row

    # Korábbi teljes hetek ugyaneddig a hétközi pontig.
    for w in status.get("complete_weeks", [])[-6:]:
        if str(w) == str(week):
            continue
        g = data[(data["_week_real_v411"].astype(str) == str(w)) & (data["_dt204"].dt.weekday <= cutoff_day)].copy()
        row = _row_from_group(g, str(w), str(w), f"azonos hétközi pontig ({cutoff_day + 1}. nap)")
        if row:
            rows.append(row)

    # Az aktuális teljes vagy csonka hét mindig külön sorban szerepel.
    current_row = _row_from_group(
        selected,
        str(week),
        f"{format_week_label(str(week))} – aktuális",
        f"tényleges adat eddig ({cutoff_day + 1}. nap)",
    )
    if current_row:
        rows.append(current_row)
    return pd.DataFrame(rows)


# =============================================================================
# V423 – Éles riporttal azonos minta-PDF pipeline
# =============================================================================
@st.cache_data(show_spinner=False)
def _fpi_v423_production_like_sample_df() -> pd.DataFrame:
    """Életszerű, 8 teljes mikrociklusos mintaadat az ÉLES renderelők tesztjéhez.

    A minta PDF-ek nem külön statikus sablont használnak: ugyanazokat a
    riport-renderelőket kapják, mint a klubok éles exportjai. A szintetikus
    adat csak a bemenetet helyettesíti.
    """
    demo_raw = build_demo_performance_data()
    demo_df, _, missing = standardize_dataframe(demo_raw)
    if missing or demo_df is None or demo_df.empty:
        return pd.DataFrame()

    # Éleshez hasonló keretméret: 20 mezőnyjátékos + 3 kapus.
    roster = [
        ("Nagy Bence", "CB"), ("Kovács Márk", "CB"), ("Tóth Ádám", "FB"),
        ("Szabó Levente", "FB"), ("Varga Dávid", "DM"), ("Molnár Máté", "CM"),
        ("Farkas Bálint", "CM"), ("Horváth Patrik", "AM"), ("Kiss Zalán", "W"),
        ("Takács Dániel", "W"), ("Balogh Gergő", "F"), ("Papp András", "F"),
        ("Lakatos Milán", "CB"), ("Juhász Roland", "FB"), ("Oláh Kristóf", "DM"),
        ("Simon Áron", "CM"), ("Fehér Botond", "AM"), ("Sipos Noel", "W"),
        ("Kelemen Zsombor", "CM"), ("Bíró Dominik", "F"),
        ("Pálfi Kristóf", "GK"), ("Ruisz Barnabás", "GK"), ("Szabados István", "GK"),
    ]
    source_players = demo_df["player_name"].dropna().astype(str).drop_duplicates().tolist()
    if not source_players:
        return pd.DataFrame()

    blocks = []
    additive = [
        "total_distance", "hsr_distance", "sprint_distance", "training_load",
        "muscle_load", "sprints", "high_efforts", "acc_count", "dec_count",
        "acc_high", "dec_high", "speed_zone_4", "speed_zone_5",
    ]
    for idx, (name, position) in enumerate(roster):
        template = source_players[idx % len(source_players)]
        block = demo_df[demo_df["player_name"].astype(str).eq(str(template))].copy()
        if block.empty:
            continue
        block["player_name"] = name
        if "position" in block.columns:
            block["position"] = position
        scale = 0.90 + (idx % 11) * 0.018
        if position == "GK":
            scale = 0.72 + (idx % 3) * 0.025
        for col in additive:
            if col in block.columns:
                vals = pd.to_numeric(block[col], errors="coerce")
                metric_scale = scale
                if position == "GK" and col in {"hsr_distance", "sprint_distance", "sprints", "speed_zone_4", "speed_zone_5"}:
                    metric_scale *= 0.35
                block[col] = vals * metric_scale
        if "max_speed" in block.columns:
            ms = pd.to_numeric(block["max_speed"], errors="coerce")
            block["max_speed"] = ms - (2.8 if position == "GK" else 0.0) + ((idx % 5) - 2) * 0.18
        blocks.append(block)

    if not blocks:
        return pd.DataFrame()
    demo_df = pd.concat(blocks, ignore_index=True, sort=False)
    demo_df = add_position_group(demo_df)
    demo_df, _ = _fpi_v300_master_dataset(demo_df)

    # A beépített demo 3 teljes hetes. Visszafelé klónozzuk 8 teljes hétig,
    # hogy a trend, saját múlt és meccsreferencia ugyanúgy működjön, mint élesben.
    guard = 0
    while guard < 8:
        guard += 1
        complete = _fpi_v411_complete_week_codes(demo_df)
        if len(complete) >= 8:
            break
        if not complete:
            break
        earliest = str(complete[0])
        clone = demo_df[demo_df["week"].astype(str).eq(earliest)].copy()
        if clone.empty:
            break
        clone["start_time"] = pd.to_datetime(clone["start_time"], errors="coerce") - pd.Timedelta(days=7)
        hist_scale = max(0.88, 0.97 - 0.012 * guard)
        for col in [
            "total_distance", "hsr_distance", "sprint_distance", "training_load",
            "muscle_load", "sprints", "high_efforts", "acc_count", "dec_count",
            "acc_high", "dec_high", "speed_zone_4", "speed_zone_5",
        ]:
            if col in clone.columns:
                clone[col] = pd.to_numeric(clone[col], errors="coerce") * hist_scale
        for col in ["session_id", "match_event_id", "_fpi_event_id_v413"]:
            if col in clone.columns:
                clone[col] = clone[col].astype(str) + f"_SAMPLE_H{guard}"
        demo_df = pd.concat([clone, demo_df], ignore_index=True, sort=False)
        demo_df, _ = _fpi_v300_master_dataset(demo_df)

    return demo_df


def _fpi_v423_sample_latest_week(df: pd.DataFrame) -> Optional[str]:
    if df is None or df.empty:
        return None
    complete = _fpi_v411_complete_week_codes(df)
    if complete:
        return str(complete[-1])
    return _fpi_latest_week(df)


# A landing oldalon továbbra is egyetlen GPS-minta marad, de több teljes hetet mutat.
def build_fpi_gps_only_sample_pdf_bytes() -> Optional[bytes]:
    """GPS minta: ugyanaz az éles PDF-renderelő, ugyanaz a teljes-mikrociklus scope."""
    demo_df = _fpi_v423_production_like_sample_df()
    latest = _fpi_v423_sample_latest_week(demo_df)
    if demo_df is None or demo_df.empty or not latest:
        return None
    # Nincs külön minta-sablon és nincs eltérő főcím: ugyanaz a cím/szerkezet, mint élesben.
    # A letöltési fájlnév és a szintetikus Demo FC adatok jelzik, hogy mintáról van szó.
    return build_fpi_gps_only_pdf_bytes(
        demo_df, latest, "Magas letámadás",
    )




# =============================================================================
# V413 – Providerfüggetlen forrásfájl-eseménymotor
# =============================================================================
# Alapelv:
# - egy feltöltött forrásfájl alapértelmezetten egy csapatedzés vagy egy meccs;
# - a játékosok eltérő eszközindítási ideje nem hoz létre új sessiont;
# - ugyanazon fájl/dátum/típus csoportot csak legalább 120 perces időrés választja szét;
# - forrásmeta nélkül dátum + típus + sessionnév + időklaszter a fallback;
# - a logika minden providerre és a Smart Mapper útvonalra is érvényes.

FPI_IMPORT_ENGINE_VERSION = "FPI_V413_SOURCE_EVENT_ENGINE_2026_08_05"
FPI_EVENT_SPLIT_GAP_MIN_V413 = 120


def _fpi_v413_nonempty_text_series(df: pd.DataFrame, col: str) -> pd.Series:
    if col not in df.columns:
        return pd.Series("", index=df.index, dtype="object")
    out = df[col].astype("string").fillna("").astype(str).str.strip()
    return out.replace({"nan": "", "None": "", "<NA>": ""})


def _fpi_v413_source_token(df: pd.DataFrame) -> pd.Series:
    """Stabil, providerfüggetlen feltöltési egység azonosító.

    A fájlnév az elsődleges, mert a terméklogika szerint egy feltöltött fájl
    egy esemény. A source_key csak akkor fallback, ha nincs fájlnév.
    """
    token = pd.Series("", index=df.index, dtype="object")
    for col in ["_fpi_source_upload_id", "_fpi_source_file", "_source_file", "_fpi_source_key"]:
        candidate = _fpi_v413_nonempty_text_series(df, col)
        token = token.where(token.astype(str).str.strip().ne(""), candidate)
    return token.astype(str).str.strip()


def _fpi_v413_clean_event_name(df: pd.DataFrame) -> pd.Series:
    name = _fpi_v413_nonempty_text_series(df, "session_name").map(_fpi_v200_norm)
    generic = name.str.contains(
        r"^period\b|^split\b|^drill\b|^quarter\b|^half\b|"
        r"első félidő|elso felido|második félidő|masodik felido|"
        r"warm.?up|bemelegítés|bemelegites|cool.?down|levezetés|levezetes|"
        r"^all$|^game$|^session$",
        regex=True,
        na=False,
    )
    return name.mask(generic, "session").replace({"": "session"})


def _fpi_v413_time_clusters(start: pd.Series, group_keys: pd.DataFrame, gap_min: int = FPI_EVENT_SPLIT_GAP_MIN_V413) -> pd.Series:
    """Időklaszter: a játékosok néhány perces eltérése egy esemény marad."""
    clusters = pd.Series(0, index=start.index, dtype="int64")
    work = group_keys.copy()
    work["_start_v413"] = pd.to_datetime(start, errors="coerce")
    work["_idx_v413"] = work.index
    key_cols = [c for c in group_keys.columns]
    for _, group in work.groupby(key_cols, dropna=False, sort=False):
        valid = group[group["_start_v413"].notna()].sort_values("_start_v413")
        if valid.empty:
            continue
        unique_times = valid["_start_v413"].drop_duplicates().sort_values()
        cluster_by_time = {}
        cluster = 0
        previous = None
        for ts in unique_times:
            if previous is not None and (ts - previous).total_seconds() / 60.0 >= float(gap_min):
                cluster += 1
            cluster_by_time[ts] = cluster
            previous = ts
        clusters.loc[valid.index] = valid["_start_v413"].map(cluster_by_time).fillna(0).astype(int)
    return clusters


def _fpi_v413_assign_source_events(df: pd.DataFrame) -> pd.DataFrame:
    """Minden sort egy valódi csapateseményhez rendel.

    Forrásfájl esetén az ugyanazon fájlban, ugyanazon napon és azonos típusban
    lévő játékossorok egy sessiont alkotnak. A pontos kezdési idő nem játékos-
    session azonosító, csak az esemény reprezentatív kezdésének forrása.
    """
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df.copy()

    out = df.copy()
    raw_start_v414 = _fpi_v414_series_alias(out, "start_time", "Start Time", "Kezdési idő", "Date", "Dátum", default=pd.NaT)
    raw_type_v414 = _fpi_v414_series_alias(out, "session_type", "Session Type", "Típus", "Type", default="")
    raw_name_v414 = _fpi_v414_series_alias(out, "session_name", "Session Name", "Szakasz neve", "Session", default="Session")
    start = pd.to_datetime(raw_start_v414, errors="coerce")
    day = start.dt.strftime("%Y-%m-%d").fillna("")
    kind = raw_type_v414.apply(_fpi_v200_session_kind).replace({"other": "training"})
    source = _fpi_v413_source_token(out)
    name = _fpi_v413_clean_event_name(out)

    has_source = source.ne("")
    source_group = pd.DataFrame({
        "source": source.where(has_source, "__NO_SOURCE__"),
        "day": day,
        "kind": kind.astype(str),
        # Forrás nélkül a sessionnév szükséges a szétválasztáshoz.
        "fallback_name": name.where(~has_source, "file_event"),
    }, index=out.index)
    cluster = _fpi_v413_time_clusters(start, source_group, FPI_EVENT_SPLIT_GAP_MIN_V413)

    source_id = source.where(has_source, "fallback")
    event_id = (
        source_id.astype(str)
        + "|" + day.astype(str)
        + "|" + kind.astype(str)
        + "|" + name.where(~has_source, "file_event").astype(str)
        + "|c" + cluster.astype(str)
    )
    missing_day = day.eq("")
    if missing_day.any():
        event_id.loc[missing_day] = (
            source_id.loc[missing_day].astype(str)
            + "|nodate|" + kind.loc[missing_day].astype(str)
            + "|" + name.loc[missing_day].astype(str)
            + "|c" + cluster.loc[missing_day].astype(str)
        )

    out["_fpi_event_id"] = event_id.astype(str)
    out["_fpi_event_cluster"] = cluster.astype(int)
    out["_fpi_event_source"] = source.astype(str)

    event_start = out.groupby("_fpi_event_id", dropna=False)["start_time"].transform(
        lambda s: pd.to_datetime(s, errors="coerce").min()
    )
    out["_fpi_event_start"] = pd.to_datetime(event_start, errors="coerce")

    # Reprezentatív név: a csoport leggyakoribb, nem üres sessionneve.
    def _mode_name(s: pd.Series) -> str:
        clean = s.astype("string").fillna("").astype(str).str.strip()
        clean = clean[~clean.isin(["", "nan", "None"])]
        if clean.empty:
            return "Session"
        modes = clean.mode()
        return str(modes.iloc[0] if not modes.empty else clean.iloc[0])

    out["_fpi_event_raw_name_v414"] = raw_name_v414
    out["_fpi_event_name"] = out.groupby("_fpi_event_id", dropna=False)["_fpi_event_raw_name_v414"].transform(_mode_name)
    return out.drop(columns=["_fpi_event_raw_start_v414", "_fpi_event_raw_name_v414"], errors="ignore")


def _fpi_v413_event_key(df: pd.DataFrame) -> pd.Series:
    if df is None or df.empty:
        return pd.Series(dtype="object")
    for col in ["session_id", "_fpi_event_id"]:
        if col in df.columns:
            key = df[col].astype("string").fillna("").astype(str).str.strip()
            if key.ne("").any():
                fallback = _fpi_v413_assign_source_events(df)["_fpi_event_id"].astype(str)
                return key.where(key.ne(""), fallback)
    return _fpi_v413_assign_source_events(df)["_fpi_event_id"].astype(str)


# Minden későbbi session-, attendance- és scope-számítás ugyanazt a kulcsot használja.
def _fpi_v201_training_session_key(df: pd.DataFrame) -> pd.Series:
    return _fpi_v413_event_key(df)


def _fpi_v202_event_key(df: pd.DataFrame) -> pd.Series:
    if df is None or df.empty:
        return pd.Series(dtype="object")
    data = df.copy()
    kind = data.get("session_type", pd.Series("", index=data.index)).apply(_fpi_v200_session_kind)
    key = _fpi_v413_event_key(data)
    if "match_event_id" in data.columns:
        match_event = data["match_event_id"].astype("string").fillna("").astype(str).str.strip()
        use_match = kind.eq("match") & match_event.ne("")
        key = key.where(~use_match, "match|" + match_event)
    return key.astype(str)


# A V411 scope-wrapper marad, a kimenetet esemény- és attendance-szinten újraszámoljuk.
_fpi_v413_base_master_dataset = _fpi_v300_master_dataset

def _fpi_v300_master_dataset(data: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, object]]:
    out, report = _fpi_v413_base_master_dataset(data)
    if out is None or out.empty:
        return out, report

    out = _fpi_v413_assign_source_events(out)
    out["session_id"] = out["_fpi_event_id"].astype(str)
    if "match_event_id" in out.columns:
        match_id = out["match_event_id"].astype("string").fillna("").astype(str).str.strip()
        match_mask = out.get("session_type", pd.Series("", index=out.index)).astype(str).eq("Meccs") & match_id.ne("")
        out.loc[match_mask, "session_id"] = "match|" + match_id.loc[match_mask]

    # A korábbi importlépésben számolt attendance-et mindig felülírja a valódi
    # fájl-esemény kulccsal újraszámolt érték.
    out = _fpi_v201_add_training_attendance(out, recovery_log=[])

    report = dict(report or {})
    event_key = _fpi_v202_event_key(out)
    kinds = out.get("session_type", pd.Series("", index=out.index)).apply(_fpi_v200_session_kind)
    report["sessions"] = int(event_key.dropna().astype(str).nunique())
    report["training_sessions"] = int(event_key[kinds.eq("training")].dropna().astype(str).nunique())
    report["analysis_match_sessions"] = int(event_key[kinds.eq("match")].dropna().astype(str).nunique())
    report["event_engine_v413"] = "source-file/date/type + 120-minute split gap"
    _source_tokens_v413 = _fpi_v413_source_token(out)
    report["event_source_files_v413"] = int(_source_tokens_v413[_source_tokens_v413.astype(str).str.strip().ne("")].nunique())
    out.attrs["fpi_v300_master_report"] = report
    return out, report


# -----------------------------------------------------------------------------
# V413 – játékosrisk: játékosonként egy heti/scope-sor, minimum 2 lezárt előzmény
# -----------------------------------------------------------------------------
def _fpi_v413_player_weekly_risk(df: pd.DataFrame) -> pd.DataFrame:
    work = finalize_exposure_columns(df) if df is not None and not df.empty else pd.DataFrame()
    if work.empty or not {"player_name", "week"}.issubset(work.columns):
        return pd.DataFrame()

    work = work.copy()
    sum_cols = [
        "total_distance", "training_load", "muscle_load", "hsr_distance",
        "sprint_distance", "sprints", "acc_count", "dec_count", "high_efforts",
        "duration_min", "player_minutes",
    ]
    mean_cols = ["distance_per_min", "hr_avg", "hrv"]
    max_cols = [
        "max_speed", "is_goalkeeper", "team_training_sessions",
        "player_training_sessions", "training_availability_pct",
    ]
    agg = {c: "sum" for c in sum_cols if c in work.columns}
    agg.update({c: "mean" for c in mean_cols if c in work.columns})
    agg.update({c: "max" for c in max_cols if c in work.columns})
    if not agg:
        return pd.DataFrame()

    res = work.groupby(["player_name", "week"], as_index=False, dropna=False).agg(agg)
    if "session_type" in work.columns:
        type_map = (
            work.groupby(["player_name", "week"], dropna=False)["session_type"]
            .agg(lambda s: "Vegyes" if len(set(s.dropna().astype(str))) > 1 else (str(s.dropna().astype(str).iloc[0]) if not s.dropna().empty else ""))
            .reset_index(name="session_type")
        )
        res = res.merge(type_map, on=["player_name", "week"], how="left")
    return res


def calculate_player_risk(df: pd.DataFrame, selected_week: str) -> pd.DataFrame:
    pw = _fpi_v413_player_weekly_risk(df)
    if pw.empty or str(selected_week) not in set(pw["week"].astype(str)):
        return pd.DataFrame()

    cur = pw[pw["week"].astype(str).eq(str(selected_week))].copy()
    # A baseline csak lezárt korábbi hetekből készül. Két előzmény alatt nincs
    # százalékos "saját átlag" minősítés, mert az félrevezető lenne.
    try:
        complete_weeks = [w for w in _fpi_v411_complete_week_codes(df) if str(w) != str(selected_week)]
    except Exception:
        complete_weeks = []
    selected_sort = _fpi_week_sort_key_v99(selected_week)
    prior_complete = [w for w in complete_weeks if _fpi_week_sort_key_v99(w) < selected_sort][-4:]
    baseline_ready = len(prior_complete) >= 2
    hist = pw[pw["week"].astype(str).isin(prior_complete)].copy() if baseline_ready else pd.DataFrame()

    rows = []
    for _, row in cur.iterrows():
        player = row["player_name"]
        hp = hist[hist["player_name"].astype(str).eq(str(player))] if baseline_ready else pd.DataFrame()
        score = 20
        reasons = []
        is_gk = bool(row.get("is_goalkeeper", False))
        team_sessions = int(pd.to_numeric(pd.Series([row.get("team_training_sessions", 0)]), errors="coerce").fillna(0).iloc[0])
        player_sessions = int(pd.to_numeric(pd.Series([row.get("player_training_sessions", 0)]), errors="coerce").fillna(0).iloc[0])
        availability = pd.to_numeric(pd.Series([row.get("training_availability_pct", np.nan)]), errors="coerce").iloc[0]
        low_attendance = team_sessions >= 2 and pd.notna(availability) and availability < 75
        if low_attendance:
            score += 20 if availability < 50 else 12
            reasons.append(f"Edzésrészvétel: {player_sessions}/{team_sessions} ({availability:.0f}%)")

        metric_pack = [
            ("training_load", .35 if is_gk else .30, -0.40 if is_gk else -0.35, "Terhelési pont"),
            ("high_efforts", .45 if is_gk else .35, -0.45 if is_gk else -0.40, "High Efforts"),
            ("dec_count", .45 if is_gk else .35, -0.45 if is_gk else -0.40, "Lassítás"),
        ]
        if not is_gk:
            metric_pack.append(("sprint_distance", .45, -0.45, "Sprinttáv"))

        if baseline_ready and len(hp) >= 2:
            for metric, hi, lo, label in metric_pack:
                if metric not in row.index or metric not in hp.columns:
                    continue
                value = pd.to_numeric(pd.Series([row.get(metric, np.nan)]), errors="coerce").iloc[0]
                base = pd.to_numeric(hp[metric], errors="coerce").median()
                if pd.isna(value) or pd.isna(base) or base == 0:
                    continue
                delta = (value - base) / base
                if delta > hi:
                    score += 18
                    reasons.append(f"{label}: +{delta:.0%} a saját {len(hp)} hetes mediánhoz képest")
                elif delta < lo:
                    if low_attendance:
                        if not any("hiányos edzésrészvétel" in x for x in reasons):
                            reasons.append("Az alacsony heti érték fő oka valószínűleg a hiányos edzésrészvétel.")
                    else:
                        score += 8
                        reasons.append(f"{label}: {delta:.0%} a saját {len(hp)} hetes mediánhoz képest")

            if "player_minutes" in row.index and "player_minutes" in hp.columns:
                value = pd.to_numeric(pd.Series([row.get("player_minutes", np.nan)]), errors="coerce").iloc[0]
                base = pd.to_numeric(hp["player_minutes"], errors="coerce").median()
                if pd.notna(value) and pd.notna(base) and base > 0 and abs((value - base) / base) > .35:
                    delta = (value - base) / base
                    score += 8
                    reasons.append(f"Játékperc/exposure: {delta:+.0%} a saját mediánhoz képest")

            if (not is_gk) and "max_speed" in row.index and "max_speed" in hp.columns:
                value = pd.to_numeric(pd.Series([row.get("max_speed", np.nan)]), errors="coerce").iloc[0]
                base = pd.to_numeric(hp["max_speed"], errors="coerce").max()
                if pd.notna(value) and pd.notna(base) and base > 0 and (value - base) / base < -.06:
                    score += 14
                    reasons.append(f"Max sebesség: {(value-base)/base:.0%} a saját csúcshoz képest")

        score = int(max(0, min(100, score)))
        level = "Magas" if score >= 70 else ("Közepes" if score >= 45 else "Alacsony")
        attendance_text = f"{player_sessions}/{team_sessions} ({availability:.0f}%)" if team_sessions > 0 and pd.notna(availability) else "n.a."
        if not reasons and not baseline_ready:
            reasons.append("Nincs legalább 2 lezárt korábbi hét; csak a részvételi és aktuális abszolút jelzések értékelhetők.")
        rows.append({
            "Játékos": player,
            "Szerep": "Kapus" if is_gk else "Mezőny",
            "Típus": row.get("session_type", ""),
            "Játékperc": round(float(row.get("player_minutes", 0) or 0), 1),
            "Edzésrészvétel": attendance_text,
            "Edzések": player_sessions,
            "Csapatedzések": team_sessions,
            "Részvétel %": round(float(availability), 1) if pd.notna(availability) else np.nan,
            "Kockázati pontszám": score,
            "Kockázati szint": level,
            "Fő okok": "; ".join(reasons[:3]),
        })

    result = pd.DataFrame(rows)
    if result.empty:
        return result
    # Védőháló: játékosonként kizárólag a legmagasabb kockázatú sor maradhat.
    result["_player_v413"] = result["Játékos"].astype(str).str.strip().str.casefold()
    result = result.sort_values("Kockázati pontszám", ascending=False).drop_duplicates("_player_v413", keep="first")
    return result.drop(columns=["_player_v413"]).sort_values("Kockázati pontszám", ascending=False).reset_index(drop=True)


# -----------------------------------------------------------------------------
# V413 – mikrociklus referencia: egy hétből nincs "saját medián"
# -----------------------------------------------------------------------------
def _fpi_v407_plan_context(df: pd.DataFrame, selected_week: str) -> Dict[str, object]:
    weeks = sorted(df["week"].dropna().astype(str).unique().tolist(), key=_fpi_week_sort_key_v99) if df is not None and not df.empty and "week" in df.columns else []
    current = _fpi_v407_week_field_profile(df, selected_week)
    selected_key = _fpi_week_sort_key_v99(selected_week)
    try:
        complete = _fpi_v411_complete_week_codes(df)
    except Exception:
        complete = []
    previous_weeks = [w for w in complete if _fpi_week_sort_key_v99(w) < selected_key][-4:]
    history = [_fpi_v407_week_field_profile(df, w) for w in previous_weeks]
    history = [x for x in history if x]
    comparison_ready = len(history) >= 2
    previous = history[-1] if history else {}
    baseline = {}
    metrics = ["training_load", "total_distance", "hsr_distance", "sprint_distance", "distance_per_min", "max_speed", "dec_count", "high_efforts"]
    for metric in metrics:
        vals = [x.get(metric) for x in history if pd.notna(x.get(metric, np.nan))]
        baseline[metric] = float(np.median(vals)) if comparison_ready and vals else np.nan
    ratios = {}
    for metric in metrics:
        cur = current.get(metric, np.nan)
        base = baseline.get(metric, np.nan)
        ratios[metric] = float(cur / base) if comparison_ready and pd.notna(cur) and pd.notna(base) and base > 0 else np.nan

    daily = build_microcycle_table(df, selected_week)
    early = daily[daily.get("md_label", pd.Series("", index=daily.index)).astype(str).isin(["MD-4", "MD-3"])] if not daily.empty else pd.DataFrame()
    md2 = daily[daily.get("md_label", pd.Series("", index=daily.index)).astype(str).eq("MD-2")] if not daily.empty else pd.DataFrame()
    md1 = daily[daily.get("md_label", pd.Series("", index=daily.index)).astype(str).eq("MD-1")] if not daily.empty else pd.DataFrame()
    peak_early = pd.to_numeric(early.get("load_index"), errors="coerce").max() if not early.empty else np.nan
    md2_ratio = pd.to_numeric(md2.get("load_index"), errors="coerce").sum() / peak_early if not md2.empty and pd.notna(peak_early) and peak_early > 0 else np.nan
    md1_ratio = pd.to_numeric(md1.get("load_index"), errors="coerce").sum() / peak_early if not md1.empty and pd.notna(peak_early) and peak_early > 0 else np.nan
    peak_sprint_md = ""
    train_daily = daily[daily.get("session_type", pd.Series("", index=daily.index)).astype(str).eq("Edzés")] if not daily.empty else pd.DataFrame()
    if not train_daily.empty and "sprint_distance" in train_daily.columns and pd.to_numeric(train_daily["sprint_distance"], errors="coerce").notna().any():
        peak_sprint_md = str(train_daily.loc[pd.to_numeric(train_daily["sprint_distance"], errors="coerce").idxmax()].get("md_label", ""))
    label = (
        "saját 4 lezárt hét mediánja" if len(history) >= 4
        else f"saját {len(history)} lezárt hét mediánja" if comparison_ready
        else "nincs stabil saját heti referencia"
    )
    return {
        "current": current, "previous": previous, "baseline": baseline,
        "ratios": ratios, "previous_weeks": previous_weeks,
        "history_count": len(history), "comparison_ready": comparison_ready,
        "history_label": label, "md2_ratio": md2_ratio, "md1_ratio": md1_ratio,
        "peak_sprint_md": peak_sprint_md,
    }


_fpi_v413_base_next_microcycle_plan = build_next_microcycle_plan

def build_next_microcycle_plan(
    df: pd.DataFrame,
    selected_week: str,
    playstyle: str,
    readiness_score: int,
    periodization_type: str,
    player_risk_df: pd.DataFrame,
) -> pd.DataFrame:
    plan = _fpi_v413_base_next_microcycle_plan(
        df, selected_week, playstyle, readiness_score, periodization_type, player_risk_df
    )
    if plan is None or plan.empty:
        return plan
    ctx = _fpi_v407_plan_context(df, selected_week)
    n = int(ctx.get("history_count", 0) or 0)
    ready = bool(ctx.get("comparison_ready", False))
    out = plan.copy()

    if not ready:
        out["Tervezési alap"] = out["Tervezési alap"].astype(str).map(
            lambda x: re.sub(r"Aktuális mezőnyjátékos-load / saját \d+ hetes medián: n\.a\.;?\s*", "", x)
        )
        md4 = out["Nap"].astype(str).eq("MD-4")
        md3 = out["Nap"].astype(str).eq("MD-3")
        out.loc[md4, "Ajánlott terhelés"] = "meccs-/liga-referencia és aktuális játékosállapot alapján"
        out.loc[md4, "Tervezési alap"] = (
            "Nincs legalább 2 lezárt korábbi hét, ezért saját heti medián és százalékos terhelési eltérés nem készül. "
            f"Readiness: {readiness_score}/100; az aktuális eseménystruktúra és a meccsreferencia használható."
        )
        out.loc[md3, "Ajánlott terhelés"] = "meccsreferenciához és az aktuális ciklushoz igazítva"
        out.loc[md3, "Tervezési alap"] = (
            "Nincs stabil saját többhetes sebességi referencia; a HSR/sprint dózist a rendelkezésre álló meccsprofilhoz, "
            "a következő mérkőzés időzítéséhez és a játékosok aktuális állapotához kell igazítani."
        )
    else:
        label = f"saját {n} lezárt hét mediánja"
        out["Ajánlott terhelés"] = out["Ajánlott terhelés"].astype(str).str.replace("a saját 4 hetes medián", label, regex=False)
        out["Ajánlott terhelés"] = out["Ajánlott terhelés"].astype(str).str.replace("saját 4 hetes medián", label, regex=False)
    return out


# Sessiontábla: reprezentatív fájl-eseménynév és kezdés.
# V416: edzésnél nyers mezőnyjátékos-medián, meccsnél /90 mezőnyjátékos-medián.
FPI_MATCH_SESSION_MIN_MINUTES_V416 = 10.0

def _fpi_v416_match_per90_series(group: pd.DataFrame, metric: str) -> pd.Series:
    """Meccsen player-by-player /90 sorozat, minimum játékperc-kapuval."""
    if group is None or group.empty:
        return pd.Series(dtype=float)
    work = finalize_exposure_columns(group.copy())
    minutes = pd.to_numeric(work.get("player_minutes"), errors="coerce")
    eligible = minutes.ge(FPI_MATCH_SESSION_MIN_MINUTES_V416)
    if not eligible.any():
        return pd.Series(dtype=float)
    per90_col = f"{metric}_per90"
    if per90_col in work.columns:
        return pd.to_numeric(work.loc[eligible, per90_col], errors="coerce")
    raw = pd.to_numeric(work.loc[eligible, metric], errors="coerce") if metric in work.columns else pd.Series(dtype=float)
    mins = minutes.loc[eligible]
    return raw.div(mins.where(mins > 0)).mul(90.0)

def _fpi_v204_session_summary(df: pd.DataFrame, week: str, blocked: set) -> pd.DataFrame:
    """Sessionprofil.

    Edzés: a tényleges session mezőnyjátékos-mediánja.
    Meccs: a félidők játékosonkénti összevonása UTÁN, legalább 10 percet játszó
    mezőnyjátékosok /90 mediánja. Így a cserejátékosok nem húzzák le mesterségesen
    a meccs tipikus össztávját/HSR/sprint/load értékét.
    """
    data = df[df.get("week", pd.Series("", index=df.index)).astype(str).eq(str(week))].copy()
    if data.empty:
        return pd.DataFrame()
    data["_event204"] = _fpi_v202_event_key(data)
    data["_date204"] = pd.to_datetime(
        data.get("_fpi_event_start", data.get("start_time", pd.Series(pd.NaT, index=data.index))),
        errors="coerce",
    )
    rows = []
    for _, group in data.groupby("_event204", dropna=False):
        metric_group = (
            field_players_only(group)
            if "is_goalkeeper" in group.columns and (~group["is_goalkeeper"].fillna(False)).any()
            else group
        )
        kind = _fpi_v200_session_kind(group.get("session_type", pd.Series("", index=group.index)).iloc[0])
        if "_fpi_event_name" in group.columns and group["_fpi_event_name"].notna().any():
            name = str(group["_fpi_event_name"].dropna().iloc[0])
        else:
            name = str(group.get("session_name", pd.Series("Session", index=group.index)).iloc[0])
        start = group["_date204"].dropna().min()
        row = {
            "Dátum": start.strftime("%Y-%m-%d %H:%M") if pd.notna(start) else "—",
            "Típus": "Meccs (/90)" if kind == "match" else "Edzés",
            "Session": name,
            "Létszám": int(group.get("player_name", pd.Series(index=group.index, dtype=object)).nunique()),
        }

        if kind == "match":
            prepared = finalize_exposure_columns(metric_group.copy())
            mins = pd.to_numeric(prepared.get("player_minutes"), errors="coerce")
            eligible = prepared.loc[mins.ge(FPI_MATCH_SESSION_MIN_MINUTES_V416)].copy()
            if eligible.empty:
                eligible = prepared.copy()
                mins = pd.to_numeric(eligible.get("player_minutes"), errors="coerce")
            row["Perc"] = 90.0

            for metric, label in [
                ("total_distance", "Össztáv"),
                ("hsr_distance", "HSR"),
                ("sprint_distance", "Sprint"),
                ("training_load", "Load"),
            ]:
                if metric in blocked:
                    row[label] = np.nan
                    continue
                vals = _fpi_v416_match_per90_series(prepared, metric)
                row[label] = float(vals.median()) if vals.notna().any() else np.nan

            if "distance_per_min" in blocked:
                row["m/perc"] = np.nan
            else:
                dpm = pd.to_numeric(eligible.get("distance_per_min"), errors="coerce")
                if not dpm.notna().any():
                    d = pd.to_numeric(eligible.get("total_distance"), errors="coerce")
                    mm = pd.to_numeric(eligible.get("player_minutes"), errors="coerce")
                    dpm = d.div(mm.where(mm > 0))
                row["m/perc"] = float(dpm.median()) if dpm.notna().any() else np.nan

            actual_minutes = pd.to_numeric(prepared.get("player_minutes"), errors="coerce").dropna()
            row["_actual_minutes_median"] = float(actual_minutes.median()) if not actual_minutes.empty else np.nan
            row["_match_normalized"] = True
        else:
            for col, label in [
                ("duration_min", "Perc"),
                ("total_distance", "Össztáv"),
                ("distance_per_min", "m/perc"),
                ("hsr_distance", "HSR"),
                ("sprint_distance", "Sprint"),
                ("training_load", "Load"),
            ]:
                values = _fpi_v204_numeric(metric_group, col)
                row[label] = np.nan if col in blocked else (float(values.median()) if values.notna().any() else np.nan)
            row["_actual_minutes_median"] = row.get("Perc", np.nan)
            row["_match_normalized"] = False
        rows.append(row)
    return pd.DataFrame(rows).sort_values("Dátum").reset_index(drop=True)


# =========================================================
# V414 - Többfájlos / többmunkalapos eseménymotor + HU számformátum
# =========================================================
FPI_IMPORT_ENGINE_VERSION = "FPI_V419_NAMED_USER_AUTH_2026_08_13"
FPI_FULL_PERIOD_KEY_V414 = "__FPI_FULL_PERIOD_V414__"


def _fpi_v414_number(value: object, decimals: int = 0) -> str:
    """Magyar táblázati számformátum: 10 000 és 53,2."""
    try:
        if value is None or pd.isna(value):
            return "—"
        number = float(value)
        rendered = f"{number:,.{max(0, int(decimals))}f}"
        return rendered.replace(",", " ").replace(".", ",")
    except Exception:
        return str(value) if value not in (None, "") else "—"


def _fpi_v414_format_numeric_text(value: object) -> str:
    """Szövegbe ágyazott egész számok ezres tagolása, mértékegység megtartásával."""
    text_value = str(value or "")
    def repl(match):
        token = match.group(0)
        try:
            return f"{int(token):,}".replace(",", " ")
        except Exception:
            return token
    return re.sub(r"(?<![\d.,])\d{4,}(?![\d.,])", repl, text_value)


def _fpi_v414_sheet_event_token(df: pd.DataFrame) -> pd.Series:
    """Valódi eseménylap neve; helper-, summary- és félidőlapok nem bontanak eseményt."""
    sheet = _fpi_v413_nonempty_text_series(df, "_fpi_source_sheet")
    normalized = sheet.map(_norm_mapping_text)
    helper_pattern = (
        r"^(?:data|adat|adatok|raw data|gps data|summary|overall|osszesites|összesítés|"
        r"dashboard|targets?|settings?|config|metadata|main table|all)$|"
        r"(?:^|\b)(?:first|second|1st|2nd|elso|első|masodik|második)[ _.-]*(?:half|felido|félidő)(?:\b|$)|"
        r"(?:^|\b)(?:half|felido|félidő|warm.?up|bemelegites|bemelegítés|cool.?down|levezetes|levezetés)(?:\b|$)|"
        r"^ts\b|^ti\b"
    )
    helper = normalized.str.contains(helper_pattern, regex=True, na=False)
    return normalized.mask(helper, "").astype(str)


def _fpi_v414_source_token(df: pd.DataFrame) -> pd.Series:
    """Egyedi fizikai feltöltés azonosító; azonos fájlnév nem olvaszt össze eseményeket."""
    token = pd.Series("", index=df.index, dtype="object")
    # A read_many V414 minden top-level feltöltéshez tartalom-alapú upload ID-t ad.
    # A source_key a biztos fallback, mert a csomagon belül mindig egyedivé válik.
    for col in ["_fpi_source_upload_id", "_fpi_source_key", "_fpi_source_file", "_source_file"]:
        candidate = _fpi_v413_nonempty_text_series(df, col)
        token = token.where(token.astype(str).str.strip().ne(""), candidate)
    return token.astype(str).str.strip()



def _fpi_v414_series_alias(df: pd.DataFrame, *names: str, default: object = "") -> pd.Series:
    for name in names:
        if name in df.columns:
            return df[name]
    return pd.Series(default, index=df.index)


def _fpi_v414_clean_name_series(df: pd.DataFrame) -> pd.Series:
    raw = _fpi_v414_series_alias(df, "session_name", "Session Name", "Szakasz neve", "Session", default="")
    name = raw.astype("string").fillna("").astype(str).str.strip().map(_fpi_v200_norm)
    generic = name.str.contains(
        r"^period\b|^split\b|^drill\b|^quarter\b|^half\b|"
        r"első félidő|elso felido|második félidő|masodik felido|"
        r"warm.?up|bemelegítés|bemelegites|cool.?down|levezetés|levezetes|"
        r"^all$|^game$|^session$",
        regex=True, na=False,
    )
    return name.mask(generic, "session").replace({"": "session"})

def _fpi_v414_event_name_token(
    df: pd.DataFrame,
    source: pd.Series,
    sheet: pd.Series,
    day: pd.Series,
    kind: pd.Series,
) -> pd.Series:
    """Azonos fájlon/lapon belüli több session cím alapján csak biztos esetben bont."""
    clean_name = _fpi_v414_clean_name_series(df)
    base = pd.DataFrame({
        "source": source.astype(str),
        "sheet": sheet.astype(str),
        "day": day.astype(str),
        "kind": kind.astype(str),
        "name": clean_name.astype(str),
        "player": _fpi_v414_series_alias(df, "player_name", "Player Name", "Játékos neve", default="").astype("string").fillna("").astype(str).str.strip(),
    }, index=df.index)
    token = pd.Series("", index=df.index, dtype="object")
    group_cols = ["source", "sheet", "day", "kind"]
    for _, group in base.groupby(group_cols, dropna=False, sort=False):
        valid = group[group["name"].ne("session") & group["name"].ne("")].copy()
        if valid.empty or valid["name"].nunique() <= 1:
            continue
        support = valid.groupby("name").agg(rows=("name", "size"), players=("player", "nunique"))
        accepted = set(support[(support["rows"] >= 3) & (support["players"] >= 2)].index.astype(str))
        if len(accepted) >= 2:
            idx = group.index[group["name"].isin(accepted)]
            token.loc[idx] = group.loc[idx, "name"].astype(str)
    return token


def _fpi_v413_source_token(df: pd.DataFrame) -> pd.Series:
    return _fpi_v414_source_token(df)


def _fpi_v413_assign_source_events(df: pd.DataFrame) -> pd.DataFrame:
    """Providerfüggetlen eseményazonosítás fájl-, munkalap-, dátum- és session szinten."""
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df.copy()

    out = df.copy()
    raw_start_v414 = _fpi_v414_series_alias(out, "start_time", "Start Time", "Kezdési idő", "Date", "Dátum", default=pd.NaT)
    raw_type_v414 = _fpi_v414_series_alias(out, "session_type", "Session Type", "Típus", "Type", default="")
    raw_name_v414 = _fpi_v414_series_alias(out, "session_name", "Session Name", "Szakasz neve", "Session", default="Session")
    start = pd.to_datetime(raw_start_v414, errors="coerce")
    day = start.dt.strftime("%Y-%m-%d").fillna("")
    kind = raw_type_v414.apply(_fpi_v200_session_kind).replace({"other": "training"})
    source = _fpi_v414_source_token(out)
    sheet = _fpi_v414_sheet_event_token(out)
    name_token = _fpi_v414_event_name_token(out, source, sheet, day, kind)

    # Egy fizikai feltöltésen belül a valódi adatlap külön esemény lehet.
    # Helper-/félidőlapok üres sheet-tokenje ugyanahhoz az eseményhez csatlakozik.
    group_keys = pd.DataFrame({
        "source": source.where(source.ne(""), "__NO_SOURCE__"),
        "sheet": sheet,
        "day": day,
        "kind": kind.astype(str),
        "name": name_token,
    }, index=out.index)
    cluster = _fpi_v413_time_clusters(start, group_keys, FPI_EVENT_SPLIT_GAP_MIN_V413)

    source_id = source.where(source.ne(""), "fallback")
    fallback_name = _fpi_v414_clean_name_series(out).where(source.eq(""), "")
    event_id = (
        source_id.astype(str)
        + "|sheet:" + sheet.astype(str)
        + "|" + day.astype(str)
        + "|" + kind.astype(str)
        + "|name:" + name_token.where(name_token.ne(""), fallback_name).astype(str)
        + "|c" + cluster.astype(str)
    )
    missing_day = day.eq("")
    if missing_day.any():
        event_id.loc[missing_day] = (
            source_id.loc[missing_day].astype(str)
            + "|sheet:" + sheet.loc[missing_day].astype(str)
            + "|nodate|" + kind.loc[missing_day].astype(str)
            + "|name:" + name_token.loc[missing_day].where(
                name_token.loc[missing_day].ne(""), fallback_name.loc[missing_day]
            ).astype(str)
            + "|c" + cluster.loc[missing_day].astype(str)
        )

    out["_fpi_event_id"] = event_id.astype(str)
    out["_fpi_event_cluster"] = cluster.astype(int)
    out["_fpi_event_source"] = source.astype(str)
    out["_fpi_event_sheet"] = sheet.astype(str)

    out["_fpi_event_raw_start_v414"] = start
    event_start = out.groupby("_fpi_event_id", dropna=False)["_fpi_event_raw_start_v414"].transform("min")
    out["_fpi_event_start"] = pd.to_datetime(event_start, errors="coerce")

    def _mode_name(series: pd.Series) -> str:
        clean = series.astype("string").fillna("").astype(str).str.strip()
        clean = clean[~clean.isin(["", "nan", "None"])]
        if clean.empty:
            return "Session"
        modes = clean.mode()
        return str(modes.iloc[0] if not modes.empty else clean.iloc[0])

    out["_fpi_event_raw_name_v414"] = raw_name_v414
    out["_fpi_event_name"] = out.groupby("_fpi_event_id", dropna=False)["_fpi_event_raw_name_v414"].transform(_mode_name)
    return out.drop(columns=["_fpi_event_raw_start_v414", "_fpi_event_raw_name_v414"], errors="ignore")


def _fpi_v413_event_key(df: pd.DataFrame) -> pd.Series:
    if df is None or df.empty:
        return pd.Series(dtype="object")
    assigned = _fpi_v413_assign_source_events(df)
    # A régi session_id csak akkor használható, ha már a V414 eseményazonosítóból készült.
    if "session_id" in assigned.columns:
        key = assigned["session_id"].astype("string").fillna("").astype(str).str.strip()
        v414_key = assigned["_fpi_event_id"].astype(str)
        legacy_like = ~key.str.contains(r"\|sheet:|^match\|", regex=True, na=False)
        key = key.where(key.ne("") & ~legacy_like, v414_key)
        return key
    return assigned["_fpi_event_id"].astype(str)


def _fpi_v201_training_session_key(df: pd.DataFrame) -> pd.Series:
    return _fpi_v413_event_key(df)


def _fpi_v202_event_key(df: pd.DataFrame) -> pd.Series:
    if df is None or df.empty:
        return pd.Series(dtype="object")
    data = df.copy()
    kind = data.get("session_type", pd.Series("", index=data.index)).apply(_fpi_v200_session_kind)
    key = _fpi_v413_event_key(data)
    if "match_event_id" in data.columns:
        match_event = data["match_event_id"].astype("string").fillna("").astype(str).str.strip()
        use_match = kind.eq("match") & match_event.ne("")
        key = key.where(~use_match, "match|" + match_event)
    return key.astype(str)


# --- Többmunkalapos, providerfüggetlen import ---
_fpi_v414_base_read_single = _fpi_read_single_gps_file_v143


def _fpi_v414_prepare_one_sheet(
    raw: pd.DataFrame,
    sheet_name: str,
    provider: str,
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    try:
        if provider == "PlayerTek":
            frame = _fpi_prepare_playertek_v143(raw, forced_type, file_name)
        elif provider == "Polar Team Pro":
            frame = _fpi_prepare_polar_v143({sheet_name: raw}, forced_type, file_name)
        elif provider == "Catapult":
            frame = _fpi_prepare_catapult_vector_v160({sheet_name: raw}, forced_type, file_name)
            if frame.empty:
                frame = _fpi_prepare_catapult_v143({sheet_name: raw}, forced_type, file_name)
        else:
            frame, _mapping, missing = standardize_dataframe(raw)
            if missing:
                return pd.DataFrame()
        if frame is None or frame.empty:
            return pd.DataFrame()
        frame = frame.copy()
        frame["_fpi_source_sheet"] = str(sheet_name)
        player_col = "Player Name" if "Player Name" in frame.columns else ("player_name" if "player_name" in frame.columns else None)
        if player_col is not None:
            players = frame[player_col].astype("string").fillna("").astype(str).str.strip()
            if int(players[players.ne("")].nunique()) < 2 and len(frame) < 3:
                return pd.DataFrame()
        return frame
    except Exception:
        return pd.DataFrame()


def _fpi_read_single_gps_file_v143(
    uploaded_file,
    forced_type: Optional[str] = None,
    provider_override: str = "Automatikus felismerés",
) -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, object]]]:
    name = str(getattr(uploaded_file, "name", "gps_file"))
    data = _fpi_bytes_from_upload_v143(uploaded_file)
    ext = Path(name).suffix.lower()

    # ZIP: a belső forráskulcsot később a V414 source_key különíti el.
    if ext == ".zip":
        sheets, report = _fpi_v414_base_read_single(uploaded_file, forced_type, provider_override)
        outer_hash = hashlib.md5(data).hexdigest()[:16] if data else "empty"
        for key, frame in list(sheets.items()):
            enriched = frame.copy()
            enriched["_fpi_source_upload_id"] = f"zip:{outer_hash}:{key}"
            sheets[key] = enriched
        return sheets, report

    # Többmunkalapos Excel: minden valódi, standardizálható eseménylap külön forrás.
    if ext in {".xlsx", ".xlsm", ".xls"} and data:
        try:
            raw_sheets = _fpi_read_excel_bytes_v165(data, name, header=None)
            provider = provider_override if provider_override != "Automatikus felismerés" else _fpi_detect_provider_v143(raw_sheets, name)
            if len(raw_sheets) > 1 and provider != "Brainsports":
                prepared_parts: Dict[str, pd.DataFrame] = {}
                report_rows: List[Dict[str, object]] = []
                for sheet_name, raw in raw_sheets.items():
                    if raw is None or raw.empty or sheet_is_likely_helper(sheet_name, raw):
                        continue
                    frame = _fpi_v414_prepare_one_sheet(raw, str(sheet_name), provider, forced_type, name)
                    if frame.empty:
                        continue
                    frame, post_report = _fpi_v200_universal_postprocess(
                        frame,
                        provider=provider,
                        file_name=f"{name} / {sheet_name}",
                    )
                    frame["_fpi_source_sheet"] = str(sheet_name)
                    key = f"{Path(name).stem}__{sheet_name}__{post_report.get('provider', provider)}"
                    prepared_parts[key] = frame
                    row = _fpi_v200_report_row(f"{name} / {sheet_name}", post_report, status="OK")
                    row["Megjegyzés"] = str(row.get("Megjegyzés", "")) + " | V414: külön eseménylap"
                    report_rows.append(row)
                if len(prepared_parts) >= 2:
                    return prepared_parts, report_rows
        except Exception:
            pass

    sheets, report = _fpi_v414_base_read_single(uploaded_file, forced_type, provider_override)
    # Egylapos / generic eredménynél is őrizzük meg a munkalap nevét, ha egyértelmű.
    if ext in {".xlsx", ".xlsm", ".xls"} and data and sheets:
        try:
            raw_sheets = _fpi_read_excel_bytes_v165(data, name, header=None)
            raw_names = list(raw_sheets.keys())
            for key, frame in list(sheets.items()):
                if "_fpi_source_sheet" in frame.columns and frame["_fpi_source_sheet"].astype(str).str.strip().ne("").any():
                    continue
                matched = next((sheet for sheet in raw_names if _norm_mapping_text(str(sheet)) in _norm_mapping_text(str(key))), None)
                if matched is None and len(raw_names) == 1:
                    matched = raw_names[0]
                if matched is not None:
                    enriched = frame.copy()
                    enriched["_fpi_source_sheet"] = str(matched)
                    sheets[key] = enriched
        except Exception:
            pass
    return sheets, report


def _fpi_read_many_gps_files_v143(
    training_files: Optional[List[object]],
    match_files: Optional[List[object]],
    mixed_files: Optional[List[object]],
    provider_override: str = "Automatikus felismerés",
) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, str]:
    all_sheets: Dict[str, pd.DataFrame] = {}
    rows: List[Dict[str, object]] = []
    signature_parts: List[str] = []
    groups = [
        ("Edzés", training_files or []),
        ("Meccs", match_files or []),
        (None, mixed_files or []),
    ]
    upload_index = 0
    for forced_type, files in groups:
        for upload in files:
            upload_index += 1
            name = str(getattr(upload, "name", "gps_file"))
            data = _fpi_bytes_from_upload_v143(upload)
            content_hash = hashlib.md5(data).hexdigest() if data else f"empty-{upload_index}"
            upload_id = f"{forced_type or 'Vegyes'}:{upload_index}:{content_hash[:16]}"
            signature_parts.append(f"{forced_type}:{name}:{len(data)}:{content_hash}")
            sheets, report = _fpi_read_single_gps_file_v143(
                upload,
                forced_type=forced_type,
                provider_override=provider_override,
            )
            for key, frame in sheets.items():
                unique = key
                counter = 2
                while unique in all_sheets:
                    unique = f"{key}_{counter}"
                    counter += 1
                enriched = frame.copy()
                # ZIP belső azonosítóját megtartjuk; normál fájlnál fizikai upload ID.
                if "_fpi_source_upload_id" not in enriched.columns or not enriched["_fpi_source_upload_id"].astype(str).str.strip().ne("").any():
                    enriched["_fpi_source_upload_id"] = upload_id
                enriched["_fpi_source_file"] = name
                enriched["_fpi_source_key"] = unique
                enriched["_fpi_upload_group"] = forced_type or "Vegyes"
                all_sheets[unique] = enriched
            for row in report:
                row["Import típus"] = forced_type or "Vegyes / fájlból"
                rows.append(row)

    if all_sheets:
        combined_parts = []
        for key, frame in all_sheets.items():
            part = frame.copy()
            part["_fpi_v407_frame_key"] = key
            part["_fpi_v407_row_order"] = np.arange(len(part))
            combined_parts.append(part)
        combined = pd.concat(combined_parts, ignore_index=True, sort=False)
        combined = _fpi_v407_apply_filename_md_inference(combined)
        rebuilt = {}
        for key, group in combined.groupby("_fpi_v407_frame_key", sort=False):
            rebuilt[str(key)] = group.sort_values("_fpi_v407_row_order").drop(
                columns=["_fpi_v407_frame_key", "_fpi_v407_row_order"], errors="ignore"
            ).reset_index(drop=True)
        all_sheets = rebuilt
    signature = hashlib.md5("|".join(signature_parts).encode("utf-8")).hexdigest()
    return all_sheets, pd.DataFrame(rows), signature


# A forrásmetaadatokat a Smart Mapper / standardizálás után is megőrizzük.
_fpi_v414_base_standardize_dataframe = standardize_dataframe

def standardize_dataframe(raw: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, Optional[str]], List[str]]:
    out, mapping, missing = _fpi_v414_base_standardize_dataframe(raw)
    if out is None or raw is None or raw.empty:
        return out, mapping, missing
    meta_cols = [
        "_fpi_source_upload_id", "_fpi_source_file", "_fpi_source_key",
        "_fpi_source_sheet", "_fpi_upload_group",
    ]
    for col in meta_cols:
        if col not in raw.columns or col in out.columns:
            continue
        source = raw[col]
        try:
            if len(source) == len(out):
                out[col] = source.reset_index(drop=True).to_numpy()
            elif set(out.index).issubset(set(source.index)):
                out[col] = source.reindex(out.index).to_numpy()
        except Exception:
            pass
    return out, mapping, missing


# A V413 master wrapper után újraszámoljuk a V414 esemény- és forrásszámokat.
_fpi_v414_base_master_dataset = _fpi_v300_master_dataset


def _fpi_v300_master_dataset(data: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, object]]:
    out, report = _fpi_v414_base_master_dataset(data)
    if out is None or out.empty:
        return out, report
    out = _fpi_v413_assign_source_events(out)
    out["session_id"] = out["_fpi_event_id"].astype(str)
    if "match_event_id" in out.columns:
        match_id = out["match_event_id"].astype("string").fillna("").astype(str).str.strip()
        match_mask = out.get("session_type", pd.Series("", index=out.index)).astype(str).eq("Meccs") & match_id.ne("")
        out.loc[match_mask, "session_id"] = "match|" + match_id.loc[match_mask]
    out = _fpi_v201_add_training_attendance(out, recovery_log=[])
    report = dict(report or {})
    event_key = _fpi_v202_event_key(out)
    kinds = out.get("session_type", pd.Series("", index=out.index)).apply(_fpi_v200_session_kind)
    report["sessions"] = int(event_key.dropna().astype(str).nunique())
    report["training_sessions"] = int(event_key[kinds.eq("training")].dropna().astype(str).nunique())
    report["analysis_match_sessions"] = int(event_key[kinds.eq("match")].dropna().astype(str).nunique())
    source_uploads = _fpi_v413_nonempty_text_series(out, "_fpi_source_upload_id")
    source_keys = _fpi_v413_nonempty_text_series(out, "_fpi_source_key")
    report["gps_source_files"] = int(source_uploads[source_uploads.ne("")].nunique()) or int(source_keys[source_keys.ne("")].nunique())
    report["event_source_files_v413"] = report["gps_source_files"]
    report["event_engine_v413"] = "V414: upload + valódi munkalap + dátum/típus + 120 perces időklaszter"
    out.attrs["fpi_v300_master_report"] = report
    return out, report




# =============================================================================
# V417 – hitelesítési javítások
# =============================================================================
# 1) Barin/Brainsports HMLD = méter, nem generikus Load-pont.
# 2) Csapatszintű heti/trend/mikrociklus aggregáció mezőnyjátékos-alapú.
# 3) Teljes mikrociklusnál nincs téves "csonka hét" időarányos célcsökkentés.
# 4) Hiányzó Sprint db nem lesz 0; csak teljes forráslefedettségnél jelenik meg.
# 5) A játékostábla nem vág le 20 főnél.

FPI_IMPORT_ENGINE_VERSION = "FPI_V433_HERO_FIT_2026_08_16"


def _fpi_v417_field_players(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame() if df is None else df.copy()
    work = df.copy()
    if "is_goalkeeper" not in work.columns:
        try:
            work = add_keeper_flag_from_position(work)
        except Exception:
            work["is_goalkeeper"] = False
    if "is_goalkeeper" in work.columns:
        mask = ~work["is_goalkeeper"].fillna(False).astype(bool)
        if mask.any():
            return work.loc[mask].copy()
    return work


def _fpi_v417_load_kind(df: pd.DataFrame) -> str:
    """A training_load oszlop mögötti tényleges szolgáltatói mutató."""
    if df is None or df.empty:
        return "load"
    if "_fpi_load_metric" in df.columns:
        vals = (
            df["_fpi_load_metric"].astype("string").fillna("").astype(str)
            .str.strip().str.upper()
        )
        vals = vals[vals.ne("")]
        if not vals.empty and vals.eq("HMLD").all():
            return "hmld"
        if vals.eq("HMLD").any():
            return "mixed"
    return "load"


def _fpi_v417_load_label(df: pd.DataFrame) -> str:
    kind = _fpi_v417_load_kind(df)
    if kind == "hmld":
        return "HMLD"
    if kind == "mixed":
        return "Terhelési mutató"
    return "Load"


def _fpi_v417_load_unit(df: pd.DataFrame) -> str:
    kind = _fpi_v417_load_kind(df)
    if kind == "hmld":
        return "m"
    if kind == "mixed":
        return "forrásfüggő"
    return "pont"


def _fpi_v417_render_load_text(value: object, df: pd.DataFrame) -> object:
    """PDF-ben a Barin HMLD-t ne nevezzük Load-pontnak."""
    if _fpi_v417_load_kind(df) != "hmld" or value is None:
        return value
    text = str(value)
    replacements = [
        ("Load = a szolgáltató vagy az import által adott összterhelési pont.",
         "HMLD = High Metabolic Load Distance; a Barin/Brainsports exportban méterben mért külső terhelési mutató."),
        ("Load (terhelési pont)", "HMLD"),
        ("Összterhelési pont", "HMLD"),
        ("összterhelési pont", "HMLD"),
        ("Terhelési pont:", "HMLD:"),
        ("terhelési pont:", "HMLD:"),
        ("Terhelési pont", "HMLD"),
        ("terhelési pont", "HMLD"),
        ("Összterhelés", "HMLD-terhelés"),
        ("összterhelés", "HMLD-terhelés"),
        ("Load-trend", "HMLD-trend"),
        ("load-trend", "HMLD-trend"),
        ("Medián load", "Medián HMLD"),
        ("medián load", "medián HMLD"),
        ("Load –", "HMLD –"),
        ("load /", "HMLD /"),
        ("Load /", "HMLD /"),
        ("mezőnyjátékos-load", "mezőnyjátékos-HMLD"),
        ("saját load", "saját HMLD"),
        ("load spike", "HMLD-kiugrás"),
        ("load célzott", "HMLD célzott"),
        ("load profil", "HMLD-profil"),
    ]
    for old, new in replacements:
        text = text.replace(old, new)
    # Önálló Load szó, de a "Player Load" módszertani kifejezést ne írjuk át vakon.
    text = re.sub(r"(?<!Player )\bLoad\b", "HMLD", text)
    text = re.sub(r"\bload\b", "HMLD", text)
    text = text.replace("High Metabolic HMLD Distance", "High Metabolic Load Distance")
    text = text.replace("Player HMLD", "Player Load").replace("Training HMLD", "Training Load")
    return text


# Brainsports/Barin import: őrizzük meg, hogy a belső training_load valójában HMLD.
_fpi_v417_base_prepare_brainsports = _fpi_prepare_brainsports_v143

def _fpi_prepare_brainsports_v143(
    sheets: Dict[str, pd.DataFrame],
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    out = _fpi_v417_base_prepare_brainsports(sheets, forced_type, file_name)
    if out is None or out.empty:
        return out
    out = out.copy()
    hmld_present = "HMLD" in out.columns and pd.to_numeric(out["HMLD"], errors="coerce").notna().any()
    if hmld_present:
        out["_fpi_load_metric"] = "HMLD"
        out["_fpi_load_unit"] = "m"
    else:
        out["_fpi_load_metric"] = "Load"
        out["_fpi_load_unit"] = "pont"
    if "Sprints" in out.columns:
        out["_fpi_sprints_source_available"] = pd.to_numeric(out["Sprints"], errors="coerce").notna()
    else:
        out["_fpi_sprints_source_available"] = False
    return out


# Smart Mapper / standardizálás után is maradjon meg a szemantikai metaadat.
_fpi_v417_base_standardize_dataframe = standardize_dataframe

def standardize_dataframe(raw: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, Optional[str]], List[str]]:
    out, mapping, missing = _fpi_v417_base_standardize_dataframe(raw)
    if out is None or raw is None or raw.empty:
        return out, mapping, missing
    meta_cols = ["_fpi_load_metric", "_fpi_load_unit", "_fpi_sprints_source_available"]
    for col in meta_cols:
        if col in raw.columns and col not in out.columns:
            source = raw[col]
            try:
                if len(source) == len(out):
                    out[col] = source.reset_index(drop=True).to_numpy()
                elif set(out.index).issubset(set(source.index)):
                    out[col] = source.reindex(out.index).to_numpy()
            except Exception:
                pass
    # Kézi/generikus HMLD mapping esetén is helyes egység.
    source_load = str((mapping or {}).get("training_load") or "")
    if "hmld" in _norm_mapping_text(source_load):
        out["_fpi_load_metric"] = "HMLD"
        out["_fpi_load_unit"] = "m"
    if "_fpi_sprints_source_available" not in out.columns:
        source_sprints = (mapping or {}).get("sprints")
        if source_sprints and source_sprints in raw.columns:
            vals = pd.to_numeric(raw[source_sprints], errors="coerce")
            if len(vals) == len(out):
                out["_fpi_sprints_source_available"] = vals.reset_index(drop=True).notna().to_numpy()
        else:
            out["_fpi_sprints_source_available"] = False
    return out, mapping, missing


_fpi_v417_base_apply_mapping_to_raw = apply_mapping_to_raw

def apply_mapping_to_raw(raw: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> Tuple[pd.DataFrame, Dict[str, Optional[str]], List[str]]:
    out, fixed_mapping, missing = _fpi_v417_base_apply_mapping_to_raw(raw, mapping)
    if out is None or raw is None or raw.empty:
        return out, fixed_mapping, missing
    source_load = str((fixed_mapping or {}).get("training_load") or "")
    if "hmld" in _norm_mapping_text(source_load):
        out["_fpi_load_metric"] = "HMLD"
        out["_fpi_load_unit"] = "m"
    source_sprints = (fixed_mapping or {}).get("sprints")
    if source_sprints and source_sprints in raw.columns:
        vals = pd.to_numeric(raw[source_sprints], errors="coerce")
        if len(vals) == len(out):
            out["_fpi_sprints_source_available"] = vals.reset_index(drop=True).notna().to_numpy()
    else:
        out["_fpi_sprints_source_available"] = False
    return out, fixed_mapping, missing


