def mapper_label(std_col: str) -> str:
    return MAPPER_FIELD_INFO.get(std_col, (std_col, "", "", "", False))[0]


def mapper_unit(std_col: str) -> str:
    return MAPPER_FIELD_INFO.get(std_col, ("", "", "", "", False))[2]


def mapper_desc(std_col: str) -> str:
    label, meaning, unit, used_for, required = MAPPER_FIELD_INFO.get(std_col, (std_col, "", "", "", False))
    extra = ""
    if std_col == "speed_zone_4":
        extra = " Összevont 4+5 zóna esetén ezt válaszd ide; az app HSR-ként kezeli."
    elif std_col == "speed_zone_5":
        extra = " Ide ne darabszámot válassz, hanem méter alapú sprinttávot."
    elif std_col == "sprints":
        extra = " Ide darabszám kell, nem sprinttáv méterben."
    elif std_col in ["acc_high", "dec_high"]:
        extra = " Ha csak összesített oszlop van, az is használható."
    return f"{meaning} Várt egység: {unit}. Ebből számolódik: {used_for}.{extra}"


def mapper_warning(std_col: str, source_col: object) -> str:
    s = _norm_mapping_text(source_col)
    if not s:
        return ""
    if std_col == "sprints" and any(x in s for x in ["distance", "tav", "meter", "metre"]):
        return "⚠ Sprintekhez darabszám kell, ez inkább sprinttávnak tűnik."
    if std_col == "speed_zone_5" and any(x in s for x in ["count", "darab"]):
        return "⚠ Sprint távhoz méter kell, ez inkább sprint darabszámnak tűnik."
    if std_col in ["speed_zone_4", "speed_zone_5", "total_distance"] and any(x in s for x in ["count", "darab"]):
        return "⚠ Ehhez távolság kellene, nem darabszám."
    if std_col in ["acc_high", "dec_high", "sprints"] and any(x in s for x in ["distance", "meter", "metre"]):
        return "⚠ Ehhez darabszám jellegű oszlop kellene, nem méter."
    return ""


def enhanced_mapping_quality_df(raw_df: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> pd.DataFrame:
    rows = []
    for std_col, aliases in STANDARD_COLUMNS.items():
        src = mapping.get(std_col)
        score = smart_column_score(src, std_col, aliases) if src else 0
        required = MAPPER_FIELD_INFO.get(std_col, ("", "", "", "", std_col in CORE_REQUIRED))[4]
        rows.append({
            "App mező": mapper_label(std_col),
            "Technikai mező": std_col,
            "Mit jelent?": mapper_desc(std_col),
            "Várt egység": mapper_unit(std_col),
            "Kiválasztott Excel oszlop": src or "",
            "Bizonyosság": score,
            "Kötelező": "igen" if required else "nem",
            "Figyelmeztetés": mapper_warning(std_col, src),
        })
    return pd.DataFrame(rows)


def _fpi_derived_mapping_fields(mapping: Dict[str, Optional[str]]) -> Dict[str, str]:
    """Azokat a standard mezőket jelöli, amelyeket az app biztonságosan kiszámít."""
    derived: Dict[str, str] = {}

    if not mapping.get("match_minutes") and mapping.get("duration"):
        derived["match_minutes"] = "Időtartamból"

    effort_parts = [
        key for key in ("sprints", "acc_high", "dec_high")
        if mapping.get(key)
    ]
    if not mapping.get("high_efforts") and effort_parts:
        derived["high_efforts"] = "Sprint + intenzív gyorsítás/lassítás"

    if not mapping.get("distance_per_min") and mapping.get("total_distance") and mapping.get("duration"):
        derived["distance_per_min"] = "Össztáv / időtartam"

    return derived


def mapping_compatibility_score(mapping: Dict[str, Optional[str]]) -> Tuple[int, List[str]]:
    weights = {
        "player_name": 20, "session_type": 15, "start_time": 15,
        "total_distance": 8, "duration": 5, "distance_per_min": 7,
        "max_speed": 8, "sprints": 5, "speed_zone_4": 5,
        "speed_zone_5": 7, "training_load": 5, "match_minutes": 4, "acc_high": 3,
        "dec_high": 3, "high_efforts": 4,
    }
    derived = _fpi_derived_mapping_fields(mapping)
    total = sum(weights.values())
    got = 0
    missing = []
    for k, w in weights.items():
        if mapping.get(k) or k in derived:
            got += w
        else:
            missing.append(mapper_label(k))
    return int(round(got / total * 100)), missing


def render_mapping_score(mapping: Dict[str, Optional[str]]) -> None:
    score, missing = mapping_compatibility_score(mapping)
    derived = _fpi_derived_mapping_fields(mapping)

    if score >= 85:
        st.success(f"GPS fájl kompatibilitás: {score}% – nagyon jó")
    elif score >= 65:
        st.warning(f"GPS fájl kompatibilitás: {score}% – használható, de néhány mező hiányzik")
    else:
        st.error(f"GPS fájl kompatibilitás: {score}% – javítsd a mappinget")

    if derived:
        labels = []
        if "match_minutes" in derived:
            labels.append("Játékperc / szereplési idő")
        if "high_efforts" in derived:
            labels.append("High Efforts")
        if "distance_per_min" in derived:
            labels.append("Táv/perc")
        st.caption("Automatikusan számított mezők: " + ", ".join(labels))

    if missing:
        st.caption("Valóban hiányzó fontos mezők: " + ", ".join(missing[:8]) + ("..." if len(missing) > 8 else ""))


def normalize_combined_fields(out: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> pd.DataFrame:
    """Összevont GPS mezők kezelése, pl. Distance(4+5).
    Ha csak 4+5 oszlop van, azt HSR-ként használjuk. A sprint distance ilyenkor becslés,
    de az eredeti összevont értéket nem duplázzuk a HSR számításnál.
    """
    out = out.copy()
    src_z4 = str(mapping.get("speed_zone_4") or "").lower()
    src_z5 = str(mapping.get("speed_zone_5") or "").lower()
    combined_45 = any(x in src_z4 for x in ["4+5", "hsr", "high speed"])
    out["combined_zone_4_5_used"] = bool(combined_45)

    if "speed_zone_4" not in out.columns:
        out["speed_zone_4"] = 0
    if "speed_zone_5" not in out.columns:
        out["speed_zone_5"] = 0

    z5_missing = out["speed_zone_5"].fillna(0).sum() == 0
    if z5_missing and combined_45 and out["speed_zone_4"].fillna(0).sum() > 0:
        out["speed_zone_5"] = out["speed_zone_4"] * 0.30
        out["estimated_sprint_distance"] = True
    else:
        out["estimated_sprint_distance"] = False

    # HSR: külön z4+z5 esetén összeg, összevont 4+5 esetén maga az összevont oszlop.
    if combined_45:
        out["hsr_distance"] = out["speed_zone_4"]
    else:
        out["hsr_distance"] = out[["speed_zone_4", "speed_zone_5"]].sum(axis=1, min_count=1)
    out["sprint_distance"] = out["speed_zone_5"]
    return out


def _fpi_mapped_distance_units_to_metres(out: pd.DataFrame, mapping: Dict[str, Optional[str]]) -> pd.DataFrame:
    """A kézi/általános mapper km-ben érkező távolságait méterre váltja."""
    data = out.copy()
    for target in ["total_distance", "speed_zone_3", "speed_zone_4", "speed_zone_5"]:
        if target not in data.columns:
            continue
        raw_source = str(mapping.get(target) or "").lower()
        source = _norm_mapping_text(raw_source)
        values = pd.to_numeric(data[target], errors="coerce")
        finite = values.dropna().abs()
        km_header = "(km" in raw_source or " km" in raw_source or "kilomet" in source
        km_scale = not finite.empty and float(finite.median()) < 100.0
        data[target] = values * 1000.0 if km_header and km_scale else values
    return data


def _fpi_enforce_distance_hierarchy(df: pd.DataFrame, recovery_log: Optional[List[str]] = None) -> pd.DataFrame:
    """Fizikai ellenőrzés: sprinttáv <= HSR <= teljes táv."""
    data = df.copy()
    total = pd.to_numeric(data["total_distance"], errors="coerce") if "total_distance" in data.columns else pd.Series(np.nan, index=data.index)
    z4 = pd.to_numeric(data["speed_zone_4"], errors="coerce") if "speed_zone_4" in data.columns else pd.Series(np.nan, index=data.index)
    z5 = pd.to_numeric(data["speed_zone_5"], errors="coerce") if "speed_zone_5" in data.columns else pd.Series(np.nan, index=data.index)
    hsr = pd.to_numeric(data["hsr_distance"], errors="coerce") if "hsr_distance" in data.columns else z4.fillna(0) + z5.fillna(0)
    sprint = pd.to_numeric(data["sprint_distance"], errors="coerce") if "sprint_distance" in data.columns else z5
    issue = pd.Series(False, index=data.index)
    tol = total.abs() * 0.01 + 1.0
    z4_is_total = total.notna() & z4.notna() & ((z4-total).abs() <= tol) & z5.notna()
    if z4_is_total.any():
        z4 = z4.mask(z4_is_total, np.nan)
        hsr = hsr.mask(z4_is_total, z5)
        issue |= z4_is_total
        if recovery_log is not None: recovery_log.append(f"{int(z4_is_total.sum())} sorban a teljes táv téves Zone 4 mappingje javítva")
    sprint_bad = total.notna() & sprint.notna() & (sprint > total + tol)
    if sprint_bad.any():
        sprint = sprint.mask(sprint_bad, np.nan)
        issue |= sprint_bad
        if recovery_log is not None: recovery_log.append(f"{int(sprint_bad.sum())} fizikailag lehetetlen sprinttáv érvénytelenítve")
    hsr = hsr.where(~(hsr.isna() & sprint.notna()), sprint)
    hsr = hsr.where(~(hsr.notna() & sprint.notna() & (hsr < sprint)), sprint)
    hsr_bad = total.notna() & hsr.notna() & (hsr > total + tol)
    if hsr_bad.any():
        hsr = hsr.mask(hsr_bad, np.nan)
        issue |= hsr_bad
        if recovery_log is not None: recovery_log.append(f"{int(hsr_bad.sum())} fizikailag lehetetlen HSR érték érvénytelenítve")
    if "speed_zone_4" in data.columns: data["speed_zone_4"] = z4
    if "speed_zone_5" in data.columns: data["speed_zone_5"] = z5
    data["hsr_distance"] = hsr
    data["sprint_distance"] = sprint
    data["distance_hierarchy_issue"] = issue
    return data

