MEMORY_FILE = Path("performance_memory_v25.csv")


def score_to_label(score: float) -> str:
    if pd.isna(score):
        return "Nincs elég adat"
    if score >= 80:
        return "Jó meccskészültség"
    if score >= 65:
        return "Elfogadható, figyelendő"
    if score >= 50:
        return "Közepes kockázat"
    return "Alacsony readiness"


def score_to_color(score: float) -> str:
    if pd.isna(score):
        return "#94a3b8"
    if score >= 80:
        return "#22c55e"
    if score >= 65:
        return "#84cc16"
    if score >= 50:
        return "#f59e0b"
    return "#ef4444"


def trend_label(values: List[float], tolerance: float = 0.03) -> str:
    clean = [v for v in values if pd.notna(v)]
    if len(clean) == 0:
        return "nincs adat"
    if len(clean) == 1:
        return "egyhetes alapállapot"
    if len(clean) == 2:
        first, last = clean[0], clean[-1]
        if first == 0:
            return "kéthetes összevetés"
        change = (last - first) / abs(first)
        if change > tolerance:
            return "kéthetes emelkedés"
        if change < -tolerance:
            return "kéthetes csökkenés"
        return "kéthetes stabilitás"
    first, last = clean[0], clean[-1]
    if first == 0:
        return "nincs elég adat"
    change = (last - first) / abs(first)
    if change > tolerance:
        return "emelkedő"
    if change < -tolerance:
        return "csökkenő"
    return "stabil"


def classify_week_context(weekly_row: pd.Series, history: pd.DataFrame) -> str:
    if history.empty or len(history) < 3:
        return "Tanuló hét"
    load = weekly_row.get("training_load", np.nan)
    sprint = weekly_row.get("sprint_distance", np.nan)
    intensity = weekly_row.get("distance_per_min", np.nan)

    hist_load = history["training_load"].dropna() if "training_load" in history.columns else pd.Series(dtype=float)
    hist_sprint = history["sprint_distance"].dropna() if "sprint_distance" in history.columns else pd.Series(dtype=float)

    if len(hist_load) >= 3 and pd.notna(load):
        load_mean = hist_load.mean()
        if load_mean > 0:
            load_ratio = load / load_mean
            if load_ratio > 1.18:
                return "Terhelésépítő / overload hét"
            if load_ratio < 0.82:
                return "Recovery / alulterhelt hét"

    if len(hist_sprint) >= 3 and pd.notna(sprint):
        sprint_mean = hist_sprint.mean()
        if sprint_mean > 0 and sprint / sprint_mean < 0.75:
            return "Intenzitáshiányos hét"

    if pd.notna(intensity) and "distance_per_min" in history.columns:
        int_hist = history["distance_per_min"].dropna()
        if len(int_hist) >= 3 and int_hist.mean() > 0 and intensity / int_hist.mean() > 1.12:
            return "Intenzitásfókuszú hét"

    return "Normál hét"


def build_weekly_fingerprints(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty or "week" not in df.columns:
        return pd.DataFrame()

    agg_spec = {
        "training_load": "sum",
        "total_distance": "sum",
        "sprint_distance": "sum",
        "hsr_distance": "sum",
        "distance_per_min": "mean",
        "max_speed": "max",
        "acc_count": "sum",
        "dec_count": "sum",
        "high_efforts": "sum",
        "duration_min": "sum",
        "hrv": "mean",
        "player_name": "nunique",
    }
    usable = {k: v for k, v in agg_spec.items() if k in df.columns}
    weekly = df.groupby("week", as_index=False).agg(usable)
    weekly = weekly.rename(columns={"player_name": "players"})

    # Csak edzésekből külön load profil, ha van elég adat.
    train = df[df["session_type"] == "Edzés"].copy()
    if not train.empty:
        train_agg = train.groupby("week", as_index=False).agg({
            k: v for k, v in usable.items() if k != "player_name"
        })
        train_agg = train_agg.add_prefix("train_")
        train_agg = train_agg.rename(columns={"train_week": "week"})
        weekly = weekly.merge(train_agg, on="week", how="left")

    # Meccsprofil külön.
    match = df[df["session_type"] == "Meccs"].copy()
    if not match.empty:
        match_agg = match.groupby("week", as_index=False).agg({
            k: v for k, v in usable.items() if k != "player_name"
        })
        match_agg = match_agg.add_prefix("match_")
        match_agg = match_agg.rename(columns={"match_week": "week"})
        weekly = weekly.merge(match_agg, on="week", how="left")

    weekly = weekly.sort_values("week").reset_index(drop=True)

    # Rolling baseline-ok.
    for metric in ["training_load", "sprint_distance", "distance_per_min", "max_speed", "dec_count", "high_efforts"]:
        if metric in weekly.columns:
            weekly[f"{metric}_rolling4"] = weekly[metric].rolling(4, min_periods=2).mean()
            weekly[f"{metric}_change"] = weekly[metric].pct_change()

    contexts = []
    for idx, row in weekly.iterrows():
        contexts.append(classify_week_context(row, weekly.iloc[:idx]))
    weekly["periodizacios_tipus"] = contexts
    return weekly


def _fpi_v408_speed_exposure_assessment(daily: pd.DataFrame) -> Dict[str, object]:
    """Közös Speed Exposure logika a pontszámhoz és a magyarázathoz.

    Csak a következő mérkőzés előtti MD-5..MD-1 edzések számítanak. MD+1
    regeneráció/pótlás, ezért nem minősíthető a következő meccs előtti
    sebességi expozíció erősségeként.
    """
    result = {
        "score": 55.0, "ratio": np.nan, "md": "", "match_sprint": np.nan,
        "peak_sprint": np.nan, "valid": False, "reason": "",
        "target": "MD-4/MD-3 napon a meccs sprintreferenciájának 25–40%-a",
    }
    if daily is None or daily.empty or "sprint_distance" not in daily.columns:
        result["reason"] = "Nincs értékelhető sprinttáv-adat."
        return result

    match = daily[daily.get("session_type", pd.Series("", index=daily.index)).astype(str).eq("Meccs")].copy()
    train = daily[daily.get("session_type", pd.Series("", index=daily.index)).astype(str).eq("Edzés")].copy()
    if match.empty or train.empty:
        result["reason"] = "Nincs egyszerre teljes meccsreferencia és edzésadat; a komponens előzetes."
        return result

    match_sprint = pd.to_numeric(match["sprint_distance"], errors="coerce").mean()
    result["match_sprint"] = match_sprint
    if pd.isna(match_sprint) or match_sprint <= 0:
        result["reason"] = "A meccs sprintreferenciája nem értelmezhető."
        return result

    md_series = train.get("md_label", pd.Series("", index=train.index)).astype(str).str.upper().str.replace(" ", "", regex=False)
    eligible_labels = {"MD-5", "MD-4", "MD-3", "MD-2", "MD-1"}
    eligible = train[md_series.isin(eligible_labels)].copy()
    post_match = train[md_series.str.startswith("MD+")].copy()
    if eligible.empty:
        result["score"] = 25.0 if not post_match.empty else 45.0
        result["reason"] = (
            "Csak meccs utáni MD+ edzésen látható sprintinger; ez regenerációs vagy pótló terhelés, "
            "nem a következő mérkőzés előtti Speed Exposure."
            if not post_match.empty else
            "Nincs MD-5–MD-1 közé sorolt, értékelhető sebességi edzés."
        )
        return result

    sprint = pd.to_numeric(eligible["sprint_distance"], errors="coerce")
    if not sprint.notna().any():
        result["score"] = 35.0
        result["reason"] = "Az MD-5–MD-1 edzéseken nincs értékelhető sprinttáv."
        return result

    peak_idx = sprint.idxmax()
    peak = float(sprint.loc[peak_idx])
    ratio = peak / float(match_sprint)
    md = str(eligible.loc[peak_idx].get("md_label", "")).upper().replace(" ", "")

    # Dózispont: a 25–40%-os fő sebességi dózis kapja a legjobb értéket.
    if ratio < .10:
        dose_score = 20.0
    elif ratio < .20:
        dose_score = 40.0 + (ratio - .10) / .10 * 20.0
    elif ratio < .25:
        dose_score = 60.0 + (ratio - .20) / .05 * 20.0
    elif ratio <= .40:
        dose_score = 90.0
    elif ratio <= .50:
        dose_score = 80.0
    else:
        dose_score = max(55.0, 80.0 - (ratio - .50) * 80.0)

    timing_factor = {"MD-5": .90, "MD-4": 1.00, "MD-3": 1.00, "MD-2": .70, "MD-1": .40}.get(md, .50)
    score = max(0.0, min(100.0, dose_score * timing_factor))
    result.update({"score": score, "ratio": ratio, "md": md, "peak_sprint": peak, "valid": True})

    if md in {"MD-4", "MD-3"} and .25 <= ratio <= .40:
        reason = "megfelelő fő sprintdózis, optimális időzítéssel"
    elif md in {"MD-4", "MD-3"} and ratio < .25:
        reason = "jó időzítés, de a meccsigényhez képest alacsony dózis"
    elif md == "MD-2":
        reason = "a dózis részben megfelelő lehet, de a fő sebességi inger túl közel került a meccshez"
    elif md == "MD-1":
        reason = "a fő sprintinger túl későre került; MD-1-en csak rövid aktiváció kívánatos"
    else:
        reason = "a dózis vagy az időzítés nem esik az optimális zónába"
    result["reason"] = reason
    return result


def _fpi_v408_taper_assessment(daily: pd.DataFrame) -> Dict[str, object]:
    """Közös tapering-logika, külön MD-1 és MD-2 értelmezéssel."""
    result = {
        "score": 65.0, "md1_ratio": np.nan, "md2_ratio": np.nan,
        "md2_sprint_ratio": np.nan, "valid": False,
        "md1_target": "30–45%", "md2_target": "55–70%", "parts": [],
    }
    if daily is None or daily.empty or "md_label" not in daily.columns or "load_index" not in daily.columns:
        return result
    md = daily["md_label"].astype(str).str.upper().str.replace(" ", "", regex=False)
    md1 = daily[md.eq("MD-1")]
    md2 = daily[md.eq("MD-2")]
    early = daily[md.isin(["MD-4", "MD-3"])]
    if early.empty:
        return result
    peak_early = pd.to_numeric(early["load_index"], errors="coerce").max()
    if pd.isna(peak_early) or peak_early <= 0:
        return result

    score = 85.0
    parts = []
    if not md1.empty:
        r1 = pd.to_numeric(md1["load_index"], errors="coerce").sum() / peak_early
        result["md1_ratio"] = r1
        if r1 < .20:
            md1_score, md1_state = 65.0, "az aktivációs inger nagyon alacsony"
        elif r1 < .30:
            md1_score, md1_state = 75.0, "kissé a célzóna alatt van"
        elif r1 <= .45:
            md1_score, md1_state = 90.0, "a 30–45%-os célzónában van"
        elif r1 <= .55:
            md1_score, md1_state = 65.0, "a célzóna felett, még kontrollálható határeset"
        elif r1 <= .65:
            md1_score, md1_state = 50.0, "magas, frissességi kockázatot ad"
        else:
            md1_score, md1_state = max(20.0, 40.0 - max(0.0, r1 - .75) * 100.0), "egyértelműen túl magas MD-1 terhelés"
        score = md1_score
        parts.append(f"MD-1 {r1:.0%} (cél 30–45%): {md1_state}")
    else:
        parts.append("MD-1: nincs értékelhető load")

    if not md2.empty:
        r2 = pd.to_numeric(md2["load_index"], errors="coerce").sum() / peak_early
        result["md2_ratio"] = r2
        if .55 <= r2 <= .70:
            md2_adjust, md2_state = 0.0, "a 55–70%-os célzónában van"
        elif .45 <= r2 < .55 or .70 < r2 <= .80:
            md2_adjust, md2_state = -5.0, "a célzóna közelében, kontrollálandó"
        elif r2 > .80:
            md2_adjust, md2_state = -15.0, "túl közel került a fő terhelési naphoz"
        else:
            md2_adjust, md2_state = -8.0, "a célzóna alatt, a specifikus inger visszafogott"
        score = max(0.0, score + md2_adjust)
        parts.append(f"MD-2 {r2:.0%} (cél 55–70%): {md2_state}")

        if "sprint_distance" in daily.columns:
            early_sprint = pd.to_numeric(early["sprint_distance"], errors="coerce").max()
            md2_sprint = pd.to_numeric(md2["sprint_distance"], errors="coerce").sum()
            if pd.notna(early_sprint) and early_sprint > 0 and pd.notna(md2_sprint):
                sr = md2_sprint / early_sprint
                result["md2_sprint_ratio"] = sr
                if sr > .90:
                    score = min(score, 40.0)
                    parts.append(f"MD-2 sprint {sr:.0%} a fő sebességi naphoz képest: túl magas")
                elif sr > .70:
                    score = min(score, 55.0)
                    parts.append(f"MD-2 sprint {sr:.0%}: a kívánatosnál magasabb")
    result.update({"score": max(0.0, min(100.0, score)), "valid": True, "parts": parts})
    return result


def calculate_readiness_score(df: pd.DataFrame, selected_week: str, playstyle: str) -> Tuple[int, Dict[str, float], List[str]]:
    daily = build_microcycle_table(df, selected_week)
    weekly = build_weekly_fingerprints(df)
    current_week = weekly[weekly["week"] == selected_week]
    if current_week.empty:
        return 50, {}, ["Nincs elég adat a readiness számításhoz."]

    score = 75.0
    components = {}
    reasons = []
    analysis_mode = _fpi_v202_detect_analysis_mode(df, selected_week)
    mode_code = str(analysis_mode.get("code", "limited_data"))
    incomplete_week = mode_code in {"single_session", "training_block", "week_in_progress", "match_only", "limited_data"}

    row = current_week.iloc[0]

    if mode_code == "single_session":
        reasons.append("Egyszeri edzés: a readiness csak előzetes, nem teljes heti minősítés.")
    elif mode_code == "training_block":
        reasons.append("Meccs nélküli edzésblokk: a meccskészültségi komponensek korlátozottak.")
    elif mode_code == "week_in_progress":
        reasons.append("Folyamatban lévő hét: a readiness a további edzések és a meccs feltöltésével frissül.")

    # 0. Edzésrészvétel / availability komponens
    attendance_summary = _fpi_v201_week_attendance_summary(df, selected_week)
    team_training_sessions = int(
        attendance_summary.get("team_training_sessions", 0) or 0
    )
    mean_availability = attendance_summary.get(
        "mean_availability_pct", np.nan
    )
    attendance_component = 65.0
    if team_training_sessions >= 2 and pd.notna(mean_availability):
        attendance_component = float(mean_availability)
        if mean_availability < 60:
            score -= 14
            reasons.append(
                f"Az átlagos edzésrészvétel alacsony "
                f"({mean_availability:.0f}%); a heti csapatterhelés "
                f"részben hiányzások miatt alacsony."
            )
        elif mean_availability < 75:
            score -= 8
            reasons.append(
                f"Az edzésrészvétel csak {mean_availability:.0f}%; "
                f"a heti terhelési értékeket a hiányzásokkal együtt kell értelmezni."
            )
        elif mean_availability < 90:
            score -= 3
            reasons.append(
                f"Az edzésrészvétel {mean_availability:.0f}%; "
                f"néhány játékos nem teljes hetet végzett."
            )
        else:
            score += 3
    components["training_availability"] = max(
        0, min(100, attendance_component)
    )

    # 1. Load idősoros komponens – trend csak legalább 4 teljes hétből.
    load_change = row.get("training_load_change", np.nan)
    trend_status_v411 = (
        _fpi_v411_trend_status(df, selected_week)
        if "_fpi_v411_trend_status" in globals()
        else {"available": False, "count": 0, "label": "nincs elég teljes hét"}
    )
    if incomplete_week:
        components["load_trend"] = 55
        if pd.notna(load_change):
            reasons.append("A heti terhelésváltozás még nem minősített: a kiválasztott időszak nem teljes mikrociklus.")
    elif not trend_status_v411.get("available"):
        # 2–3 hétből lehet összehasonlítást mutatni, de az nem trend és nem módosítja a Readinesst.
        components["load_trend"] = 60 if int(trend_status_v411.get("count", 0) or 0) >= 2 else 55
        reasons.append(
            f"Terhelési trend nem készült: {trend_status_v411.get('label', 'legalább 4 teljes hét szükséges')}. "
            "Az elérhető hetek csak leíró összehasonlításként jelennek meg."
        )
    elif pd.notna(load_change):
        if load_change > 0.25:
            score -= 12
            reasons.append("A legalább négy teljes hetes idősorban a terhelés jelentősen nőtt az előző teljes héthez képest.")
        elif load_change < -0.30:
            score -= 6
            reasons.append("A legalább négy teljes hetes idősorban a terhelés jelentősen visszaesett, ami alulterheltséget is jelezhet.")
        else:
            score += 4
        components["load_trend"] = max(0, min(100, 80 - abs(load_change) * 60))
    else:
        components["load_trend"] = 55

    # 2. Sebességi expozíció – közös V408 motor
    speed_assessment = _fpi_v408_speed_exposure_assessment(daily)
    speed_component = float(speed_assessment.get("score", 55) or 55)
    components["speed_exposure"] = max(0, min(100, speed_component))
    speed_ratio = speed_assessment.get("ratio", np.nan)
    speed_md = str(speed_assessment.get("md", ""))
    if not speed_assessment.get("valid"):
        if speed_component < 50:
            score -= 10
        reasons.append(str(speed_assessment.get("reason", "A sebességi expozíció nem értékelhető teljesen.")))
    elif speed_component < 50:
        score -= 12
        reasons.append(f"Sebességi expozíció: {speed_assessment.get('reason')} ({speed_ratio:.0%}, {speed_md}).")
    elif speed_component < 65:
        score -= 6
        reasons.append(f"Sebességi expozíció: {speed_assessment.get('reason')} ({speed_ratio:.0%}, {speed_md}).")
    elif speed_component >= 80:
        score += 5

    # 3. Taper / MD-1 / MD-2 kontroll – külön célzónákkal
    taper_assessment = _fpi_v408_taper_assessment(daily)
    taper_component = float(taper_assessment.get("score", 65) or 65)
    components["tapering"] = max(0, min(100, taper_component))
    if taper_assessment.get("valid"):
        r1 = taper_assessment.get("md1_ratio", np.nan)
        r2 = taper_assessment.get("md2_ratio", np.nan)
        if pd.notna(r1) and r1 > .55:
            score -= 10 if r1 <= .65 else 14
            reasons.append(f"Az MD-1 load a fő nap {r1:.0%}-a; az alkalmazás 30–45%-os célzónájához képest magas.")
        elif pd.notna(r1) and .30 <= r1 <= .45:
            score += 5
        if pd.notna(r2) and r2 > .80:
            score -= 7
            reasons.append(f"Az MD-2 load a fő nap {r2:.0%}-a; a 55–70%-os célzóna fölött van.")
        md2_sprint_ratio = taper_assessment.get("md2_sprint_ratio", np.nan)
        if pd.notna(md2_sprint_ratio) and md2_sprint_ratio > .90:
            score -= 7
            reasons.append("Az MD-2 sprintterhelés a fő sebességi nap szintjén volt; ez frissességi kockázat.")
    # 4. Játékmodell illeszkedés
    playstyle_component = 70
    current = df[df["week"] == selected_week]
    cur_train = current[current["session_type"] == "Edzés"]
    cur_match = current[current["session_type"] == "Meccs"]
    if not cur_train.empty and not cur_match.empty:
        def ratio(metric):
            if metric not in current.columns:
                return np.nan
            m = cur_match[metric].mean()
            t = cur_train[metric].mean()
            return t / m if pd.notna(m) and m > 0 and pd.notna(t) else np.nan

        int_ratio = ratio("distance_per_min")
        spr_ratio = ratio("sprint_distance")
        eff_ratio = ratio("high_efforts")

        if playstyle == "Pressing":
            vals = [v for v in [int_ratio / 0.90 if pd.notna(int_ratio) else np.nan,
                                eff_ratio / 0.75 if pd.notna(eff_ratio) else np.nan] if pd.notna(v)]
        elif playstyle == "Transition":
            vals = [spr_ratio / 0.80] if pd.notna(spr_ratio) else []
        elif playstyle == "Possession":
            vals = [1.0 - max(0, (int_ratio - 1.15)) if pd.notna(int_ratio) else np.nan]
            vals = [v for v in vals if pd.notna(v)]
        elif playstyle == "Low Block":
            vals = [spr_ratio / 0.60] if pd.notna(spr_ratio) else []
        else:
            vals = [1.0]

        if vals:
            playstyle_component = max(0, min(100, np.mean([min(1.15, v) for v in vals]) * 85))
            if playstyle_component < 60:
                score -= 8
                reasons.append(f"A heti profil nem illeszkedik elég jól a(z) {playstyle} játékmodellhez.")
            elif playstyle_component > 80:
                score += 3

    components["playstyle_fit"] = max(0, min(100, playstyle_component))
    # 5. Meccskészültség végső skála
    score = int(max(0, min(100, round(score))))
    if not reasons:
        reasons.append("A readiness fő komponensei stabilnak tűnnek.")
    return score, components, reasons


def build_pattern_insights(df: pd.DataFrame, selected_week: str) -> List[Insight]:
    insights: List[Insight] = []
    weekly = build_weekly_fingerprints(df)
    if weekly.empty or selected_week not in weekly["week"].values:
        return insights

    idx = weekly.index[weekly["week"] == selected_week][0]
    hist = weekly.iloc[max(0, idx-5):idx+1].copy()

    if len(hist) < 3:
        insights.append(Insight(
            "Kevés történeti adat", "INFORMÁCIÓ",
            "A multi-week mintázatokhoz legalább 3 hét adat szükséges.",
            "Kevesebb adat mellett a rendszer inkább óvatos heti következtetéseket tud adni.",
            "Érdemes több heti adatot egy fájlban feltölteni vagy használni a performance memória funkciót.",
            scope="Memory",
        ))
        return insights

    # Sprint trend
    if "sprint_distance" in hist.columns:
        label = trend_label(hist["sprint_distance"].tolist())
        if label == "csökkenő":
            insights.append(Insight(
                "Többhetes sprintcsökkenés", "FIGYELMEZTETÉS",
                "Az elmúlt hetek sprintprofilja csökkenő mintázatot mutat.",
                "A tartós maximális sebességű inger hiány hosszabb távon ronthatja a maximális sebesség és intenzitás fenntartását.",
                "Érdemes célzottan megvizsgálni, hogy tudatos terheléscsökkentésről vagy nem kívánt intenzitáshiányról van-e szó.",
                scope="Memory",
            ))

    # Load trend
    if "training_load" in hist.columns:
        label = trend_label(hist["training_load"].tolist())
        if label == "emelkedő":
            insights.append(Insight(
                "Többhetes terhelésnövekedés", "FIGYELMEZTETÉS",
                "Az elmúlt hetek terhelési profilja emelkedő mintázatot mutat.",
                "A folyamatos load növekedés hasznos lehet építő periódusban, de frissességi problémát is okozhat.",
                "Érdemes ellenőrizni, hogy a növekvő terhelés illeszkedik-e a periodizációs célhoz.",
                scope="Memory",
            ))

    # Max speed trend
    if "max_speed" in hist.columns:
        label = trend_label(hist["max_speed"].tolist(), tolerance=0.02)
        if label == "csökkenő":
            insights.append(Insight(
                "Max sebesség csökkenő trend", "INFORMÁCIÓ",
                "Az elmúlt hetek maximális sebességprofilja enyhén csökkenő mintázatot mutat.",
                "Ez lehet edzéstartalom-függő, de jelezhet neuromuszkuláris frissességi problémát is.",
                "Érdemes ellenőrizni, hogy volt-e megfelelő maximális sebességű inger a hetekben.",
                scope="Memory",
            ))

    return insights


def memory_file_exists() -> bool:
    return MEMORY_FILE.exists()


def load_memory_df() -> pd.DataFrame:
    if not MEMORY_FILE.exists():
        return pd.DataFrame()
    try:
        return pd.read_csv(MEMORY_FILE, parse_dates=["start_time"])
    except Exception:
        return pd.DataFrame()


def save_to_memory(df: pd.DataFrame) -> Tuple[bool, str]:
    try:
        existing = load_memory_df()
        combined = pd.concat([existing, df], ignore_index=True) if not existing.empty else df.copy()
        # Duplikáció minimalizálása.
        key_cols = [c for c in ["player_name", "start_time", "session_type", "session_name", "total_distance", "training_load"] if c in combined.columns]
        if key_cols:
            combined = combined.drop_duplicates(subset=key_cols, keep="last")
        combined.to_csv(MEMORY_FILE, index=False, encoding="utf-8-sig")
        return True, f"Memory mentve: {len(combined)} sor."
    except Exception as exc:
        return False, f"Memory mentés sikertelen: {exc}"


def merge_with_memory(current_df: pd.DataFrame, use_memory: bool) -> pd.DataFrame:
    if not use_memory:
        return current_df
    mem = load_memory_df()
    if mem.empty:
        return current_df
    combined = pd.concat([mem, current_df], ignore_index=True)
    key_cols = [c for c in ["player_name", "start_time", "session_type", "session_name", "total_distance", "training_load"] if c in combined.columns]
    if key_cols:
        combined = combined.drop_duplicates(subset=key_cols, keep="last")
    # Dátummezők visszaállítása.
    if "start_time" in combined.columns:
        combined["start_time"] = pd.to_datetime(combined["start_time"], errors="coerce")
        combined["session_date"] = combined["start_time"].dt.date
        combined["week"] = make_iso_week_series(combined["start_time"])
    return combined


def build_adaptive_recommendations(
    insights: List[Insight],
    readiness_score: int,
    periodization_type: str,
    pattern_insights: List[Insight],
    playstyle: str
) -> List[Dict[str, str]]:
    recs = []

    if readiness_score < 55:
        recs.append({
            "Cím": "Meccskészültség elsődleges figyelem",
            "Súlyosság": "KRITIKUS",
            "Teendő": "A következő edzésen érdemes óvatosan bánni a terheléssel, és külön figyelni, mennyire frissek a játékosok.",
            "Miért": "A meccskészültségi pontszám alacsony, vagyis több jel is arra utal, hogy a csapat nem teljesen friss.",
        })
    elif readiness_score < 70:
        recs.append({
            "Cím": "Meccskészültség kontroll",
            "Súlyosság": "FIGYELMEZTETÉS",
            "Teendő": "A következő 1–2 edzésen ne a plusz terhelés legyen a fő cél, hanem a frissesség stabil megtartása.",
            "Miért": "A csapat nincs rossz állapotban, de nem is tűnik teljesen frissnek. Ilyenkor a túl nagy változtatás visszaüthet.",
        })

    if "overload" in periodization_type.lower() or "terhelésépítő" in periodization_type.lower():
        recs.append({
            "Cím": "Overload hét kontrollja",
            "Súlyosság": "FIGYELMEZTETÉS",
            "Teendő": "Ellenőrizd, hogy a magasabb terhelés tervezett-e, és legyen meg a következő frissítő blokk.",
            "Miért": "Terhelésépítő héten a következő napok/frissítés minősége kulcsfontosságú.",
        })
    elif "recovery" in periodization_type.lower() or "alulterhelt" in periodization_type.lower():
        recs.append({
            "Cím": "Könnyebb hét értelmezése",
            "Súlyosság": "INFORMÁCIÓ",
            "Teendő": "Tisztázd, hogy ez szándékosan könnyebb hét volt-e. Ha igen, rendben lehet; ha nem, akkor hiányozhatott a megfelelő edzésinger.",
            "Miért": "Az alacsonyabb terhelés rövid távon frissíthet, de ha több héten át így marad, a csapat intenzitása visszaeshet.",
        })

    for ins in pattern_insights:
        if ins.severity in ["KRITIKUS", "FIGYELMEZTETÉS"]:
            recs.append({
                "Cím": ins.title,
                "Súlyosság": ins.severity,
                "Teendő": ins.recommendation,
                "Miért": ins.impact,
            })

    # Alap insightokból pótoljuk 3 elemre.
    for item in top_coaching_priorities(insights, limit=5):
        if len(recs) >= 3:
            break
        if item["Cím"] not in [r["Cím"] for r in recs]:
            recs.append(item)

    return recs[:3]


def render_score_card(title: str, score: int, subtitle: str, reasons: List[str]) -> None:
    color = score_to_color(score)
    reason_html = "<br>".join([f"• {html.escape(str(r))}" for r in reasons[:4]])
    st.markdown(
        f"""
        <div class="score-card">
            <div class="score-number" style="color:{color};">{score}/100</div>
            <div class="score-label">{html.escape(title)}</div>
            <div class="mini-muted">{html.escape(subtitle)}</div>
            <div class="mini-muted" style="margin-top:10px;">{reason_html}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def severity_icon(sev: str) -> str:
    if sev == "KRITIKUS":
        return "🔴"
    if sev == "FIGYELMEZTETÉS":
        return "🟠"
    return "🔵"


def severity_class(sev: str) -> str:
    if sev == "KRITIKUS":
        return "pill-critical"
    if sev == "FIGYELMEZTETÉS":
        return "pill-warning"
    return "pill-info"


def metric_card(label: str, value: object, help_text: str = ""):
    st.metric(label, value if value is not None else "—", help=help_text)


def _safe_filename_week(week: str) -> str:
    return re.sub(r"[^0-9A-Za-z_-]+", "_", str(week)).strip("_") or "het"


def build_insight_export_df(insights: List[Insight]) -> pd.DataFrame:
    df = pd.DataFrame([i.as_dict() for i in insights])
    if df.empty:
        return df
    order = {"KRITIKUS": 1, "FIGYELMEZTETÉS": 2, "INFORMÁCIÓ": 3}
    df.insert(0, "Prioritás", df["Súlyosság"].map(order).fillna(9).astype(int))
    df["Súlyosság"] = df["Súlyosság"].map({
        "KRITIKUS": "🔴 KRITIKUS",
        "FIGYELMEZTETÉS": "🟠 FIGYELMEZTETÉS",
        "INFORMÁCIÓ": "🔵 INFORMÁCIÓ",
    }).fillna(df["Súlyosság"])
    return df


def render_insight_cards(insights: List[Insight]) -> None:
    for ins in insights:
        pill = severity_class(ins.severity)
        st.markdown(
            f"""
            <div class="insight-card">
                <div>
                    <span class="pill {pill}">{severity_icon(ins.severity)} {html.escape(ins.severity)}</span>
                    <span class="pill pill-info">{html.escape(ins.scope)}</span>
                </div>
                <div class="insight-title">{html.escape(ins.title)}</div>
                <div class="insight-label">Mit látunk?</div>
                <div class="insight-text">{html.escape(ins.observation)}</div>
                <div class="insight-label">Miért fontos?</div>
                <div class="insight-text">{html.escape(ins.impact)}</div>
                <div class="insight-label">Javaslat</div>
                <div class="insight-text">{html.escape(ins.recommendation)}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )


def render_wrapped_table(df: pd.DataFrame) -> None:
    if df.empty:
        st.info("Nincs megjeleníthető adat.")
        return
    table_html = ['<div class="wrap-table"><table>']
    table_html.append("<thead><tr>" + "".join(f"<th>{html.escape(str(c))}</th>" for c in df.columns) + "</tr></thead>")
    table_html.append("<tbody>")
    for _, row in df.iterrows():
        table_html.append("<tr>" + "".join(f"<td>{html.escape(str(row.get(c, '')))}</td>" for c in df.columns) + "</tr>")
    table_html.append("</tbody></table></div>")
    st.markdown("".join(table_html), unsafe_allow_html=True)


def insights_to_excel_bytes(insights_df: pd.DataFrame, selected_week: str) -> bytes:
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        insights_df.to_excel(writer, index=False, sheet_name="Megállapítások", startrow=3)
        wb = writer.book
        ws = writer.sheets["Megállapítások"]

        from openpyxl.styles import Alignment, Font, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter

        max_col = max(1, len(insights_df.columns))
        ws["A1"] = "Performance megállapítások és javaslatok"
        ws["A2"] = f"Hét: {selected_week}"
        ws["A3"] = f"Generálva: {datetime.now().strftime('%Y-%m-%d %H:%M')}"
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=max_col)
        ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=max_col)
        ws.merge_cells(start_row=3, start_column=1, end_row=3, end_column=max_col)
        ws["A1"].font = Font(bold=True, size=16)
        ws["A2"].font = Font(bold=True, size=11)
        ws["A3"].font = Font(italic=True, size=10)

        header_row = 4
        header_fill = PatternFill("solid", fgColor="1F4E78")
        header_font = Font(color="FFFFFF", bold=True)
        thin = Side(style="thin", color="D9E2F3")

        for cell in ws[header_row]:
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)

        widths = {
            "Prioritás": 10,
            "Súlyosság": 18,
            "Terület": 14,
            "Megállapítás": 28,
            "Mit látunk?": 58,
            "Miért fontos?": 58,
            "Javaslat": 68,
        }
        for idx, col_name in enumerate(insights_df.columns, start=1):
            ws.column_dimensions[get_column_letter(idx)].width = widths.get(str(col_name), 22)

        for row in ws.iter_rows(min_row=5, max_row=ws.max_row, max_col=ws.max_column):
            max_lines = 1
            for cell in row:
                cell.alignment = Alignment(vertical="top", wrap_text=True)
                cell.border = Border(top=thin, left=thin, right=thin, bottom=thin)
                text = str(cell.value or "")
                max_lines = max(max_lines, min(8, (len(text) // 50) + 1))
            ws.row_dimensions[row[0].row].height = max(26, max_lines * 17)

        ws.freeze_panes = "A5"
        ws.auto_filter.ref = ws.dimensions
    return output.getvalue()


def insights_to_word_bytes(insights_df: pd.DataFrame, selected_week: str) -> Optional[bytes]:
    if Document is None:
        return None
    doc = Document()
    section = doc.sections[0]
    section.left_margin = Inches(0.55)
    section.right_margin = Inches(0.55)
    section.top_margin = Inches(0.55)
    section.bottom_margin = Inches(0.55)

    doc.add_heading("Performance megállapítások és javaslatok", level=1)
    p = doc.add_paragraph()
    p.add_run(f"Hét: {selected_week}\n").bold = True
    p.add_run(f"Generálva: {datetime.now().strftime('%Y-%m-%d %H:%M')}")

    for _, row in insights_df.iterrows():
        doc.add_heading(f"{row.get('Súlyosság', '')} · {row.get('Megállapítás', '')}", level=2)
        meta = doc.add_paragraph()
        meta.add_run("Terület: ").bold = True
        meta.add_run(str(row.get("Terület", "")))
        for label in ["Mit látunk?", "Miért fontos?", "Javaslat"]:
            para = doc.add_paragraph()
            para.add_run(f"{label}: ").bold = True
            para.add_run(str(row.get(label, "")))

    doc.add_page_break()
    doc.add_heading("Összesítő tábla", level=2)
    table = doc.add_table(rows=1, cols=len(insights_df.columns))
    table.style = "Table Grid"
    hdr_cells = table.rows[0].cells
    for i, col in enumerate(insights_df.columns):
        hdr_cells[i].text = str(col)
        for paragraph in hdr_cells[i].paragraphs:
            for run in paragraph.runs:
                run.bold = True
                run.font.size = Pt(8)

    for _, row in insights_df.iterrows():
        cells = table.add_row().cells
        for i, col in enumerate(insights_df.columns):
            cells[i].text = str(row.get(col, ""))
            for paragraph in cells[i].paragraphs:
                for run in paragraph.runs:
                    run.font.size = Pt(8)

    output = io.BytesIO()
    doc.save(output)
    return output.getvalue()


def _fpi_v408_font_supports_hungarian(path: object) -> bool:
    """Csak olyan TTF/OTF fontot fogad el, amely biztosan tartalmaz ő/Ő/ű/Ű glyph-et."""
    try:
        from fontTools.ttLib import TTFont as FontToolsTTFont
        font = FontToolsTTFont(str(path), lazy=True)
        cmap = set()
        for table in font["cmap"].tables:
            cmap.update(table.cmap.keys())
        font.close()
        return all(ord(ch) in cmap for ch in "őŐűŰ")
    except Exception:
        # fontTools hiányában a legismertebb, ellenőrzött családokat engedjük.
        low = Path(str(path)).name.lower()
        return any(name in low for name in ("dejavu", "notosans", "liberationsans", "arial"))


def _fpi_v409_python_font_pairs() -> List[Tuple[str, str]]:
    """Unicode-font párok keresése a telepített Python-csomagokban.

    Streamlit Cloudon előfordul, hogy nincs rendszerfont a szokásos
    /usr/share/fonts útvonalon, miközben a Matplotlib saját DejaVu Sans
    készlete elérhető a site-packages könyvtárban.
    """
    pairs: List[Tuple[str, str]] = []
    seen: set = set()

    relative_pairs = [
        (
            Path("matplotlib/mpl-data/fonts/ttf/DejaVuSans.ttf"),
            Path("matplotlib/mpl-data/fonts/ttf/DejaVuSans-Bold.ttf"),
        ),
        (
            Path("cv2/qt/fonts/DejaVuSans.ttf"),
            Path("cv2/qt/fonts/DejaVuSans-Bold.ttf"),
        ),
    ]
    for raw_root in sys.path:
        if not raw_root:
            continue
        root = Path(raw_root)
        try:
            root_key = str(root.resolve())
        except Exception:
            root_key = str(root)
        if root_key in seen or not root.exists():
            continue
        seen.add(root_key)
        for regular_rel, bold_rel in relative_pairs:
            regular = root / regular_rel
            bold = root / bold_rel
            if regular.exists():
                pairs.append((str(regular), str(bold if bold.exists() else regular)))
    return pairs


def _fpi_v409_fontconfig_pair() -> Tuple[Optional[str], Optional[str]]:
    """A Linux fontconfig adatbázisából kér Unicode-fontot, ha elérhető."""
    families = ("DejaVu Sans", "Noto Sans", "Liberation Sans", "Arial")
    for family in families:
        try:
            regular_run = subprocess.run(
                ["fc-match", "-f", "%{file}", family],
                capture_output=True,
                text=True,
                timeout=4,
                check=False,
            )
            regular = regular_run.stdout.strip()
            if not regular or not Path(regular).exists() or not _fpi_v408_font_supports_hungarian(regular):
                continue

            bold_run = subprocess.run(
                ["fc-match", "-f", "%{file}", f"{family}:style=Bold"],
                capture_output=True,
                text=True,
                timeout=4,
                check=False,
            )
            bold = bold_run.stdout.strip()
            if not bold or not Path(bold).exists() or not _fpi_v408_font_supports_hungarian(bold):
                bold = regular
            return regular, bold
        except Exception:
            continue
    return None, None


def _fpi_v408_find_unicode_font_pair() -> Tuple[Optional[str], Optional[str]]:
    """V409: platformfüggetlen Unicode-fontkeresés több biztonsági szinttel."""
    env_regular = os.environ.get("FPI_PDF_FONT_REGULAR", "").strip()
    env_bold = os.environ.get("FPI_PDF_FONT_BOLD", "").strip()
    pairs: List[Tuple[str, str]] = []
    if env_regular:
        pairs.append((env_regular, env_bold or env_regular))

    # Elsőként a Python-környezetbe csomagolt fontok: Streamlit Cloudon ez a
    # legmegbízhatóbb útvonal, mert nem függ az operációs rendszer image-étől.
    pairs.extend(_fpi_v409_python_font_pairs())
    pairs.extend([
        ("/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf", "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Bold.ttf"),
        ("/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf", "/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"),
        ("C:/Windows/Fonts/arial.ttf", "C:/Windows/Fonts/arialbd.ttf"),
        ("C:/Windows/Fonts/calibri.ttf", "C:/Windows/Fonts/calibrib.ttf"),
        ("/Library/Fonts/Arial.ttf", "/Library/Fonts/Arial Bold.ttf"),
        ("/System/Library/Fonts/Supplemental/Arial.ttf", "/System/Library/Fonts/Supplemental/Arial Bold.ttf"),
    ])
    for regular, bold in pairs:
        if regular and Path(regular).exists() and _fpi_v408_font_supports_hungarian(regular):
            valid_bold = bold if bold and Path(bold).exists() and _fpi_v408_font_supports_hungarian(bold) else regular
            return str(regular), str(valid_bold)

    # Második biztonsági szint: kérdezzük le a rendszer fontconfig adatbázisát.
    fc_regular, fc_bold = _fpi_v409_fontconfig_pair()
    if fc_regular:
        return fc_regular, fc_bold or fc_regular

    # Harmadik szint: ismert fontnevek rekurzív keresése a tipikus könyvtárakban.
    roots = [
        Path("/usr/share/fonts"), Path("/usr/local/share/fonts"),
        Path.home() / ".fonts", Path.home() / ".local/share/fonts",
        Path("C:/Windows/Fonts"), Path("/Library/Fonts"),
        Path("/System/Library/Fonts"),
    ]
    wanted_regular = {
        "NotoSans-Regular.ttf", "DejaVuSans.ttf", "DejaVuSansCondensed.ttf",
        "LiberationSans-Regular.ttf", "Arial.ttf", "arial.ttf",
    }
    wanted_bold = {
        "NotoSans-Bold.ttf", "DejaVuSans-Bold.ttf", "DejaVuSansCondensed-Bold.ttf",
        "LiberationSans-Bold.ttf", "Arial Bold.ttf", "arialbd.ttf",
    }
    found_regular: Optional[str] = None
    found_bold: Optional[str] = None
    for root in roots:
        if not root.exists():
            continue
        try:
            for candidate in root.rglob("*"):
                if not candidate.is_file() or candidate.suffix.lower() not in {".ttf", ".otf"}:
                    continue
                if found_regular is None and candidate.name in wanted_regular and _fpi_v408_font_supports_hungarian(candidate):
                    found_regular = str(candidate)
                if found_bold is None and candidate.name in wanted_bold and _fpi_v408_font_supports_hungarian(candidate):
                    found_bold = str(candidate)
                if found_regular and found_bold:
                    return found_regular, found_bold
        except Exception:
            continue
    if found_regular:
        return found_regular, found_bold or found_regular
    return None, None


def _register_pdf_font() -> Tuple[str, str]:
    """V409: felhőbiztos Unicode-fontregisztráció, leállás nélküli fallbackkel.

    Elsődlegesen ő/Ő/ű/Ű glyph-eket tartalmazó TTF/OTF családot használ.
    Ha ilyen a futtatókörnyezetben egyáltalán nincs, nem dob RuntimeError-t:
    a ReportLab alapfontjára vált, és a sanitizer csak ebben a vészmódban
    ő→ö, ű→ü helyettesítést alkalmaz.
    """
    cached = globals().get("_FPI_V408_PDF_FONT_CACHE")
    if cached:
        return cached

    if pdfmetrics is None or TTFont is None:
        globals()["_FPI_PDF_STANDARD_FONT_FALLBACK"] = True
        fallback = ("Helvetica", "Helvetica-Bold")
        globals()["_FPI_V408_PDF_FONT_CACHE"] = fallback
        globals()["_FPI_V408_PDF_FONT_PATHS"] = (None, None)
        return fallback

    normal_path, bold_path = _fpi_v408_find_unicode_font_pair()
    if not normal_path:
        globals()["_FPI_PDF_STANDARD_FONT_FALLBACK"] = True
        fallback = ("Helvetica", "Helvetica-Bold")
        globals()["_FPI_V408_PDF_FONT_CACHE"] = fallback
        globals()["_FPI_V408_PDF_FONT_PATHS"] = (None, None)
        return fallback

    regular_name = "FPIUnicodeV409"
    bold_name = "FPIUnicodeV409-Bold"
    try:
        registered = set(pdfmetrics.getRegisteredFontNames())
        if regular_name not in registered:
            pdfmetrics.registerFont(TTFont(regular_name, normal_path))
        if bold_name not in registered:
            pdfmetrics.registerFont(TTFont(bold_name, bold_path or normal_path))
        pdfmetrics.registerFontFamily(
            regular_name,
            normal=regular_name,
            bold=bold_name,
            italic=regular_name,
            boldItalic=bold_name,
        )
    except Exception:
        # Hibás vagy a ReportLab által nem olvasható font se állítsa le az appot.
        globals()["_FPI_PDF_STANDARD_FONT_FALLBACK"] = True
        fallback = ("Helvetica", "Helvetica-Bold")
        globals()["_FPI_V408_PDF_FONT_CACHE"] = fallback
        globals()["_FPI_V408_PDF_FONT_PATHS"] = (None, None)
        return fallback

    globals()["_FPI_PDF_STANDARD_FONT_FALLBACK"] = False
    globals()["_FPI_V408_PDF_FONT_CACHE"] = (regular_name, bold_name)
    globals()["_FPI_V408_PDF_FONT_PATHS"] = (normal_path, bold_path)
    return regular_name, bold_name

def insights_to_pdf_bytes(insights_df: pd.DataFrame, selected_week: str) -> Optional[bytes]:
    if SimpleDocTemplate is None:
        return None

    font_name, font_bold = _register_pdf_font()

    output = io.BytesIO()
    doc = SimpleDocTemplate(
        output,
        pagesize=landscape(A4),
        rightMargin=0.8 * cm,
        leftMargin=0.8 * cm,
        topMargin=0.8 * cm,
        bottomMargin=0.8 * cm,
    )
    styles = getSampleStyleSheet()

    title_style = ParagraphStyle(
        "MagyarCim",
        parent=styles["Title"],
        fontName=font_bold,
        fontSize=17,
        leading=21,
        spaceAfter=10,
    )
    meta_style = ParagraphStyle(
        "MagyarMeta",
        parent=styles["Normal"],
        fontName=font_name,
        fontSize=9,
        leading=11,
    )
    normal = ParagraphStyle(
        "MagyarNormalWrapped",
        parent=styles["Normal"],
        fontName=font_name,
        fontSize=7,
        leading=9,
        wordWrap="CJK",
    )
    header = ParagraphStyle(
        "MagyarHeaderWrapped",
        parent=styles["Normal"],
        fontName=font_bold,
        fontSize=7,
        leading=9,
        textColor=colors.white,
        wordWrap="CJK",
    )

    story = [
        Paragraph(pdf_safe_text("Performance megállapítások és javaslatok"), title_style),
        Paragraph(pdf_safe_text(f"Hét: {selected_week} · Generálva: {datetime.now().strftime('%Y-%m-%d %H:%M')}"), meta_style),
        Spacer(1, 0.25 * cm),
    ]

    cols = ["Súlyosság", "Terület", "Megállapítás", "Mit látunk?", "Miért fontos?", "Javaslat"]
    cols = [c for c in cols if c in insights_df.columns]

    def safe_paragraph(value, style):
        text = "" if pd.isna(value) else str(value)
        text = pdf_safe_text(text)
        return Paragraph(html.escape(text).replace("\n", "<br/>",), style)

    table_data = [[safe_paragraph(c, header) for c in cols]]
    for _, row in insights_df.iterrows():
        table_data.append([safe_paragraph(row.get(c, ""), normal) for c in cols])

    col_widths_map = {
        "Súlyosság": 2.6 * cm,
        "Terület": 2.0 * cm,
        "Megállapítás": 3.8 * cm,
        "Mit látunk?": 6.0 * cm,
        "Miért fontos?": 6.0 * cm,
        "Javaslat": 7.2 * cm,
    }
    table = Table(table_data, colWidths=[col_widths_map.get(c, 3 * cm) for c in cols], repeatRows=1)
    table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#1F4E78")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTNAME", (0, 0), (-1, 0), font_bold),
        ("FONTNAME", (0, 1), (-1, -1), font_name),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#BFBFBF")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F7F9FC")]),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
    ]))
    story.append(table)

    # V5 PDF pages - past/current/next split planning
    try:
        _past_review = globals().get("past_week_review_df", pd.DataFrame())
        _past_text = globals().get("past_week_review_text", "")
        _current_plan = globals().get("current_remaining_plan_df", pd.DataFrame())
        _current_text = globals().get("current_remaining_text", "")
        _next_week_plan = globals().get("next_week_plan_df", pd.DataFrame())
        _next_week_text = globals().get("next_week_plan_text", "")
        _player_actions = globals().get("player_next_actions_df", pd.DataFrame())

        try:
            from reportlab.platypus import PageBreak
        except Exception:
            PageBreak = None

        if PageBreak:
            story.append(PageBreak())
        story.append(P("Múlt hét / aktuális hét / jövő hét", title))
        story.append(P("Teljes múlt heti értékelés, aktuális hét hátralévő napjai, és jövő heti mikrociklus terv.", subtitle))

        story.append(section_bar("1) Múlt hét -> javaslat erre a hétre"))
        story.append(data_table([[P("Összefoglaló", header)], [P(_past_text, body)]], [27.7 * cm], header_bg="#1E3A8A", row_bgs=[colors.HexColor("#EFF6FF")]))
        if _past_review is not None and not _past_review.empty:
            cols = [c for c in ["Prioritás", "Múlt heti megállapítás", "Súlyosság", "Javaslat erre a hétre"] if c in _past_review.columns]
            pdata = [[P(c, header) for c in cols]]
            for _, rr in _past_review.head(6).iterrows():
                pdata.append([P(rr.get(c, ""), tiny) for c in cols])
            story.append(data_table(pdata, [1.7 * cm, 7.0 * cm, 3.0 * cm, 16.0 * cm][:len(cols)], header_bg="#0F172A", row_bgs=[colors.white, colors.HexColor("#F8FAFC")]))

        story += [Spacer(1, 0.25 * cm)]
        story.append(section_bar("2) Aktuális hét -> hátralévő napok"))
        story.append(data_table([[P("Összefoglaló", header)], [P(_current_text, body)]], [27.7 * cm], header_bg="#166534", row_bgs=[colors.HexColor("#ECFDF5")]))
        if _current_plan is not None and not _current_plan.empty:
            cols = [c for c in ["Hátralévő pont", "Fókusz", "Ajánlott terhelés", "Javaslat"] if c in _current_plan.columns]
            cdata = [[P(c, header) for c in cols]]
            for _, rr in _current_plan.head(6).iterrows():
                cdata.append([P(rr.get(c, ""), tiny) for c in cols])
            story.append(data_table(cdata, [3.2 * cm, 4.8 * cm, 3.5 * cm, 16.2 * cm][:len(cols)], header_bg="#166534", row_bgs=[colors.white, colors.HexColor("#ECFDF5")]))

        if PageBreak:
            story.append(PageBreak())
        story.append(P("Jövő heti mikrociklus terv", title))
        story.append(P(_next_week_text, subtitle))
        if _next_week_plan is not None and not _next_week_plan.empty:
            cols = [c for c in ["Nap", "Szerep", "Fő cél", "Ajánlott terhelés", "Javaslat", "Tervezési alap"] if c in _next_week_plan.columns]
            ndata = [[P(c, header) for c in cols]]
            for _, rr in _next_week_plan.head(8).iterrows():
                ndata.append([P(rr.get(c, ""), tiny) for c in cols])
            story.append(data_table(ndata, [1.7 * cm, 3.2 * cm, 4.0 * cm, 3.0 * cm, 8.8 * cm, 7.0 * cm][:len(cols)], header_bg="#312E81", row_bgs=[colors.white, colors.HexColor("#F5F3FF")]))

        if _player_actions is not None and not _player_actions.empty:
            story += [Spacer(1, 0.25 * cm)]
            story.append(section_bar("Játékosszintű következő teendők"))
            cols = [c for c in ["Játékos", "Prioritás", "Holnap / következő edzés", "Következő hét", "Indok"] if c in _player_actions.columns]
            adata = [[P(c, header) for c in cols]]
            for _, rr in _player_actions.head(8).iterrows():
                adata.append([P(rr.get(c, ""), tiny) for c in cols])
            story.append(data_table(adata, [3.3 * cm, 2.5 * cm, 7.0 * cm, 7.0 * cm, 7.9 * cm][:len(cols)], header_bg="#7F1D1D", row_bgs=[colors.white, colors.HexColor("#FFF7ED")]))
    except Exception:
        pass


    _fpi_pdf_build_v406(doc, story)
    return output.getvalue()



# -----------------------------------------------------------------------------
# V3 - Premium visualization + Player Risk + Positional layer + improved PDF
# -----------------------------------------------------------------------------
POSITION_GROUPS = {
    "Kapus": ["gk", "kapus", "goalkeeper"],
    "Belső védő": ["cb", "belső védő", "center back", "centre back"],
    "Szélső védő": ["fb", "wb", "szélső védő", "fullback", "wingback"],
    "Középpályás": ["cm", "dm", "am", "középpályás", "midfielder"],
    "Szélső": ["winger", "szélső", "wide"],
    "Csatár": ["st", "cf", "csatár", "striker", "forward"],
}

def infer_position_group(value: object) -> str:
    if value is None or pd.isna(value): return "Ismeretlen"
    text = str(value).lower().strip()
    for group, keys in POSITION_GROUPS.items():
        if any(k in text for k in keys): return group
    return str(value).strip() if str(value).strip() else "Ismeretlen"

def add_position_group(df: pd.DataFrame) -> pd.DataFrame:
    out=df.copy(); out["position_group"] = out["position"].apply(infer_position_group) if "position" in out.columns else "Ismeretlen"; return out

def _fpi_v303_is_partial_week(df: pd.DataFrame, week: str) -> bool:
    current = df[df.get("week", pd.Series("", index=df.index)).astype(str).eq(str(week))].copy()
    if current.empty:
        return False
    starts = pd.to_datetime(current.get("start_time"), errors="coerce").dropna()
    has_match = current.get("session_type", pd.Series("", index=current.index)).astype(str).eq("Meccs").any()
    latest_day = int(starts.max().weekday()) if not starts.empty else 6
    return (not has_match) and latest_day < 6

def _fpi_v303_adjust_partial_week_risk(risks: pd.DataFrame, df: pd.DataFrame, week: str) -> pd.DataFrame:
    if risks is None or risks.empty or not _fpi_v303_is_partial_week(df, week):
        return risks
    out = risks.copy()
    level_col = next((c for c in ["Szint", "Risk Level", "risk_level"] if c in out.columns), None)
    reason_col = next((c for c in ["Miért fontos?", "Reason", "reason"] if c in out.columns), None)
    if level_col is None or reason_col is None:
        return out
    txt = out[reason_col].fillna("").astype(str).str.lower()
    negative = txt.str.contains(r"terhelési pont:\s*-|sprinttáv:\s*-|high efforts:\s*-|játékperc/exposure:\s*-", regex=True, na=False)
    attendance = txt.str.contains("edzésrészvétel", na=False)
    overload = txt.str.contains(r"terhelési pont:\s*\+|high efforts:\s*\+|lassítás:\s*\+", regex=True, na=False)
    mask = negative & ~attendance & ~overload
    out.loc[mask, level_col] = "Előzetes"
    out.loc[mask, reason_col] = out.loc[mask, reason_col].astype(str) + " | Csonka hét: még nem végleges kockázati minősítés."
    return out

def calculate_player_risk(df: pd.DataFrame, selected_week: str) -> pd.DataFrame:
    pw=player_weekly(df)
    if pw.empty or selected_week not in pw["week"].values: return pd.DataFrame()
    weeks=sorted(pw["week"].dropna().unique().tolist()); idx=weeks.index(selected_week)
    cur=pw[pw["week"]==selected_week].copy(); hist=pw[pw["week"].isin(weeks[max(0,idx-4):idx])].copy(); rows=[]
    for _, row in cur.iterrows():
        player=row["player_name"]; hp=hist[hist["player_name"]==player]; score=20; reasons=[]
        is_gk = bool(row.get("is_goalkeeper", False))
        team_sessions = int(row.get("team_training_sessions", 0) or 0)
        player_sessions = int(row.get("player_training_sessions", 0) or 0)
        availability = pd.to_numeric(
            pd.Series([row.get("training_availability_pct", np.nan)]),
            errors="coerce",
        ).iloc[0]
        low_attendance = (
            team_sessions >= 2
            and pd.notna(availability)
            and availability < 75
        )
        if low_attendance:
            if availability < 50:
                score += 20
            else:
                score += 12
            reasons.append(
                f"Edzésrészvétel: {player_sessions}/{team_sessions} "
                f"({availability:.0f}%)"
            )

        # Kapusnál nem büntetjük ugyanúgy az alacsony sprint/HSR profilt.
        # A risk fő fókusza nála a teljes load, high efforts, lassítás/gyorsulás és játékperc.
        metric_pack = [
            ("training_load", .35 if is_gk else .30, -0.40 if is_gk else -0.35, "Terhelési pont"),
            ("high_efforts", .45 if is_gk else .35, -0.45 if is_gk else -0.40, "High Efforts"),
            ("dec_count", .45 if is_gk else .35, -0.45 if is_gk else -0.40, "Lassítás"),
        ]
        if not is_gk:
            metric_pack.append(("sprint_distance", .45, -0.45, "Sprinttáv"))
        for metric, hi, lo, lab in metric_pack:
            if metric in row.index and metric in hp.columns:
                v=row.get(metric,np.nan); base=hp[metric].mean()
                if pd.notna(v) and pd.notna(base) and base!=0:
                    d=(v-base)/base
                    if d>hi:
                        score += 18
                        reasons.append(f"{lab}: +{d:.0%} a saját átlaghoz képest")
                    elif d<lo:
                        # Alacsony heti összterhelésnél különbséget teszünk:
                        # hiányzás vagy teljes részvétel melletti alacsony inger.
                        if low_attendance and metric in {
                            "training_load", "high_efforts", "dec_count",
                            "sprint_distance",
                        }:
                            if not any("alacsony heti érték fő oka" in x for x in reasons):
                                reasons.append(
                                    "Az alacsony heti érték fő oka valószínűleg "
                                    "a hiányos edzésrészvétel."
                                )
                        else:
                            score += 8
                            reasons.append(
                                f"{lab}: {d:.0%} a saját átlaghoz képest"
                            )
        if "player_minutes" in row.index and "player_minutes" in hp.columns:
            v=row.get("player_minutes",np.nan); base=hp["player_minutes"].mean()
            if pd.notna(v) and pd.notna(base) and base>0 and abs((v-base)/base)>.35:
                d=(v-base)/base; score+=8; reasons.append(f"Játékperc/exposure: {d:+.0%} a saját átlaghoz képest")
        if (not is_gk) and "max_speed" in row.index and "max_speed" in hp.columns:
            v=row.get("max_speed",np.nan); base=hp["max_speed"].max()
            if pd.notna(v) and pd.notna(base) and base>0 and (v-base)/base < -.06:
                score+=14; reasons.append(f"Max sebesség: {(v-base)/base:.0%} a saját csúcshoz képest")
        score=int(max(0,min(100,score))); level="Magas" if score>=70 else ("Közepes" if score>=45 else "Alacsony")
        role = "Kapus" if is_gk else "Mezőny"
        attendance_text = (
            f"{player_sessions}/{team_sessions} ({availability:.0f}%)"
            if team_sessions > 0 and pd.notna(availability)
            else "n.a."
        )
        rows.append({
            "Játékos": player,
            "Szerep": role,
            "Típus": row.get("session_type", ""),
            "Játékperc": round(row.get("player_minutes", 0) or 0, 1),
            "Edzésrészvétel": attendance_text,
            "Edzések": player_sessions,
            "Csapatedzések": team_sessions,
            "Részvétel %": round(float(availability), 1) if pd.notna(availability) else np.nan,
            "Kockázati pontszám": score,
            "Kockázati szint": level,
            "Fő okok": "; ".join(reasons[:3]) if reasons else "Nincs jelentős eltérés a saját előzményhez képest.",
        })
    res=pd.DataFrame(rows); return res.sort_values("Kockázati pontszám",ascending=False) if not res.empty else res

def render_premium_kpi(label: str, value: str, note: str="", color: str="#22c55e") -> None:
    st.markdown(f"""<div class='premium-kpi'><div class='premium-kpi-label'>{html.escape(label)}</div><div class='premium-kpi-value' style='color:{color};'>{html.escape(str(value))}</div><div class='premium-kpi-note'>{html.escape(note)}</div></div>""", unsafe_allow_html=True)

def render_hero(selected_week: str, selected_playstyle: str, readiness_score: int, periodization_type: str) -> None:
    color=score_to_color(readiness_score) if "score_to_color" in globals() else "#22c55e"; label=score_to_label(readiness_score) if "score_to_label" in globals() else ""
    st.markdown(f"""<div class='hero-box'><div class='hero-title'>Football Performance Intelligence</div><div class='hero-sub'><span class='section-chip'>Hét: {html.escape(str(selected_week))}</span><span class='section-chip'>Játékmodell: {html.escape(str(selected_playstyle))}</span><span class='section-chip'>Meccskészültség: <b style='color:{color};'>{readiness_score}/100</b> - {html.escape(label)}</span><span class='section-chip'>Periodizáció: {html.escape(str(periodization_type))}</span></div></div>""", unsafe_allow_html=True)

def render_risk_cards(risk_df: pd.DataFrame, limit: int=5) -> None:
    if risk_df.empty: st.info("Nincs elég adat játékosszintű risk engine számításhoz."); return
    for _, row in risk_df.head(limit).iterrows():
        level=row.get("Kockázati szint","Alacsony"); css="risk-high" if level=="Magas" else ("risk-medium" if level=="Közepes" else "risk-low")
        st.markdown(f"""<div class='insight-card {css}'><div class='insight-title'>{html.escape(str(row.get('Játékos','')))} · {html.escape(str(level))} kockázat · {row.get('Kockázati pontszám',0)}/100</div><div class='insight-label'>Fő okok</div><div class='insight-text'>{html.escape(str(row.get('Fő okok','')))}</div></div>""", unsafe_allow_html=True)





