def _fpi_to_standard_if_needed(data: pd.DataFrame) -> pd.DataFrame:
    """Bármely támogatott Excelből vagy már standardizált DF-ből riportképes DF-et készít."""
    if data is None or data.empty:
        return pd.DataFrame()
    if {"player_name", "week", "start_time"}.issubset(set(data.columns)):
        out = data.copy()
    else:
        out, _, missing = standardize_dataframe(data.copy())
        if missing:
            return pd.DataFrame()
    try:
        out = add_position_group(out)
    except Exception:
        pass
    return out


def _fpi_latest_week(df: pd.DataFrame, selected_week: Optional[str] = None) -> Optional[str]:
    if df is None or df.empty or "week" not in df.columns:
        return selected_week
    weeks = sorted(df["week"].dropna().astype(str).unique().tolist())
    if selected_week in weeks:
        return selected_week
    return weeks[-1] if weeks else selected_week



# =============================================================================
# V300 – Unified Core Engine
# =============================================================================
_FPI_V300_HALF_RE = re.compile(
    r"(?:^|\b)(?:first|second|1st|2nd|1|2)\s*[-_. ]*(?:half(?:\s*time)?|halftime|felido|felidő)\b"
    r"|\b(?:half(?:\s*time)?|halftime|felido|felidő)\s*[-_. ]*(?:1|2)\b"
    r"|(?:^|\b)h\s*[-_. ]*(?:1|2)\b",
    flags=re.IGNORECASE,
)


def _fpi_v300_is_half(value: object) -> bool:
    return bool(_FPI_V300_HALF_RE.search(_norm_mapping_text(str(value or ""))))


def _fpi_v300_base_match_name(value: object) -> str:
    text = str(value or "")
    text = _FPI_V300_HALF_RE.sub("", text)
    text = re.sub(r"\s+", " ", text).strip(" -_")
    return text or "Meccs"


def _fpi_v300_iso_week(series: pd.Series) -> pd.Series:
    dt = pd.to_datetime(series, errors="coerce")
    iso = dt.dt.isocalendar()
    result = pd.Series(pd.NA, index=series.index, dtype="object")
    ok = dt.notna()
    result.loc[ok] = (
        iso.loc[ok, "year"].astype(str)
        + "-W"
        + iso.loc[ok, "week"].astype(str).str.zfill(2)
    )
    return result



def _fpi_v301_date_from_text(value: object) -> pd.Timestamp:
    """Dátummentés Barin session- és lapnevekből.

    Elfogadott példák:
    - Training 2026-7-23 AM
    - 1 half 2026-7-18 10:36
    - 2026_07_23
    """
    text = str(value or "")
    match = re.search(r"(?<!\d)(20\d{2})[-_./ ](\d{1,2})[-_./ ](\d{1,2})(?!\d)", text)
    if not match:
        return pd.NaT
    try:
        return pd.Timestamp(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except Exception:
        return pd.NaT


def _fpi_v301_repair_start_time(df: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, int]]:
    """A start_time dátumrészét a session/lap nevéből menti vissza.

    A Barin időcellája időnként hibás naptári dátumként olvasódik be. A session
    nevében szereplő YYYY-M-D dátum erősebb forrás, az időpontot viszont az
    eredeti start_time értékből megtartjuk.
    """
    out = df.copy()
    original = pd.to_datetime(out.get("start_time"), errors="coerce")
    text_cols = [c for c in ["session_name", "_fpi_source_sheet", "_fpi_source_key"] if c in out.columns]
    rescued = pd.Series(pd.NaT, index=out.index, dtype="datetime64[ns]")
    for col in text_cols:
        candidate = out[col].map(_fpi_v301_date_from_text)
        rescued = rescued.where(rescued.notna(), candidate)

    repaired = original.copy()
    mask = rescued.notna()
    if mask.any():
        hours = original.dt.hour.fillna(0)
        minutes = original.dt.minute.fillna(0)
        seconds = original.dt.second.fillna(0)
        repaired.loc[mask] = (
            rescued.loc[mask]
            + pd.to_timedelta(hours.loc[mask], unit="h")
            + pd.to_timedelta(minutes.loc[mask], unit="m")
            + pd.to_timedelta(seconds.loc[mask], unit="s")
        )
    changed = int((mask & (original.dt.normalize() != repaired.dt.normalize())).sum())
    out["start_time"] = repaired
    return out, {"rescued_rows": int(mask.sum()), "changed_date_rows": changed}


def _fpi_v301_assign_match_events(df: pd.DataFrame) -> pd.DataFrame:
    """Első és második félidők párosítása teljes meccseseménnyé.

    V416: a félidőjel nemcsak a session_name mezőből, hanem a forrás munkalap
    nevéből is felismerhető. Egy napon több mérkőzés is lehet: minden 1. félidő
    új eseményt indít, az azt követő 2. félidő ugyanahhoz az eseményhez kerül.
    """
    out = df.copy()
    out["match_event_id"] = pd.NA
    matches = out[out["session_type"].eq("Meccs")].copy()
    if matches.empty:
        return out

    cols = ["session_id", "start_time", "session_name", "session_date"]
    if "_fpi_source_sheet" in matches.columns:
        cols.append("_fpi_source_sheet")
    session_meta = (
        matches[cols]
        .drop_duplicates("session_id")
        .sort_values(["session_date", "start_time", "session_id"])
    )
    mapping = {}
    for day, group in session_meta.groupby("session_date", dropna=False):
        event_no = 0
        active_event = None
        for _, row in group.iterrows():
            name = str(row.get("session_name", "") or "")
            sheet = str(row.get("_fpi_source_sheet", "") or "")
            half_context = (name + " " + sheet).strip()
            norm = _norm_mapping_text(half_context)
            half_no_v406 = _fpi_v406_half_number(half_context) if "_fpi_v406_half_number" in globals() else None
            first = half_no_v406 == 1 or bool(re.search(r"(?:first|1st|\b1\b)\s*[-_. ]*(?:half|felido)|(?:half|felido)\s*[-_. ]*1\b", norm))
            second = half_no_v406 == 2 or bool(re.search(r"(?:second|2nd|\b2\b)\s*[-_. ]*(?:half|felido)|(?:half|felido)\s*[-_. ]*2\b", norm))
            if first or active_event is None:
                event_no += 1
                active_event = f"{day}|match-{event_no}"
            mapping[row["session_id"]] = active_event
            if second:
                active_event = None
    mask = out["session_type"].eq("Meccs")
    out.loc[mask, "match_event_id"] = out.loc[mask, "session_id"].map(mapping)
    return out


_FPI_V406_HALFTIME_SUM_COLUMNS = [
    "duration_min", "match_minutes", "total_distance", "training_load",
    "sprint_distance", "hsr_distance", "sprints", "high_efforts",
    "acc_count", "dec_count", "acc_low", "acc_mid", "acc_high",
    "dec_low", "dec_mid", "dec_high", "speed_zone_3", "speed_zone_4",
    "speed_zone_5", "muscle_load",
]
_FPI_V406_HALFTIME_AVG_COLUMNS = []
_FPI_V411_HALFTIME_MAX_COLUMNS = ["max_speed"]


def _fpi_v406_half_number(value: object) -> Optional[int]:
    norm = _norm_mapping_text(str(value or ""))
    if re.search(r"(?:first|1st|\b1\b)\s*[-_. ]*(?:half(?:\s*time)?|halftime|felido)|(?:half(?:\s*time)?|halftime|felido)\s*[-_. ]*1\b|\bh\s*[-_. ]*1\b", norm):
        return 1
    if re.search(r"(?:second|2nd|\b2\b)\s*[-_. ]*(?:half(?:\s*time)?|halftime|felido)|(?:half(?:\s*time)?|halftime|felido)\s*[-_. ]*2\b|\bh\s*[-_. ]*2\b", norm):
        return 2
    return None


def _fpi_v406_drop_exposure_derivatives(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    fixed = {
        "player_minutes", "event_duration_min", "match_length_label",
        "session_player_count", "field_player_count", "team_player_minutes",
        "field_team_minutes", "keeper_weight",
    }
    suffixes = ("_per90", "_per_player", "_per_field_player", "_keeper_adjusted")
    drop_cols = [c for c in out.columns if c in fixed or c.endswith(suffixes)]
    return out.drop(columns=drop_cols, errors="ignore")


def _fpi_v406_merge_halftime_matches(df: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, int]]:
    """Half 1 + Half 2 sorokból játékosonként egyetlen Match-sort készít.

    Összegzi a volumen- és akciómutatókat, a Max Speed értékénél a nagyobbik
    félidős értéket tartja meg, majd az exposure/per90 mezőket a teljes
    mérkőzésre újraszámolja. A félidőjel a session- vagy munkalapnévből is
    felismerhető. A nem félidős edzések és teljes meccsexportok változatlanok.
    """
    empty_report = {
        "halftime_source_sessions": 0,
        "halftime_merged_events": 0,
        "halftime_merged_player_rows": 0,
    }
    if df is None or df.empty or "match_event_id" not in df.columns:
        return df, empty_report

    out = df.copy()
    session_half_context = out.get("session_name", pd.Series("", index=out.index)).astype(str)
    if "_fpi_source_sheet" in out.columns:
        session_half_context = session_half_context + " " + out["_fpi_source_sheet"].fillna("").astype(str)
    half_mask = session_half_context.map(_fpi_v300_is_half)
    match_mask = out.get("session_type", pd.Series("", index=out.index)).astype(str).eq("Meccs")
    half_rows = out[half_mask & match_mask & out["match_event_id"].notna()].copy()
    if half_rows.empty:
        return out, empty_report

    half_context_rows = half_rows["session_name"].fillna("").astype(str)
    if "_fpi_source_sheet" in half_rows.columns:
        half_context_rows = half_context_rows + " " + half_rows["_fpi_source_sheet"].fillna("").astype(str)
    half_rows["_fpi_v406_half_no"] = half_context_rows.map(_fpi_v406_half_number)
    session_coverage = (
        half_rows.groupby("match_event_id", dropna=False)
        .agg(
            half_sessions=("session_id", "nunique"),
            half_numbers=("_fpi_v406_half_no", lambda s: set(x for x in s.dropna().astype(int).tolist())),
        )
    )
    merge_events = session_coverage[
        (session_coverage["half_sessions"] >= 2)
        & session_coverage["half_numbers"].map(lambda s: {1, 2}.issubset(s))
    ].index.tolist()
    if not merge_events:
        return out, {
            "halftime_source_sessions": int(half_rows["session_id"].nunique()),
            "halftime_merged_events": 0,
            "halftime_merged_player_rows": 0,
        }

    to_merge = out[out["match_event_id"].isin(merge_events) & half_mask & match_mask].copy()
    keep = out[~(out["match_event_id"].isin(merge_events) & half_mask & match_mask)].copy()
    to_merge["start_time"] = pd.to_datetime(to_merge["start_time"], errors="coerce")

    rows = []
    for (event_id, player), group in to_merge.groupby(["match_event_id", "player_name"], dropna=False, sort=False):
        group = group.sort_values(["start_time", "session_id"], kind="mergesort")
        row = group.iloc[0].copy()
        source_names = group["session_name"].dropna().astype(str).tolist()
        base_names = [
            _fpi_v300_base_match_name(name)
            for name in source_names
            if _fpi_v300_base_match_name(name) not in {"", "Meccs"}
        ]
        base_name = base_names[0] if base_names else "Meccs"
        row["session_name"] = base_name
        row["session_type"] = "Meccs"
        row["start_time"] = group["start_time"].dropna().min()
        row["session_date"] = pd.to_datetime(row["start_time"], errors="coerce").normalize() if pd.notna(row["start_time"]) else pd.NaT
        row["week"] = _fpi_v300_iso_week(pd.Series([row["start_time"]])).iloc[0]
        row["match_event_id"] = event_id
        row["session_id"] = f"{event_id}|merged-match"
        row["halftime_merged"] = True
        row["halftime_parts"] = int(group["session_id"].nunique())
        row["halftime_source_sessions"] = " | ".join(dict.fromkeys(source_names))
        for source_col_v406 in ["_fpi_source_file", "_fpi_source_key", "_fpi_source_sheet", "_fpi_upload_group"]:
            if source_col_v406 in group.columns:
                source_values_v406 = group[source_col_v406].dropna().astype(str).str.strip()
                source_values_v406 = source_values_v406[source_values_v406.ne("")]
                if not source_values_v406.empty:
                    row[source_col_v406] = " | ".join(dict.fromkeys(source_values_v406.tolist()))

        for col in _FPI_V406_HALFTIME_SUM_COLUMNS:
            if col in group.columns:
                nums = pd.to_numeric(group[col], errors="coerce")
                row[col] = nums.sum(min_count=1)
        for col in _FPI_V406_HALFTIME_AVG_COLUMNS:
            if col in group.columns:
                nums = pd.to_numeric(group[col], errors="coerce")
                row[col] = nums.mean() if nums.notna().any() else np.nan
        for col in _FPI_V411_HALFTIME_MAX_COLUMNS:
            if col in group.columns:
                nums = pd.to_numeric(group[col], errors="coerce")
                row[col] = nums.max() if nums.notna().any() else np.nan

        duration = pd.to_numeric(pd.Series([row.get("duration_min")]), errors="coerce").iloc[0]
        distance = pd.to_numeric(pd.Series([row.get("total_distance")]), errors="coerce").iloc[0]
        if pd.notna(duration) and duration > 0 and pd.notna(distance):
            row["distance_per_min"] = float(distance) / float(duration)
        elif "distance_per_min" in group.columns:
            weights = pd.to_numeric(group.get("duration_min"), errors="coerce")
            values = pd.to_numeric(group["distance_per_min"], errors="coerce")
            valid = values.notna() & weights.notna() & weights.gt(0)
            row["distance_per_min"] = float(np.average(values[valid], weights=weights[valid])) if valid.any() else values.mean()

        if "avg_speed" in group.columns:
            weights = pd.to_numeric(group.get("duration_min"), errors="coerce")
            values = pd.to_numeric(group["avg_speed"], errors="coerce")
            valid = values.notna() & weights.notna() & weights.gt(0)
            row["avg_speed"] = float(np.average(values[valid], weights=weights[valid])) if valid.any() else values.mean()
        rows.append(row)

    merged = pd.DataFrame(rows)
    combined = pd.concat([keep, merged], ignore_index=True, sort=False)
    combined = _fpi_v406_drop_exposure_derivatives(combined)
    combined = finalize_exposure_columns(combined)
    combined = combined.sort_values(["start_time", "session_type", "session_name", "player_name"], kind="mergesort").reset_index(drop=True)
    return combined, {
        "halftime_source_sessions": int(to_merge["session_id"].nunique()),
        "halftime_merged_events": int(len(merge_events)),
        "halftime_merged_player_rows": int(len(merged)),
    }







def _fpi_v300_master_dataset(data: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, object]]:
    df = _fpi_to_standard_if_needed(data)
    if df is None or df.empty:
        return pd.DataFrame(), {
            "sessions": 0, "training_sessions": 0,
            "match_phase_sessions": 0, "match_events": 0,
            "weeks": [], "date_min": None, "date_max": None,
            "deduplicated_rows": 0,
        }

    out = df.copy()
    for c in ["player_name", "session_name", "session_type", "start_time"]:
        if c not in out.columns:
            out[c] = pd.NA

    out["start_time"] = pd.to_datetime(out["start_time"], errors="coerce")
    out["session_name"] = out["session_name"].fillna("").astype(str).str.strip()
    out, date_repair_v301 = _fpi_v301_repair_start_time(out)

    half_mask = out["session_name"].map(_fpi_v300_is_half)
    out.loc[half_mask, "session_type"] = "Meccs"
    out["session_type"] = out["session_type"].apply(normalize_session_type)
    out["session_type"] = out["session_type"].where(
        out["session_type"].isin(["Edzés", "Meccs"]), "Edzés"
    )

    # A hét mindig a tényleges sessiondátumból készül.
    out["week"] = _fpi_v300_iso_week(out["start_time"])
    out["session_date"] = out["start_time"].dt.normalize()
    out["session_id"] = (
        out["start_time"].dt.floor("min").astype(str)
        + "|"
        + out["session_name"].map(_norm_mapping_text)
        + "|"
        + out["session_type"].astype(str)
    )

    out = _fpi_v301_assign_match_events(out)

    before = len(out)
    out, dedup = _fpi_v205_deduplicate_overlapping_exports(out)
    removed = int(dedup.get("removed", before - len(out)))

    # Deduplikálás után stabil kulcsok.
    out["start_time"] = pd.to_datetime(out["start_time"], errors="coerce")
    out["week"] = _fpi_v300_iso_week(out["start_time"])
    out["session_date"] = out["start_time"].dt.normalize()
    out["session_id"] = (
        out["start_time"].dt.floor("min").astype(str)
        + "|"
        + out["session_name"].map(_norm_mapping_text)
        + "|"
        + out["session_type"].astype(str)
    )
    out = _fpi_v301_assign_match_events(out)
    gps_source_files_v406 = 0
    source_col_v406 = "_fpi_source_file" if "_fpi_source_file" in out.columns else ("_fpi_source_key" if "_fpi_source_key" in out.columns else None)
    if source_col_v406:
        gps_source_files_v406 = int(
            out[source_col_v406].dropna().astype(str).str.strip().replace("", np.nan).dropna().nunique()
        )
    if gps_source_files_v406 == 0 and not out.empty:
        gps_source_files_v406 = 1
    match_phase_sessions_before_v406 = int(
        out.loc[out["session_type"].eq("Meccs"), "session_id"].dropna().nunique()
    )
    out, halftime_report_v406 = _fpi_v406_merge_halftime_matches(out)

    starts = out["start_time"].dropna()
    weeks = sorted(
        out["week"].dropna().astype(str).unique().tolist(),
        key=_fpi_week_sort_key_v99,
    )
    report = {
        "sessions": int(out["session_id"].dropna().nunique()),
        "training_sessions": int(
            out.loc[out["session_type"].eq("Edzés"), "session_id"].dropna().nunique()
        ),
        "match_phase_sessions": match_phase_sessions_before_v406,
        "analysis_match_sessions": int(
            out.loc[out["session_type"].eq("Meccs"), "session_id"].dropna().nunique()
        ),
        "match_events": int(
            out.loc[out["session_type"].eq("Meccs"), "match_event_id"].dropna().nunique()
        ),
        "weeks": weeks,
        "date_min": starts.min() if not starts.empty else None,
        "date_max": starts.max() if not starts.empty else None,
        "deduplicated_rows": removed,
        "date_rescued_rows": int(date_repair_v301.get("rescued_rows", 0)),
        "date_changed_rows": int(date_repair_v301.get("changed_date_rows", 0)),
        "gps_source_files": gps_source_files_v406,
        **halftime_report_v406,
    }
    out.attrs["fpi_v300_master_report"] = report
    return out, report


def _fpi_v300_match_reference(master: pd.DataFrame) -> Dict[str, object]:
    """Tényleges játékperces, mezőnyjátékos-alapú meccsreferencia.

    Módszer: Half 1 + Half 2 játékosonként előbb összeadódik; a legalább
    10 percet játszó mezőnyjátékosok mutatóit ezután egyenként /90-re
    normalizáljuk, majd ezek mediánja adja a meccsreferenciát.
    A referencia kizárólag ezen játékosszintű /90 logikán alapul.
    """
    if master is None or master.empty:
        return {"available": False}
    matches = master[master["session_type"].eq("Meccs")].copy()
    if matches.empty:
        return {"available": False}
    matches = finalize_exposure_columns(matches)
    sum_metrics = [c for c in [
        "total_distance", "hsr_distance", "sprint_distance", "sprints", "high_efforts",
        "training_load", "acc_count", "dec_count", "acc_high", "dec_high"
    ] if c in matches.columns]
    max_metrics = [c for c in ["max_speed"] if c in matches.columns]
    for c in ["player_minutes"] + sum_metrics + max_metrics:
        if c in matches.columns:
            matches[c] = pd.to_numeric(matches[c], errors="coerce")

    agg = {c: "sum" for c in ["player_minutes"] + sum_metrics}
    agg.update({c: "max" for c in max_metrics})
    if "is_goalkeeper" in matches.columns:
        agg["is_goalkeeper"] = "max"
    pm = matches.groupby(["match_event_id", "player_name"], dropna=False).agg(agg).reset_index()

    field_all = pm.copy()
    if "is_goalkeeper" in pm.columns and (~pm["is_goalkeeper"].fillna(False)).any():
        field_all = pm[~pm["is_goalkeeper"].fillna(False)].copy()

    # A néhány perces csere ne adjon irreális egyéni /90 értéket.
    field_eligible = field_all[field_all["player_minutes"].ge(10)].copy()
    per90, raw_med = {}, {}
    for c in sum_metrics:
        raw = pd.to_numeric(field_eligible[c], errors="coerce")
        mins = pd.to_numeric(field_eligible["player_minutes"], errors="coerce")
        vals = raw / mins.where(mins > 0) * 90.0
        per90[c] = float(vals.dropna().median()) if vals.notna().any() else None
        raw_med[c] = float(raw.dropna().median()) if raw.notna().any() else None
    for c in max_metrics:
        vals = pd.to_numeric(field_eligible[c], errors="coerce").dropna()
        per90[c] = float(vals.median()) if not vals.empty else None
        raw_med[c] = per90[c]

    minute_vals = pd.to_numeric(field_eligible["player_minutes"], errors="coerce").dropna()
    return {
        "available": True,
        "match_events": int(matches["match_event_id"].dropna().nunique()),
        "player_match_rows": len(pm),
        "eligible_player_match_rows": len(field_eligible),
        "metrics": per90,
        "metrics_per90": per90,
        "metrics_actual_median": raw_med,
        "player_minutes_median": float(minute_vals.median()) if not minute_vals.empty else None,
        "reference_note": "Mezőnyjátékos /90 medián (min. 10 perc); Half 1 + Half 2 előbb játékosonként összeadódik.",
    }


def _fpi_v302_week_context_factor(analysis_df: pd.DataFrame, selected_week: str) -> Dict[str, object]:
    if analysis_df is None or analysis_df.empty:
        return {"completion":1.0,"phase_factor":1.0,"label":"teljes hét","week_type":"normál","partial":False}
    starts=pd.to_datetime(analysis_df.get("start_time"),errors="coerce").dropna()
    wd=int(starts.max().weekday()) if not starts.empty else 6
    train=analysis_df[analysis_df.get("session_type",pd.Series("",index=analysis_df.index)).astype(str).eq("Edzés")]
    events=int(_fpi_v202_event_key(train).nunique()) if not train.empty else 0
    completion=min(1.0,max(.35,.55*max(.35,(wd+1)/6)+.45*max(.35,events/5 if events else .35)))
    phase=_norm_mapping_text(st.session_state.get("fpi_season_phase_v205","Automatikus felismerés"))
    week_hint=_norm_mapping_text(st.session_state.get("clean_week_type_v137","") or st.session_state.get("app_week_type_v112",""))
    if "recovery" in week_hint or "regener" in week_hint or "alulterhelt" in week_hint:
        pf=.78; wt="recovery"
    elif "overload" in week_hint or "terhelesepito" in week_hint:
        pf=1.12; wt="overload"
    elif "felkesz" in phase:
        pf=1.05; wt="felkészülés"
    else:
        pf=1.0; wt="normál"
    return {"completion":completion,"phase_factor":pf,"label":f"csonka hét, {completion*100:.0f}% időarányos cél" if completion<.96 else "teljes hét","week_type":wt,"partial":completion<.96}


def _fpi_v407_readiness_component_details(
    df: pd.DataFrame,
    selected_week: str,
    playstyle: str,
    components: Dict[str, float],
) -> Dict[str, str]:
    """Minden readiness komponenshez saját, számszerű aktuális értelmezés."""
    details: Dict[str, str] = {}
    daily = build_microcycle_table(df, selected_week)
    weekly = build_weekly_fingerprints(df)
    row = weekly[weekly["week"].astype(str).eq(str(selected_week))].iloc[0] if not weekly.empty and weekly["week"].astype(str).eq(str(selected_week)).any() else pd.Series(dtype=object)

    att = _fpi_v201_week_attendance_summary(df, selected_week)
    sessions = int(att.get("team_training_sessions", 0) or 0)
    availability = att.get("mean_availability_pct", np.nan)
    if pd.notna(availability) and sessions:
        judgement = "stabil csapatszintű rendelkezésre állás" if availability >= 90 else "kisebb hiányzásokkal terhelt részvétel" if availability >= 75 else "a heti csapatterhelést érdemben torzító hiányzás"
        details["training_availability"] = f"{sessions} csapatedzés alapján az átlagos játékosrészvétel {availability:.0f}%; ez {judgement}."
    else:
        details["training_availability"] = "Nincs legalább két, részvétel alapján összevethető csapatedzés; a komponens előzetes értéken marad."

    load_change = row.get("training_load_change", np.nan)
    if pd.notna(load_change):
        direction = "nőtt" if load_change > 0 else "csökkent"
        magnitude = abs(float(load_change)) * 100
        if load_change > .25:
            meaning = "hirtelen terhelésnövekedés, ezért frissességi kockázat"
        elif load_change < -.30:
            meaning = "nagy visszaesés, ezért alulexpozíciós kockázat"
        else:
            meaning = "kontrollált heti változás"
        details["load_trend"] = f"A heti összterhelés az előző héthez képest {magnitude:.0f}%-kal {direction}; ez {meaning}."
    else:
        details["load_trend"] = "Nincs közvetlenül megelőző, összevethető hét; a terhelési trend pontszáma semleges előzetes érték."

    speed_assessment = _fpi_v408_speed_exposure_assessment(daily)
    speed_score = float(components.get("speed_exposure", speed_assessment.get("score", 55)) or 55)
    if speed_assessment.get("valid"):
        details["speed_exposure"] = (
            f"A legnagyobb, meccs előtti edzésnapi sprintdózis a meccs sprintreferenciájának "
            f"{float(speed_assessment.get('ratio')):.0%}-a volt, {speed_assessment.get('md')} napon. "
            f"{str(speed_assessment.get('reason')).capitalize()}. Operatív cél: {speed_assessment.get('target')}. "
            "Az MD+1 terhelés nem számít bele a következő mérkőzés előtti Speed Exposure értékelésébe."
        )
    else:
        details["speed_exposure"] = (
            f"{speed_assessment.get('reason')} Operatív cél: {speed_assessment.get('target')}. "
            "A meccs utáni MD+1 sprint nem minősíthető a következő meccs előtti erősségként."
        )

    taper_assessment = _fpi_v408_taper_assessment(daily)
    if taper_assessment.get("valid"):
        parts = "; ".join(taper_assessment.get("parts", []))
        details["tapering"] = (
            f"{parts}. A pontszámot az MD-1 és MD-2 külön célzónája alapján számoljuk; "
            "az egyik nap megfelelő értéke nem teszi automatikusan megfelelővé a másikat."
        )
    else:
        details["tapering"] = (
            "Nincs teljes MD-4/MD-3–MD-1 terhelési lánc; a tapering előzetes. "
            "Operatív cél: MD-1 a fő nap 30–45%-a, MD-2 55–70%-a."
        )

    current = df[df["week"].astype(str).eq(str(selected_week))].copy() if "week" in df.columns else pd.DataFrame()
    tr = current[current.get("session_type", pd.Series("", index=current.index)).astype(str).eq("Edzés")]
    ma = current[current.get("session_type", pd.Series("", index=current.index)).astype(str).eq("Meccs")]
    ratios = []
    for metric, label in [("distance_per_min", "intenzitás"), ("sprint_distance", "sprint"), ("high_efforts", "High Efforts")]:
        if metric in current.columns and not tr.empty and not ma.empty:
            m = pd.to_numeric(ma[metric], errors="coerce").mean(); t = pd.to_numeric(tr[metric], errors="coerce").mean()
            if pd.notna(m) and m > 0 and pd.notna(t):
                ratios.append(f"{label} {t/m:.0%} a meccshez képest")
    fit = float(components.get("playstyle_fit", 70) or 70)
    fit_meaning = "jól támogatja" if fit >= 75 else "részben támogatja" if fit >= 55 else "nem támogatja elég erősen"
    details["playstyle_fit"] = (", ".join(ratios) + f"; a heti fizikai profil {fit_meaning} a(z) {playstyle} játékmodellt.") if ratios else f"Nincs teljes edzés–meccs összevetés; a(z) {playstyle} játékmodell-illeszkedés előzetes."
    return details


def _fpi_v302_readiness_breakdown(
    score: int,
    components: Dict[str, float],
    reasons: List[str],
    component_details: Optional[Dict[str, str]] = None,
) -> pd.DataFrame:
    """Readiness komponensek: definíció + kizárólag a saját aktuális értelmezésük."""
    labels = {
        "training_availability": "Edzésrészvétel",
        "load_trend": "Terhelési trend",
        "speed_exposure": "Sebességi expozíció",
        "tapering": "Terheléscsökkentés / frissítés",
        "playstyle_fit": "Játékmodell-illeszkedés",
    }
    definitions = {
        "training_availability": "Azt mutatja, hogy a keret mekkora része és milyen rendszerességgel végezte el a csapat edzéseit; az alacsony részvétel torzíthatja a csapatszintű terhelési képet.",
        "load_trend": "A kiválasztott hét összterhelésének változása a saját közelmúlthoz képest; a túl gyors emelkedés frissességi, a nagy visszaesés alulexpozíciós kockázat.",
        "speed_exposure": "A HSR/sprint jellegű, nagy futósebességű inger dózisa és időzítése a saját meccs-sprintreferenciához képest. Nem azonos a robbanékony akciókkal: a High Efforts rövid gyorsításokat és lassításokat is tartalmazhat anélkül, hogy a játékos maximális sebességet érne el.",
        "tapering": "A meccs előtti MD-2 és MD-1 terheléscsökkentés minősége; azt vizsgálja, marad-e élesség új fáradtság létrehozása nélkül.",
        "playstyle_fit": "A heti fizikai profil mennyire szolgálja a kiválasztott játékmodell intenzitási, sprint- és nagy intenzitású akcióigényét.",
    }
    details = component_details or {}
    rows = []
    for key in ["training_availability", "load_trend", "speed_exposure", "tapering", "playstyle_fit"]:
        if key not in (components or {}):
            continue
        value = float(components.get(key, 0) or 0)
        value = max(0, min(100, value))
        status = "Erősség" if value >= 75 else "Stabil / elfogadható" if value >= 65 else "Figyelendő" if value >= 50 else "Lehúzó tényező"
        current = details.get(key, "Az aktuális adatból nem készült külön komponensmagyarázat.")
        rows.append({
            "Komponens": labels[key],
            "Pont": round(value),
            "Státusz": status,
            "Magyarázat": f"Mit jelent? {definitions[key]} Most: {current} A {round(value)}/100 pont ezt jelenti: {status.lower()}.",
        })
    return pd.DataFrame(rows)



def _fpi_v302_coach_actions(benchmark_df:pd.DataFrame)->pd.DataFrame:
    """V304: egyértelmű magyar terület + javaslat + indoklás; leállítási feltétel nélkül."""
    if benchmark_df is None or benchmark_df.empty:return pd.DataFrame()
    presets={
        "Össztáv":("Edzésvolumen", "15–25 perces kontrollált játékblokk", "A heti össztáv a célzóna alatt maradt."),
        "HSR":("Nagysebességű futás (HSR)", "2×4–6 nagysebességű futás, teljes visszapihenéssel", "A heti HSR-inger nem érte el a kívánt tartományt."),
        "Sprint táv":("Sprinttávolság", "4–8 minőségi sprint, 2–3 perces pihenőkkel", "A sprinttávolság elmaradt a célzónától."),
        "Sprint db":("Sprintismétlések", "4–6 technikailag tiszta, maximális közeli ismétlés", "Kevés minőségi sprintismétlés történt."),
        "High Efforts":("Robbanékony akciók", "2–3 rövid, meccsszerű intenzív blokk", "A gyorsításokból, lassításokból és intenzív akciókból álló terhelés alacsony."),
        "Load":("Összterhelés", "15–20 perc közepes–magas munkasűrűség", "A teljes külső terhelés a célzóna alatt maradt."),
        "HMLD":("HMLD-terhelés", "15–20 perc közepes–magas munkasűrűség", "A heti HMLD a célzóna alatt maradt.")
    }
    source=benchmark_df[benchmark_df["Szint"].astype(str).eq("Heti edzésösszeg")]
    out=[]
    for _,r in source.iterrows():
        actual=pd.to_numeric(pd.Series([r.get("Tényleges érték")]),errors="coerce").iloc[0]
        nums=re.findall(r"\d+(?:[.,]\d+)?",str(r.get("Benchmark érték","")))
        if pd.isna(actual) or len(nums)<2:continue
        lo,hi=float(nums[0].replace(",",".")),float(nums[1].replace(",","."))
        metric=str(r.get("Mutató",""));unit=str(r.get("Egység",""))
        if actual<lo:
            area,block,why=presets.get(metric,("Célzott terhelési terület","Rövid célzott blokk","A mutató a heti célzóna alatt maradt."))
            out.append({"Prioritás":"Magas" if actual<lo*.65 else "Közepes","Fejlesztendő terület":area,"Hiány / többlet":f"−{lo-actual:.0f} {unit}","Javasolt beavatkozás":block,"Miért?":why})
        elif actual>hi:
            area=presets.get(metric,(metric,"",""))[0]
            out.append({"Prioritás":"Közepes","Fejlesztendő terület":area,"Hiány / többlet":f"+{actual-hi:.0f} {unit}","Javasolt beavatkozás":"Csökkentett volumen, megtartott végrehajtási intenzitás.","Miért?":"A heti érték a célzóna felső határa fölé került; további volumen helyett frissítés indokolt."})
    return pd.DataFrame(out).head(5)

def _fpi_v411_single_session_actions(benchmark_df: pd.DataFrame) -> pd.DataFrame:
    """Egyetlen edzéshez sessioncélzóna-alapú olvasat; nem számol heti hiányt."""
    if benchmark_df is None or benchmark_df.empty:
        return pd.DataFrame()
    source = benchmark_df[benchmark_df["Szint"].astype(str).eq("Egy edzés mediánja")].copy()
    rows = []
    for _, r in source.iterrows():
        metric = str(r.get("Mutató", ""))
        actual = pd.to_numeric(pd.Series([r.get("Tényleges érték")]), errors="coerce").iloc[0]
        nums = re.findall(r"\d+(?:[.,]\d+)?", str(r.get("Benchmark érték", "")))
        if pd.isna(actual) or len(nums) < 2:
            continue
        lo, hi = float(nums[0].replace(",", ".")), float(nums[1].replace(",", "."))
        unit = str(r.get("Egység", ""))
        if actual < lo:
            state = "Alacsony sessiondózis"
            suggestion = "Az edzés jellegével együtt értékeld; önmagában nem jelent heti alulterhelést. Ha ez volt a hét fő ingere, a következő megfelelő napon célzott kiegészítés mérlegelhető."
            why = f"Az adott edzés {metric.lower()} értéke az egyedzéses célzóna alatt volt, de a rendszer ebből nem számol heti hiányt."
        elif actual > hi:
            state = "Magas sessiondózis"
            suggestion = "A következő nap terhelését és a játékosok egyéni reakcióját kontrolláld; újabb azonos inger csak indokolt esetben kerüljön be."
            why = f"Az adott edzés {metric.lower()} értéke az egyedzéses célzóna fölé került."
        else:
            state = "Sessioncélzónában"
            suggestion = "Az inger az adott session szintjén megfelelő; a heti következtetéshez további napok adata szükséges."
            why = f"Az adott edzés {metric.lower()} értéke az egyedzéses célzónában volt."
        rows.append({
            "Prioritás": "Közepes" if state != "Sessioncélzónában" else "Információ",
            "Fejlesztendő terület": metric,
            "Hiány / többlet": state,
            "Javasolt beavatkozás": suggestion,
            "Miért?": why + f" Tényleges érték: {actual:.0f} {unit}; sessioncél: {lo:.0f}-{hi:.0f} {unit}."
        })
    return pd.DataFrame(rows).head(5)


def _fpi_v300_training_match_ratios(
    analysis_df: pd.DataFrame,
    master_df: pd.DataFrame,
) -> pd.DataFrame:
    """V301: olvasható benchmark heti és edzésenkénti sorokkal.

    Minden sor tartalmazza:
    - tényleges érték,
    - meccsreferencia,
    - tényleges százalék,
    - cél százalékos sáv,
    - cél értéksáv,
    - rövid értékelés.
    """
    ref = _fpi_v300_match_reference(master_df)
    if not ref.get("available"):
        return pd.DataFrame()
    training = analysis_df[analysis_df["session_type"].eq("Edzés")].copy()
    if training.empty:
        return pd.DataFrame()
    training["_v300_event"] = _fpi_v202_event_key(training)
    selected_week = str(training.get("week", pd.Series("", index=training.index)).dropna().astype(str).iloc[0]) if len(training) else ""
    rows=[]
    for label,col,unit in [
        ("Össztáv","total_distance","m"),
        ("HSR","hsr_distance","m"),
        ("Sprint táv","sprint_distance","m"),
        ("Sprint db","sprints","db"),
        ("High Efforts","high_efforts","db/pont"),
        (_fpi_v417_load_label(analysis_df),"training_load",_fpi_v417_load_unit(analysis_df)),
    ]:
        if col not in training.columns: continue
        training[col]=pd.to_numeric(training[col],errors="coerce")
        player_week=training.groupby("player_name")[col].sum(min_count=1)
        event_player=training.groupby(["_v300_event","player_name"])[col].sum(min_count=1)
        event_medians=event_player.groupby(level=0).median() if not event_player.empty else pd.Series(dtype=float)
        weekly=float(player_week.median()) if player_week.notna().any() else None
        per_training=float(event_medians.median()) if not event_medians.empty else None
        match_value=ref["metrics"].get(col)
        if match_value in {None,0} or pd.isna(match_value): continue
        _,_,wlo,whi,alo,ahi,profile = _fpi_composition_reference_ranges_v116(master_df, selected_week, col)
        context_v302=_fpi_v302_week_context_factor(analysis_df,selected_week)
        scope_meta_v411 = _fpi_v411_scope_meta_for_week(selected_week) if "_fpi_v411_scope_meta_for_week" in globals() else {}
        if scope_meta_v411.get("scope_type") == "single_session":
            context_v302 = {"completion":1.0,"phase_factor":1.0,"label":"egyetlen esemény; csak sessioncélzóna","week_type":"session","partial":True}
        wlo=wlo*context_v302["completion"]*context_v302["phase_factor"]; whi=whi*context_v302["completion"]*context_v302["phase_factor"]
        alo=alo*context_v302["phase_factor"]; ahi=ahi*context_v302["phase_factor"]
        profile=f"{profile} | {context_v302['week_type']} | {context_v302['label']}"
        for scope,actual,lo,hi in [("Heti edzésösszeg",weekly,wlo,whi),("Egy edzés mediánja",per_training,alo,ahi)]:
            pct=(actual/match_value*100) if actual is not None and not pd.isna(actual) else None
            target_low=match_value*lo/100
            target_high=match_value*hi/100
            if pct is None: rating="Nincs adat"
            elif pct<lo: rating="Célzóna alatt"
            elif pct>hi: rating="Célzóna felett"
            else: rating="Célzónában"
            rows.append({
                "Mutató":label,"Szint":scope,"Tényleges érték":actual,"Egység":unit,
                "Meccsreferencia":match_value,"Tényleges %":pct,
                "Benchmark %":f"{int(lo)}–{int(hi)}%",
                "Benchmark érték":f"{target_low:.0f}–{target_high:.0f} {unit}",
                "Értékelés":rating,"Referencia profil":profile,
            })
    return pd.DataFrame(rows)


def _fpi_v300_microcycle_plan(master: pd.DataFrame, analysis: pd.DataFrame) -> pd.DataFrame:
    match_dates = pd.to_datetime(
        master.loc[master["session_type"].eq("Meccs"), "start_time"],
        errors="coerce",
    ).dropna().sort_values()
    analysis_max = pd.to_datetime(analysis.get("start_time"), errors="coerce").max()

    # V303: a kézzel megadott következő meccsnap az elsődleges.
    manual = st.session_state.get("fpi_manual_match_date_v300")
    manual_day = pd.to_datetime(manual, errors="coerce") if manual else pd.NaT
    match_day = manual_day.normalize() if pd.notna(manual_day) else pd.NaT

    # Automatikusan csak valóban jövőbeli, feltöltött meccset használunk.
    if pd.isna(match_day) and pd.notna(analysis_max) and not match_dates.empty:
        future = match_dates[match_dates.dt.normalize() > analysis_max.normalize()]
        if not future.empty:
            match_day = future.iloc[0].normalize()

    if pd.isna(match_day):
        return pd.DataFrame()
    if pd.notna(analysis_max) and match_day <= analysis_max.normalize():
        return pd.DataFrame()

    plan = {
        4: ("Fő terhelési nap", "Volumen + HSR + kontrollált sprint", "A hét legnagyobb ingerét itt add."),
        3: ("Specifikus intenzitás", "Rövid meccsszerű blokkok", "Magas minőség, mérsékelt volumen."),
        2: ("Terheléscsökkentés", "Rövid gyorsasági érintés", "Ne halmozz új fáradtságot."),
        1: ("Aktiváció", "Reakció, mobilitás, döntési sebesség", "A frissesség az elsődleges."),
    }
    rows = []
    for md in [4, 3, 2, 1]:
        focus, tactical, note = plan[md]
        day = match_day - pd.Timedelta(days=md)
        rows.append({
            "Dátum": day.strftime("%Y-%m-%d"),
            "Nap": f"MD-{md}",
            "Erőnléti fókusz": focus,
            "Taktikai fókusz": tactical,
            "Edzői megjegyzés": note,
        })
    return pd.DataFrame(rows)


def _fpi_report_context(data: pd.DataFrame, selected_week: Optional[str] = None, playstyle: str = "Kiegyensúlyozott", tactical_context: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    """Riportok közös számítási magja; GPS-only és GPS+taktikai ugyanazt használja."""
    df, master_report_v300 = _fpi_v300_master_dataset(data)
    df = _fpi_v407_apply_filename_md_inference(df)
    week = _fpi_latest_week(df, selected_week)
    if df.empty or not week:
        return {"df": df, "selected_week": week, "error": "Nincs riportképes adat."}
    try:
        base = team_insights(df, week)
        micro = microcycle_insights(df, week)
        style = playstyle_insights(df, week, playstyle)
        pattern = build_pattern_insights(df, week)
        readiness_score, readiness_components, readiness_reasons = calculate_readiness_score(df, week, playstyle)
        component_details = _fpi_v407_readiness_component_details(df, week, playstyle, readiness_components)
        breakdown = _fpi_v302_readiness_breakdown(readiness_score, readiness_components, readiness_reasons, component_details)
        fingerprints = build_weekly_fingerprints(df)
        current_fp = fingerprints[fingerprints["week"].astype(str).eq(str(week))] if not fingerprints.empty and "week" in fingerprints.columns else pd.DataFrame()
        periodization_type = current_fp["periodizacios_tipus"].iloc[0] if not current_fp.empty and "periodizacios_tipus" in current_fp.columns else "Nincs elég adat"
        insights = sorted(base + micro + style + pattern, key=lambda x: SEVERITY_RANK.get(x.severity, 9))[:18]
        summary = build_weekly_summary(insights, week, playstyle)
        insights = humanize_insights(insights)
        priorities = humanize_priority_list(build_adaptive_recommendations(insights, readiness_score, periodization_type, pattern, playstyle))
        summary = coach_friendly_phrase(summary)
        risk = _fpi_v303_adjust_partial_week_risk(calculate_player_risk(df, week), df, week)
        past_df, past_text = build_past_week_review(df, week, playstyle)
        current_df, current_text = build_current_remaining_days_plan(df, week, playstyle, readiness_score, periodization_type, risk)
        next_df, next_text = build_next_week_plan_v5(df, week, playstyle, readiness_score, periodization_type, risk, past_df, current_df)
        player_actions = build_player_next_actions(risk, df, week)
        weekly = aggregate_weekly(df) if "week" in df.columns else pd.DataFrame()
        player_week = player_weekly(df) if "week" in df.columns else pd.DataFrame()
        return {
            "df": df, "selected_week": week, "playstyle": playstyle,
            "readiness_score": readiness_score, "readiness_components": readiness_components,
            "readiness_reasons": readiness_reasons, "readiness_component_details": component_details,
            "readiness_breakdown_v302": breakdown, "periodization_type": periodization_type,
            "insights": insights, "insights_df": build_insight_export_df(insights), "priorities": priorities,
            "summary": summary + f"\n\nMeccskészültség: {readiness_score}/100 ({score_to_label(readiness_score)})\nPeriodizációs besorolás: {periodization_type}",
            "risk_df": risk, "past_df": past_df, "past_text": past_text,
            "current_df": current_df, "current_text": current_text, "next_df": next_df, "next_text": next_text,
            "player_actions_df": player_actions, "weekly": weekly, "player_week": player_week,
            "fingerprints": fingerprints, "master_report_v300": master_report_v300,
            "match_reference_v300": _fpi_v300_match_reference(df),
            "training_match_ratios_v300": _fpi_v300_training_match_ratios(df[df["week"].astype(str).eq(str(week))].copy(), df),
            "microcycle_plan_v300": next_df,
        }
    except Exception as exc:
        return {"df": df, "selected_week": week, "error": str(exc)}




def _fpi_pdf_tactical_source_status_v80(tactical_context: Optional[Dict[str, object]]) -> str:
    if not tactical_context:
        return "Nincs taktikai input – GPS-only riport."
    own_pdf = bool(tactical_context.get("has_own_pdf"))
    opp_pdf = bool(tactical_context.get("has_opp_pdf"))
    own_topics = tactical_context.get("own_topics", []) or []
    opp_topics = tactical_context.get("opp_topics", []) or []
    excel_ok = bool(tactical_context.get("has_own_team_excel") or tactical_context.get("has_opp_team_excel") or tactical_context.get("has_own_player_excel") or tactical_context.get("has_opp_player_excel"))
    if (own_topics or opp_topics) and excel_ok:
        return "PDF + Excel együtt – a következtetésekben mindkettő szerepel."
    if own_topics or opp_topics:
        return "PDF-alapú taktikai jelzések – Excel nélkül vagy korlátozott Excel-adattal."
    if (own_pdf or opp_pdf) and excel_ok:
        return "PDF feltöltve, de nem adott erős tématalálatot; a taktikai következtetések főleg az Excelből készültek."
    if excel_ok:
        return "Taktikai Excel-alapú következtetések."
    if own_pdf or opp_pdf:
        return "PDF feltöltve, de nincs kinyert / felismert taktikai téma."
    return "Nincs használható taktikai input."

def _fpi_pdf_short_tactical_topics_v80(tactical_context: Optional[Dict[str, object]], limit: int = 3) -> str:
    if not tactical_context:
        return "n.a."
    rows = []
    for side, key in [("Saját", "own_topics"), ("Ellenfél", "opp_topics")]:
        for r in (tactical_context.get(key, []) or [])[:limit]:
            tema = str(r.get("Téma", "")).strip()
            if tema:
                rows.append(f"{side}: {tema}")
    return "; ".join(rows[:limit]) if rows else "Nincs erős PDF-tématalálat."

def _fpi_pdf_primary_tactical_finding_v80(tactical_context: Optional[Dict[str, object]]) -> str:
    if not tactical_context:
        return "Nincs taktikai input."
    findings = tactical_context.get("tactical_findings", []) or []
    if findings:
        f = findings[0]
        return f"{f.get('Téma', '')}: {f.get('Edzői következtetés', '')}"
    risks = tactical_context.get("risks", []) or []
    if risks:
        return str(risks[0])
    return _fpi_pdf_tactical_source_status_v80(tactical_context)

def _fpi_pdf_next_integrated_decision_v80(tactical_context: Optional[Dict[str, object]], fallback: str) -> str:
    if tactical_context and tactical_context.get("md_plan"):
        try:
            md = tactical_context.get("md_plan")[0]
            return f"Következő mikrociklus-lépés: {md[0]} – {md[1]}. Indoklás: {md[2]}"
        except Exception:
            pass
    if tactical_context and tactical_context.get("plan_a"):
        return f"Meccsterv irány: {tactical_context.get('plan_a')}. Következő edzésen ehhez igazított erőnléti + taktikai cél."
    return fallback



def _fpi_compact_text_v81(x: object, max_len: int = 260) -> str:
    s = re.sub(r"\s+", " ", str(x or "")).strip()
    return s if len(s) <= max_len else s[:max_len-1].rstrip() + "…"

def _fpi_pdf_scope_line_v81(tactical_context: Optional[Dict[str, object]]) -> str:
    if not tactical_context:
        return "PDF: nincs feltöltött taktikai PDF."
    own_chars = int(tactical_context.get("own_pdf_chars", 0) or 0)
    opp_chars = int(tactical_context.get("opp_pdf_chars", 0) or 0)
    own_pages = int(tactical_context.get("own_pdf_pages", 0) or 0)
    opp_pages = int(tactical_context.get("opp_pdf_pages", 0) or 0)
    topics = len(tactical_context.get("own_topics", []) or []) + len(tactical_context.get("opp_topics", []) or [])
    if own_chars + opp_chars > 0:
        return f"PDF: {own_pages}+{opp_pages} oldalból {own_chars + opp_chars} karakter feldolgozva; felismert témák: {topics}. A riport a legerősebb PDF-témákat használja, a többi következtetés Excelből jön."
    if tactical_context.get("has_own_pdf") or tactical_context.get("has_opp_pdf"):
        return f"PDF: feltöltve ({own_pages}+{opp_pages} oldal), de nincs kinyert szöveg vagy erős tématalálat; taktikai döntés főleg Excelből."
    return "PDF: nincs használható PDF-jelzés; taktikai döntés Excelből."



def _fpi_clean_sentence_v82(x: object, max_len: int = 160) -> str:
    """Teljes gondolatot ad vissza; mondatot soha nem vág félbe három ponttal."""
    s = re.sub(r"\s+", " ", str(x or "")).strip()
    s = s.replace("->", "→").replace("=>", "→")
    if not s or len(s) <= max_len:
        return s

    sentences = re.split(r"(?<=[.!?])\s+", s)
    selected = []
    total = 0
    for sentence in sentences:
        sentence = sentence.strip()
        if not sentence:
            continue
        projected = total + len(sentence) + (1 if selected else 0)
        if selected and projected > max_len:
            break
        selected.append(sentence)
        total = projected
        if total >= max_len:
            break

    # Ha már az első mondat is hosszabb, inkább teljesen meghagyjuk.
    return " ".join(selected).strip() if selected else s

def _fpi_readiness_short_v82(score: int) -> str:
    try:
        score = int(score)
    except Exception:
        score = 70
    if score >= 80:
        return "jó állapot, vállalható intenzitás"
    if score >= 65:
        return "vállalható, de frissességre figyelni kell"
    if score >= 50:
        return "figyelendő, terheléskontroll szükséges"
    return "magas kockázat, óvatos mikrociklus"



def _fpi_norm_risk_level_v126(x: object) -> str:
    s = unicodedata.normalize("NFKD", str(x or "").strip().lower())
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    if "magas" in s or "high" in s:
        return "Magas"
    if "kozep" in s or "medium" in s:
        return "Közepes"
    if "alacsony" in s or "low" in s:
        return "Alacsony"
    return str(x or "").strip() or "Alacsony"


def _fpi_count_risk_levels_v126(risk_df: pd.DataFrame) -> Tuple[int, int]:
    """Játékosszintű risk darabszám.

    V12.7 javítás: nem sorokat számolunk, hanem egyedi játékosokat.
    Ha egy játékos több sorban szerepel, a legmagasabb kockázati szintje számít.
    Így nem fordulhat elő, hogy a PDF 5 közepes risket ír, miközben valójában
    csak 1 játékos közepes kockázatú.
    """
    if risk_df is None or risk_df.empty or "Kockázati szint" not in risk_df.columns:
        return 0, 0

    tmp = risk_df.copy()
    tmp["_risk_norm"] = tmp["Kockázati szint"].apply(_fpi_norm_risk_level_v126)
    tmp["_risk_rank"] = tmp["_risk_norm"].map({"Magas": 3, "Közepes": 2, "Alacsony": 1}).fillna(1).astype(int)

    # Lehetséges játékosnév-oszlopok több exportverzióból.
    player_col = None
    for c in ["Játékos", "Játékos neve", "player_name", "Player", "Név", "Nev", "Name"]:
        if c in tmp.columns:
            player_col = c
            break

    if player_col:
        tmp["_player_key"] = tmp[player_col].astype(str).str.strip().replace({"": np.nan, "nan": np.nan, "None": np.nan})
        known = tmp[tmp["_player_key"].notna()].copy()
        unknown = tmp[tmp["_player_key"].isna()].copy()
        if not known.empty:
            idx = known.groupby("_player_key")["_risk_rank"].idxmax()
            tmp = pd.concat([known.loc[idx], unknown], ignore_index=True)

    high = int((tmp["_risk_norm"] == "Magas").sum())
    med = int((tmp["_risk_norm"] == "Közepes").sum())
    return high, med


def _fpi_pdf_week_type_label_v126(ctx: Dict[str, object], demo_label: str = "") -> str:
    raw = str(ctx.get("periodization_type", "") or "").strip()
    raw = _fpi_normalize_coach_week_label_v121(raw) if "_fpi_normalize_coach_week_label_v121" in globals() else raw
    bad = {"", "n.a.", "na", "none", "nincs elég adat", "nincs eleg adat", "nan"}
    if raw.lower() in bad:
        return "Mérkőzésre felkészítő mikrociklus" if demo_label else "Stabilizáló mikrociklus"
    return raw


def _fpi_week_type_interpretation_v126(label: str) -> str:
    l = str(label or "").lower()
    if "regener" in l:
        return "A hét elsődleges célja a frissesség visszaépítése és a terhelési kockázat csökkentése."
    if "stabil" in l:
        return "A hét célja a terhelési szint megtartása, kontrollált sebességi és intenzitási ingerekkel."
    if "terhelésfokoz" in l or "terhelesfokoz" in l:
        return "A hét célja a fokozatos terhelésépítés, külön kontrollal a sprint és HSR ingerekre."
    if "fejleszt" in l:
        return "A hét célja célzott fizikai fejlesztés, de a readiness és játékoskockázat folyamatos kontrollja mellett."
    if "formaid" in l:
        return "A hét célja a meccs előtti frissítés: alacsonyabb volumen, rövid és minőségi intenzív ingerek."
    if "mérkőzés" in l or "merkozes" in l:
        return "A hét célja a mérkőzésre optimalizált mikrociklus: terhelésépítés, sebességi inger, majd frissítés."
    return "A hét típusa a terhelési trend, readiness és játékosszintű kockázatok alapján értelmezendő."


def _fpi_short_counts_sentence_v126(high_risk: int, med_risk: int) -> str:
    if high_risk or med_risk:
        return f"Játékoskockázat: {high_risk} magas, {med_risk} közepes."
    return "Játékoskockázat: nincs kiemelt magas vagy közepes jelzés."

def _fpi_top_tactical_messages_v82(tactical_context: Optional[Dict[str, object]], limit: int = 3, gps_context: Optional[Dict[str, object]] = None, readiness: Optional[int] = None, priorities: Optional[List[dict]] = None, week: Optional[str] = None) -> List[str]:
    if not _fpi_has_tactical_signal_v95(tactical_context):
        if gps_context is not None:
            return _fpi_gps_only_conclusions_v95(gps_context, priorities or [], int(readiness or 70), str(week or gps_context.get("selected_week", "")), limit=max(limit, 5))
        return ["GPS-only mód: nincs taktikai input, ezért a javaslat az erőnléti/GPS adatokra épül."]
    out = []
    findings = tactical_context.get("tactical_findings") or []
    pdf_first = [f for f in findings if str(f.get("Téma", "")).lower().startswith("pdf") or "PDF" in str(f.get("Forrás", ""))]
    other = [f for f in findings if f not in pdf_first]
    for f in (pdf_first + other)[:limit]:
        theme = str(f.get("Téma", "")).strip()
        decision = str(f.get("Edzői következtetés", "")).strip()
        if theme and decision:
            out.append(f"{theme}: {decision}")
    if not out:
        risks = tactical_context.get("risks", []) or []
        out = [str(x) for x in risks[:limit]]
    if not out:
        topics = []
        for key in ["opp_topics", "own_topics"]:
            for row in tactical_context.get(key, []) or []:
                if row.get("Téma"):
                    topics.append(str(row.get("Téma")))
        if topics:
            out.append("PDF témák: " + ", ".join(topics[:3]))
    return [_fpi_clean_sentence_v82(x, 180) for x in out[:limit]] or ["Nincs erős taktikai jelzés."]

def _fpi_top_fitness_messages_v82(ctx: Dict[str, object], priorities: List[dict], readiness: int, limit: int = 3) -> List[str]:
    out = []
    summary = str(ctx.get("summary", "") or "")
    # prefer short existing messages from summary
    for line in summary.splitlines():
        line = line.strip("- ").strip()
        if any(k in line.lower() for k in ["legfontosabb", "md-1", "stabil", "readiness", "terhelés"]):
            out.append(line)
    for p in priorities or []:
        t = p.get("Teendő", p.get("Cím", ""))
        if t:
            out.append(t)
    if not out:
        out.append(f"Readiness {readiness}/100 – {_fpi_readiness_short_v82(readiness)}.")
    return [_fpi_clean_sentence_v82(x, 170) for x in list(dict.fromkeys(out))[:limit]]

def _fpi_compact_player_risk_rows_v82(risk_df: pd.DataFrame, max_rows: int = 12) -> List[List[str]]:
    rows = [["Játékos", "Szint", "Miért fontos?"]]
    if risk_df is None or risk_df.empty:
        rows.append(["Nincs kiemelt", "Alacsony", "Nincs azonnali beavatkozási jelzés."])
        return rows
    df = risk_df.copy()
    level_col = "Kockázati szint" if "Kockázati szint" in df.columns else None
    reason_col = "Fő okok" if "Fő okok" in df.columns else "Fő ok" if "Fő ok" in df.columns else None
    player_col = "Játékos" if "Játékos" in df.columns else "player_name" if "player_name" in df.columns else df.columns[0]
    if level_col:
        df["_risk_norm_v126"] = df[level_col].apply(_fpi_norm_risk_level_v126)
        focus = df[df["_risk_norm_v126"].isin(["Magas", "Közepes"])]
        if not focus.empty:
            order = {"Magas": 0, "Közepes": 1, "Alacsony": 2}
            focus = focus.assign(_risk_order=focus["_risk_norm_v126"].map(order).fillna(9))
            df = focus.sort_values(["_risk_order"])
    for _, r in df.head(max_rows).iterrows():
        level = _fpi_norm_risk_level_v126(r.get(level_col, "Alacsony") if level_col else "Figyelendő")
        rows.append([
            _fpi_clean_sentence_v82(r.get(player_col, ""), 42),
            _fpi_clean_sentence_v82(level, 30),
            _fpi_clean_sentence_v82(r.get(reason_col, "Monitoring.") if reason_col else "Monitoring.", 105),
        ])
    return rows


def _fpi_md_plan_rows_v82(tactical_context: Optional[Dict[str, object]], gps_context: Optional[Dict[str, object]] = None, readiness: Optional[int] = None, priorities: Optional[List[dict]] = None, week: Optional[str] = None) -> List[Tuple[str, str, str]]:
    # output: nap, erőnléti cél, taktikai/GPS cél
    if not _fpi_has_tactical_signal_v95(tactical_context) and gps_context is not None:
        return _fpi_gps_only_md_plan_v95(gps_context, int(readiness or 70), priorities or [], str(week or gps_context.get("selected_week", "")))
    if tactical_context:
        md = tactical_context.get("md_plan", []) or []
        out = []
        for item in md:
            try:
                day, tactical_focus, why = item
            except Exception:
                continue
            fgoal = "Terheléskontroll"
            tgoal = str(tactical_focus)
            low = (str(tactical_focus) + " " + str(why)).lower()
            if "regener" in low:
                fgoal = "Regeneráció, frissítés"
            elif "hsr" in low or "sprint" in low or "átmenet" in low:
                fgoal = "HSR/sprint inger kontrolláltan"
            elif "aktiv" in low:
                fgoal = "Aktiváció, frissesség"
            elif "volumen" in low:
                fgoal = "Fő terhelési nap"
            elif "terheléskontroll" in low:
                fgoal = "Terhelés csökkentése"
            out.append((str(day), fgoal, _fpi_clean_sentence_v82(tgoal, 95)))
        # vezetői oldalon MD-4-től MD-1-ig a lényeg
        filtered = [x for x in out if any(k in x[0] for k in ["MD-4", "MD-3", "MD-2", "MD-1"])]
        return filtered[:4] if filtered else out[:4]
    return [
        ("MD-4", "Fő terhelési nap", "Saját játékmodell"),
        ("MD-3", "HSR/sprint inger", "Átmenetek"),
        ("MD-2", "Terhelés csökkentése", "Meccsterv"),
        ("MD-1", "Aktiváció", "Pontrúgás + frissítés"),
    ]

def _fpi_plan_why_v82(tactical_context: Optional[Dict[str, object]], readiness: int, gps_context: Optional[Dict[str, object]] = None, priorities: Optional[List[dict]] = None, week: Optional[str] = None) -> str:
    if not _fpi_has_tactical_signal_v95(tactical_context):
        if gps_context is not None:
            msgs = _fpi_gps_only_conclusions_v95(gps_context, priorities or [], readiness, str(week or gps_context.get("selected_week", "")), limit=2)
            return _fpi_clean_sentence_v82("; ".join(msgs), 260)
        return f"GPS alapján: readiness {readiness}/100, taktikai input nélkül."
    msgs = _fpi_top_tactical_messages_v82(tactical_context, 2)
    return _fpi_clean_sentence_v82("; ".join(msgs), 260)




def _fpi_uploaded_files_to_bytes_v88(files: List[object]) -> List[dict]:
    """Stabil UploadFile -> bytes mentés.
    Streamlit download/re-run közben a file_uploader objektum nem mindig olvasható újra megbízhatóan,
    ezért azonnal byte-listát mentünk session_state-be.
    """
    out = []
    for f in files or []:
        try:
            b = f.getvalue()
        except Exception:
            try:
                b = f.read()
            except Exception:
                b = b""
        if b:
            out.append({
                "name": getattr(f, "name", "uploaded.pdf"),
                "size": len(b),
                "md5": hashlib.md5(b).hexdigest(),
                "bytes": b,
            })
    return out

def _fpi_restore_uploaded_file_wrappers_v88(items: List[dict]) -> List[object]:
    class _FPIBytesPDF:
        def __init__(self, name, data):
            self.name = name
            self._data = data
        def getvalue(self):
            return self._data
        def read(self):
            return self._data
    return [_FPIBytesPDF(x.get("name", "uploaded.pdf"), x.get("bytes", b"")) for x in (items or []) if x.get("bytes")]

def _fpi_tactical_app_extract_pdf_pages_v88(file_bytes: bytes, max_pages: int = 80) -> List[dict]:
    """Régi Tactical app út + PyMuPDF fallback.
    Elsődleges: pdfplumber.open(io.BytesIO(bytes)).
    Fallback: PyMuPDF, ha pdfplumber nincs vagy hibázik.
    """
    out = []
    if not file_bytes:
        return out

    # 1) pdfplumber / pdfminer út
    try:
        if pdfplumber is not None:
            with pdfplumber.open(io.BytesIO(file_bytes)) as pdf:
                total_pages = min(len(pdf.pages), max_pages)
                for p in range(total_pages):
                    txt = pdf.pages[p].extract_text(x_tolerance=1, y_tolerance=3) or ""
                    if txt.strip():
                        out.append({
                            "page_index": p,
                            "page_number": p + 1,
                            "reader": "legacy_tactical_pdfplumber_v90",
                            "chars": len(txt),
                            "has_text": True,
                            "text": txt,
                        })
        if out:
            return out
    except Exception as e:
        out.append({
            "page_index": None,
            "page_number": None,
            "reader": "legacy_tactical_pdfplumber_v90",
            "chars": 0,
            "has_text": False,
            "error": str(e),
            "text": "",
        })

    # 2) PyMuPDF fallback
    try:
        if PYMUPDF_AVAILABLE and fitz is not None:
            doc = fitz.open(stream=file_bytes, filetype="pdf")
            for p in range(min(len(doc), max_pages)):
                txt = doc[p].get_text("text") or ""
                if txt.strip():
                    out.append({
                        "page_index": p,
                        "page_number": p + 1,
                        "reader": "pymupdf_fallback_v90",
                        "chars": len(txt),
                        "has_text": True,
                        "text": txt,
                    })
            doc.close()
            if out:
                return out
    except Exception as e:
        out.append({
            "page_index": None,
            "page_number": None,
            "reader": "pymupdf_fallback_v90",
            "chars": 0,
            "has_text": False,
            "error": str(e),
            "text": "",
        })

    return out


def _fpi_tactical_app_combine_pdf_texts_v88(items: List[dict]) -> Tuple[str, List[dict]]:
    page_blocks = []
    texts = []
    for item in items or []:
        b = item.get("bytes", b"") if isinstance(item, dict) else b""
        name = item.get("name", "uploaded.pdf") if isinstance(item, dict) else "uploaded.pdf"
        pages = _fpi_tactical_app_extract_pdf_pages_v88(b)
        for p in pages:
            p["file"] = name
        page_blocks.extend(pages)
        texts.extend([x["text"] for x in pages if x.get("text", "").strip()])
    return "\n\n".join(texts), page_blocks




def _fpi_tactical_app_combine_uploadfiles_v89(files: List[object]) -> Tuple[str, List[dict], List[dict]]:
    """Aktuális file_uploader objektumból azonnal olvas. Ez a régi Tactical app útja."""
    items = _fpi_uploaded_files_to_bytes_v88(files or [])
    text, pages = _fpi_tactical_app_combine_pdf_texts_v88(items)
    return text, pages, items

def _fpi_store_current_pdf_text_v89(side: str, text: str, pages: List[dict], items: List[dict]) -> None:
    st.session_state[f"tactical_pro_{side}_pdf_text_store_v89"] = {
        "text": text or "",
        "pages": pages or [],
        "items": items or [],
        "chars": len(text or ""),
        "page_count": len([p for p in (pages or []) if p.get("has_text") or p.get("text")]),
        "files": [x.get("name", "") for x in (items or [])],
        "signature": "|".join([f"{x.get('name')}:{x.get('size')}:{x.get('md5')}" for x in (items or [])]),
        "reader": "direct_upload_legacy_tactical_reader_v89",
    }

def _fpi_get_pdf_text_store_v89(side: str) -> Dict[str, object]:
    return st.session_state.get(f"tactical_pro_{side}_pdf_text_store_v89") or {}

def _fpi_clear_pdf_side_state_v91(side: str) -> None:
    """Ha a file_uploader üres, ne maradjon bent régi PDF-context.
    Ez javítja azt, hogy a riport 'PDF feltöltve'-t írt, miközben a widgetben len=0.
    """
    for key in [
        f"tactical_pro_{side}_pdf_text_store_v89",
        f"tactical_pro_{side}_pdf_bytes_v88",
    ]:
        st.session_state.pop(key, None)

def _fpi_has_current_pdf_upload_v91(files: List[object]) -> bool:
    return bool(files) and len(files or []) > 0

def _fpi_pdf_upload_state_key_v92(side: str) -> str:
    return f"tactical_pro_{side}_pdf_upload_manager_v92"

def _fpi_set_pdf_upload_state_v92(side: str, files: List[object]) -> Dict[str, object]:
    """Stabil PDF upload manager.
    A file_uploader visszatérési értékét AZONNAL bytes + text formában tárolja.
    Innentől a Tactical Pro+ és az export ugyanebből dolgozik.
    """
    state = {
        "has_files": False,
        "files": [],
        "items": [],
        "text": "",
        "pages": [],
        "chars": 0,
        "page_count": 0,
        "reader": "not_run",
        "error": "",
    }
    if not files:
        st.session_state[_fpi_pdf_upload_state_key_v92(side)] = state
        _fpi_clear_pdf_side_state_v91(side)
        return state

    items = _fpi_uploaded_files_to_bytes_v88(files or [])
    state["has_files"] = bool(items)
    state["items"] = items
    state["files"] = [x.get("name", "") for x in items]

    if items:
        try:
            txt, pages = _fpi_tactical_app_combine_pdf_texts_v88(items)
            state["text"] = txt or ""
            state["pages"] = pages or []
            state["chars"] = len(txt or "")
            state["page_count"] = len([p for p in (pages or []) if p.get("has_text") or p.get("text")])
            state["reader"] = "legacy_tactical_reader_v92"
        except Exception as e:
            state["error"] = f"legacy reader error: {e}"

        if not state["text"]:
            try:
                wrappers = _fpi_restore_uploaded_file_wrappers_v88(items)
                txt2, pages2 = _fpi_tactical_extract_pdf_text(wrappers)
                state["text"] = txt2 or ""
                state["pages"] = pages2 or []
                state["chars"] = len(txt2 or "")
                state["page_count"] = len([p for p in (pages2 or []) if p.get("has_text") or p.get("text")])
                state["reader"] = "multi_reader_fallback_v92"
            except Exception as e:
                state["error"] = (state.get("error", "") + f" | fallback error: {e}").strip(" |")

    st.session_state[_fpi_pdf_upload_state_key_v92(side)] = state

    # Kompatibilitás a korábbi v88/v89 kulcsokkal
    st.session_state[f"tactical_pro_{side}_pdf_bytes_v88"] = items
    _fpi_store_current_pdf_text_v89(side, state["text"], state["pages"], items)
    return state

def _fpi_get_pdf_upload_state_v92(side: str) -> Dict[str, object]:
    return st.session_state.get(_fpi_pdf_upload_state_key_v92(side)) or {
        "has_files": False, "files": [], "items": [], "text": "", "pages": [],
        "chars": 0, "page_count": 0, "reader": "missing", "error": ""
    }

def _fpi_pdf_uploader_v92(label: str, side: str, key: str):
    """Izolált uploader: a widget key és a feldolgozó state külön van."""
    files = st.file_uploader(label, type=["pdf"], accept_multiple_files=True, key=key)
    state = _fpi_set_pdf_upload_state_v92(side, files or [])
    if state.get("has_files"):
        if state.get("chars", 0) > 0:
            st.success(f"PDF OK: {len(state.get('files', []))} fájl, {state.get('page_count', 0)} oldal, {state.get('chars', 0)} karakter.")
        else:
            st.error(f"PDF feltöltve, de nincs kinyert szöveg. Reader: {state.get('reader')}. Hiba: {state.get('error') or 'n.a.'}")
    else:
        st.info("Nincs PDF feltöltve ebben a mezőben.")
    return files, state






def _fpi_uploaded_file_signature_v87(files: List[object]) -> str:
    parts = []
    for f in files or []:
        try:
            b = f.getvalue()
            parts.append(f"{getattr(f, 'name', 'pdf')}:{len(b)}:{hashlib.md5(b[:200000]).hexdigest()}")
        except Exception:
            parts.append(str(getattr(f, "name", "unknown")))
    return "|".join(parts)

def _fpi_build_pdf_only_context_from_session_v87(gps_context: Dict[str, object]) -> Optional[Dict[str, object]]:
    """V8.9: export előtti PDF context rebuild a már kinyert PDF-SZÖVEGBŐL.
    Először text-store, utána byte-store, utána UploadFile fallback.
    """
    try:
        own_state_v92 = _fpi_get_pdf_upload_state_v92("own")
        opp_state_v92 = _fpi_get_pdf_upload_state_v92("opp")
        own_store = _fpi_get_pdf_text_store_v89("own")
        opp_store = _fpi_get_pdf_text_store_v89("opp")

        own_pdf_text = own_state_v92.get("text", "") or own_store.get("text", "") or ""
        opp_pdf_text = opp_state_v92.get("text", "") or opp_store.get("text", "") or ""
        own_pdf_pages = own_state_v92.get("pages", []) or own_store.get("pages", []) or []
        opp_pdf_pages = opp_state_v92.get("pages", []) or opp_store.get("pages", []) or []
        own_items = own_state_v92.get("items", []) or own_store.get("items", []) or []
        opp_items = opp_state_v92.get("items", []) or opp_store.get("items", []) or []

        if not own_pdf_text:
            own_items = st.session_state.get("tactical_pro_own_pdf_bytes_v88") or _fpi_uploaded_files_to_bytes_v88(st.session_state.get("tactical_pro_own_pdfs") or [])
            own_pdf_text, own_pdf_pages = _fpi_tactical_app_combine_pdf_texts_v88(own_items)
        if not opp_pdf_text:
            opp_items = st.session_state.get("tactical_pro_opp_pdf_bytes_v88") or _fpi_uploaded_files_to_bytes_v88(st.session_state.get("tactical_pro_opp_pdfs") or [])
            opp_pdf_text, opp_pdf_pages = _fpi_tactical_app_combine_pdf_texts_v88(opp_items)

        if not own_pdf_text and own_items:
            own_pdf_text, own_pdf_pages = _fpi_tactical_extract_pdf_text(_fpi_restore_uploaded_file_wrappers_v88(own_items))
        if not opp_pdf_text and opp_items:
            opp_pdf_text, opp_pdf_pages = _fpi_tactical_extract_pdf_text(_fpi_restore_uploaded_file_wrappers_v88(opp_items))
    except Exception:
        return None

    has_any_pdf = bool(own_items or opp_items or own_pdf_text or opp_pdf_text)
    if not has_any_pdf:
        return None

    own_pdf_insights = _fpi_tactical_pdf_insights(own_pdf_text) if own_pdf_text else {"blocks": {}, "topics": [], "raw_text_len": 0, "sportsbase_findings": [], "sportsbase_lines": []}
    opp_pdf_insights = _fpi_tactical_pdf_insights(opp_pdf_text) if opp_pdf_text else {"blocks": {}, "topics": [], "raw_text_len": 0, "sportsbase_findings": [], "sportsbase_lines": []}

    own_real_pages = len({(p.get("file"), p.get("page_number", p.get("page"))) for p in own_pdf_pages if p.get("has_text") or p.get("text")})
    opp_real_pages = len({(p.get("file"), p.get("page_number", p.get("page"))) for p in opp_pdf_pages if p.get("has_text") or p.get("text")})

    own_pdf_insights["pdf_uploaded"] = bool(own_items or own_pdf_text)
    own_pdf_insights["pdf_pages"] = own_real_pages
    own_pdf_insights["raw_text_len"] = len(own_pdf_text or "")
    own_pdf_insights["upload_signature"] = own_store.get("signature", "") or "|".join([f"{x.get('name')}:{x.get('size')}:{x.get('md5')}" for x in own_items])
    own_pdf_insights["reader_version"] = "V8.9 direct UploadFile text-store + legacy Tactical reader"
    own_pdf_insights["page_debug"] = own_pdf_pages[:10]

    opp_pdf_insights["pdf_uploaded"] = bool(opp_items or opp_pdf_text)
    opp_pdf_insights["pdf_pages"] = opp_real_pages
    opp_pdf_insights["raw_text_len"] = len(opp_pdf_text or "")
    opp_pdf_insights["upload_signature"] = opp_store.get("signature", "") or "|".join([f"{x.get('name')}:{x.get('size')}:{x.get('md5')}" for x in opp_items])
    opp_pdf_insights["reader_version"] = "V8.9 direct UploadFile text-store + legacy Tactical reader"
    opp_pdf_insights["page_debug"] = opp_pdf_pages[:10]

    merged_pdf_insights = _fpi_safe_merge_tactical_pdf_insights_v104(own_pdf_insights, opp_pdf_insights)

    previous = st.session_state.get("tactical_pro_context") or {}
    own_team_metrics = previous.get("own_team_metrics", {}) or {}
    opp_team_metrics = previous.get("opp_team_metrics", {}) or {}
    own_player_tables = previous.get("own_player_tables", {}) or {}
    opp_player_tables = previous.get("opp_player_tables", {}) or {}

    has_excel = bool(own_team_metrics or opp_team_metrics or previous.get("has_own_player_excel") or previous.get("has_opp_player_excel"))
    level_label = "Full Intelligence – GPS + frissített taktikai PDF + meglévő Excel context" if has_excel else "GPS + frissített taktikai PDF"

    tactical_ctx_for_plan = {
        "analysis_level_label": level_label,
        "pdf_insights": merged_pdf_insights,
        "team_metrics": opp_team_metrics,
        "player_tables": opp_player_tables,
        "own": {"pdf_insights": own_pdf_insights, "team_metrics": own_team_metrics, "player_tables": own_player_tables},
        "opponent": {"pdf_insights": opp_pdf_insights, "team_metrics": opp_team_metrics, "player_tables": opp_player_tables},
    }
    plan = _fpi_safe_build_adaptive_plan_v104(gps_context or {}, tactical_ctx_for_plan)
    ctx = _build_tactical_executive_context(gps_context or {}, tactical_ctx_for_plan, plan)
    ctx["forced_pdf_rebuild"] = True
    ctx["forced_pdf_signature"] = (own_pdf_insights.get("upload_signature", "") + "||" + opp_pdf_insights.get("upload_signature", ""))
    ctx["own_pdf_chars"] = len(own_pdf_text or "")
    ctx["opp_pdf_chars"] = len(opp_pdf_text or "")
    ctx["own_pdf_pages"] = own_real_pages
    ctx["opp_pdf_pages"] = opp_real_pages
    ctx["pdf_reader_debug"] = {
        "own_files": own_store.get("files", []) or [x.get("name") for x in own_items],
        "opp_files": opp_store.get("files", []) or [x.get("name") for x in opp_items],
        "own_chars": len(own_pdf_text or ""),
        "opp_chars": len(opp_pdf_text or ""),
        "own_pages": own_real_pages,
        "opp_pages": opp_real_pages,
        "source": "v89_text_store_first",
    }
    return ctx


def _fpi_context_for_export_v87(gps_context: Dict[str, object]) -> Optional[Dict[str, object]]:
    """Riportexporthoz mindig próbálunk friss PDF-contextet építeni.
    Ha sikerül és talált PDF-sorokat/következtetéseket, azt használjuk.
    """
    fresh = _fpi_build_pdf_only_context_from_session_v87(gps_context or {})
    old = st.session_state.get("tactical_pro_context") if "st" in globals() else None

    # V9.1: ha nincs aktuális PDF a widgetben és nincs text-store, ne használjunk régi PDF-es contextet.
    try:
        no_pdf_now = (
            not st.session_state.get("tactical_pro_own_pdfs")
            and not st.session_state.get("tactical_pro_opp_pdfs")
            and not (_fpi_get_pdf_text_store_v89("own").get("text"))
            and not (_fpi_get_pdf_text_store_v89("opp").get("text"))
        )
        if no_pdf_now and old:
            old = dict(old)
            old["has_own_pdf"] = False
            old["has_opp_pdf"] = False
            old["own_pdf_pages"] = 0
            old["opp_pdf_pages"] = 0
            old["own_pdf_chars"] = 0
            old["opp_pdf_chars"] = 0
            old["pdf_provider_lines"] = []
            old["pdf_provider_findings"] = []
    except Exception:
        pass

    if fresh:
        fresh_score = int(fresh.get("pdf_direct_findings_count", 0) or 0) + int(fresh.get("pdf_direct_lines_count", 0) or 0)
        old_score = int((old or {}).get("pdf_direct_findings_count", 0) or 0) + int((old or {}).get("pdf_direct_lines_count", 0) or 0)
        fresh_pages = int(fresh.get("own_pdf_pages", 0) or 0) + int(fresh.get("opp_pdf_pages", 0) or 0)
        fresh_chars = int(fresh.get("own_pdf_chars", 0) or 0) + int(fresh.get("opp_pdf_chars", 0) or 0)
        old_pages = int((old or {}).get("own_pdf_pages", 0) or 0) + int((old or {}).get("opp_pdf_pages", 0) or 0)
        old_chars = int((old or {}).get("own_pdf_chars", 0) or 0) + int((old or {}).get("opp_pdf_chars", 0) or 0)
        if fresh_pages > 0 or fresh_chars > 0 or fresh_score > 0 or (old_pages == 0 and old_chars == 0):
            st.session_state["tactical_pro_context"] = fresh
            return fresh
    return old



