        pdf_line = f"PDF: {len(pdf_files)} fájl, {int(pdf_state.get('page_count', 0) or 0)} oldal, {int(pdf_state.get('chars', 0) or 0)} karakter"
        team_ok = sum(1 for x in team_diag if x.get("Státusz") == "OK")
