def _fpi_bytes_from_upload_v143(uploaded_file) -> bytes:
    if uploaded_file is None:
        return b""
    try:
        return uploaded_file.getvalue()
    except Exception:
        try:
            return uploaded_file.read()
        except Exception:
            return b""


def _fpi_read_csv_bytes_v143(data: bytes, name: str = "") -> pd.DataFrame:
    """Robusztus CSV-olvasó Catapult Vector/OpenField meta-fejléccel is."""
    last_err = None
    for enc in ["utf-8-sig", "utf-8", "cp1250", "latin2", "iso-8859-2", "cp1252"]:
        try:
            text = data.decode(enc)
            lines = text.splitlines()
            header_idx = None
            for i, line in enumerate(lines[:80]):
                normalized = line.lstrip("\ufeff").strip()
                if (normalized.startswith('"Player Name",') or normalized.startswith("Player Name,")) and "Period Name" in normalized:
                    header_idx = i
                    break
            if header_idx is not None:
                trimmed = "\n".join(lines[header_idx:])
                df = pd.read_csv(io.StringIO(trimmed), sep=",", engine="c", header=None, low_memory=False)
                df.attrs["fpi_source_system"] = "Catapult Vector / OpenField"
                return df
            return pd.read_csv(io.StringIO(text), sep=None, engine="python", header=None)
        except Exception as exc:
            last_err = exc
    raise ValueError(f"CSV beolvasási hiba ({name}): {last_err}")


def _fpi_excel_serial_to_datetime_v143(value):
    try:
        if pd.isna(value):
            return pd.NaT
    except Exception:
        pass
    if isinstance(value, (pd.Timestamp, datetime)):
        return pd.to_datetime(value, errors="coerce")
    try:
        num = float(value)
        if 20000 <= num <= 80000:
            return pd.Timestamp("1899-12-30") + pd.to_timedelta(num, unit="D")
    except Exception:
        pass
    return pd.to_datetime(value, errors="coerce", dayfirst=True)


def _fpi_clean_headers_v143(values) -> List[str]:
    result = []
    used = {}
    for idx, value in enumerate(list(values)):
        text = clean_col_name(value)
        if not text or str(text).lower() in {"nan", "none"}:
            text = f"Unnamed_{idx+1}"
        base = text
        used[base] = used.get(base, 0) + 1
        if used[base] > 1:
            text = f"{base}_{used[base]}"
        result.append(text)
    return result


def _fpi_find_header_row_v143(raw: pd.DataFrame, required_terms: List[str], max_scan: int = 40) -> Optional[int]:
    if raw is None or raw.empty:
        return None
    required = [str(x).lower() for x in required_terms]
    best_idx, best_score = None, -1
    for idx in range(min(max_scan, len(raw))):
        vals = [str(x).strip().lower() for x in raw.iloc[idx].tolist() if str(x).strip().lower() not in {"", "nan", "none"}]
        joined = " | ".join(vals)
        score = sum(1 for term in required if term in joined)
        if score > best_score:
            best_idx, best_score = idx, score
    return best_idx if best_score >= max(1, min(2, len(required))) else None


def _fpi_table_from_raw_v143(raw: pd.DataFrame, header_idx: int, stop_markers: Optional[List[str]] = None) -> pd.DataFrame:
    if raw is None or raw.empty or header_idx is None or header_idx >= len(raw):
        return pd.DataFrame()
    headers = _fpi_clean_headers_v143(raw.iloc[header_idx].tolist())
    data = raw.iloc[header_idx + 1 :].copy()
    data.columns = headers
    data = data.dropna(how="all")
    if stop_markers:
        stop_terms = [str(x).lower() for x in stop_markers]
        keep_rows = []
        for _, row in data.iterrows():
            row_text = " | ".join(str(x).strip().lower() for x in row.tolist() if str(x).strip().lower() not in {"", "nan", "none"})
            if any(marker in row_text for marker in stop_terms):
                break
            keep_rows.append(row)
        data = pd.DataFrame(keep_rows, columns=headers) if keep_rows else pd.DataFrame(columns=headers)
    return data.reset_index(drop=True)


def _fpi_detect_provider_v143(sheets: Dict[str, pd.DataFrame], file_name: str = "") -> str:
    name = str(file_name).lower()
    sheet_names = " ".join(str(x).lower() for x in sheets.keys())
    sample_text = ""
    for frame in list(sheets.values())[:4]:
        try:
            sample_text += " " + " ".join(str(x).lower() for x in frame.head(15).fillna("").astype(str).values.ravel().tolist())
        except Exception:
            pass

    if "playertek" in name or "playerteck" in name or all(x in sample_text for x in ["player name", "player load", "distance (km)"]):
        return "PlayerTek"
    if "brainsport" in name or "targets summary" in sample_text or "heart exertion" in sample_text or "main table" in sheet_names:
        return "Brainsports"
    if (
        "polar" in name
        or "edzési terhelési pontérték" in sample_text
        or "kardióterhelés" in sample_text
        or ("játékos neve" in sample_text and "táv/perc" in sample_text and "hrv (rmssd)" in sample_text)
    ):
        return "Polar Team Pro"
    old_catapult = all(x in sample_text for x in ["athlete_name", "activity_name", "total_player_load"])
    vector_catapult = all(x in sample_text for x in ["player name", "period name", "total player load"]) and ("meterage per minute" in sample_text or "max velocity" in sample_text)
    if "catapult" in name or old_catapult or vector_catapult:
        return "Catapult"
    return "Egyéb / Smart Mapper"


def _fpi_session_type_from_hint_v143(series: pd.Series, forced_type: Optional[str], file_name: str = "") -> pd.Series:
    """V205: sessiontípus-felismerés Barin félidőlapokkal.

    A következő minták mindig meccsnek számítanak:
    - first half / second half
    - 1st half / 2nd half
    - 1 half / 2 half
    - half1 / half2
    - 1. félidő / 2. félidő
    """
    if forced_type in {"Edzés", "Meccs"}:
        return pd.Series([forced_type] * len(series), index=series.index)

    hint = _norm_mapping_text(str(file_name))
    match_pattern = re.compile(
        r"(?:^|\b)(?:first|second|1st|2nd|1|2)\s*[-_. ]*half\b"
        r"|\bhalf\s*[-_. ]*(?:1|2)\b"
        r"|\b(?:1|2)\s*[-_. ]*felido\b"
        r"|\b(?:match|game|meccs|merkozes)\b",
        flags=re.IGNORECASE,
    )

    if match_pattern.search(hint):
        default = "Meccs"
    elif any(x in hint for x in ["training", "train", "edzes"]):
        default = "Edzés"
    else:
        default = "Edzés"

    if series is None:
        return pd.Series(dtype="object")

    raw = series.astype(str)
    normalized = raw.apply(normalize_session_type)
    normalized_hint = raw.apply(_norm_mapping_text)
    half_or_match = normalized_hint.str.contains(match_pattern, regex=True, na=False)

    out = normalized.where(normalized.isin(["Edzés", "Meccs"]), default)
    out = out.mask(half_or_match, "Meccs")
    return out


def _fpi_prepare_brainsports_v143(
    sheets: Dict[str, pd.DataFrame],
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    candidates = []
    for sheet_name, raw in sheets.items():
        low_name = str(sheet_name).lower()
        if low_name.startswith("ts ") or low_name.startswith("ti "):
            continue
        header_idx = _fpi_find_header_row_v143(raw, ["name", "total distance", "duration"])
        if header_idx is None:
            continue
        table = _fpi_table_from_raw_v143(
            raw,
            header_idx,
            stop_markers=["targets summary", "targeted values", "targets intensity"],
        )
        if table.empty:
            continue
        cols_norm = {clean_col_name(c).lower(): c for c in table.columns}
        if not any("total distance" in k for k in cols_norm):
            continue
        candidates.append((sheet_name, table))

    if not candidates:
        return pd.DataFrame()

    # V203: Barin / Brainsports többmunkalapos export.
    #
    # A teljes munkafüzetből csak a csapatszintű, egy sessiont tartalmazó
    # főlapokat fűzzük össze. TS/TI, Overall és játékosonkénti lapok kimaradnak.
    session_candidates = []
    skipped_sheet_names = []
    candidate_details = []

    for sheet_name, candidate_table in candidates:
        low = str(sheet_name).strip().lower()
        norm_cols = {
            clean_col_name(c).lower(): c
            for c in candidate_table.columns
        }

        name_col = next(
            (original for normalized, original in norm_cols.items()
             if normalized == "name" or normalized.endswith(" name")),
            None,
        )
        split_col = next(
            (original for normalized, original in norm_cols.items()
             if "split" in normalized),
            None,
        )

        if name_col is not None:
            names = (
                candidate_table[name_col]
                .dropna()
                .astype(str)
                .str.strip()
            )
            names = names[
                ~names.str.lower().isin(
                    {"", "nan", "none", "overall", "name", "average", "avg"}
                )
            ]
            unique_players = int(names.nunique())
        else:
            unique_players = 0

        if split_col is not None:
            splits = (
                candidate_table[split_col]
                .dropna()
                .astype(str)
                .str.strip()
            )
            splits = splits[
                ~splits.str.lower().isin(
                    {"", "nan", "none", "split", "session", "average", "avg"}
                )
            ]
            unique_splits = int(splits.nunique())
            split_values = splits.str.lower().unique().tolist()
        else:
            unique_splits = 0
            split_values = []

        helper_name = (
            low.startswith(("ts ", "ti "))
            or low in {"overall", "summary", "összesítés", "osszesites"}
        )
        overall_content = any(
            value in {"overall", "summary", "összesítés", "osszesites"}
            for value in split_values
        )
        team_session_sheet = (
            not helper_name
            and not overall_content
            and unique_players >= 3
            and unique_splits == 1
        )

        candidate_details.append({
            "sheet": str(sheet_name),
            "players": unique_players,
            "sessions": unique_splits,
            "selected": team_session_sheet,
        })

        if team_session_sheet:
            frame = candidate_table.copy()
            frame["_fpi_source_sheet"] = str(sheet_name)
            session_candidates.append((sheet_name, frame))
        else:
            skipped_sheet_names.append(str(sheet_name))

    # Kompatibilis fallback az egyszerű, egylapos Brainsports exportokra.
    if session_candidates:
        table = pd.concat(
            [frame for _, frame in session_candidates],
            ignore_index=True,
            sort=False,
        )
        selected_sheet_names = [str(name) for name, _ in session_candidates]
        selection_mode = "multi_session"
    else:
        ranked_candidates = []
        for sheet_name, candidate_table in candidates:
            low = str(sheet_name).lower().strip()
            norm_cols = {
                clean_col_name(c).lower(): c
                for c in candidate_table.columns
            }
            name_col = next(
                (original for normalized, original in norm_cols.items()
                 if normalized == "name" or normalized.endswith(" name")),
                None,
            )
            unique_players = (
                int(candidate_table[name_col].dropna().astype(str).nunique())
                if name_col is not None else 0
            )
            overall_penalty = 10000 if low in {
                "overall", "summary", "összesítés", "osszesites"
            } else 0
            single_player_penalty = 5000 if unique_players <= 2 else 0
            ranked_candidates.append(
                (
                    overall_penalty + single_player_penalty - unique_players,
                    sheet_name,
                    candidate_table,
                )
            )
        ranked_candidates.sort(key=lambda item: item[0])
        selected_name = ranked_candidates[0][1]
        table = ranked_candidates[0][2].copy()
        table["_fpi_source_sheet"] = str(selected_name)
        selected_sheet_names = [str(selected_name)]
        selection_mode = "legacy_fallback"

    def col_like(*needles):
        for c in table.columns:
            lc = clean_col_name(c).lower()
            if all(n.lower() in lc for n in needles):
                return c
        return None

    out = pd.DataFrame()
    c_name = col_like("name")
    c_split = col_like("split")
    c_start = col_like("start")
    c_duration = col_like("duration")
    c_dist = col_like("total distance")
    # V204: a Barin exportban gyakran nincs "Total sprints distance" oszlop;
    # a valódi sprinttáv a speed zone 5 távolsága.
    c_sprint_dist = col_like("total sprints distance") or col_like("distance speed zone 5")
    c_sprints = col_like("sprints count")
    c_hsr = col_like("distance(4+5)")
    c_top = col_like("top speed")
    c_he = col_like("high efforts")
    c_hmld = col_like("hmld")
    c_acc = col_like("total accelerations")
    c_dec = col_like("total decelerations")
    c_acc_1 = col_like("accelerations 1")
    c_acc_2 = col_like("accelerations 2")
    c_acc_3 = col_like("accelerations 3")
    c_dec_1 = col_like("decelerations 1")
    c_dec_2 = col_like("decelerations 2")
    c_dec_3 = col_like("decelerations 3")
    c_hr = col_like("heart exertion")

    if c_name is None or c_start is None:
        return pd.DataFrame()

    # V204: a fő Barin lap alján újabb "Ratio values" tábla található.
    # Csak a tényleges játékos-session sorokat tartjuk meg.
    valid_name = table[c_name].astype(str).str.strip()
    valid_start = table[c_start].apply(_fpi_excel_serial_to_datetime_v143).notna()
    valid_distance = (
        pd.to_numeric(table[c_dist], errors="coerce").notna()
        if c_dist is not None else pd.Series(True, index=table.index)
    )
    # A fő adatblokk Duration mezője mm:ss; az alsó ratio táblában ugyanebbe
    # az oszlopba 0–1 közötti arányszám kerül. Ez a legerősebb blokkhatár-jel.
    if c_duration is not None:
        duration_text_v204 = table[c_duration].astype(str).str.strip()
        duration_numeric_v204 = pd.to_numeric(table[c_duration], errors="coerce")
        valid_duration = (
            duration_text_v204.str.match(r"^\d+:\d{1,2}(?:\.\d+)?$", na=False)
            | duration_numeric_v204.gt(2)
        )
    else:
        valid_duration = pd.Series(True, index=table.index)
    table = table[
        valid_start
        & valid_distance
        & valid_duration
        & ~valid_name.str.lower().isin(
            {"", "nan", "none", "name", "ratio values", "average", "avg", "overall"}
        )
    ].copy()
    if table.empty:
        return pd.DataFrame()

    def _barin_duration_minutes_v204(series: pd.Series) -> pd.Series:
        text = series.astype(str).str.strip()
        # mm:ss értékeknél a pandas önmagában óraként értelmezhet; ezért kézzel bontjuk.
        parts = text.str.extract(r"^(?P<m>\d+):(?P<s>\d{1,2})(?:\.(?P<ms>\d+))?$")
        manual = pd.to_numeric(parts["m"], errors="coerce") + pd.to_numeric(parts["s"], errors="coerce") / 60.0
        numeric = pd.to_numeric(series, errors="coerce")
        # Excel-időtöredék: nap -> perc; egyéb numerikus érték: perc.
        numeric_minutes = numeric.where(numeric.abs() > 2, numeric * 24.0 * 60.0)
        return manual.where(manual.notna(), numeric_minutes)

    out["Player Name"] = table[c_name]
    out["Session Type"] = _fpi_session_type_from_hint_v143(
        table[c_split] if c_split else pd.Series([""] * len(table)),
        forced_type,
        file_name,
    )
    out["Session Name"] = table[c_split] if c_split else Path(file_name).stem
    out["Start Time"] = table[c_start].apply(_fpi_excel_serial_to_datetime_v143)
    if c_duration:
        out["Duration"] = _barin_duration_minutes_v204(table[c_duration])
    if c_dist:
        out["Total Distance"] = pd.to_numeric(table[c_dist], errors="coerce")
    if c_duration and c_dist:
        duration_v204 = pd.to_numeric(out["Duration"], errors="coerce")
        distance_v204 = pd.to_numeric(out["Total Distance"], errors="coerce")
        out["Distance Per Min"] = distance_v204.div(duration_v204.where(duration_v204 > 0))
    if c_sprint_dist:
        out["Sprint Distance"] = table[c_sprint_dist]
    if c_sprints:
        out["Sprints"] = table[c_sprints]
    if c_hsr:
        # Brainsports Distance(4+5) already combines HSR + sprint.
        out["HSR Distance"] = table[c_hsr]
    if c_top:
        top_speed = pd.to_numeric(table[c_top], errors="coerce")
        out["Top Speed"] = top_speed.where(top_speed > 15, top_speed * 3.6)
    if c_he:
        out["High Efforts"] = table[c_he]
    if c_hmld:
        out["HMLD"] = table[c_hmld]
        out["Player Load"] = table[c_hmld]
    if c_acc:
        out["Total Accelerations"] = pd.to_numeric(table[c_acc], errors="coerce")
    else:
        acc_parts = [
            pd.to_numeric(table[c], errors="coerce")
            for c in (c_acc_1, c_acc_2, c_acc_3) if c
        ]
        if acc_parts:
            out["Total Accelerations"] = pd.concat(acc_parts, axis=1).sum(
                axis=1, min_count=1
            )
    if c_dec:
        out["Total Decelerations"] = pd.to_numeric(table[c_dec], errors="coerce")
    else:
        dec_parts = [
            pd.to_numeric(table[c], errors="coerce")
            for c in (c_dec_1, c_dec_2, c_dec_3) if c
        ]
        if dec_parts:
            out["Total Decelerations"] = pd.concat(dec_parts, axis=1).sum(
                axis=1, min_count=1
            )
    if c_hr:
        out["Heart Exertion"] = table[c_hr]

    # Ismételt belső fejléc- és összesítő sorok eltávolítása.
    if "Player Name" in out.columns:
        player_text = out["Player Name"].astype(str).str.strip().str.lower()
        out = out[
            ~player_text.isin(
                {"", "nan", "none", "name", "average", "avg", "overall"}
            )
        ].copy()

    result = out.dropna(how="all").reset_index(drop=True)
    result.attrs["fpi_barin_import"] = {
        "selection_mode": selection_mode,
        "workbook_sheet_count": len(sheets),
        "candidate_sheet_count": len(candidates),
        "selected_sheet_count": len(selected_sheet_names),
        "selected_sheets": selected_sheet_names,
        "skipped_sheet_count": max(0, len(sheets) - len(selected_sheet_names)),
        "skipped_sheets": skipped_sheet_names,
        "detected_sessions": int(
            result["Session Name"].dropna().astype(str).nunique()
        ) if "Session Name" in result.columns else len(selected_sheet_names),
    }
    return result


def _fpi_prepare_playertek_v143(
    raw: pd.DataFrame,
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    """PlayerTek CSV mapping: km->m, HSR=Z4+Z5, sprint=Z5, all split elsődleges."""
    header_idx = _fpi_find_header_row_v143(raw, ["player name", "distance", "player load"])
    if header_idx is None:
        return pd.DataFrame()
    table = _fpi_table_from_raw_v143(raw, header_idx)
    if table.empty:
        return table

    def pick(*names):
        norm = {clean_col_name(c).lower(): c for c in table.columns}
        for name in names:
            n = clean_col_name(name).lower()
            if n in norm:
                return norm[n]
        for c in table.columns:
            lc = clean_col_name(c).lower()
            if any(clean_col_name(n).lower() in lc for n in names):
                return c
        return None

    c_name=pick("Player Name"); c_date=pick("Date"); c_title=pick("Session Title")
    c_split=pick("Split Name"); c_tags=pick("Tags"); c_start=pick("Split Start Time")
    c_duration=pick("Duration"); c_dist=pick("Distance (km)"); c_sprints=pick("Sprints")
    c_provider_sprint=pick("Sprint Distance (m)")
    c_z3=pick("Distance in Speed Zone 3  (km)","Distance in Speed Zone 3 (km)")
    c_z4=pick("Distance in Speed Zone 4  (km)","Distance in Speed Zone 4 (km)")
    c_z5=pick("Distance in Speed Zone 5  (km)","Distance in Speed Zone 5 (km)")
    c_acc=pick("Accelerations"); c_dec=pick("Decelerations"); c_load=pick("Player Load")
    c_speed=pick("Top Speed (km/h)"); c_dpm=pick("Distance Per Min (m/min)")
    if c_name is None or c_date is None:
        return pd.DataFrame()

    work=table.copy()
    if c_split:
        work["_fpi_split_norm"]=work[c_split].astype(str).map(_norm_mapping_text)
        keys=[c_name,c_date]+([c_title] if c_title else [])
        has_all=work.groupby(keys,dropna=False)["_fpi_split_norm"].transform(lambda s:s.isin({"all","overall","total"}).any())
        work=work.loc[(has_all & work["_fpi_split_norm"].isin({"all","overall","total"})) | ~has_all].copy()
        # all hiányában a game összesítő elsődleges, ha félidők is vannak
        has_game=work.groupby(keys,dropna=False)["_fpi_split_norm"].transform(lambda s:s.eq("game").any())
        has_half=work.groupby(keys,dropna=False)["_fpi_split_norm"].transform(lambda s:s.str.contains(r"half|felido|félidő",regex=True,na=False).any())
        work=work.loc[(has_game & has_half & work["_fpi_split_norm"].eq("game")) | ~(has_game & has_half)].copy()

    out=pd.DataFrame(index=work.index)
    out["Player Name"]=work[c_name]
    hints=work[c_tags] if c_tags else pd.Series("",index=work.index)
    out["Session Type"]=_fpi_session_type_from_hint_v143(hints,forced_type,file_name)
    title=work[c_title].astype(str) if c_title else pd.Series(Path(file_name).stem,index=work.index)
    if c_split and "_fpi_split_norm" in work.columns:
        summary=work["_fpi_split_norm"].isin({"all","overall","total","game"})
        out["Session Name"]=title.where(summary,title+" | "+work[c_split].astype(str))
    else:
        out["Session Name"]=title
    out["Start Time"]=(work[c_start] if c_start else work[c_date]).apply(_fpi_excel_serial_to_datetime_v143)
    if c_duration:
        out["Duration"]=pd.to_numeric(work[c_duration],errors="coerce")/60.0
        out["Match Minutes"]=out["Duration"]
    if c_dist: out["Total Distance"]=pd.to_numeric(work[c_dist],errors="coerce")*1000.0
    if c_sprints: out["Sprints"]=pd.to_numeric(work[c_sprints],errors="coerce")
    if c_z3: out["Speed Zone 3"]=pd.to_numeric(work[c_z3],errors="coerce")*1000.0
    if c_z4: out["Speed Zone 4"]=pd.to_numeric(work[c_z4],errors="coerce")*1000.0
    if c_z5: out["Speed Zone 5"]=pd.to_numeric(work[c_z5],errors="coerce")*1000.0
    if c_z4 or c_z5:
        z4=pd.to_numeric(out["Speed Zone 4"],errors="coerce") if "Speed Zone 4" in out.columns else pd.Series(0.0,index=out.index)
        z5=pd.to_numeric(out["Speed Zone 5"],errors="coerce") if "Speed Zone 5" in out.columns else pd.Series(0.0,index=out.index)
        out["HSR Distance"]=z4.fillna(0)+z5.fillna(0)
        out["Sprint Distance"]=z5
    elif c_provider_sprint:
        out["HSR Distance"]=pd.to_numeric(work[c_provider_sprint],errors="coerce")
        out["Sprint Distance"]=np.nan
    if c_provider_sprint: out["PlayerTek Provider Sprint Distance"]=pd.to_numeric(work[c_provider_sprint],errors="coerce")
    if c_acc: out["Total Accelerations"]=pd.to_numeric(work[c_acc],errors="coerce")
    if c_dec: out["Total Decelerations"]=pd.to_numeric(work[c_dec],errors="coerce")
    if c_load: out["Player Load"]=pd.to_numeric(work[c_load],errors="coerce")
    if c_speed: out["Top Speed"]=pd.to_numeric(work[c_speed],errors="coerce")
    if c_dpm: out["Distance Per Min"]=pd.to_numeric(work[c_dpm],errors="coerce")
    elif "Total Distance" in out.columns and "Duration" in out.columns:
        out["Distance Per Min"]=out["Total Distance"]/out["Duration"].where(out["Duration"]>0)
    out=out.dropna(how="all").reset_index(drop=True)
    out.attrs["fpi_playertek_import"]={"source_rows":len(table),"kept_rows":len(out),"hsr":"Zone 4 + Zone 5","sprint":"Zone 5"}
    return out


def _fpi_prepare_polar_v143(
    sheets: Dict[str, pd.DataFrame],
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    """Polar Team Pro magyar összegző export standardizálása."""

    table = None
    for _, raw in sheets.items():
        header_idx = _fpi_find_header_row_v143(
            raw,
            ["játékos neve", "kezdési idő", "időtartam"],
            max_scan=40,
        )
        if header_idx is None:
            continue
        candidate = _fpi_table_from_raw_v143(raw, header_idx)
        normalized_headers = {
            clean_col_name(c).lower() for c in candidate.columns
        }
        if (
            any("játékos neve" in c or "jatekos neve" in c for c in normalized_headers)
            and any("kezdési idő" in c or "kezdesi ido" in c for c in normalized_headers)
        ):
            table = candidate
            break

    if table is None or table.empty:
        return pd.DataFrame()

    def pick(*aliases: str):
        exact = {
            clean_col_name(c).lower(): c
            for c in table.columns
        }
        for alias in aliases:
            key = clean_col_name(alias).lower()
            if key in exact:
                return exact[key]
        for c in table.columns:
            current = clean_col_name(c).lower()
            for alias in aliases:
                needle = clean_col_name(alias).lower()
                if needle and needle in current:
                    return c
        return None

    def numeric(col):
        if col is None:
            return pd.Series(np.nan, index=table.index, dtype=float)
        return pd.to_numeric(table[col], errors="coerce")

    def duration_minutes(col):
        if col is None:
            return pd.Series(np.nan, index=table.index, dtype=float)
        source = table[col]
        td = pd.to_timedelta(source.astype(str).str.strip(), errors="coerce")
        result = td.dt.total_seconds() / 60.0
        numeric_value = pd.to_numeric(source, errors="coerce")
        # Excel időtöredék esetén nap -> perc; tiszta nagy szám esetén perc.
        fallback = numeric_value.where(
            numeric_value.abs() > 2,
            numeric_value * 24.0 * 60.0,
        )
        return result.where(result.notna(), fallback)

    c_name = pick("Játékos neve", "Jatekos neve")
    c_type = pick("Típus", "Tipus", "Type")
    c_session = pick("Szakasz neve", "Edzésszakasz neve")
    c_start = pick("Kezdési idő", "Kezdesi ido")
    c_end = pick("Befejezési idő", "Befejezesi ido")
    c_duration = pick("Időtartam", "Idotartam")
    c_distance = pick("Teljes táv [m]", "Tel­jes táv [m]")
    c_dpm = pick("Táv/perc [m/min]")
    c_max_speed = pick("Maximális sebesség [km/h]")
    c_avg_speed = pick("Átlagsebesség [km/h]")
    c_sprints = pick("Sprintek")
    c_zone3 = pick("Táv a sebesség célzónában 3")
    c_zone4 = pick("Táv a sebesség célzónában 4")
    c_zone5 = pick("Táv a sebesség célzónában 5")
    c_load = pick("Edzési terhelési pontérték")
    c_cardio = pick("Kardióterhelés")
    c_recovery = pick("Regenerálódási idő [h]")
    c_muscle = pick("Izomterhelés")
    c_hr_avg = pick("Átlagos pulzus [bpm]")
    c_hr_max = pick("Maximális pulzus [bpm]")
    c_hrv = pick("HRV (RMSSD)")
    c_dec_high = pick("Gyorsulások száma (-50.00 - -3.00 m/s²)")
    c_dec_mid = pick("Gyorsulások száma (-2.99 - -2.00 m/s²)")
    c_acc_mid = pick("Gyorsulások száma (2.00 - 2.99 m/s²)")
    c_acc_high = pick("Gyorsulások száma (3.00 - 50.00 m/s²)")

    if c_name is None or c_start is None:
        return pd.DataFrame()

    out = pd.DataFrame(index=table.index)
    out["Player Name"] = table[c_name].astype(str).str.strip()

    if forced_type in {"Edzés", "Meccs"}:
        out["Session Type"] = forced_type
    elif c_type:
        out["Session Type"] = table[c_type].astype(str).apply(normalize_session_type)
        raw_type = table[c_type].astype(str).str.lower()
        out.loc[raw_type.str.contains("meccs|match|game", regex=True, na=False), "Session Type"] = "Meccs"
        out.loc[raw_type.str.contains("edzés|edzes|training|train", regex=True, na=False), "Session Type"] = "Edzés"
        out["Session Type"] = out["Session Type"].where(
            out["Session Type"].isin(["Edzés", "Meccs"]),
            "Edzés",
        )
    else:
        out["Session Type"] = _fpi_session_type_from_hint_v143(
            pd.Series([""] * len(table), index=table.index),
            forced_type,
            file_name,
        )

    out["Session Name"] = (
        table[c_session].astype(str).str.strip()
        if c_session else Path(file_name).stem
    )
    out["Start Time"] = pd.to_datetime(table[c_start], errors="coerce")
    if c_end:
        out["End Time"] = pd.to_datetime(table[c_end], errors="coerce")

    out["Duration"] = duration_minutes(c_duration)
    out["Match Minutes"] = out["Duration"]
    out["Total Distance"] = numeric(c_distance)
    out["Distance Per Min"] = numeric(c_dpm)
    out["Top Speed"] = numeric(c_max_speed)
    if c_avg_speed:
        out["Average Speed"] = numeric(c_avg_speed)
    out["Sprints"] = numeric(c_sprints)

    zone3 = numeric(c_zone3)
    zone4 = numeric(c_zone4)
    zone5 = numeric(c_zone5)
    if c_zone3:
        out["Speed Zone 3 Distance"] = zone3
    if c_zone4:
        out["HSR Distance"] = zone4
    if c_zone5:
        out["Sprint Distance"] = zone5

    out["Player Load"] = numeric(c_load)
    if c_cardio:
        out["Cardio Load"] = numeric(c_cardio)
    if c_recovery:
        out["Recovery Time"] = numeric(c_recovery)
    if c_muscle:
        out["Muscle Load"] = numeric(c_muscle)
    if c_hr_avg:
        out["Average HR"] = numeric(c_hr_avg)
    if c_hr_max:
        out["Max HR"] = numeric(c_hr_max)
    if c_hrv:
        out["HRV"] = numeric(c_hrv)

    # A Polar külön gyorsulási/lassulási zónákat ad.
    # A kompatibilitáshoz a nagy intenzitású kategóriákat használjuk.
    acc_high = numeric(c_acc_high)
    dec_high = numeric(c_dec_high)
    out["Total Accelerations"] = acc_high
    out["Total Decelerations"] = dec_high

    high_effort_parts = [
        numeric(c_sprints),
        acc_high,
        dec_high,
    ]
    out["High Efforts"] = pd.concat(
        high_effort_parts,
        axis=1,
    ).sum(axis=1, min_count=1)

    # Kiegészítő közepes intenzitású mozgások a későbbi elemzéshez.
    if c_acc_mid:
        out["Medium Accelerations"] = numeric(c_acc_mid)
    if c_dec_mid:
        out["Medium Decelerations"] = numeric(c_dec_mid)

    out = out.replace([np.inf, -np.inf], np.nan)
    out = out[
        out["Player Name"].ne("")
        & out["Player Name"].str.lower().ne("nan")
    ]
    return out.dropna(how="all").reset_index(drop=True)

def _fpi_prepare_catapult_vector_v160(
    sheets: Dict[str, pd.DataFrame],
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    """Catapult Vector/OpenField 1500+ oszlopos széles CSV standardizálása."""
    table = None
    for _, raw in sheets.items():
        idx = _fpi_find_header_row_v143(raw, ["player name", "period name", "total distance", "total player load"], max_scan=80)
        if idx is None:
            continue
        candidate = _fpi_table_from_raw_v143(raw, idx)
        cols = {clean_col_name(c).lower() for c in candidate.columns}
        if "player name" in cols and "period name" in cols:
            table = candidate
            break
    if table is None or table.empty:
        return pd.DataFrame()

    def pick(*names):
        norm = {clean_col_name(c).lower(): c for c in table.columns}
        for name in names:
            key = clean_col_name(name).lower()
            if key in norm:
                return norm[key]
        return None

    c_name = pick("Player Name")
    c_period = pick("Period Name")
    if c_name is None or c_period is None:
        return pd.DataFrame()

    out = pd.DataFrame(index=table.index)
    out["Player Name"] = table[c_name].astype(str).str.strip()
    out["Session Name"] = table[c_period].astype(str).str.strip()
    if forced_type in {"Edzés", "Meccs"}:
        out["Session Type"] = forced_type
    else:
        hint = (table[c_period].astype(str) + " " + str(file_name)).str.lower()
        out["Session Type"] = np.where(hint.str.contains(r"match|game|meccs|mérk", regex=True, na=False), "Meccs", "Edzés")

    mapping = {
        "Position": ("Position Name",),
        "Total Distance": ("Total Distance",),
        "Distance Per Min": ("Meterage Per Minute",),
        "Top Speed": (
            "Max Velocity (km/h)", "Maximum Velocity (km/h)",
            "Max Velocity", "Maximum Velocity", "Top Speed (km/h)"
        ),
        "Player Load": ("Total Player Load",),
        "Player Load Per Min": ("Player Load Per Minute",),
        "HSR Distance": (
            "High Speed Running (19,2 - 25,2 km/h) (m)",
            "High Speed Running Distance", "HSR Distance"
        ),
        "Sprint Distance": (
            "Sprint Distance (>25 km/h)", "Sprint Distance", "Sprint Distance (m)"
        ),
        "Sprints": ("Sprint Efforts", "Sprint Count", "Sprints"),
        "Total Accelerations": (
            "Acceleration B3 Efforts (Gen 2)",
            "Acceleration Band 3 Total Effort Count",
            "Acceleration B2-3 Total Efforts (Gen 2)",
            "Acceleration B3+ Efforts (Gen 2)",
            "Total Accelerations"
        ),
        "Total Decelerations": (
            "Deceleration B3 Efforts (Gen 2)",
            "Deceleration B2-3 Total Efforts (Gen 2)",
            "Deceleration Band 3 Total Effort Count",
            "Deceleration B3+ Efforts (Gen 2)",
            "Total Decelerations"
        ),
        "Average HR": ("Avg Heart Rate",),
        "Max HR": ("Maximum Heart Rate",),
    }
    for target, aliases in mapping.items():
        col = pick(*aliases)
        if col is not None:
            out[target] = table[col] if target == "Position" else pd.to_numeric(table[col], errors="coerce")

    c_start = pick("Unix Start Time", "Period Start Time")
    if c_start is not None:
        out["Start Time"] = pd.to_datetime(pd.to_numeric(table[c_start], errors="coerce"), unit="s", errors="coerce")

    c_duration = pick("Total Duration")
    if c_duration is not None:
        td = pd.to_timedelta(table[c_duration].astype(str).str.strip(), errors="coerce")
        num = pd.to_numeric(table[c_duration], errors="coerce") / 60.0
        out["Duration"] = (td.dt.total_seconds() / 60.0).where(td.notna(), num)

    out = out[out["Player Name"].ne("") & out["Player Name"].str.lower().ne("nan")]
    return out.dropna(how="all").reset_index(drop=True)


def _fpi_prepare_catapult_v143(
    sheets: Dict[str, pd.DataFrame],
    forced_type: Optional[str],
    file_name: str,
) -> pd.DataFrame:
    raw_table = None
    for _, raw in sheets.items():
        header_idx = _fpi_find_header_row_v143(raw, ["athlete_name", "activity_name", "total_distance"])
        if header_idx is not None:
            raw_table = _fpi_table_from_raw_v143(raw, header_idx)
            if not raw_table.empty:
                break
    if raw_table is None or raw_table.empty:
        return pd.DataFrame()

    table = raw_table.copy()
    table.columns = [clean_col_name(c) for c in table.columns]
    lookup = {c.lower(): c for c in table.columns}

    def c(name):
        return lookup.get(clean_col_name(name).lower())

    athlete = c("athlete_name")
    activity = c("activity_name")
    date_col = c("date")
    if athlete is None or activity is None or date_col is None:
        return pd.DataFrame()

    numeric_names = [
        "total_duration", "total_distance", "velocity2_band3_total_distance",
        "velocity2_band4_total_distance", "velocity2_band3_total_effort_count",
        "velocity2_band4_total_effort_count", "max_vel", "hsr_efforts",
        "gen2_acceleration_band6plus_total_effort_count",
        "gen2_acceleration_band3plus_total_effort_count",
        "total_player_load", "mean_heart_rate", "max_heart_rate",
    ]
    for name in numeric_names:
        col = c(name)
        if col:
            table[col] = pd.to_numeric(table[col], errors="coerce")

    group_cols = [athlete, activity, date_col]
    pos_col = c("position_name")
    day_col = c("day_name")
    if pos_col:
        group_cols.append(pos_col)
    if day_col:
        group_cols.append(day_col)

    agg = {}
    for name in [
        "total_duration", "total_distance", "velocity2_band3_total_distance",
        "velocity2_band4_total_distance", "velocity2_band3_total_effort_count",
        "velocity2_band4_total_effort_count", "hsr_efforts",
        "gen2_acceleration_band6plus_total_effort_count",
        "gen2_acceleration_band3plus_total_effort_count",
        "total_player_load",
    ]:
        col = c(name)
        if col:
            agg[col] = "sum"
    for name in ["max_vel", "max_heart_rate"]:
        col = c(name)
        if col:
            agg[col] = "max"
    mean_hr = c("mean_heart_rate")
    if mean_hr:
        agg[mean_hr] = "mean"

    grouped = table.groupby(group_cols, dropna=False).agg(agg).reset_index()
    out = pd.DataFrame()
    out["Player Name"] = grouped[athlete]
    out["Session Name"] = grouped[activity]
    if forced_type in {"Edzés", "Meccs"}:
        out["Session Type"] = forced_type
    else:
        hint = grouped[day_col] if day_col and day_col in grouped.columns else grouped[activity]
        out["Session Type"] = hint.astype(str).apply(normalize_session_type)
        inferred = grouped[activity].astype(str).str.lower().str.contains("match|game|meccs", regex=True)
        out.loc[inferred, "Session Type"] = "Meccs"
        out.loc[~inferred & ~out["Session Type"].isin(["Edzés", "Meccs"]), "Session Type"] = "Edzés"
    out["Start Time"] = grouped[date_col].apply(_fpi_excel_serial_to_datetime_v143)
    if pos_col and pos_col in grouped:
        out["Position"] = grouped[pos_col]
    col = c("total_duration")
    if col and col in grouped:
        out["Duration"] = grouped[col] / 60.0
        out["Match Minutes"] = out["Duration"]
    col = c("total_distance")
    if col and col in grouped:
        out["Total Distance"] = grouped[col]
    v3 = c("velocity2_band3_total_distance")
    v4 = c("velocity2_band4_total_distance")
    if v3 and v3 in grouped:
        out["HSR Distance"] = grouped[v3]
    if v4 and v4 in grouped:
        out["Sprint Distance"] = grouped[v4]
    e3 = c("velocity2_band3_total_effort_count")
    e4 = c("velocity2_band4_total_effort_count")
    if e4 and e4 in grouped:
        out["Sprints"] = grouped[e4]
    elif e3 and e3 in grouped:
        out["Sprints"] = grouped[e3]
    max_vel = c("max_vel")
    if max_vel and max_vel in grouped:
        out["Top Speed"] = grouped[max_vel] * 3.6
    he = c("hsr_efforts")
    if he and he in grouped:
        out["High Efforts"] = grouped[he]
    acc = c("gen2_acceleration_band3plus_total_effort_count")
    if acc and acc in grouped:
        out["Total Accelerations"] = grouped[acc]
    load = c("total_player_load")
    if load and load in grouped:
        out["Player Load"] = grouped[load]
    hr_avg = c("mean_heart_rate")
    hr_max = c("max_heart_rate")
    if hr_avg and hr_avg in grouped:
        out["Average HR"] = grouped[hr_avg]
    if hr_max and hr_max in grouped:
        out["Max HR"] = grouped[hr_max]
    return out.reset_index(drop=True)


def _fpi_ensure_xlrd_v166() -> Tuple[bool, str]:
    """Biztosítja a régi bináris .xls fájlok olvasásához szükséges xlrd-t."""
    try:
        import xlrd  # noqa: F401
        return True, "xlrd elérhető"
    except Exception as first_exc:
        first_error = str(first_exc)

    # Streamlit/virtuális környezetben megkíséreljük ugyanabba a Pythonba telepíteni.
    try:
        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "--disable-pip-version-check",
                "--quiet",
                "xlrd>=2.0.1",
            ],
            capture_output=True,
            text=True,
            timeout=120,
            check=False,
        )
        importlib.invalidate_caches()
        try:
            import xlrd  # noqa: F401
            return True, "xlrd automatikusan telepítve"
        except Exception as second_exc:
            detail = result.stderr.strip() or result.stdout.strip() or str(second_exc)
            return False, f"xlrd telepítési kísérlet sikertelen: {detail}"
    except Exception as exc:
        return False, f"xlrd hiányzik ({first_error}); automatikus telepítés sem sikerült: {exc}"


def _fpi_read_excel_bytes_v165(
    data: bytes,
    file_name: str,
    header=None,
) -> Dict[str, pd.DataFrame]:
    """Excel fájl olvasása több motorral, stabil régi .xls támogatással."""
    ext = Path(str(file_name)).suffix.lower()
    errors: List[str] = []

    # Régi OLE2 .xls: elsődlegesen xlrd. Ez a stabil, szerverfüggetlen út.
    if ext == ".xls":
        xlrd_ok, xlrd_note = _fpi_ensure_xlrd_v166()
        if xlrd_ok:
            try:
                sheets = pd.read_excel(
                    io.BytesIO(data),
                    sheet_name=None,
                    header=header,
                    engine="xlrd",
                )
                if sheets:
                    return sheets
                errors.append("xlrd: a munkafüzet nem tartalmaz olvasható lapot")
            except Exception as exc:
                errors.append(f"xlrd: {exc}")
        else:
            errors.append(xlrd_note)

        # Opcionális calamine fallback.
        try:
            sheets = pd.read_excel(
                io.BytesIO(data),
                sheet_name=None,
                header=header,
                engine="calamine",
            )
            if sheets:
                return sheets
        except Exception as exc:
            errors.append(f"calamine: {exc}")

        # Helyi gépen / megfelelő szerveren LibreOffice fallback.
        office = shutil.which("libreoffice") or shutil.which("soffice")
        if office:
            try:
                with tempfile.TemporaryDirectory(prefix="fpi_xls_") as temp_dir:
                    temp_path = Path(temp_dir)
                    safe_name = Path(file_name).name or "polar_import.xls"
                    input_path = temp_path / safe_name
                    input_path.write_bytes(data)

                    result = subprocess.run(
                        [
                            office,
                            "--headless",
                            "--convert-to", "xlsx",
                            "--outdir", str(temp_path),
                            str(input_path),
                        ],
                        capture_output=True,
                        text=True,
                        timeout=90,
                        check=False,
                    )
                    converted = temp_path / f"{input_path.stem}.xlsx"
                    if converted.exists():
                        sheets = pd.read_excel(
                            converted,
                            sheet_name=None,
                            header=header,
                            engine="openpyxl",
                        )
                        if sheets:
                            return sheets
                    errors.append(
                        "LibreOffice: "
                        + (result.stderr.strip() or result.stdout.strip() or "nem készült konvertált fájl")
                    )
            except Exception as exc:
                errors.append(f"LibreOffice: {exc}")

        raise ValueError(
            "A régi Polar .xls fájl megnyitható, de a futtatókörnyezet nem tudja "
            "feldolgozni. Telepítsd az `xlrd>=2.0.1` csomagot a requirements.txt-ben, "
            "vagy mentsd a fájlt .xlsx formátumba. Részletek: "
            + " | ".join(errors[-5:])
        )

    # Modern Excel formátumok.
    attempts = [
        {"engine": "openpyxl"},
        {"engine": "calamine"},
        {},
    ]
    for kwargs in attempts:
        try:
            sheets = pd.read_excel(
                io.BytesIO(data),
                sheet_name=None,
                header=header,
                **kwargs,
            )
            if sheets:
                return sheets
        except Exception as exc:
            errors.append(f"{kwargs.get('engine', 'automatikus')}: {exc}")

    raise ValueError(
        "Az Excel fájl nem olvasható. " + " | ".join(errors[-4:])
    )

def _fpi_read_single_gps_file_v143(
    uploaded_file,
    forced_type: Optional[str] = None,
    provider_override: str = "Automatikus felismerés",
) -> Tuple[Dict[str, pd.DataFrame], List[Dict[str, object]]]:
    name = str(getattr(uploaded_file, "name", "gps_file"))
    data = _fpi_bytes_from_upload_v143(uploaded_file)
    ext = Path(name).suffix.lower()
    report = []
    if not data:
        return {}, [{"Fájl": name, "Státusz": "HIBA", "Rendszer": "", "Sorok": 0, "Megjegyzés": "Üres fájl"}]

    if ext == ".zip":
        sheets = {}
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as zf:
                for member in zf.namelist():
                    if member.endswith("/") or member.startswith("__MACOSX/"):
                        continue
                    m_ext = Path(member).suffix.lower()
                    if m_ext not in {".xlsx", ".xls", ".xlsm", ".csv"}:
                        continue
                    member_bytes = zf.read(member)
                    pseudo = type("FPIUpload", (), {
                        "name": Path(member).name,
                        "getvalue": lambda self, b=member_bytes: b,
                    })()
                    inner_sheets, inner_report = _fpi_read_single_gps_file_v143(
                        pseudo,
                        forced_type=forced_type,
                        provider_override=provider_override,
                    )
                    for key, frame in inner_sheets.items():
                        sheets[f"{Path(member).stem}__{key}"] = frame
                    for row in inner_report:
                        row["Fájl"] = member
                        report.append(row)
            return sheets, report
        except Exception as exc:
            return {}, [{"Fájl": name, "Státusz": "HIBA", "Rendszer": "", "Sorok": 0, "Megjegyzés": str(exc)}]

    try:
        if ext == ".csv":
            raw_sheets = {"CSV": _fpi_read_csv_bytes_v143(data, name)}
        elif ext in {".xlsx", ".xlsm", ".xls"}:
            raw_sheets = _fpi_read_excel_bytes_v165(
                data,
                name,
                header=None,
            )
        else:
            return {}, [{"Fájl": name, "Státusz": "KIHAGYVA", "Rendszer": "", "Sorok": 0, "Megjegyzés": "Nem támogatott kiterjesztés"}]

        provider = provider_override if provider_override != "Automatikus felismerés" else _fpi_detect_provider_v143(raw_sheets, name)
        prepared = pd.DataFrame()
        if provider == "Brainsports":
            prepared = _fpi_prepare_brainsports_v143(raw_sheets, forced_type, name)
        elif provider == "PlayerTek":
            raw = next(iter(raw_sheets.values()), pd.DataFrame())
            prepared = _fpi_prepare_playertek_v143(raw, forced_type, name)
        elif provider == "Polar Team Pro":
            prepared = _fpi_prepare_polar_v143(raw_sheets, forced_type, name)
        elif provider == "Catapult":
            prepared = _fpi_prepare_catapult_vector_v160(raw_sheets, forced_type, name)
            if prepared.empty:
                prepared = _fpi_prepare_catapult_v143(raw_sheets, forced_type, name)

        if not prepared.empty:
            barin_meta = dict(prepared.attrs.get("fpi_barin_import", {}) or {})
            prepared, v200_report = _fpi_v200_universal_postprocess(
                prepared,
                provider=provider,
                file_name=name,
            )
            key = f"{Path(name).stem}__{v200_report.get('provider', provider)}"
            report_row = _fpi_v200_report_row(name, v200_report, status="OK")

            if provider == "Brainsports" and barin_meta:
                selected_count = int(barin_meta.get("selected_sheet_count", 0) or 0)
                total_count = int(barin_meta.get("workbook_sheet_count", 0) or 0)
                detected_sessions = int(barin_meta.get("detected_sessions", 0) or 0)
                selected_names = barin_meta.get("selected_sheets", []) or []
                preview = ", ".join(str(x) for x in selected_names[:5])
                if len(selected_names) > 5:
                    preview += f", +{len(selected_names) - 5} további"
                report_row["Megjegyzés"] += (
                    f" | Barin multi-sheet: {selected_count}/{total_count} lap kiválasztva"
                    f" | Felismert sessionök: {detected_sessions}"
                    + (f" | Használt lapok: {preview}" if preview else "")
                )

            return {key: prepared}, [report_row]

        # Polar esetén az üres eredmény ne vesszen el néma Smart Mapper fallbackben.
        if provider == "Polar Team Pro":
            sheet_shapes = ", ".join(
                f"{sheet_name}: {frame.shape[0]}x{frame.shape[1]}"
                for sheet_name, frame in raw_sheets.items()
                if isinstance(frame, pd.DataFrame)
            )
            return {}, [{
                "Fájl": name,
                "Státusz": "HIBA",
                "Rendszer": provider,
                "Sorok": 0,
                "Megjegyzés": (
                    "A Polar munkafüzet megnyílt, de az Összegzés fejlécét nem sikerült "
                    "standardizálni. Lapok: " + (sheet_shapes or "nincs olvasható lap")
                ),
            }]

        # V200 generic fallback: először automatikus standardizálás minden lapon.
        generic = {}
        generic_reports = []
        for sheet_name, raw in raw_sheets.items():
            if raw is None or raw.empty:
                continue
            try:
                standardized, _mapping, missing_core = standardize_dataframe(raw)
            except Exception:
                standardized, missing_core = pd.DataFrame(), ["standardizálási hiba"]

            if not standardized.empty and not missing_core:
                standardized, v200_report = _fpi_v200_universal_postprocess(
                    standardized,
                    provider=provider,
                    file_name=f"{name} / {sheet_name}",
                )
                generic[f"{Path(name).stem}__{sheet_name}"] = standardized
                generic_reports.append(v200_report)
            else:
                # Ha nem standardizálható, megmarad a Smart Mapper számára.
                generic[f"{Path(name).stem}__{sheet_name}"] = raw

        if generic_reports:
            best_report = max(
                generic_reports,
                key=lambda item: (item.get("quality_score", 0), item.get("rows", 0)),
            )
            return generic, [
                _fpi_v200_report_row(name, best_report, status="OK")
            ]

        fallback_rows = sum(len(x) for x in generic.values())
        return generic, [{
            "Fájl": name,
            "Státusz": "MAPPER",
            "Rendszer": provider,
            "Sorok": fallback_rows,
            "Import minőség": "",
            "Játékosok": "",
            "Hetek": "",
            "Edzés sor": "",
            "Meccs sor": "",
            "Megjegyzés": "V200 nem talált biztonságosan standardizálható lapot; Smart Mapper szükséges",
        }]
    except Exception as exc:
        inferred_system = "Polar Team Pro" if "polar" in name.lower() else ""
        return {}, [{
            "Fájl": name,
            "Státusz": "HIBA",
            "Rendszer": inferred_system,
            "Sorok": 0,
            "Megjegyzés": str(exc),
        }]


def _fpi_read_many_gps_files_v143(
    training_files: Optional[List[object]],
    match_files: Optional[List[object]],
    mixed_files: Optional[List[object]],
    provider_override: str = "Automatikus felismerés",
) -> Tuple[Dict[str, pd.DataFrame], pd.DataFrame, str]:
    all_sheets: Dict[str, pd.DataFrame] = {}
    rows: List[Dict[str, object]] = []
    signature_parts = []

    groups = [
        ("Edzés", training_files or []),
        ("Meccs", match_files or []),
        (None, mixed_files or []),
    ]
    for forced_type, files in groups:
        for upload in files:
            name = str(getattr(upload, "name", "gps_file"))
            data = _fpi_bytes_from_upload_v143(upload)
            signature_parts.append(f"{forced_type}:{name}:{len(data)}:{hashlib.md5(data[:200000]).hexdigest() if data else ''}")
            sheets, report = _fpi_read_single_gps_file_v143(
                upload,
                forced_type=forced_type,
                provider_override=provider_override,
            )
            for key, frame in sheets.items():
                unique = key
                counter = 2
                while unique in all_sheets:
                    unique = f"{key}_{counter}"
                    counter += 1

                frame_with_source = frame.copy()
                frame_with_source["_fpi_source_file"] = name
                frame_with_source["_fpi_source_key"] = unique
                frame_with_source["_fpi_upload_group"] = forced_type or "Vegyes"
                all_sheets[unique] = frame_with_source
            for row in report:
                row["Import típus"] = forced_type or "Vegyes / fájlból"
                rows.append(row)

    if all_sheets:
        combined_parts = []
        for key, frame in all_sheets.items():
            part = frame.copy()
            part["_fpi_v407_frame_key"] = key
            part["_fpi_v407_row_order"] = np.arange(len(part))
            combined_parts.append(part)
        combined = pd.concat(combined_parts, ignore_index=True, sort=False)
        combined = _fpi_v407_apply_filename_md_inference(combined)
        rebuilt = {}
        for key, group in combined.groupby("_fpi_v407_frame_key", sort=False):
            rebuilt[str(key)] = group.sort_values("_fpi_v407_row_order").drop(columns=["_fpi_v407_frame_key", "_fpi_v407_row_order"], errors="ignore").reset_index(drop=True)
        all_sheets = rebuilt
    return all_sheets, pd.DataFrame(rows), hashlib.md5("|".join(signature_parts).encode("utf-8")).hexdigest()


def _fpi_team_level_tactical_messages_v143(
    tactical_context: Dict[str, object],
    tactical_msgs: List[str],
    limit: int = 4,
) -> List[str]:
    opponent_players = []
    for row in (tactical_context or {}).get("opponent_player_evaluation", []) or []:
        name = str(row.get("Játékos", "")).strip().lower()
        if name:
            opponent_players.append(name)

    cleaned = []
    for msg in tactical_msgs or []:
        text = _fpi_clean_sentence_v82(str(msg), 180)
        low = text.lower()
        if any(name in low for name in opponent_players):
            continue
        if text and text not in cleaned:
            cleaned.append(text)

    if not cleaned:
        plan = str((tactical_context or {}).get("plan_a", "KIE – kiegyensúlyozott meccsterv"))
        cleaned = [
            f"Csapatszintű alapirány: {plan}.",
            "A blokk-, presszing- és átmeneti viselkedést egységes csapatelvekkel kell végrehajtani.",
            "A labdavesztés utáni biztosítás és a második labdák kontrollja legyen közös csapatszintű prioritás.",
        ]
    return cleaned[:limit]



# =========================================================
# V144 - Magyar szakmai nyelvi és kontextusmotor
# =========================================================
def _fpi_hu_plain_text_v144(value: object) -> str:
    text = str(value or "")
    text = re.sub(r"(?i)<br\s*/?>", "\n", text)
    text = re.sub(r"(?i)</?b>", "", text)
    text = text.replace("&nbsp;", " ")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    replacements = {
        "pressing": "letámadás",
        "presszing": "letámadás",
        "transition": "átmenet",
        "rest defense": "labdavesztés elleni biztosítás",
        "build-up": "labdakihozatal",
        "high block": "magas védekezés",
        "mid block": "középső védekezési blokk",
        "low block": "mély védekezési blokk",
        "wide play": "szélső játék",
        "half-space": "félterület",
        "second ball": "második labda",
        "counterpress": "visszatámadás",
        "counter-press": "visszatámadás",
    }
    for source, target in replacements.items():
        text = re.sub(rf"(?i)\b{re.escape(source)}\b", target, text)
    return text.strip()


def _fpi_context_seed_v144(
    tactical_context: Optional[Dict[str, object]],
    week: Optional[str],
    readiness: Optional[int],
) -> int:
    ctx = tactical_context or {}
    opponent = str(
        ctx.get("opponent_name")
        or st.session_state.get("clean_opponent_v94", "")
        or st.session_state.get("fpi_match_context_v94", {}).get("opponent", "")
    )
    source = "|".join([
        str(week or ""),
        opponent,
        str(ctx.get("plan_a", "")),
        str(ctx.get("plan_b", "")),
        str(ctx.get("own_topics", "")),
        str(ctx.get("opp_topics", "")),
        str(readiness or ""),
    ])
    return int(hashlib.md5(source.encode("utf-8")).hexdigest()[:8], 16)


def _fpi_rotate_v144(items: List[str], seed: int) -> List[str]:
    clean_items = [x for x in items if str(x).strip()]
    if not clean_items:
        return []
    shift = seed % len(clean_items)
    return clean_items[shift:] + clean_items[:shift]


def _fpi_tactical_features_v144(tactical_context: Optional[Dict[str, object]]) -> Dict[str, object]:
    ctx = tactical_context or {}
    all_text = " ".join([
        str(ctx.get("plan_a", "")),
        str(ctx.get("plan_b", "")),
        " ".join(map(str, ctx.get("risks", []) or [])),
        " ".join(map(str, ctx.get("tactical_findings", []) or [])),
        " ".join(map(str, ctx.get("own_topics", []) or [])),
        " ".join(map(str, ctx.get("opp_topics", []) or [])),
        " ".join(map(str, ctx.get("pdf_provider_findings", []) or [])),
    ]).lower()

    def has(*terms):
        return any(term.lower() in all_text for term in terms)

    return {
        "high_press": has("magas letámadás", "high press", "mlt", "presszing", "letámadás"),
        "mid_block": has("középső blokk", "mid block", "bat"),
        "deep_block": has("mély blokk", "low block", "kon"),
        "transition": has("átmenet", "transition", "kontra", "gat", "bat"),
        "possession": has("dominancia", "labdabirtoklás", "pozíciós", "dom", "poz", "lab"),
        "wide": has("szélső", "beadás", "oldali", "wide", "wing"),
        "central": has("középső", "félterület", "vonalak között", "central", "half-space"),
        "set_piece": has("pontrúgás", "szöglet", "szabadrúgás", "set piece"),
        "build_up": has("labdakihozatal", "építkezés", "build-up", "build up"),
        "second_ball": has("második labda", "second ball", "direkt játék"),
        "plan": _fpi_hu_plain_text_v144(ctx.get("plan_a", "KIE – kiegyensúlyozott meccsterv")),
    }


def _fpi_team_level_tactical_messages_v144(
    tactical_context: Optional[Dict[str, object]],
    gps_context: Optional[Dict[str, object]],
    readiness: int,
    priorities: Optional[List[dict]],
    week: Optional[str],
    limit: int = 3,
) -> List[str]:
    ctx = tactical_context or {}
    features = _fpi_tactical_features_v144(ctx)
    seed = _fpi_context_seed_v144(ctx, week, readiness)
    opponent = str(
        ctx.get("opponent_name")
        or st.session_state.get("clean_opponent_v94", "")
        or st.session_state.get("fpi_match_context_v94", {}).get("opponent", "")
        or "az ellenfél"
    )

    candidates: List[Tuple[str, str]] = []
    plan = features["plan"]
