# V150 - Executive vizuális hierarchia és automatikus kiemelőmotor
# =========================================================
FPI_HIGHLIGHT_TERMS_V150 = [
    # taktikai zónák és akciók
    "bal oldal", "jobb oldal", "félterület", "középső blokk", "mély blokk",
    "magas letámadás", "letámadás", "visszatámadás", "átmenet", "támadó átmenet",
    "védekező átmenet", "második labda", "labdakihozatal", "labdavesztés",
    "labdaszerzés", "mélységi futás", "oldalváltás", "visszagurítás", "beadás",
    "pontrúgás", "hosszú oldal", "belső passzsáv", "vonalak között",
    "szélső játék", "direkt játék", "pozíciós játék", "kontra", "kontrák",
    # erőnléti fogalmak
    "Readiness", "készenlét", "frissesség", "sprint", "sprintterhelés",
    "sprintexpozíció", "HSR", "nagy sebességű futás", "High Efforts",
    "nagy intenzitású akció", "Load", "terhelési pont", "össztáv", "volumen",
    "négyhetes trend", "4 hetes trend", "regeneráció", "gyorsítás", "lassítás",
    "kockázat", "benchmark", "referencia", "alulterhelés", "túlterhelés",
    # döntési szavak
    "fő veszély", "kulcsjátékos", "kulcsember", "támadási cél", "védekezési cél",
    "elsődleges cél", "fő prioritás", "kiemelt figyelem", "alacsony", "közepes", "magas",
]


def _fpi_highlight_numbers_v150(text: str) -> str:
    """A százalékok, pontszámok és pozitív/negatív eltérések automatikus kiemelése."""
    patterns = [
        r"(?<![\w>])[-+]?\d+(?:[.,]\d+)?\s*%",
        r"(?<![\w>])\d{1,3}\s*/\s*100",
        r"(?<![\w>])[-+]?\d+(?:[.,]\d+)?\s*(?:m|km|m/min|km/h|perc|nap|hét)\b",
    ]
    out = text
    for pattern in patterns:
        out = re.sub(
            pattern,
            lambda m: f"<b>{m.group(0)}</b>" if "<b>" not in m.group(0) else m.group(0),
            out,
            flags=re.IGNORECASE,
        )
    return out


def _fpi_highlight_terms_v150(text: object, max_highlights: int = 5) -> str:
    """
    A kifejtésen belül is kiemeli a legfontosabb fogalmakat.
    Nem vastagít mindent: egy bekezdésben legfeljebb néhány kulcsrészletet.
    """
    clean = _fpi_strip_raw_repr_v146(_fpi_extract_coach_text_v145(text, 900))
    if not clean:
        return ""

    escaped = pdf_safe_text(clean)
    protected = []
    count = 0

    # Hosszabb kifejezések előbb, hogy ne törjük szét őket.
    terms = sorted(FPI_HIGHLIGHT_TERMS_V150, key=len, reverse=True)
    for term in terms:
        if count >= max_highlights:
            break
        pattern = re.compile(rf"(?i)(?<![\wáéíóöőúüű])({re.escape(term)})(?![\wáéíóöőúüű])")
        if pattern.search(escaped):
            placeholder = f"@@FPIHL{len(protected)}@@"
            escaped = pattern.sub(placeholder, escaped, count=1)
            protected.append(f"<b>{term}</b>")
            count += 1

    escaped = _fpi_highlight_numbers_v150(escaped)

    for idx, replacement in enumerate(protected):
        escaped = escaped.replace(f"@@FPIHL{idx}@@", replacement)

    return escaped


def _fpi_emphasize_message_v150(text: object, max_len: int = 460) -> str:
    """
    Rövid cím + a magyarázó mondatban is 2–5 kiemelt szó/kifejezés.
    """
    clean = _fpi_strip_raw_repr_v146(_fpi_extract_coach_text_v145(text, max_len))
    if not clean:
        return ""

    if ":" in clean:
        head, rest = clean.split(":", 1)
        head = head.strip()
        rest = rest.strip()
        if 1 <= len(head.split()) <= 6:
            return f"<b>{pdf_safe_text(head)}:</b> {_fpi_highlight_terms_v150(rest, 5)}"

    sentences = re.split(r"(?<=[.!?])\s+", clean, maxsplit=1)
    if len(sentences) == 2 and len(sentences[0]) <= 105:
        return f"<b>{pdf_safe_text(sentences[0])}</b><br/>{_fpi_highlight_terms_v150(sentences[1], 5)}"

    return _fpi_highlight_terms_v150(clean, 5)


def _fpi_key_messages_v150(
    tactical_insights: List[FPIInsightV146],
    match_plan_insights: List[FPIInsightV146],
    fitness_insights: List[FPIInsightV146],
    opponent_players: Optional[List[dict]] = None,
    minimum: int = 3,
    maximum: int = 5,
) -> List[Tuple[str, str, str]]:
    """
    3–5 különböző témájú vezetői kulcsüzenet.
    Visszatér: ikon, rövid cím, rövid üzenet.
    """
    candidates: List[Tuple[str, str, str, int]] = []
    used_topics = set()

    icon_map = {
        "vedekezesi_zona": "🛡",
        "tamadasi_zona": "⚽",
        "veszelyes_jatekos": "⚠",
        "masodik_veszely": "⚠",
        "sajat_kulcsember": "👤",
        "sebesseg": "📈",
        "readiness": "📈",
        "terheles": "📊",
        "atmenet": "🔄",
        "szelso": "↔",
        "kozepso": "🎯",
        "pontrugas": "🎯",
    }

    def add_from(items, source_priority):
        for item in items or []:
            topic = str(getattr(item, "topic", "") or "egyeb")
            if topic in used_topics:
                continue
            title = str(getattr(item, "title", "") or "Kulcsüzenet")
            finding = str(getattr(item, "finding", "") or "")
            recommendation = str(getattr(item, "recommendation", "") or "")
            message = finding.strip()
            if recommendation:
                message = f"{message} {recommendation}".strip()
            message = _fpi_clean_sentence_v82(message, 190)
            if not message:
                continue
            icon = icon_map.get(topic, "◆")
            priority = int(getattr(item, "priority", 50) or 50) + source_priority
            candidates.append((icon, title, message, priority, topic))

    add_from(match_plan_insights, 25)
    add_from(tactical_insights, 15)
    add_from(fitness_insights, 5)

    # Ha van ellenfél-játékosadat, legalább egy játékosüzenet lehetőleg kerüljön be.
    if opponent_players:
        for row in opponent_players[:2]:
            if not isinstance(row, dict):
                continue
            name = str(row.get("Játékos", "")).strip()
            role = _fpi_extract_coach_text_v145(row.get("Szerep", ""), 60)
            eval_text = _fpi_extract_coach_text_v145(row.get("Értelmezés", ""), 120)
            if name:
                candidates.append((
                    "👤",
                    "Ellenfél-kulcsember",
                    _fpi_clean_sentence_v82(f"{name} ({role}): {eval_text}", 175),
                    92,
                    f"player_{name.lower()}",
                ))

    selected = []
    seen_topics = set()
    seen_texts = []
    for icon, title, message, priority, topic in sorted(candidates, key=lambda x: x[3], reverse=True):
        if topic in seen_topics:
            continue
        if _fpi_is_near_duplicate_v145(message, seen_texts, 0.72):
            continue
        selected.append((icon, title, message))
        seen_topics.add(topic)
        seen_texts.append(message)
        if len(selected) >= maximum:
            break

    # Biztonsági feltöltés 3 üzenetig.
    fallback = [
        ("🛡", "Védekezési irány", "A védekezési magasságot és a labda terelésének oldalát előre rögzítsük."),
        ("⚽", "Támadási irány", "Az elsődleges támadási zónát és a keresendő játékost tudatosan jelöljük ki."),
        ("📈", "Erőnléti fókusz", "A heti terhelési döntést a készenlét, a sebességi inger és a regeneráció együtt határozza meg."),
    ]
    for item in fallback:
        if len(selected) >= minimum:
            break
        if not _fpi_is_near_duplicate_v145(item[2], [x[2] for x in selected], 0.70):
            selected.append(item)

    return selected[:maximum]


def _fpi_key_messages_table_v150(
    messages: List[Tuple[str, str, str]],
    P,
    head_style,
    body_style,
):
    rows = [[P("KULCSÜZENETEK – 5 MÁSODPERCES ÁTTEKINTÉS", head_style)]]
    for icon, title, message in messages:
        rows.append([
            P(
                f"<b>{pdf_safe_text(icon)} {pdf_safe_text(title)}:</b> "
                f"{_fpi_highlight_terms_v150(message, 4)}",
                body_style,
            )
        ])
    obj = Table(rows, colWidths=[27.7*cm])
    style = [
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#92400E")),
        ("TEXTCOLOR", (0,0), (-1,0), colors.white),
        ("BACKGROUND", (0,1), (-1,-1), colors.HexColor("#FFFBEB")),
        ("BOX", (0,0), (-1,-1), 1.0, colors.HexColor("#F59E0B")),
        ("INNERGRID", (0,1), (-1,-1), 0.4, colors.HexColor("#FDE68A")),
        ("LEFTPADDING", (0,0), (-1,-1), 10),
        ("RIGHTPADDING", (0,0), (-1,-1), 10),
        ("TOPPADDING", (0,0), (-1,-1), 7),
        ("BOTTOMPADDING", (0,0), (-1,-1), 7),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
    ]
    obj.setStyle(TableStyle(style))
    return obj



# =========================================================
# V151 - Magyar profi scoutingnyelv és tömör döntési lánc
# =========================================================
FPI_FOOTBALL_LANGUAGE_MAP_V151 = [
    ("oldali veszély", "szélső veszély"),
    ("oldali játék", "szélső játék"),
    ("oldali védekezés", "szélső védekezés"),
    ("oldali kombináció", "szélső kombináció"),
    ("oldali 1v1 kontroll", "szélső párharcok kontrollja"),
    ("beadásblokkolás", "a beadások megakadályozása"),
    ("hosszú oldali zárás", "a hosszú oldal biztosítása"),
    ("aktív befejező", "rendszeresen kerül lövőhelyzetbe"),
    ("kapura veszélyes", "gyakran kerül kapu elé"),
    ("más típusú veszélyt jelent", "más módon veszélyes"),
    ("felvétel korlátozása", "labdaátvételének korlátozása"),
    ("Boxon belüli", "tizenhatoson belüli"),
    ("boxon belüli", "tizenhatoson belüli"),
    ("rest defense", "labdavesztés elleni biztosítás"),
    ("presszing", "letámadás"),
    ("pressing", "letámadás"),
    ("build-up", "labdakihozatal"),
    ("half-space", "félterület"),
    ("second ball", "második labda"),
    ("high block", "magas védekezési blokk"),
    ("mid block", "középső védekezési blokk"),
    ("low block", "mély védekezési blokk"),
]


def _fpi_pro_football_hu_v151(value: object) -> str:
    text = _fpi_hu_plain_text_v144(value)
    for source, target in FPI_FOOTBALL_LANGUAGE_MAP_V151:
        text = re.sub(re.escape(source), target, text, flags=re.IGNORECASE)

    # Gyakori nyers exportnyelvi töredékek tisztítása.
    text = re.sub(r"(?i)\bjelentős száma\b", "magas gyakorisága", text)
    text = re.sub(r"(?i)\bjó kreatív kapcsolódási pont\b", "a támadások egyik fő összekötő játékosa", text)
    text = re.sub(r"(?i)\btöbb kulcspasszal\b", "rendszeresen készít elő helyzetet", text)
    text = re.sub(r"(?i)\bkapura veszélyes játékos\b", "befejező játékos", text)
    text = re.sub(r"(?i)\bszélső / beadó veszély\b", "szélső, beadásokból veszélyes", text)
    text = re.sub(r"(?i)\bbefejező / kapura veszélyes játékos\b", "befejező, rendszeresen kerül helyzetbe", text)
    text = re.sub(r"\s+([,.;:])", r"\1", text)
    text = re.sub(r"\s{2,}", " ", text).strip()
    if text:
        text = text[0].upper() + text[1:]
    return text


def _fpi_complete_text_v151(value: object) -> str:
    """Eltávolítja a korábbi levágások maradványait és teljes gondolatot őriz meg."""
    text = _fpi_pro_football_hu_v151(value)
    text = text.replace("…", "")
    text = re.sub(r"\.{3,}", ".", text)
    return text.strip(" ;")


def _fpi_role_v151(value: object) -> str:
    role = _fpi_pro_football_hu_v151(value)
    role_map = {
        "Befejező / kapura veszélyes játékos": "Befejező, rendszeresen kerül helyzetbe",
        "Szélső / beadó veszély": "Szélső, beadásokból veszélyes",
        "Kreatív kulcsjátékos": "Kreatív szervező",
        "Progresszív kulcsjátékos": "Progresszív összekötő",
        "Labdafelvivő": "Labdával területet nyerő játékos",
        "Stabil szerepjátékos": "Stabil szerkezeti játékos",
    }
    return role_map.get(role, role)


def _fpi_player_eval_v151(row: dict) -> Tuple[str, str, str, str]:
    name = str(row.get("Játékos", "")).strip()
    role = _fpi_role_v151(row.get("Szerep", ""))
    evaluation = _fpi_complete_text_v151(row.get("Értelmezés", ""))
    action = _fpi_complete_text_v151(row.get("Javaslat", ""))

    # Scouting-kompatibilis, pályán használható megfogalmazások.
    low = f"{role} {evaluation} {action}".lower()
    if "beadás" in low or "szélső" in low:
        action = action or "A labdaátvétel előtt szűkítsük a területét; ne engedjük lendületből az alapvonal felé fordulni."
    elif "befejez" in low or "löv" in low or "helyzet" in low:
        action = action or "A tizenhatos előterében ne kapjon tiszta testhelyzetet; a második labdáknál maradjon szoros kontroll alatt."
    elif "kreat" in low or "kulcspassz" in low:
        action = action or "A labdaátvételét a vonalak között korlátozzuk, és a következő passzirányát már az átvétel előtt zárjuk."
    elif "progressz" in low or "labdával" in low:
        action = action or "A labdával történő előrehaladását oldalra tereléssel és korai nyomással lassítsuk."

    return name, role, evaluation, action


def _fpi_arrow_chain_v151(title: str, observation: str, response: str) -> str:
    observation = _fpi_complete_text_v151(observation).rstrip(".")
    response = _fpi_complete_text_v151(response).rstrip(".")
    return f"{title}: {observation} → {response}"


def _fpi_pro_tactical_findings_v151(
    tactical_context: Optional[Dict[str, object]],
    gps_context: Optional[Dict[str, object]],
    readiness: int,
    priorities: Optional[List[dict]],
    week: Optional[str],
    limit: int = 7,
) -> List[FPIInsightV146]:
    ctx = tactical_context or {}
    features = _fpi_tactical_features_v144(ctx)
    opponent = _fpi_opponent_name_v145(ctx)
    pool: List[FPIInsightV146] = []

    # A nyers forrásból csak teljes, értelmezhető scoutingkövetkeztetés kerülhet be.
    # Az "Edzői megállapítás", önálló gondolatjel és félkész exporttöredék nem jelenhet meg.
    for key in ["risks", "tactical_findings", "pdf_provider_findings", "opp_topics"]:
        for raw in ctx.get(key, []) or []:
            insight = _fpi_normalize_any_insight_v146(raw)
            if not insight:
                continue

            title = _fpi_tactical_pdf_text_v157(insight.title or "")
            finding = _fpi_tactical_pdf_text_v157(insight.finding)
            recommendation = _fpi_tactical_pdf_text_v157(insight.recommendation)

            if title.lower() in {
                "", "edzöi megállapítás", "edzői megállapítás",
                "taktikai megállapítás", "megállapítás"
            }:
                continue
            if not finding or finding in {"—", "-", "–"}:
                continue
            if not recommendation and len(finding.split()) < 7:
                continue

            candidate = FPIInsightV146(
                topic=f"source_{insight.topic}",
                title=title,
                finding=finding,
                recommendation=recommendation,
                priority=max(82, insight.priority),
            )
            if _fpi_valid_tactical_insight_v157(candidate):
                pool.append(candidate)

    if features["transition"]:
        pool.append(FPIInsightV146(
            "atmenet", "Átmeneti veszély",
            f"{opponent} labdaszerzés után az első vagy második passzal mélységet keres.",
            "Labda mögötti biztosítás és az első előrepassz zárása; csak rendezett helyzetből induljon visszatámadás.",
            priority=97,
        ))
    if features["wide"]:
        pool.append(FPIInsightV146(
            "szelso", "Szélső veszély",
            f"{opponent} a szélső zónából és beadásokból rendszeresen alakít ki kapu előtti helyzetet.",
            "A szélső labdaátvételét már az átvétel előtt szűkítsük; a túloldali érkezést és a tizenhatos előtti visszagurítást külön kontrolláljuk.",
            priority=95,
        ))
    if features["central"]:
        pool.append(FPIInsightV146(
            "kozepso", "Belső kapcsolatok",
            f"{opponent} a középpályás és védősor közötti területből gyorsítja fel a támadásait.",
            "Az átvevő játékos mögötti passzkapcsolatot zárjuk, és a következő mélységi futást a belső védő biztosítsa.",
            priority=94,
        ))
    if features["second_ball"]:
        pool.append(FPIInsightV146(
            "masodik_labda", "Második labdák",
            f"{opponent} direkt játékánál a lepattanók megszerzéséből tartja fenn a támadást.",
            "A párharc körüli területet előre töltsük fel; a középpályás sor a fejpárbaj pillanatában már a várható második labdára zárjon.",
            priority=92,
        ))
    if features["build_up"]:
        pool.append(FPIInsightV146(
            "labdakihozatal", "Első építési vonal",
            f"{opponent} letámadása a belső passzsáv lezárására épül.",
            "A kijátszás elsődleges pontja a szélső védő mögötti vagy a védekező középpályás melletti szabad terület legyen; ne általános labdajáratásból próbáljuk bontani.",
            priority=89,
        ))
    if features["set_piece"]:
        pool.append(FPIInsightV146(
            "pontrugas", "Pontrúgás utáni második akció",
            f"{opponent} a pontrúgások utáni lepattanókból is újra támad.",
            "A felszabadítás iránya és a tizenhatos előtti terület kontrollja fontosabb, mint az azonnali teljes kilépés.",
            priority=86,
        ))

    selected, used = [], set()
    for item in sorted(pool, key=lambda x: x.priority, reverse=True):
        if item.topic in used:
            continue
        selected.append(item)
        used.add(item.topic)
        if len(selected) >= limit:
            break
    return selected


def _fpi_pro_match_plan_v151(
    tactical_context: Optional[Dict[str, object]],
    gps_context: Optional[Dict[str, object]],
    readiness: int,
    priorities: Optional[List[dict]],
    week: Optional[str],
    limit: int = 6,
) -> List[FPIInsightV146]:
    ctx = tactical_context or {}
    features = _fpi_tactical_features_v144(ctx)
    opponent = _fpi_opponent_name_v145(ctx)
    opp_players = ctx.get("opponent_player_evaluation", []) or []
    own_players = ctx.get("own_player_evaluation", []) or []
    pool: List[FPIInsightV146] = []

    # Hol védekezzünk? – nem alapelv, hanem ellenfélprofilból következő döntés.
    if features["transition"] and features["mid_block"]:
        pool.append(FPIInsightV146(
            "vedekezesi_zona", "Védekezési magasság",
            f"{opponent} gyors átmenetei miatt a középső védekezési blokk kedvezőbb, mint a folyamatos magas letámadás.",
            "A labdát oldalra tereljük, a középső sávban ne adjunk első érintésből előrejátékot.",
            priority=99,
        ))
    elif features["high_press"] and features["build_up"]:
        pool.append(FPIInsightV146(
            "vedekezesi_zona", "Letámadási zóna",
            f"{opponent} első építési fázisa nyomás alatt támadható.",
            "A letámadást a visszapasszra vagy a szélső védő zárt testhelyzetű átvételére időzítsük; a cél a labdaszerzés a szélső sávban.",
            priority=99,
        ))
    else:
        pool.append(FPIInsightV146(
            "vedekezesi_zona", "Védekezési zóna",
            f"{opponent} ellen a középső harmad kontrollja adja a legjobb kockázat–hozam arányt.",
            "A támadásépítést az egyik oldalra tereljük, és ott hozzunk létre létszámfölényt a labda körül.",
            priority=91,
        ))

    # Hol támadjunk?
    if features["wide"]:
        pool.append(FPIInsightV146(
            "tamadasi_zona", "Támadási célterület",
            f"{opponent} szélső védekezése a második mozgásra és a gyors visszaforgatásra érzékeny.",
            "Első akcióval kössük le a szélső védőt, majd a félterületi visszagurítást vagy a túloldali érkezést keressük.",
            priority=98,
        ))
    elif features["central"] or features["possession"]:
        pool.append(FPIInsightV146(
            "tamadasi_zona", "Támadási célterület",
            f"{opponent} középpályás és védősora között nyílhat a legértékesebb fogadóterület.",
            "A vonalak között átvett labda után azonnal mélységi futás vagy harmadik játékoshoz történő kapcsolat következzen.",
            priority=98,
        ))
    else:
        pool.append(FPIInsightV146(
            "tamadasi_zona", "Támadási irány",
            f"{opponent} visszarendeződésekor a gyenge oldal maradhat üresen.",
            "Labdaszerzés után az első döntés a gyors oldalváltás vagy a védők mögötti szélső terület támadása legyen.",
            priority=93,
        ))

    # Ellenfél kulcsemberei.
    for idx, row in enumerate(opp_players[:2]):
        if not isinstance(row, dict):
            continue
        name, role, evaluation, action = _fpi_player_eval_v151(row)
        if not name:
            continue
        pool.append(FPIInsightV146(
            "veszelyes_jatekos" if idx == 0 else "masodik_veszely",
            "Elsődleges ellenfélfókusz" if idx == 0 else "Másodlagos ellenfélfókusz",
            f"{name} – {role}. {evaluation}",
            action,
            priority=100 - idx * 3,
        ))

    # Saját kulcsjátékos – csak ha az input ténylegesen megnevez valakit.
    for row in own_players[:1]:
        if not isinstance(row, dict):
            continue
        name = str(row.get("Játékos", "")).strip()
        role = _fpi_role_v151(row.get("Szerep", ""))
        evaluation = _fpi_complete_text_v151(row.get("Értelmezés", ""))
        if name:
            pool.append(FPIInsightV146(
                "sajat_kulcsember", "Saját kapcsolópont",
                f"{name} – {role}. {evaluation}",
                "Az első két építési fázisban és labdaszerzés után tudatosan keressük a számára kedvező fogadóterületet.",
                priority=95,
            ))

    if features["transition"]:
        pool.append(FPIInsightV146(
            "elso_tamado_gondolat", "Első támadó gondolat",
            f"{opponent} labdavesztése után a védők mögötti vagy a gyenge oldali terület nyílik meg.",
            "Első tiszta előrepassz a mélységbe; ha ez zárt, megtartás és azonnali oldalváltás.",
            priority=96,
        ))

    if readiness < 60:
        pool.append(FPIInsightV146(
            "allapothoz_igazitva", "Intenzitáskezelés",
            "A jelenlegi fizikai állapot mellett a meccsterv nem épülhet folyamatos, egész pályás nyomásra.",
            "A letámadási szakaszokat előre kijelölt ellenfél-akciókhoz kössük; közte középső blokkban kontrolláljuk a területet.",
            priority=92,
        ))

    selected, used = [], set()
    for item in sorted(pool, key=lambda x: x.priority, reverse=True):
        if item.topic in used:
            continue
        selected.append(item)
        used.add(item.topic)
        if len(selected) >= limit:
            break
    return selected


def _fpi_compact_scouting_line_v151(insight: FPIInsightV146) -> str:
    title = _fpi_complete_text_v151(insight.title).rstrip("?")
    observation = _fpi_complete_text_v151(insight.finding).rstrip(".")
    action = _fpi_complete_text_v151(insight.recommendation).rstrip(".")
    if action:
        return f"{title}: {observation} → {action}"
    return f"{title}: {observation}"


def _fpi_key_messages_v151(
    tactical_insights: List[FPIInsightV146],
    match_plan_insights: List[FPIInsightV146],
    fitness_insights: List[FPIInsightV146],
    minimum: int = 3,
    maximum: int = 5,
) -> List[str]:
    candidates = []
    for source_bonus, collection in [(30, match_plan_insights), (20, tactical_insights), (10, fitness_insights)]:
        for item in collection or []:
            candidates.append((int(item.priority) + source_bonus, item.topic, _fpi_compact_scouting_line_v151(item)))

    selected, used_topics, used_texts = [], set(), []
    for _, topic, text in sorted(candidates, key=lambda x: x[0], reverse=True):
        if topic in used_topics:
            continue
        if _fpi_is_near_duplicate_v145(text, used_texts, 0.78):
            continue
        selected.append(text)
        used_topics.add(topic)
        used_texts.append(text)
        if len(selected) >= maximum:
            break

    fallback = [
        "Védekezési fókusz: ellenfél elsődleges előrejátékának lezárása → labdaszerzési zóna tudatos kijelölése",
        "Támadási fókusz: ellenfél gyenge oldala vagy vonalak közötti területe → első tiszta előrejáték oda",
        "Erőnléti fókusz: heti állapot és sebességi terhelés → a fő inger pontos időzítése",
    ]
    for text in fallback:
        if len(selected) >= minimum:
            break
        selected.append(text)
    return selected[:maximum]


def _fpi_key_messages_table_v151(messages: List[str], P, head_style, body_style):
    rows = [[P("KULCSÜZENETEK – GYORS ÁTTEKINTÉS", head_style)]]
    for message in messages:
        rows.append([P(_fpi_complete_text_v151(message), body_style)])
    obj = Table(rows, colWidths=[27.7*cm])
    obj.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#1E3A8A")),
        ("TEXTCOLOR", (0,0), (-1,0), colors.white),
        ("BACKGROUND", (0,1), (-1,-1), colors.HexColor("#EFF6FF")),
        ("BOX", (0,0), (-1,-1), 0.8, colors.HexColor("#93C5FD")),
        ("INNERGRID", (0,1), (-1,-1), 0.35, colors.HexColor("#BFDBFE")),
        ("LEFTPADDING", (0,0), (-1,-1), 10),
        ("RIGHTPADDING", (0,0), (-1,-1), 10),
        ("TOPPADDING", (0,0), (-1,-1), 7),
        ("BOTTOMPADDING", (0,0), (-1,-1), 7),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
    ]))
    return obj


def _fpi_contextual_md_plan_rows_v151(
    tactical_context: Optional[Dict[str, object]],
    gps_context: Optional[Dict[str, object]],
    readiness: int,
    priorities: Optional[List[dict]],
    week: Optional[str],
) -> List[Tuple[str, str, str]]:
    rows = _fpi_contextual_md_plan_rows_v146(
        tactical_context, gps_context, readiness, priorities, week
    )
    result = []
    for day, fitness_goal, tactical_goal in rows:
        t = _fpi_complete_text_v151(tactical_goal)
        t = re.sub(r"^(Játékfelépítés|Átmenetek|Védekezés|Szélső játék|Pontrúgások|Letámadás|Aktiváció|Meccsterv):\s*", "", t)
        low = t.lower()
        if "labdakihozatal" in low or "építési" in low:
            label = "Labdakihozatal"
        elif "átmenet" in low or "labdavesztés" in low or "labdaszerzés" in low:
            label = "Átmenetek"
        elif "letámadás" in low:
            label = "Letámadás"
        elif "szélső" in low or "beadás" in low:
            label = "Szélső zóna"
        elif "pontrúgás" in low:
            label = "Pontrúgás"
        elif "blokk" in low or "védekez" in low:
            label = "Védekezési blokk"
        elif "aktiv" in low:
            label = "Aktiváció"
        else:
            label = "Meccsterv"
        result.append((day, _fpi_complete_text_v151(fitness_goal), f"{label}: {t}"))
    return result




# =========================================================
# V157 - Tactical-only szövegtisztítás és PDF-biztos magyar karakterek
# =========================================================
def _fpi_tactical_pdf_text_v157(value: object) -> str:
    """Taktikai szövegtisztítás az egységes V406 PDF-sanitize réteggel."""
    text = fpi_pdf_sanitize_v406(_fpi_complete_text_v151(value))
    text = re.sub(r"(?i)\bedzöi megállapítás\b[:\s—-]*", "", text)
    text = re.sub(r"(?i)\bedzői megállapítás\b[:\s—-]*", "", text)
    text = re.sub(r"\s*[—–-]\s*$", "", text)
    text = re.sub(r"(?i)\bbiztosítás\s+biztosítás\b", "biztosítás", text)
    text = re.sub(r"\s{2,}", " ", text).strip(" —–-;")
    return fpi_pdf_sanitize_v406(text)


def _fpi_valid_tactical_insight_v157(insight: Optional[FPIInsightV146]) -> bool:
    if insight is None:
        return False
    title = _fpi_tactical_pdf_text_v157(insight.title)
    finding = _fpi_tactical_pdf_text_v157(insight.finding)
    recommendation = _fpi_tactical_pdf_text_v157(insight.recommendation)

    if not finding:
        return False
    if title.lower() in {
        "", "edzöi megállapítás", "edzői megállapítás",
        "taktikai megállapítás", "megállapítás"
    }:
        return False
    if finding in {"—", "-", "–"}:
        return False
    if not recommendation and len(finding.split()) < 5:
        return False
    return True


def _fpi_clean_tactical_insights_v157(
    insights: List[FPIInsightV146],
    limit: int = 8,
) -> List[FPIInsightV146]:
    """
    Ugyanazt a megtisztított taktikai insight-listát használja
    a Tactical-only és az integrált riport.
    """
    result: List[FPIInsightV146] = []
    accepted_texts: List[str] = []

    for item in insights or []:
        if not _fpi_valid_tactical_insight_v157(item):
            continue

        cleaned = FPIInsightV146(
            topic=item.topic,
            title=_fpi_tactical_pdf_text_v157(item.title),
            finding=_fpi_tactical_pdf_text_v157(item.finding),
            recommendation=_fpi_tactical_pdf_text_v157(item.recommendation),
            source=_fpi_tactical_pdf_text_v157(item.source),
            priority=item.priority,
            block=item.block,
            day=item.day,
        )
        rendered = " ".join([
            cleaned.title,
            cleaned.finding,
            cleaned.recommendation,
        ]).strip()

        if _fpi_is_near_duplicate_v145(rendered, accepted_texts, 0.78):
            continue

        result.append(cleaned)
        accepted_texts.append(rendered)
        if len(result) >= limit:
            break

    return result


# =========================================================
# V156 - Öt riportmód, közös tartalmi motor
# =========================================================
def _fpi_canonical_report_bundle_v156(
    data: Optional[pd.DataFrame],
    selected_week: Optional[str],
    playstyle: str,
    tactical_context: Optional[Dict[str, object]],
) -> Dict[str, object]:
    tctx = tactical_context or {}
    has_gps = isinstance(data, pd.DataFrame) and not data.empty
    week = str(selected_week or "")

    gps_ctx, readiness, priorities, fitness_insights, risk_df = {}, None, [], [], pd.DataFrame()
    if has_gps:
        try:
            report_ctx = _fpi_report_context(data, selected_week, playstyle)
            gps_ctx = report_ctx
            readiness = int(report_ctx.get("readiness_score", 70) or 70)
            priorities = report_ctx.get("priorities", []) or []
            risk_df = report_ctx.get("risk_df") if isinstance(report_ctx.get("risk_df"), pd.DataFrame) else pd.DataFrame()
            fitness_insights = _fpi_contextual_gps_only_insights_v146(
                gps_ctx, priorities, readiness, week, 8
            )
        except Exception:
            pass

    tactical_insights, match_plan = [], []
    if _fpi_has_tactical_signal_v95(tctx):
        tactical_readiness = readiness if readiness is not None else 70
        tactical_insights = _fpi_clean_tactical_insights_v157(
            _fpi_pro_tactical_findings_v151(
                tctx, gps_ctx, tactical_readiness, priorities, week, 10
            ),
            limit=8,
        )
        match_plan = _fpi_clean_tactical_insights_v157(
            _fpi_pro_match_plan_v151(
                tctx, gps_ctx, tactical_readiness, priorities, week, 9
            ),
            limit=7,
        )

    return {
        "has_gps": has_gps,
        "has_tactical": bool(_fpi_has_tactical_signal_v95(tctx)),
        "week": week,
        "gps_context": gps_ctx,
        "readiness": readiness,
        "priorities": priorities,
        "risk_df": risk_df,
        "fitness_insights": fitness_insights,
        "tactical_insights": tactical_insights,
        "match_plan": match_plan,
        "tactical_context": tctx,
    }


def _fpi_own_pdf_findings_v156(tactical_context: Optional[Dict[str, object]], limit: int = 8) -> List[str]:
    ctx = tactical_context or {}
    own = ctx.get("own", {}) if isinstance(ctx.get("own"), dict) else {}
    pdf = own.get("pdf_insights", {}) if isinstance(own.get("pdf_insights"), dict) else {}
    values = []
    for key in ["sportsbase_findings", "topics", "sportsbase_lines"]:
        raw = pdf.get(key, []) or []
        if isinstance(raw, dict):
            raw = list(raw.values())
        for item in raw:
            text = _fpi_complete_text_v151(_fpi_extract_coach_text_v145(item, 500))
            if text and text not in values:
                values.append(text)
    blocks = pdf.get("blocks", {}) if isinstance(pdf.get("blocks"), dict) else {}
    for raw in blocks.values():
        if isinstance(raw, (list, tuple)):
            candidates = raw
        else:
            candidates = [raw]
        for item in candidates:
            text = _fpi_complete_text_v151(_fpi_extract_coach_text_v145(item, 500))
            if text and text not in values:
                values.append(text)
    return values[:limit]


def _fpi_v402_priority_rank(value: object) -> int:
    txt = _norm_mapping_text(str(value or ""))
    if any(k in txt for k in ["magas", "kritikus", "azonnali"]): return 3
    if any(k in txt for k in ["kozepes", "figyelendo"]): return 2
    return 1

def _fpi_v402_tactical_dimensions(ctx: Optional[Dict[str, object]], findings) -> List[dict]:
    """Coach-friendly, forrásarányos taktikai állapotkép közös riportfilozófiával."""
    ctx = ctx or {}
    framework = ctx.get("strategy_framework", {}) or {}
    dims_raw = framework.get("dimensions", {}) if isinstance(framework, dict) else {}
    definitions = {
        "Játékfelépítés": "A labdakihozatal stabilitása, az első és második vonal átjátszhatósága.",
        "Területnyerés": "A támadások előrehaladása és a veszélyes zónák elérésének minősége.",
        "Pressing": "A labda nélküli nyomás időzítése, intenzitása és kollektív támogatása.",
        "Átmenetek": "A labdaszerzés és labdavesztés utáni első másodpercek hatékonysága.",
        "Védekezési kontroll": "A blokk kompakt­sága, mélységvédelme és az ellenfél kulcsterületeinek lezárása.",
    }
    aliases = {
        "build": "Játékfelépítés", "possession": "Játékfelépítés", "progress": "Területnyerés",
        "press": "Pressing", "transition": "Átmenetek", "defen": "Védekezési kontroll",
    }
    rows=[]
    if isinstance(dims_raw, dict):
        for key,val in dims_raw.items():
            label=str(key)
            norm=_norm_mapping_text(label)
            for a,b in aliases.items():
                if a in norm: label=b; break
            try:
                score=float(val.get("score", val) if isinstance(val,dict) else val)
                if score<=1.5: score*=100
            except Exception:
                continue
            score=max(0,min(100,score))
            status="Jó" if score>=75 else ("Figyelendő" if score>=55 else "Fejlesztendő")
            rows.append({"Terület":label,"Pont":round(score),"Státusz":status,"Definíció":definitions.get(label,"A taktikai inputokból képzett területi állapotmutató.")})
    if not rows:
        buckets={k:[] for k in definitions}
        for item in findings or []:
            txt=_norm_mapping_text(f"{getattr(item,'title','')} {getattr(item,'finding','')} {getattr(item,'recommendation','')}")
            pr=100-15*(_fpi_v402_priority_rank(getattr(item,'priority',''))-1)
            matched=False
            for a,b in aliases.items():
                if a in txt: buckets[b].append(pr); matched=True
            if not matched: buckets["Védekezési kontroll"].append(70)
        for label,vals in buckets.items():
            if vals:
                score=sum(vals)/len(vals)
                status="Jó" if score>=75 else ("Figyelendő" if score>=55 else "Fejlesztendő")
                rows.append({"Terület":label,"Pont":round(score),"Státusz":status,"Definíció":definitions[label]})
    return rows[:5]

def _fpi_v402_tactical_reliability(ctx: Optional[Dict[str, object]]) -> tuple:
    ctx=ctx or {}
    signals=[]
    if ctx.get('has_own_pdf'): signals.append('saját PDF')
    if ctx.get('has_opp_pdf'): signals.append('ellenfél PDF')
    if ctx.get('has_own_team_excel'): signals.append('saját csapat Excel')
    if ctx.get('has_opp_team_excel'): signals.append('ellenfél csapat Excel')
    if ctx.get('has_own_player_excel'): signals.append('saját játékos Excel')
    if ctx.get('has_opp_player_excel'): signals.append('ellenfél játékos Excel')
    n=len(signals)
    score=min(100, 35+n*11 + (8 if (ctx.get('own_pdf_chars',0) or 0)>1500 else 0) + (8 if (ctx.get('opp_pdf_chars',0) or 0)>1500 else 0))
    status='Magas' if score>=75 else ('Közepes' if score>=50 else 'Korlátozott')
    return score,status,', '.join(signals) if signals else 'nincs azonosított forrás'

def build_fpi_tactical_only_pdf_bytes_v156(
    tactical_context: Optional[Dict[str, object]],
    demo_label: str = "",
) -> Optional[bytes]:
    """V410 Tactical-only: négy, egymásra épülő edzői blokk.

    1. ellenfélminták, 2. saját meccsterv, 3. játékosfeladatok,
    4. heti taktikai felkészítés. GPS-adatot nem használ.
    """
    if SimpleDocTemplate is None:
        return None
    ctx = tactical_context or {}
    if not _fpi_has_tactical_signal_v95(ctx):
        return None

    model = _fpi_v410_build_tactical_model(ctx, None, None, [], "")
    opp_eval = ctx.get("opponent_player_evaluation", []) or []
    own_eval = ctx.get("own_player_evaluation", []) or []
    day_focus = _fpi_v410_tactical_focus_by_day(model)

    font_name, font_bold = _register_pdf_font()
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=landscape(A4), rightMargin=1.0*cm, leftMargin=1.0*cm, topMargin=.9*cm, bottomMargin=.9*cm)
    styles = getSampleStyleSheet()
    title = ParagraphStyle("FPITacOnlyTitleV410", parent=styles["Title"], fontName=font_bold, fontSize=21, leading=24, textColor=colors.HexColor("#0F172A"))
    body = ParagraphStyle("FPITacOnlyBodyV410", parent=styles["BodyText"], fontName=font_name, fontSize=9.8, leading=12.8, alignment=0, textColor=colors.HexColor("#111827"))
    small = ParagraphStyle("FPITacOnlySmallV410", parent=body, fontSize=8.8, leading=11.4)
    head = ParagraphStyle("FPITacOnlyHeadV410", parent=body, fontName=font_bold, fontSize=9.2, leading=11.2, alignment=1, textColor=colors.white)
    strong = ParagraphStyle("FPITacOnlyStrongV410", parent=body, fontName=font_bold, fontSize=10.6, leading=13.5, alignment=0)

    def P(v, style=body):
        clean = fpi_pdf_sanitize_v406(_fpi_v410_football_hungarian(v, 1600))
        if style in (title, head, strong):
            clean = clean.rstrip('.')
        return Paragraph(html.escape(clean).replace("\n", "<br/>") or "Nincs értékelhető adat.", style)

    def section(text, bg="#DBEAFE", border="#93C5FD"):
        t = Table([[P(text, strong)]], colWidths=[27.7*cm])
        t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),colors.HexColor(bg)),("BOX",(0,0),(-1,-1),.5,colors.HexColor(border)),("LEFTPADDING",(0,0),(-1,-1),8),("RIGHTPADDING",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
        return t

    def tbl(rows, widths, header="#1E3A8A"):
        t = Table(rows, colWidths=widths, repeatRows=1, splitByRow=1)
        t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor(header)),("GRID",(0,0),(-1,-1),.32,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAFC")]),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
        return t

    story = [
        P("Football Performance Intelligence – Tactical-only", title),
        P(f"{demo_label or 'ÉLES RIPORT'} | Tactical Decision Engine V410 | GPS-adat nélkül.", small),
        Spacer(1,.12*cm),
    ]
    call = Table([[P("A riport kulcsüzenete", strong), P(_fpi_v410_key_message(model), body)]], colWidths=[5.2*cm,22.5*cm])
    call.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),colors.HexColor("#ECFDF5")),("BOX",(0,0),(-1,-1),.7,colors.HexColor("#10B981")),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),8),("RIGHTPADDING",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))

    story += [call, Spacer(1,.18*cm), section("1. Mit kell tudnunk az ellenfélről?", "#E0F2FE", "#2563EB")]
    pattern_rows = [[P("Minta",head),P("Mit látunk?",head),P("Hol és mikor?",head),P("Miért fontos?",head),P("Bizonyosság",head)]]
    for item in model.get("patterns", [])[:4]:
        pattern_rows.append([P(item.get("title",""),small),P(item.get("observation",""),small),P(item.get("situation",""),small),P(item.get("importance",""),small),P(item.get("confidence",""),small)])
    story.append(tbl(pattern_rows,[3.8*cm,7.2*cm,5.0*cm,8.4*cm,3.3*cm]))
    story += [Spacer(1,.10*cm), P("A bizonyosság a rendelkezésre álló ellenfél-PDF, csapat- és játékosadat forrásfedezetét jelzi. Korlátozott forrásnál a rendszer nem pótolja általános taktikai közhellyel a hiányzó információt.", small)]

    story += [PageBreak(), section("2. A mi meccstervünk", "#FEF3C7", "#F59E0B")]
    for index, item in enumerate(model.get("decisions", [])[:3], start=1):
        decision_header = Table([[P(f"{index}. {item.get('decision','')}", strong)]], colWidths=[27.7*cm])
        decision_header.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),colors.HexColor("#FFF7ED")),("BOX",(0,0),(-1,-1),.5,colors.HexColor("#F59E0B")),("LEFTPADDING",(0,0),(-1,-1),8),("RIGHTPADDING",(0,0),(-1,-1),8),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)]))
        rows = [
            [P("Amit az ellenfélnél látunk",head),P(item.get("opponent_evidence",""),body)],
            [P("Ami nálunk ezt támogatja vagy korlátozza",head),P(item.get("own_support",""),body)],
            [P("Mit kérünk a pályán?",head),P(item.get("on_pitch",""),body)],
            [P("Mire figyeljünk?",head),P(item.get("risk",""),body)],
        ]
        block = Table(rows, colWidths=[6.1*cm,21.6*cm], splitByRow=1)
        block.setStyle(TableStyle([("BACKGROUND",(0,0),(0,-1),colors.HexColor("#92400E")),("TEXTCOLOR",(0,0),(0,-1),colors.white),("GRID",(0,0),(-1,-1),.35,colors.HexColor("#CBD5E1")),("ROWBACKGROUNDS",(1,0),(1,-1),[colors.white,colors.HexColor("#FFFBEB")]),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),7),("RIGHTPADDING",(0,0),(-1,-1),7),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)]))
        story += [Spacer(1,.14*cm), KeepTogether([decision_header, block])]

    story += [PageBreak(), section("3. Játékosszintű taktikai feladatok", "#FEE2E2", "#EF4444")]
    player_rows = [[P("Oldal",head),P("Játékos",head),P("Szerep",head),P("Mit látunk?",head),P("Mit kérünk tőle vagy ellene?",head)]]
    for side, entries in [("ELLENFÉL",opp_eval),("SAJÁT",own_eval)]:
        for row in entries[:5]:
            player_rows.append([P(side,small),P(row.get('Játékos',''),small),P(row.get('Szerep',''),small),P(row.get('Értelmezés',''),small),P(row.get('Javaslat','') or 'A játékosfeladatot a videó alapján kell pontosítani.',small)])
    if len(player_rows) == 1:
        player_rows.append([P("-",small),P("Nincs játékos Excel",small),P("-",small),P("Csapatszintű elemzés készült.",small),P("Játékosszintű input szükséges a konkrét feladathoz.",small)])
    story.append(tbl(player_rows,[2.3*cm,3.7*cm,4.3*cm,8.4*cm,9.0*cm],header="#991B1B"))

    story += [PageBreak(), section("4. Heti taktikai felkészítés", "#DCFCE7", "#22C55E")]
    micro_rows = [[P("Nap",head),P("Fókusz",head),P("Mit gyakoroljunk?",head),P("Edzői megjegyzés",head)]]
    notes = {
        "MD-4": "A játékosok értsék a helyzetet és a szerepeket; még ne az ismétlésszám legyen a cél.",
        "MD-3": "Ez legyen a hét fő, meccsszerű taktikai napja; a végrehajtás sebessége és az együttmozgás döntő.",
        "MD-2": "Rövidebb blokkok, kevesebb ismétlés, több pontosítás. A fő döntéseket ne terheljük új szabályokkal.",
        "MD-1": "Rövid aktiváció és közös jelek. Csak az első számú megoldásokat ismételjük át.",
    }
    labels = {"MD-4":"Alaphelyzetek", "MD-3":"Fő meccshelyzet", "MD-2":"Pontosítás", "MD-1":"Aktiváció"}
    for md in ["MD-4","MD-3","MD-2","MD-1"]:
        micro_rows.append([P(md,small),P(labels[md],small),P(day_focus.get(md,""),small),P(notes[md],small)])
    story.append(tbl(micro_rows,[2.5*cm,4.3*cm,13.1*cm,7.8*cm],header="#166534"))
    story += [Spacer(1,.18*cm), P("A riport sorrendje: ellenfélminta → saját meccsterv → játékosfeladat → heti felkészítés. A GPS+taktikai riport ugyanezeket a döntéseket egészíti ki fizikai dózissal és readiness-korláttal.", small)]

    _fpi_pdf_build_v406(doc, story)
    buffer.seek(0)
    return buffer.getvalue()


def build_fpi_tactical_only_sample_pdf_bytes_v156() -> Optional[bytes]:
    """Tactical-only minta: pontosan az éles Tactical-only renderelővel."""
    return build_fpi_tactical_only_pdf_bytes_v156(
        _build_demo_tactical_context(),
        demo_label="MINTA RIPORT / DEMO FC – TACTICAL-ONLY",
    )


def build_fpi_integrated_sample_pdf_bytes_v156() -> Optional[bytes]:
    """GPS+taktikai minta: ugyanaz a production bundle/renderelő, mint éles exportnál."""
    demo_df = _fpi_v423_production_like_sample_df()
    latest = _fpi_v423_sample_latest_week(demo_df)
    if demo_df is None or demo_df.empty or not latest:
        return None
    return build_fpi_product_pdf_bytes(
        demo_df, latest, "Magas letámadás",
        report_type="executive",
        tactical_context=_build_demo_tactical_context(),
        demo_label="MINTA RIPORT / DEMO FC – GPS + TAKTIKAI",
    )


def build_fpi_own_team_tactical_only_pdf_bytes_v156(
    tactical_context: Optional[Dict[str, object]],
    demo_label: str = "",
) -> Optional[bytes]:
    if SimpleDocTemplate is None:
        return None
    ctx = tactical_context or {}
    own_findings = _fpi_own_pdf_findings_v156(ctx, 10)
    own_metrics = ctx.get("own_team_metrics", {}) or {}
    own_eval = ctx.get("own_player_evaluation", []) or []
    if not own_eval:
        own_eval = _fpi_build_player_evaluation_v132(ctx.get("own_player_tables", {}) or {}, side="own", max_rows=10)
    if not own_findings and not own_metrics and not own_eval:
        return None

    font_name, font_bold = _register_pdf_font()
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=landscape(A4), rightMargin=1.1*cm, leftMargin=1.1*cm, topMargin=1.0*cm, bottomMargin=1.0*cm)
    styles = getSampleStyleSheet()
    title = ParagraphStyle("FPIOwnTacTitleV156", parent=styles["Title"], fontName=font_bold, fontSize=22, leading=26)
    body = ParagraphStyle("FPIOwnTacBodyV156", parent=styles["BodyText"], fontName=font_name, fontSize=10.5, leading=14, alignment=4)
    small = ParagraphStyle("FPIOwnTacSmallV156", parent=styles["BodyText"], fontName=font_name, fontSize=9.3, leading=12.2, alignment=4)
    head = ParagraphStyle("FPIOwnTacHeadV156", parent=styles["BodyText"], fontName=font_bold, fontSize=10.2, leading=12.5, alignment=1, textColor=colors.white)

    def P(v, style=body):
        clean_v157 = _fpi_tactical_pdf_text_v157(v)
        return Paragraph(html.escape(clean_v157).replace("\n", "<br/>") or "Nincs értékelhető adat.", style)

    def tbl(rows, widths, header="#0F766E"):
        t = Table(rows, colWidths=widths, repeatRows=1, splitByRow=1)
        t.setStyle(TableStyle([
            ("BACKGROUND",(0,0),(-1,0),colors.HexColor(header)),
            ("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#CBD5E1")),
            ("VALIGN",(0,0),(-1,-1),"TOP"),
            ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAFC")]),
            ("LEFTPADDING",(0,0),(-1,-1),7),("RIGHTPADDING",(0,0),(-1,-1),7),
            ("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6),
        ]))
        return t

    story = [P("Football Performance Intelligence – saját csapat profil", title), P(f"{demo_label or 'ÉLES RIPORT'} | Saját taktikai PDF/Excel alapú elemzés, GPS nélkül.", small)]
    story.append(Spacer(1,0.2*cm))
    rows = [[P("Forrás", head), P("Saját csapat taktikai megállapítás", head)]]
    for text in own_findings:
        rows.append([P("Saját taktikai PDF", small), P(text, small)])
    if len(rows) == 1:
        rows.append([P("Saját taktikai input", small), P("A PDF nem adott külön szöveges megállapítást; az Excel-alapú profil szerepel a következő oldalakon.", small)])
    story.append(tbl(rows, [5.0*cm, 22.5*cm]))

    story.append(PageBreak())
    metric_rows = _fpi_team_metric_rows_v132(own_metrics)
    mr = [[P("Mutató", head), P("Érték", head), P("Referencia / értékelés", head), P("Edzői olvasat", head)]]
    for lab, val, ref_txt, reading, _key in metric_rows:
        mr.append([P(lab, small), P(val, small), P(ref_txt, small), P(reading, small)])
    if len(mr) == 1:
        mr.append([P("Csapatmutatók", small), P("—", small), P("Nincs saját csapat Excel", small), P("Az elemzés a saját taktikai PDF-re támaszkodik.", small)])
    story.append(tbl(mr, [4.3*cm,3.0*cm,6.0*cm,14.2*cm], header="#1E3A8A"))

    story.append(PageBreak())
    pr = [[P("Játékos", head), P("Szerep", head), P("Konkrét mutatók", head), P("Értékelés", head), P("Használati javaslat", head)]]
    for r in own_eval[:10]:
        pr.append([P(r.get("Játékos",""),small),P(r.get("Szerep",""),small),P(r.get("Bizonyíték",""),small),P(r.get("Értelmezés",""),small),P(r.get("Javaslat",""),small)])
    if len(pr) == 1:
        pr.append([P("—",small),P("—",small),P("Nincs saját játékos Excel",small),P("Játékosszintű számszerű értékelés nem készült.",small),P("Tölts fel saját játékos Excel/CSV-t.",small)])
    story.append(tbl(pr,[3.8*cm,4.8*cm,6.0*cm,6.2*cm,6.7*cm], header="#166534"))

    _fpi_pdf_build_v406(doc, story)
    buffer.seek(0)
    return buffer.getvalue()


